swiftSource "LawSpecRuntime/Actors.swift" = "// Actors and supervision trees. A handle names a stable mailbox, not a\n// worker: a supervised restart replaces the worker and keeps the committed\n// checkpoint and the messages waiting. Each actor handles one message at a\n// time on a thread of its own; a handler that returns commits its next state\n// before the reply, and one that throws commits nothing. Supervisors restart\n// their children by strategy (one for one, one for all, rest for one) and\n// lifetime (permanent, transient, temporary) within a rolling restart budget,\n// and escalate to their own supervisor when it is spent. Calls block their\n// caller, as the synchronous runtime's every call does.\n// ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\n\nimport Foundation\n\npublic enum Actors {\n  /// When a supervisor restarts a child that stopped.\n  public enum Lifetime: Sendable {\n    /// Always.\n    case permanent\n    /// Only after a crash.\n    case transient\n    /// Never.\n    case temporary\n  }\n\n  /// Which children a supervisor restarts when one fails.\n  public enum Strategy: Sendable {\n    case oneForOne\n    case oneForAll\n    case restForOne\n  }\n\n  /// What a tree runs: an actor (its start and its restart from the last\n  /// checkpoint) or a supervisor of named children.\n  public indirect enum Spec: @unchecked Sendable {\n    case actor(start: () throws -> Any, restart: (Any) throws -> Any)\n    case supervisor(\n      strategy: Strategy, restarts: Int, periodMicros: Int64, children: [(String, Lifetime, Spec)])\n\n    var isActor: Bool {\n      if case .actor = self { return true }\n      return false\n    }\n  }\n\n  /// What an observer is told about a handle.\n  public enum Event: @unchecked Sendable {\n    case crashed(any Error)\n    case stopped\n  }\n\n  /// A reply slot, settled once.\n  final class Reply: @unchecked Sendable {\n    private let done = DispatchSemaphore(value: 0)\n    private let result = Locked<Result<Any, any Error>?>(nil)\n\n    func settle(_ outcome: Result<Any, any Error>) {\n      let first: Bool = result.with { r in\n        if r != nil { return false }\n        r = outcome\n        return true\n      }\n      if first { done.signal() }\n    }\n\n    func wait() throws -> Any {\n      done.wait()\n      return try result.with { $0 }!.get()\n    }\n  }\n\n  enum Operation {\n    case run((Any) throws -> (Any, Any))\n    case crash(any Error, ObjectIdentifier)\n    case restart\n    case stop\n  }\n\n  struct Entry {\n    let reply: Reply?\n    let operation: Operation\n  }\n\n  /// A mailbox of events from the handles it monitors, received selectively.\n  public final class Inbox: @unchecked Sendable {\n    private var events: [(Handle, Event)] = []\n    private let condition = NSCondition()\n\n    public init() {}\n\n    func post(_ handle: Handle, _ event: Event) {\n      condition.lock()\n      events.append((handle, event))\n      condition.broadcast()\n      condition.unlock()\n    }\n\n    /// The next event of a handle, waiting at most a number of milliseconds.\n    public func receive(_ handle: Handle, _ milliseconds: Int) -> Event? {\n      let deadline = Date().addingTimeInterval(Double(milliseconds) / 1000)\n      condition.lock()\n      defer { condition.unlock() }\n      while true {\n        if let i = events.firstIndex(where: { $0.0 == handle }) { return events.remove(at: i).1 }\n        if Date() >= deadline { return nil }\n        _ = condition.wait(until: deadline)\n      }\n    }\n  }\n\n  final class TreeNode {\n    let path: [String]\n    let spec: Spec\n    let parent: [String]?\n    let lifetime: Lifetime\n    var children: [(String, [String])] = []\n    var state: Any = ()\n    var checkpoint: Any?\n    /// Run start, or restart from the checkpoint, before the next message.\n    var initial = false\n    var worker = 0\n    /// Which incarnation of the worker runs: a restart makes a new one.\n    var incarnation = 0\n    var waiting: [Entry] = []\n    var active: Entry?\n    var running = false\n    var accepting = true\n    var removed = false\n    var observers: [Inbox] = []\n    var links: [Handle] = []\n    var seen = Set<ObjectIdentifier>()\n    var restarts: [Int64] = []\n    var stopNotified = false\n\n    init(_ path: [String], _ spec: Spec, _ parent: [String]?, _ lifetime: Lifetime) {\n      self.path = path\n      self.spec = spec\n      self.parent = parent\n      self.lifetime = lifetime\n    }\n\n    var isActor: Bool { spec.isActor }\n  }\n\n  /// The tree of one started spec: its nodes, under one lock. No\n  /// application code runs under the lock.\n  final class Tree: @unchecked Sendable {\n    let gate = NSRecursiveLock()\n    var nodes: [[String]: TreeNode] = [:]\n\n    func locked<T>(_ body: () throws -> T) rethrows -> T {\n      gate.lock()\n      defer { gate.unlock() }\n      return try body()\n    }\n  }\n\n  /// A stable handle on an actor or a supervisor of a tree.\n  public struct Handle: Sendable, Equatable, CustomStringConvertible {\n    let tree: Tree\n    let path: [String]\n\n    public static func == (a: Handle, b: Handle) -> Bool { a.tree === b.tree && a.path == b.path }\n\n    public var description: String { \"actor \" + path.joined(separator: \"/\") }\n  }\n\n  /// An origin of a crash, by identity.\n  private final class Origin {}\n\n  private static let currentKey = \"lawspec.actors.current\"\n\n  private static func now() -> Int64 { Int64(DispatchTime.now().uptimeNanoseconds / 1000) }\n\n  private static func stoppedError() -> any Error {\n    Fail.with(\"ActorStopped\", \"the actor has stopped\")\n  }\n\n  private static func crashedError(_ cause: any Error) -> any Error {\n    LawSpecError(\"ActorCrashed\", Node.message(cause), cause: String(describing: cause))\n  }\n\n  private static func reply(_ entry: Entry, _ result: Result<Any, any Error>) {\n    entry.reply?.settle(result)\n  }\n\n  private static func node(_ tree: Tree, _ path: [String]) -> TreeNode { tree.nodes[path]! }\n\n  private static func descendants(_ tree: Tree, _ path: [String]) -> [[String]] {\n    [path] + node(tree, path).children.flatMap { descendants(tree, $0.1) }\n  }\n\n  private static func notify(_ tree: Tree, _ n: TreeNode, _ event: Event) {\n    for inbox in n.observers { inbox.post(Handle(tree: tree, path: n.path), event) }\n  }\n\n  /// Mark a subtree gone: every waiting caller is told the actor stopped.\n  private static func halt(_ tree: Tree, _ path: [String]) {\n    for p in descendants(tree, path).reversed() {\n      let n = node(tree, p)\n      if n.removed { continue }\n      if let e = n.active { reply(e, .failure(stoppedError())) }\n      for e in n.waiting { reply(e, .failure(stoppedError())) }\n      n.waiting.removeAll()\n      if !n.stopNotified { notify(tree, n, .stopped) }\n      n.removed = true\n      n.accepting = false\n      n.active = nil\n      n.stopNotified = true\n      n.worker += 1\n    }\n  }\n\n  private static func schedule(_ tree: Tree, _ n: TreeNode) {\n    guard !n.running, !n.removed, n.isActor, n.initial || !n.waiting.isEmpty else { return }\n    n.running = true\n    let generation = n.worker\n    let box = UncheckedBox(n)\n    LawThread.start { pump(tree, box.value, generation) }\n  }\n\n  /// A supervisor restarts a group of its children: the failed actor starts\n  /// again from its checkpoint before its next message; every other actor\n  /// restarts after the messages it had already accepted.\n  private static func restartGroup(\n    _ tree: Tree, _ parent: [String], _ failed: [String], _ origin: [String]\n  ) {\n    let supervisor = node(tree, parent)\n    let live = supervisor.children.map(\\.1).filter { !node(tree, $0).removed }\n    let group: [[String]]\n    switch supervisor.spec {\n    case .supervisor(.oneForAll, _, _, _): group = live\n    case .supervisor(.restForOne, _, _, _): group = Array(live.drop(while: { $0 != failed }))\n    default: group = [failed]\n    }\n    for member in group {\n      if node(tree, member).lifetime == .temporary {\n        halt(tree, member)\n        continue\n      }\n      for p in descendants(tree, member) {\n        let n = node(tree, p)\n        if n.removed { continue }\n        n.accepting = true\n        n.incarnation += 1\n        if n.isActor {\n          if p == origin {\n            n.initial = true\n          } else {\n            n.waiting.append(Entry(reply: nil, operation: .restart))\n          }\n          schedule(tree, n)\n        } else {\n          n.restarts = []\n        }\n      }\n    }\n  }\n\n  /// Decide what a stop (normal) or crash (abnormal) means: a restart\n  /// within the parent's budget, an escalation, or the end of the subtree.\n  private static func decide(_ tree: Tree, _ path: [String], _ abnormal: Bool, _ origin: [String]) {\n    let n = node(tree, path)\n    let restart = !n.removed && (n.lifetime == .permanent || (n.lifetime == .transient && abnormal))\n    if let parent = n.parent, restart {\n      let supervisor = node(tree, parent)\n      guard case .supervisor(_, let limit, let period, _) = supervisor.spec else {\n        halt(tree, path)\n        return\n      }\n      let at = now()\n      let recent = supervisor.restarts.filter { at - $0 <= period }\n      if recent.count < limit && !supervisor.removed {\n        supervisor.restarts = recent + [at]\n        restartGroup(tree, parent, path, origin)\n      } else {\n        decide(tree, parent, true, origin)\n      }\n      return\n    }\n    if !n.isActor && abnormal {\n      notify(tree, n, .crashed(Fail.with(\"RestartLimit\", path.joined(separator: \"/\"))))\n      n.stopNotified = true\n    }\n    halt(tree, path)\n  }\n\n  /// An actor failed: its caller learns why, its observers and linked\n  /// actors are told, and its supervisor decides.\n  private static func failed(\n    _ tree: Tree, _ n: TreeNode, _ entry: Entry?, _ cause: any Error, _ origin: ObjectIdentifier\n  ) -> [Handle] {\n    if let e = entry {\n      if case .crash = e.operation {\n        reply(e, .success(()))\n      } else {\n        reply(e, .failure(crashedError(cause)))\n      }\n    }\n    n.active = nil\n    n.seen.insert(origin)\n    notify(tree, n, .crashed(cause))\n    n.stopNotified = true\n    let links = n.links\n    decide(tree, n.path, true, n.path)\n    if !n.removed { n.stopNotified = false }\n    return links\n  }\n\n  private static func propagate(_ links: [Handle], _ cause: any Error, _ origin: ObjectIdentifier) {\n    for other in links {\n      let t = other.tree\n      t.locked {\n        guard let n = t.nodes[other.path], n.accepting, !n.removed, !n.seen.contains(origin) else {\n          return\n        }\n        n.seen.insert(origin)\n        n.waiting.append(Entry(reply: nil, operation: .crash(cause, origin)))\n        schedule(t, n)\n      }\n    }\n  }\n\n  private enum Step {\n    case initialize(Any?)\n    case message(Entry)\n  }\n\n  private static func pump(_ tree: Tree, _ n: TreeNode, _ generation: Int) {\n    while true {\n      let originObject = Origin()\n      let origin = ObjectIdentifier(originObject)\n      let step: Step? = tree.locked {\n        if n.worker != generation || n.removed {\n          if n.worker == generation { n.running = false }\n          return nil\n        }\n        if n.initial { return .initialize(n.checkpoint) }\n        if !n.waiting.isEmpty {\n          let e = n.waiting.removeFirst()\n          n.active = e\n          return .message(e)\n        }\n        n.running = false\n        return nil\n      }\n      guard let step else { return }\n      guard case .actor(let start, let restart) = n.spec else { return }\n      switch step {\n      case .initialize(let checkpoint):\n        let outcome = Result { try checkpoint.map(restart) ?? start() }\n        let links: [Handle] = tree.locked {\n          if n.worker != generation { return [] }\n          switch outcome {\n          case .success(let v):\n            n.state = v\n            n.checkpoint = v\n            n.initial = false\n            return []\n          case .failure(let e):\n            return failed(tree, n, nil, e, origin)\n          }\n        }\n        if case .failure(let e) = outcome, !links.isEmpty { propagate(links, e, origin) }\n      case .message(let entry):\n        let state = tree.locked { n.state }\n        func run(_ body: () throws -> (Any, Any)) -> Result<(Any, Any), any Error> {\n          Thread.current.threadDictionary[currentKey] = UncheckedBox(n)\n          defer { Thread.current.threadDictionary[currentKey] = nil }\n          return Result { try body() }\n        }\n        switch entry.operation {\n        case .stop:\n          tree.locked {\n            if n.worker == generation {\n              n.active = nil\n              reply(entry, .success(()))\n              decide(tree, n.path, false, n.path)\n            }\n          }\n        case .crash(let cause, let crashOrigin):\n          let links: [Handle] = tree.locked {\n            n.worker == generation ? failed(tree, n, entry, cause, crashOrigin) : []\n          }\n          propagate(links, cause, crashOrigin)\n        case .run(let handler):\n          let outcome = run { try handler(state) }\n          commit(tree, n, generation, entry, outcome, origin, answer: true)\n        case .restart:\n          let outcome = run { ((), try restart(state)) }\n          commit(tree, n, generation, entry, outcome, origin, answer: false)\n        }\n      }\n    }\n  }\n\n  private static func commit(\n    _ tree: Tree, _ n: TreeNode, _ generation: Int, _ entry: Entry,\n    _ outcome: Result<(Any, Any), any Error>,\n    _ origin: ObjectIdentifier, answer: Bool\n  ) {\n    let links: [Handle] = tree.locked {\n      if n.worker != generation { return [] }\n      switch outcome {\n      case .success(let (reply, next)):\n        n.state = next\n        n.checkpoint = next\n        n.active = nil\n        if answer { Actors.reply(entry, .success(reply)) }\n        return []\n      case .failure(let e):\n        return failed(tree, n, entry, e, origin)\n      }\n    }\n    if case .failure(let e) = outcome, !links.isEmpty { propagate(links, e, origin) }\n  }\n\n  // MARK: Specs\n\n  /// An actor: its state's start, and its state after a crash from the\n  /// last committed one.\n  public static func actor(\n    _ start: @escaping () throws -> Any, _ restart: @escaping (Any) throws -> Any\n  ) -> Spec {\n    .actor(start: start, restart: restart)\n  }\n\n  /// An actor whose state after a crash is a fresh start.\n  public static func actorOf(_ start: @escaping () throws -> Any) -> Spec {\n    .actor(start: start, restart: { _ in try start() })\n  }\n\n  /// A supervisor: its strategy, at most a number of restarts within a\n  /// period (microseconds), and its children in start order, each named\n  /// and with its lifetime.\n  public static func supervisor(\n    _ strategy: Strategy, _ restarts: Int, _ periodMicros: Int64,\n    _ children: [(String, Lifetime, Spec)]\n  ) throws -> Spec {\n    if restarts < 0 || periodMicros <= 0 {\n      throw Fail.with(\"InvalidSupervisor\", \"a supervisor needs restarts >= 0 and a positive period\")\n    }\n    if Set(children.map(\\.0)).count != children.count {\n      throw Fail.with(\"InvalidSupervisor\", \"duplicate child names\")\n    }\n    return .supervisor(\n      strategy: strategy, restarts: restarts, periodMicros: periodMicros, children: children)\n  }\n\n  // MARK: Starting and stopping trees\n\n  private static func allocate(\n    _ tree: Tree, _ path: [String], _ spec: Spec, _ parent: [String]?, _ lifetime: Lifetime\n  ) {\n    let n = TreeNode(path, spec, parent, lifetime)\n    tree.nodes[path] = n\n    switch spec {\n    case .supervisor(_, _, _, let children):\n      n.children = children.map { ($0.0, path + [$0.0]) }\n      for (name, life, child) in children { allocate(tree, path + [name], child, path, life) }\n    case .actor:\n      n.initial = true\n    }\n  }\n\n  /// Stop a handle: an actor finishes the messages it accepted first; a\n  /// supervisor stops its whole subtree. Stopping a stopped handle does nothing.\n  public static func stop(_ handle: Handle) {\n    let tree = handle.tree\n    let wait: Reply? = tree.locked {\n      let n = node(tree, handle.path)\n      if n.removed { return nil }\n      if n.isActor {\n        n.accepting = n.parent != nil && n.lifetime == .permanent\n        let r = Reply()\n        n.waiting.append(Entry(reply: r, operation: .stop))\n        schedule(tree, n)\n        return r\n      }\n      if n.parent != nil && n.lifetime == .permanent {\n        decide(tree, handle.path, false, handle.path)\n      } else {\n        halt(tree, handle.path)\n      }\n      return nil\n    }\n    _ = try? wait?.wait()\n  }\n\n  /// Start a spec. Its actors start in order; a start that fails stops the\n  /// tree and fails here. An actor alone runs as the temporary child of a\n  /// supervisor with no restarts; its handle is the actor's.\n  public static func start(_ spec: Spec) throws -> Handle {\n    let tree = Tree()\n    let root: Spec\n    let visible: [String]\n    if spec.isActor {\n      root = .supervisor(\n        strategy: .oneForOne, restarts: 0, periodMicros: 1, children: [(\"actor\", .temporary, spec)])\n      visible = [\"actor\"]\n    } else {\n      root = spec\n      visible = []\n    }\n    tree.locked { allocate(tree, [], root, nil, .permanent) }\n    let actors = tree.locked { descendants(tree, []).map { node(tree, $0) }.filter(\\.isActor) }\n    for n in actors {\n      guard case .actor(let start, _) = n.spec else { continue }\n      let value: Any\n      do {\n        value = try start()\n      } catch {\n        tree.locked { halt(tree, []) }\n        throw LawSpecError(\n          \"ActorStartFailed\", Node.message(error), cause: String(describing: error))\n      }\n      tree.locked {\n        n.state = value\n        n.checkpoint = value\n        n.initial = false\n      }\n    }\n    return Handle(tree: tree, path: visible)\n  }\n\n  /// Run a body with a started spec, stopping its tree afterwards.\n  public static func withSpec<T>(_ spec: Spec, _ body: (Handle) throws -> T) throws -> T {\n    let handle = try start(spec)\n    defer { stop(Handle(tree: handle.tree, path: [])) }\n    return try body(handle)\n  }\n\n  // MARK: Messages\n\n  /// The reply of a queued message; refused at once when the actor stopped.\n  private static func enqueue(_ handle: Handle, _ operation: Operation, _ wait: Bool) throws\n    -> Reply\n  {\n    let tree = handle.tree\n    return try tree.locked {\n      let n = node(tree, handle.path)\n      if wait, let current = Thread.current.threadDictionary[currentKey] as? UncheckedBox<TreeNode>,\n        current.value === n\n      {\n        throw Fail.with(\"ActorSelfCall\", \"an actor cannot call itself\")\n      }\n      if !n.isActor || !n.accepting || n.removed { throw stoppedError() }\n      let r = Reply()\n      n.waiting.append(Entry(reply: r, operation: operation))\n      schedule(tree, n)\n      return r\n    }\n  }\n\n  /// Send a handler and wait for its reply. The handler gets the state and\n  /// gives the reply and the next state.\n  public static func call(_ handle: Handle, _ handler: @escaping (Any) throws -> (Any, Any)) throws\n    -> Any\n  {\n    try enqueue(handle, .run(handler), true).wait()\n  }\n\n  /// Send a handler without waiting for it.\n  public static func tell(_ handle: Handle, _ handler: @escaping (Any) throws -> (Any, Any)) throws\n  {\n    _ = try enqueue(handle, .run(handler), false)\n  }\n\n  /// The actor's committed state.\n  public static func state(_ handle: Handle) throws -> Any { try call(handle) { ($0, $0) } }\n\n  /// Crash the actor in order with its messages, as a failing handler would.\n  public static func crash(_ handle: Handle) throws {\n    let origin = Origin()\n    _ = try enqueue(handle, .crash(Fail.with(\"CrashedOnPurpose\"), ObjectIdentifier(origin)), true)\n      .wait()\n  }\n\n  /// Kill the actor's worker now, as an external failure: a handler it is\n  /// running commits nothing and its caller learns the actor crashed; the\n  /// messages waiting run after its supervisor restarts it.\n  public static func kill(_ handle: Handle) {\n    let tree = handle.tree\n    let originObject = Origin()\n    let origin = ObjectIdentifier(originObject)\n    let cause = Fail.with(\"ActorKilled\", \"the actor's worker was killed\")\n    let links: [Handle]? = tree.locked {\n      let n = node(tree, handle.path)\n      if n.removed || !n.isActor { return nil }\n      n.worker += 1\n      n.incarnation += 1\n      n.running = false\n      let links = failed(tree, n, n.active, cause, origin)\n      schedule(tree, n)\n      return links\n    }\n    if let links { propagate(links, cause, origin) }\n  }\n\n  /// A supervisor's child by name (stable across restarts).\n  public static func child(_ handle: Handle, _ name: String) throws -> Handle {\n    try handle.tree.locked {\n      guard let (_, path) = node(handle.tree, handle.path).children.first(where: { $0.0 == name })\n      else {\n        throw Fail.with(\"UnknownChild\", name)\n      }\n      return Handle(tree: handle.tree, path: path)\n    }\n  }\n\n  /// A supervisor's children that have not stopped for good, in order.\n  public static func children(_ handle: Handle) -> [(String, Handle)] {\n    handle.tree.locked {\n      node(handle.tree, handle.path).children.filter { !node(handle.tree, $0.1).removed }.map {\n        ($0.0, Handle(tree: handle.tree, path: $0.1))\n      }\n    }\n  }\n\n  /// Restarts a supervisor has made in its current period.\n  public static func restartCount(_ handle: Handle) -> Int {\n    handle.tree.locked { node(handle.tree, handle.path).restarts.count }\n  }\n\n  /// The worker now behind a handle (it changes when the worker is\n  /// replaced), or nil when the handle has stopped.\n  public static func worker(_ handle: Handle) -> Int? {\n    handle.tree.locked {\n      let n = node(handle.tree, handle.path)\n      return n.removed ? nil : n.incarnation\n    }\n  }\n\n  /// Tell an inbox about a handle's crashes and its stop.\n  public static func monitor(_ handle: Handle, _ inbox: Inbox) {\n    handle.tree.locked { node(handle.tree, handle.path).observers.insert(inbox, at: 0) }\n  }\n\n  /// Link two actors: a crash of either crashes the other.\n  public static func link(_ left: Handle, _ right: Handle) {\n    left.tree.locked { node(left.tree, left.path).links.insert(right, at: 0) }\n    right.tree.locked { node(right.tree, right.path).links.insert(left, at: 0) }\n  }\n\n  /// The next event of a handle in an inbox, waiting at most a number of\n  /// milliseconds.\n  public static func receiveEvent(_ inbox: Inbox, _ handle: Handle, _ milliseconds: Int) -> Event? {\n    inbox.receive(handle, milliseconds)\n  }\n}\n"
swiftSource "LawSpecRuntime/BigInt.swift" = "// LawSpec's arbitrary-precision integer. Swift's standard library has none,\n// and the runtime takes no package dependencies, so it is here: a sign and a\n// magnitude of 64-bit words, least significant first, with no high zero word.\n// ref:DEC-swift-runtime-from-scratch ref:DEC-portable-exact-arithmetic\n\n/// An integer of any size. Division truncates towards zero, as LawSpec's\n/// `quot` and `rem` do; shifts and bitwise operators act on the two's\n/// complement form, as on a native integer.\npublic struct BigInt: Sendable, Hashable, Comparable, CustomStringConvertible,\n  ExpressibleByIntegerLiteral\n{\n  /// The magnitude, least significant word first, without high zero words.\n  @usableFromInline var words: [UInt64]\n  /// Whether the integer is below zero; zero is never negative.\n  @usableFromInline var negative: Bool\n\n  @usableFromInline init(words: [UInt64], negative: Bool) {\n    var trimmed = words\n    while let last = trimmed.last, last == 0 { trimmed.removeLast() }\n    self.words = trimmed\n    self.negative = trimmed.isEmpty ? false : negative\n  }\n\n  public static let zero = BigInt(words: [], negative: false)\n  public static let one = BigInt(words: [1], negative: false)\n\n  public init(integerLiteral value: Int) { self.init(value) }\n\n  public init(_ value: Int) {\n    if value >= 0 {\n      self.init(words: [UInt64(value)], negative: false)\n    } else {\n      self.init(words: [UInt64(bitPattern: Int64(value)).twosComplementMagnitude], negative: true)\n    }\n  }\n\n  public init<T: BinaryInteger>(_ value: T) {\n    if value < 0 {\n      // Magnitude of a negative value: complement the two's complement words.\n      let positive = BigInt(words: value.words.map { UInt64($0) }, negative: false)\n      let width = value.bitWidth\n      let modulus = BigInt.one << width\n      self = -(modulus - positive.truncatedTo(bits: width))\n    } else {\n      self.init(words: value.words.map { UInt64($0) }, negative: false)\n    }\n  }\n\n  /// The integer of decimal digits, with an optional sign.\n  public init?(_ text: String) { self.init(text, radix: 10) }\n\n  /// The integer of digits in a radix from 2 to 36, with an optional sign.\n  public init?(_ text: String, radix: Int) {\n    guard radix >= 2 && radix <= 36 else { return nil }\n    var digits = Substring(text)\n    var negative = false\n    if let first = digits.first, first == \"-\" || first == \"+\" {\n      negative = first == \"-\"\n      digits = digits.dropFirst()\n    }\n    guard !digits.isEmpty else { return nil }\n    var result = BigInt.zero\n    // Digits are taken in chunks that fit a word, then folded in.\n    let chunk = radix == 10 ? 19 : 8\n    var power: UInt64 = 1\n    for _ in 0..<chunk { power *= UInt64(radix) }\n    var accumulator: UInt64 = 0\n    var count = 0\n    for character in digits {\n      guard let digit = character.hexDigitValue ?? character.letterValue, digit < radix else {\n        return nil\n      }\n      accumulator = accumulator * UInt64(radix) + UInt64(digit)\n      count += 1\n      if count == chunk {\n        result = result.multipliedAdding(power, accumulator)\n        accumulator = 0\n        count = 0\n      }\n    }\n    if count > 0 {\n      var scale: UInt64 = 1\n      for _ in 0..<count { scale *= UInt64(radix) }\n      result = result.multipliedAdding(scale, accumulator)\n    }\n    result.negative = negative && !result.words.isEmpty\n    self = result\n  }\n\n  /// self * factor + addend, on the magnitude.\n  private func multipliedAdding(_ factor: UInt64, _ addend: UInt64) -> BigInt {\n    var result = [UInt64]()\n    result.reserveCapacity(words.count + 1)\n    var carry = addend\n    for word in words {\n      let (high, low) = word.multipliedFullWidth(by: factor)\n      let (sum, overflow) = low.addingReportingOverflow(carry)\n      result.append(sum)\n      carry = high &+ (overflow ? 1 : 0)\n    }\n    if carry != 0 { result.append(carry) }\n    return BigInt(words: result, negative: negative)\n  }\n\n  // MARK: Properties\n\n  public var isZero: Bool { words.isEmpty }\n  /// -1, 0 or 1.\n  public var signum: Int { words.isEmpty ? 0 : (negative ? -1 : 1) }\n  public var isNegative: Bool { negative }\n  public var isEven: Bool { words.isEmpty || words[0] & 1 == 0 }\n  public var magnitude: BigInt { BigInt(words: words, negative: false) }\n  /// The number of bits of the magnitude: 0 for zero.\n  public var bitLength: Int {\n    guard let last = words.last else { return 0 }\n    return (words.count - 1) * 64 + (64 - last.leadingZeroBitCount)\n  }\n\n  /// The value as a fixed-width integer, if it fits.\n  public func exactly<T: FixedWidthInteger>(_ type: T.Type) -> T? {\n    guard bitLength <= T.bitWidth else { return nil }\n    if words.isEmpty { return 0 }\n    if negative {\n      guard T.isSigned else { return nil }\n      // The magnitude of T.min is 2^(width-1).\n      if bitLength == T.bitWidth {\n        return self == BigInt(T.min) ? T.min : nil\n      }\n      var value: T = 0\n      for (i, word) in words.enumerated() { value |= T(truncatingIfNeeded: word) << (i * 64) }\n      return 0 - value\n    }\n    if T.isSigned && bitLength == T.bitWidth { return nil }\n    var value: T = 0\n    for (i, word) in words.enumerated() { value |= T(truncatingIfNeeded: word) << (i * 64) }\n    return value\n  }\n\n  /// The low bits of the two's complement form, as a fixed-width integer.\n  public func truncated<T: FixedWidthInteger>(_ type: T.Type) -> T {\n    let low = truncatedTo(bits: T.bitWidth)\n    var value: T = 0\n    for (i, word) in low.words.enumerated() where i * 64 < T.bitWidth {\n      value |= T(truncatingIfNeeded: word) << (i * 64)\n    }\n    return value\n  }\n\n  /// The value modulo 2^bits, as a non-negative integer.\n  func truncatedTo(bits: Int) -> BigInt {\n    let modulus = BigInt.one << bits\n    var r = self % modulus\n    if r.negative { r = r + modulus }\n    return r\n  }\n\n  /// The nearest Double, rounding the magnitude's leading bits.\n  public var doubleValue: Double {\n    var result = 0.0\n    for word in words.reversed() { result = result * 18446744073709551616.0 + Double(word) }\n    return negative ? -result : result\n  }\n\n  // MARK: Magnitudes\n\n  private static func compareMagnitudes(_ a: [UInt64], _ b: [UInt64]) -> Int {\n    if a.count != b.count { return a.count < b.count ? -1 : 1 }\n    var i = a.count - 1\n    while i >= 0 {\n      if a[i] != b[i] { return a[i] < b[i] ? -1 : 1 }\n      i -= 1\n    }\n    return 0\n  }\n\n  private static func addMagnitudes(_ a: [UInt64], _ b: [UInt64]) -> [UInt64] {\n    let (long, short) = a.count >= b.count ? (a, b) : (b, a)\n    var result = [UInt64]()\n    result.reserveCapacity(long.count + 1)\n    var carry: UInt64 = 0\n    for i in 0..<long.count {\n      let (s1, o1) = long[i].addingReportingOverflow(i < short.count ? short[i] : 0)\n      let (s2, o2) = s1.addingReportingOverflow(carry)\n      result.append(s2)\n      carry = (o1 ? 1 : 0) + (o2 ? 1 : 0)\n    }\n    if carry != 0 { result.append(carry) }\n    return result\n  }\n\n  /// a - b, where a's magnitude is at least b's.\n  private static func subtractMagnitudes(_ a: [UInt64], _ b: [UInt64]) -> [UInt64] {\n    var result = [UInt64]()\n    result.reserveCapacity(a.count)\n    var borrow: UInt64 = 0\n    for i in 0..<a.count {\n      let (d1, o1) = a[i].subtractingReportingOverflow(i < b.count ? b[i] : 0)\n      let (d2, o2) = d1.subtractingReportingOverflow(borrow)\n      result.append(d2)\n      borrow = (o1 ? 1 : 0) + (o2 ? 1 : 0)\n    }\n    return result\n  }\n\n  private static func multiplyMagnitudes(_ a: [UInt64], _ b: [UInt64]) -> [UInt64] {\n    if a.isEmpty || b.isEmpty { return [] }\n    var result = [UInt64](repeating: 0, count: a.count + b.count)\n    for i in 0..<a.count {\n      var carry: UInt64 = 0\n      let x = a[i]\n      if x == 0 { continue }\n      for j in 0..<b.count {\n        let (high, low) = x.multipliedFullWidth(by: b[j])\n        let (s1, o1) = low.addingReportingOverflow(result[i + j])\n        let (s2, o2) = s1.addingReportingOverflow(carry)\n        result[i + j] = s2\n        carry = high &+ (o1 ? 1 : 0) &+ (o2 ? 1 : 0)\n      }\n      result[i + b.count] = carry\n    }\n    return result\n  }\n\n  /// Divide a magnitude by one word: the quotient and the remainder.\n  private static func divideByWord(_ a: [UInt64], _ divisor: UInt64) -> ([UInt64], UInt64) {\n    var quotient = [UInt64](repeating: 0, count: a.count)\n    var remainder: UInt64 = 0\n    var i = a.count - 1\n    while i >= 0 {\n      let (q, r) = divisor.dividingFullWidth((remainder, a[i]))\n      quotient[i] = q\n      remainder = r\n      i -= 1\n    }\n    return (quotient, remainder)\n  }\n\n  /// Knuth's algorithm D on magnitudes: the quotient and the remainder.\n  private static func divideMagnitudes(_ a: [UInt64], _ b: [UInt64]) -> ([UInt64], [UInt64]) {\n    if compareMagnitudes(a, b) < 0 { return ([], a) }\n    if b.count == 1 {\n      let (q, r) = divideByWord(a, b[0])\n      return (q, r == 0 ? [] : [r])\n    }\n    let shift = b[b.count - 1].leadingZeroBitCount\n    let v = shiftLeftWords(b, shift)\n    var u = shiftLeftWords(a, shift)\n    if u.count == a.count { u.append(0) }\n    let n = v.count\n    let m = u.count - n\n    var q = [UInt64](repeating: 0, count: m)\n    let vTop = v[n - 1]\n    let vNext = v[n - 2]\n    var j = m - 1\n    while j >= 0 {\n      // Estimate the quotient word from the top two words.\n      var qhat: UInt64\n      var rhat: UInt64\n      if u[j + n] >= vTop {\n        qhat = UInt64.max\n        let (r, overflow) = u[j + n - 1].addingReportingOverflow(vTop)\n        rhat = r\n        if overflow {\n          qhat = UInt64.max\n        } else {\n          while true {\n            let (high, low) = qhat.multipliedFullWidth(by: vNext)\n            if high > rhat || (high == rhat && low > u[j + n - 2]) {\n              qhat -= 1\n              let (r2, o2) = rhat.addingReportingOverflow(vTop)\n              rhat = r2\n              if o2 { break }\n            } else {\n              break\n            }\n          }\n        }\n      } else {\n        (qhat, rhat) = vTop.dividingFullWidth((u[j + n], u[j + n - 1]))\n        while true {\n          let (high, low) = qhat.multipliedFullWidth(by: vNext)\n          if high > rhat || (high == rhat && low > u[j + n - 2]) {\n            qhat -= 1\n            let (r2, o2) = rhat.addingReportingOverflow(vTop)\n            rhat = r2\n            if o2 { break }\n          } else {\n            break\n          }\n        }\n      }\n      // Multiply and subtract.\n      var borrow: UInt64 = 0\n      var carry: UInt64 = 0\n      for i in 0..<n {\n        let (high, low) = qhat.multipliedFullWidth(by: v[i])\n        let (product, o1) = low.addingReportingOverflow(carry)\n        carry = high &+ (o1 ? 1 : 0)\n        let (d1, b1) = u[i + j].subtractingReportingOverflow(product)\n        let (d2, b2) = d1.subtractingReportingOverflow(borrow)\n        u[i + j] = d2\n        borrow = (b1 ? 1 : 0) + (b2 ? 1 : 0)\n      }\n      let (d1, b1) = u[j + n].subtractingReportingOverflow(carry)\n      let (d2, b2) = d1.subtractingReportingOverflow(borrow)\n      u[j + n] = d2\n      if b1 || b2 {\n        // Add back: the estimate was one too large.\n        qhat -= 1\n        var c: UInt64 = 0\n        for i in 0..<n {\n          let (s1, o1) = u[i + j].addingReportingOverflow(v[i])\n          let (s2, o2) = s1.addingReportingOverflow(c)\n          u[i + j] = s2\n          c = (o1 ? 1 : 0) + (o2 ? 1 : 0)\n        }\n        u[j + n] = u[j + n] &+ c\n      }\n      q[j] = qhat\n      j -= 1\n    }\n    let remainder = shiftRightWords(Array(u[0..<n]), shift)\n    return (q, remainder)\n  }\n\n  private static func shiftLeftWords(_ a: [UInt64], _ bits: Int) -> [UInt64] {\n    if bits == 0 { return a }\n    var result = [UInt64]()\n    result.reserveCapacity(a.count + 1)\n    var carry: UInt64 = 0\n    for word in a {\n      result.append((word << UInt64(bits)) | carry)\n      carry = word >> UInt64(64 - bits)\n    }\n    if carry != 0 { result.append(carry) }\n    return result\n  }\n\n  private static func shiftRightWords(_ a: [UInt64], _ bits: Int) -> [UInt64] {\n    if bits == 0 { return a }\n    var result = [UInt64](repeating: 0, count: a.count)\n    for i in 0..<a.count {\n      let next = i + 1 < a.count ? a[i + 1] << UInt64(64 - bits) : 0\n      result[i] = (a[i] >> UInt64(bits)) | next\n    }\n    return result\n  }\n\n  // MARK: Arithmetic\n\n  public static func + (a: BigInt, b: BigInt) -> BigInt {\n    if a.negative == b.negative {\n      return BigInt(words: addMagnitudes(a.words, b.words), negative: a.negative)\n    }\n    let c = compareMagnitudes(a.words, b.words)\n    if c == 0 { return .zero }\n    if c > 0 { return BigInt(words: subtractMagnitudes(a.words, b.words), negative: a.negative) }\n    return BigInt(words: subtractMagnitudes(b.words, a.words), negative: b.negative)\n  }\n\n  public static prefix func - (a: BigInt) -> BigInt {\n    BigInt(words: a.words, negative: !a.negative)\n  }\n\n  public static func - (a: BigInt, b: BigInt) -> BigInt { a + (-b) }\n\n  public static func * (a: BigInt, b: BigInt) -> BigInt {\n    BigInt(words: multiplyMagnitudes(a.words, b.words), negative: a.negative != b.negative)\n  }\n\n  public static func += (a: inout BigInt, b: BigInt) { a = a + b }\n  public static func -= (a: inout BigInt, b: BigInt) { a = a - b }\n  public static func *= (a: inout BigInt, b: BigInt) { a = a * b }\n\n  /// The quotient truncated towards zero and the remainder with the\n  /// dividend's sign. The divisor must not be zero.\n  public func quotientAndRemainder(dividingBy divisor: BigInt) -> (\n    quotient: BigInt, remainder: BigInt\n  ) {\n    precondition(!divisor.isZero, \"BigInt division by zero\")\n    let (q, r) = BigInt.divideMagnitudes(words, divisor.words)\n    return (\n      BigInt(words: q, negative: negative != divisor.negative), BigInt(words: r, negative: negative)\n    )\n  }\n\n  public static func / (a: BigInt, b: BigInt) -> BigInt {\n    a.quotientAndRemainder(dividingBy: b).quotient\n  }\n  public static func % (a: BigInt, b: BigInt) -> BigInt {\n    a.quotientAndRemainder(dividingBy: b).remainder\n  }\n\n  /// The quotient rounded towards negative infinity.\n  public func floorDivided(by divisor: BigInt) -> BigInt {\n    let (q, r) = quotientAndRemainder(dividingBy: divisor)\n    return (!r.isZero && (r.negative != divisor.negative)) ? q - .one : q\n  }\n\n  /// self raised to a non-negative power.\n  public func power(_ exponent: Int) -> BigInt {\n    precondition(exponent >= 0, \"BigInt negative exponent\")\n    var result = BigInt.one\n    var base = self\n    var e = exponent\n    while e > 0 {\n      if e & 1 == 1 { result = result * base }\n      e >>= 1\n      if e > 0 { base = base * base }\n    }\n    return result\n  }\n\n  /// The greatest common divisor, never negative.\n  public static func gcd(_ a: BigInt, _ b: BigInt) -> BigInt {\n    var x = a.magnitude\n    var y = b.magnitude\n    while !y.isZero {\n      let r = x % y\n      x = y\n      y = r\n    }\n    return x\n  }\n\n  public static func min(_ a: BigInt, _ b: BigInt) -> BigInt { a <= b ? a : b }\n  public static func max(_ a: BigInt, _ b: BigInt) -> BigInt { a >= b ? a : b }\n\n  // MARK: Shifts and bits\n\n  public static func << (a: BigInt, bits: Int) -> BigInt {\n    if bits < 0 { return a >> (-bits) }\n    if a.isZero || bits == 0 { return a }\n    let whole = bits / 64\n    let shifted = shiftLeftWords(a.words, bits % 64)\n    return BigInt(words: [UInt64](repeating: 0, count: whole) + shifted, negative: a.negative)\n  }\n\n  /// An arithmetic shift: it rounds towards negative infinity.\n  public static func >> (a: BigInt, bits: Int) -> BigInt {\n    if bits < 0 { return a << (-bits) }\n    if a.isZero || bits == 0 { return a }\n    if a.negative {\n      // floor(a / 2^bits) for a negative a.\n      return -(((-a) - .one) >> bits) - .one\n    }\n    let whole = bits / 64\n    if whole >= a.words.count { return .zero }\n    return BigInt(words: shiftRightWords(Array(a.words[whole...]), bits % 64), negative: false)\n  }\n\n  /// Two's complement words of a given count, for bitwise operators.\n  private func complementWords(_ count: Int) -> [UInt64] {\n    var result = words + [UInt64](repeating: 0, count: Swift.max(0, count - words.count))\n    if !negative { return result }\n    // -m in two's complement: invert m - 1.\n    var borrow: UInt64 = 1\n    for i in 0..<result.count {\n      let (d, o) = result[i].subtractingReportingOverflow(borrow)\n      result[i] = ~d\n      borrow = o ? 1 : 0\n    }\n    return result\n  }\n\n  private static func fromComplement(_ words: [UInt64], negative: Bool) -> BigInt {\n    if !negative { return BigInt(words: words, negative: false) }\n    var result = words.map { ~$0 }\n    var carry: UInt64 = 1\n    for i in 0..<result.count {\n      let (s, o) = result[i].addingReportingOverflow(carry)\n      result[i] = s\n      carry = o ? 1 : 0\n    }\n    return BigInt(words: result, negative: true)\n  }\n\n  private static func bitwise(\n    _ a: BigInt, _ b: BigInt, _ op: (UInt64, UInt64) -> UInt64, _ sign: (Bool, Bool) -> Bool\n  ) -> BigInt {\n    let count = Swift.max(a.words.count, b.words.count) + 1\n    let x = a.complementWords(count)\n    let y = b.complementWords(count)\n    var result = [UInt64](repeating: 0, count: count)\n    for i in 0..<count { result[i] = op(x[i], y[i]) }\n    return fromComplement(result, negative: sign(a.negative, b.negative))\n  }\n\n  public static func & (a: BigInt, b: BigInt) -> BigInt { bitwise(a, b, { $0 & $1 }, { $0 && $1 }) }\n  public static func | (a: BigInt, b: BigInt) -> BigInt { bitwise(a, b, { $0 | $1 }, { $0 || $1 }) }\n  public static func ^ (a: BigInt, b: BigInt) -> BigInt { bitwise(a, b, { $0 ^ $1 }, { $0 != $1 }) }\n\n  // MARK: Order and text\n\n  public static func < (a: BigInt, b: BigInt) -> Bool { compare(a, b) < 0 }\n\n  /// -1, 0 or 1.\n  public static func compare(_ a: BigInt, _ b: BigInt) -> Int {\n    if a.negative != b.negative { return a.negative ? -1 : 1 }\n    let c = compareMagnitudes(a.words, b.words)\n    return a.negative ? -c : c\n  }\n\n  public var description: String { toString(radix: 10) }\n\n  /// The digits in a radix from 2 to 36, lowercase, with a leading minus.\n  public func toString(radix: Int) -> String {\n    if words.isEmpty { return \"0\" }\n    let chunk = radix == 10 ? 19 : 8\n    var divisor: UInt64 = 1\n    for _ in 0..<chunk { divisor *= UInt64(radix) }\n    var parts = [String]()\n    var rest = words\n    while !rest.isEmpty {\n      let (q, r) = BigInt.divideByWord(rest, divisor)\n      rest = q\n      while let last = rest.last, last == 0 { rest.removeLast() }\n      parts.append(String(r, radix: radix))\n    }\n    var text = negative ? \"-\" : \"\"\n    text += parts.last ?? \"0\"\n    for part in parts.dropLast().reversed() {\n      text += String(repeating: \"0\", count: chunk - part.count) + part\n    }\n    return text\n  }\n}\n\nextension UInt64 {\n  /// The magnitude of this bit pattern read as a negative Int64.\n  fileprivate var twosComplementMagnitude: UInt64 { (~self) &+ 1 }\n}\n\nextension Character {\n  /// a to z as 10 to 35.\n  fileprivate var letterValue: Int? {\n    guard let ascii = asciiValue else { return nil }\n    if ascii >= 97 && ascii <= 122 { return Int(ascii) - 87 }\n    if ascii >= 65 && ascii <= 90 { return Int(ascii) - 55 }\n    return nil\n  }\n}\n"
swiftSource "LawSpecRuntime/ChannelProtocol.swift" = "// Pure transitions of a reliable, movable network channel end. Its owner\n// keeps the timers and sends the frames each transition returns.\n// Application values enter as canonical bytes and leave in send order,\n// exactly once; an end that has not been used can move to another node with\n// its state, and its peer follows it. Times are monotonic microseconds.\n// ref:DEC-distribution-canonical-wire ref:DEC-sessions-by-construction\n\npublic enum ChannelProtocol {\n  static let retry: Int64 = 50000\n\n  public struct Unacked: Sendable {\n    var body: [UInt8]\n    var first: Int64\n    var last: Int64\n  }\n\n  public struct Taking: Sendable {\n    var from: String\n    var token: String\n    var first: Int64\n    var last: Int64\n  }\n\n  public struct State: Sendable {\n    public var address: String\n    var deadline: Int64\n    public var peer: String?\n    var out: Int64 = 0\n    var expected: Int64 = 0\n    var unacked: [Int64: Unacked] = [:]\n    var early: [Int64: [UInt8]] = [:]\n    var received: [[UInt8]] = []\n    public var failure: String?\n    public var closed = false\n    public var eof = false\n    public var used = false\n    var history: [String] = []\n    var token: String?\n    public var moved: String?\n    var snapshot: [UInt8]?\n    var taking: Taking?\n    var taken = false\n    var confirmed = false\n    var announcing = false\n    var announcedAt: Int64?\n\n    init(address: String, deadline: Int64) {\n      self.address = address\n      self.deadline = deadline\n    }\n  }\n\n  /// What a reader gets.\n  public enum Received: Sendable {\n    case empty\n    case body([UInt8])\n    case failed(String)\n  }\n\n  public static let eofReason = \"the other end gave up the conversation\"\n  public static let takeFailure =\n    \"the node the end came from did not hand it over in time (unreachable)\"\n  static let hello = Array(\"hello\".utf8)\n\n  private static func unavailable() -> LawSpecError { Fail.with(\"ChannelEndUnavailable\") }\n\n  private static func check(_ condition: Bool) throws {\n    if !condition { throw Fail.with(\"InvalidChannelOperation\") }\n  }\n\n  /// A new end at an address; the deadline is in microseconds.\n  public static func create(_ address: String, _ deadline: Int64) throws -> State {\n    _ = try Wire.splitAddress(address)\n    try check(deadline > 0)\n    return State(address: address, deadline: deadline)\n  }\n\n  private static func message(_ destination: String, _ kind: String, _ payload: [UInt8]) -> Frame {\n    Wire.frameTo(destination, kind, payload)\n  }\n\n  private static func usable(_ state: State) throws {\n    if state.eof { throw unavailable() }\n    let fresh = state.failure == nil && !state.closed && state.token == nil && state.moved == nil\n    if !(fresh && (state.taking == nil || state.taken)) { throw unavailable() }\n  }\n\n  private static func channelFrame(_ state: State, _ sequence: Int64, _ body: [UInt8]) throws\n    -> Frame\n  {\n    message(state.peer!, \"chan\", try Wire.channel(sequence, state.address, body))\n  }\n\n  private static func transmit(_ state: State, _ sequence: Int64, _ body: [UInt8], _ now: Int64)\n    throws -> (State, [Frame])\n  {\n    _ = try Wire.channel(sequence, state.address, body)\n    var next = state\n    next.unacked[sequence] = Unacked(body: body, first: now, last: now)\n    return (next, state.peer == nil ? [] : [try channelFrame(state, sequence, body)])\n  }\n\n  /// Greet a peer end.\n  public static func connect(_ state: State, _ peer: String, _ now: Int64) throws -> (\n    State, [Frame]\n  ) {\n    try usable(state)\n    try check(state.peer == nil)\n    _ = try Wire.splitAddress(peer)\n    var s = state\n    s.peer = peer\n    return try transmit(s, -1, hello, now)\n  }\n\n  /// Send a value's bytes.\n  public static func send(_ state: State, _ bytes: [UInt8], _ now: Int64) throws -> (State, [Frame])\n  {\n    try usable(state)\n    var s = state\n    s.out += 1\n    s.used = true\n    return try transmit(s, state.out, [0] + bytes, now)\n  }\n\n  /// Give up the conversation: an ordered end-of-file frame.\n  public static func abandon(_ state: State, _ now: Int64) throws -> (State, [Frame]) {\n    if state.closed || state.moved != nil { return (state, []) }\n    var s = state\n    s.closed = true\n    if state.failure != nil { return (s, []) }\n    s.out += 1\n    return try transmit(s, state.out, [1], now)\n  }\n\n  /// The next value for a reader, if there is one.\n  public static func receiveBody(_ state: State) -> (Received, State) {\n    if state.token != nil || state.moved != nil {\n      return (.failed(\"the channel end has been offered or moved\"), state)\n    }\n    var s = state\n    if let body = state.received.first {\n      if body.count >= 1 && body[0] == 0 {\n        s.received.removeFirst()\n        s.used = true\n        return (.body(Array(body.dropFirst())), s)\n      }\n      s.received = []\n      s.used = true\n      s.eof = true\n      return (.failed(eofReason), s)\n    }\n    if state.eof { return (.failed(eofReason), state) }\n    if let reason = state.failure { return (.failed(reason), state) }\n    return (.empty, state)\n  }\n\n  private static func validBody(_ body: [UInt8]) -> Bool {\n    (body.count >= 1 && body[0] == 0) || body == [1]\n  }\n\n  private static func drain(_ state: State) -> State {\n    var s = state\n    while let body = s.early.removeValue(forKey: s.expected) {\n      s.expected += 1\n      s.received.append(body)\n    }\n    return s\n  }\n\n  private static func fail(_ reason: String, _ state: State) -> State {\n    if state.failure != nil { return state }\n    var s = state\n    s.failure = reason\n    s.unacked = [:]\n    return s\n  }\n\n  private static func numbered(_ entries: [(Int64, [UInt8])]) throws -> [UInt8] {\n    var out = try Descriptors.varint(BigInt(entries.count))\n    for (n, body) in entries {\n      out += try Wire.fields([Wire.sequenceType, Wire.bytesType], [.int(BigInt(n)), .bytes(body)])\n    }\n    return out\n  }\n\n  private static func readNumbered(_ bytes: [UInt8], _ start: Int) throws -> (\n    [(Int64, [UInt8])], Int\n  ) {\n    let (count, position) = try Descriptors.readVarint(bytes, start)\n    try check(count <= BigInt((bytes.count - position) / 2))\n    var at = position\n    var entries = [(Int64, [UInt8])]()\n    for _ in 0..<(count.exactly(Int.self) ?? 0) {\n      let (values, next) = try Wire.readFields([Wire.sequenceType, Wire.bytesType], bytes, at)\n      guard case .int(let n) = values[0], let v = n.exactly(Int64.self),\n        case .bytes(let body) = values[1]\n      else {\n        throw Fail.with(\"InvalidSnapshot\")\n      }\n      entries.append((v, body))\n      at = next\n    }\n    return (entries, at)\n  }\n\n  private static func snapshot(_ state: State) throws -> [UInt8] {\n    let prefix = try Wire.fields(\n      [\n        Wire.textType, Wire.textType, Wire.textType, .forms([.atom(\"list\"), Wire.textType]),\n        Wire.sequenceType, Wire.sequenceType,\n      ],\n      [\n        .text(state.token ?? \"\"), .text(state.failure ?? \"\"), .text(state.peer ?? \"\"),\n        .list((state.history + [state.address]).map { .text($0) }), .int(BigInt(state.out)),\n        .int(BigInt(state.expected)),\n      ])\n    let unacked = state.unacked.keys.sorted().map { ($0, state.unacked[$0]!.body) }\n    let early = state.early.keys.sorted().map { ($0, state.early[$0]!) }\n    return prefix + (try numbered(unacked)) + (try numbered(early))\n      + (try Wire.bytesList(state.received))\n  }\n\n  private static func tickTaking(_ state: State, _ taking: Taking, _ now: Int64) throws -> (\n    State, [Frame]\n  ) {\n    if now - taking.first >= state.deadline { return (fail(takeFailure, state), []) }\n    if now - taking.last > retry {\n      var s = state\n      var t = taking\n      t.last = now\n      s.taking = t\n      return (s, [message(taking.from, \"take\", try Wire.texts([taking.token, state.address]))])\n    }\n    return (state, [])\n  }\n\n  private static func announce(_ state: State, _ now: Int64) throws -> (State, [Frame]) {\n    guard state.announcing, !state.confirmed else { return (state, []) }\n    if let at = state.announcedAt, now - at <= retry { return (state, []) }\n    var s = state\n    s.announcedAt = now\n    return (\n      s,\n      [\n        message(\n          state.peer!, \"moved\", try Wire.textList(state.history) + (try Wire.texts([state.address]))\n        )\n      ]\n    )\n  }\n\n  /// Retransmit what is due, fail what is overdue, and keep a take going.\n  public static func tick(_ state: State, _ now: Int64) throws -> (State, [Frame]) {\n    if state.moved != nil || state.failure != nil { return (state, []) }\n    if let taking = state.taking, !state.taken { return try tickTaking(state, taking, now) }\n    let due = state.unacked.keys.sorted().compactMap { n in\n      state.unacked[n].flatMap { now - $0.last > retry ? (n, $0) : nil }\n    }\n    if due.contains(where: { now - $0.1.first > state.deadline }) {\n      return (fail(\"the other end did not answer in time (unreachable)\", state), [])\n    }\n    if state.peer == nil { return (state, []) }\n    var (s1, announced) = try announce(state, now)\n    var frames = [Frame]()\n    for (n, e) in due {\n      frames.append(try channelFrame(s1, n, e.body))\n      s1.unacked[n]?.last = now\n    }\n    return (s1, announced + frames)\n  }\n\n  private static func give(_ state: State, _ payload: [UInt8]) throws -> (State, [Frame]) {\n    let (values, next) = try Wire.readTexts(2, payload, 0)\n    guard next == payload.count else { return (state, []) }\n    let (token, taker) = (values[0], values[1])\n    _ = try Wire.splitAddress(taker)\n    if state.token != token { return (state, []) }\n    if let moved = state.moved {\n      return moved == taker ? (state, [message(taker, \"state\", state.snapshot!)]) : (state, [])\n    }\n    let snap = try snapshot(state)\n    var s = state\n    s.moved = taker\n    s.snapshot = snap\n    s.unacked = [:]\n    s.early = [:]\n    return (s, [message(taker, \"state\", snap)])\n  }\n\n  private static func install(_ state: State, _ payload: [UInt8], _ now: Int64) throws -> (\n    State, [Frame]\n  ) {\n    let taking = state.taking!\n    let (values, r1) = try Wire.readTexts(3, payload, 0)\n    let (token, failure, peer) = (values[0], values[1], values[2])\n    guard token == taking.token else { return (state, []) }\n    let (history, r2) = try Wire.readTextList(payload, r1)\n    try check(!history.isEmpty && history.last == taking.from)\n    for h in history { _ = try Wire.splitAddress(h) }\n    if !peer.isEmpty { _ = try Wire.splitAddress(peer) }\n    let (outExpected, r3) = try Wire.readFields(\n      [Wire.sequenceType, Wire.sequenceType], payload, r2)\n    guard case .int(let o) = outExpected[0], case .int(let e) = outExpected[1],\n      let out = o.exactly(Int64.self), let expected = e.exactly(Int64.self)\n    else { throw Fail.with(\"InvalidSnapshot\") }\n    try check(out >= 0 && expected >= 0)\n    let (unacked, r4) = try readNumbered(payload, r3)\n    let (early, r5) = try readNumbered(payload, r4)\n    let (received, r6) = try Wire.readBytesList(payload, r5)\n    try check(r6 == payload.count)\n    try check(received.allSatisfy(validBody))\n    try check(early.allSatisfy { $0.0 >= expected && validBody($0.1) })\n    try check(\n      unacked.allSatisfy {\n        ($0.0 == -1 && $0.1 == hello) || ($0.0 >= 0 && $0.0 < out && validBody($0.1))\n      })\n    try check(Set(unacked.map(\\.0)).count == unacked.count)\n    try check(Set(early.map(\\.0)).count == early.count)\n    var s1 = state\n    s1.peer = peer.isEmpty ? nil : peer\n    s1.history = history\n    s1.out = out\n    s1.expected = expected\n    s1.unacked = Dictionary(\n      uniqueKeysWithValues: unacked.map {\n        ($0.0, Unacked(body: $0.1, first: now, last: now - retry - 1))\n      })\n    s1.early = Dictionary(uniqueKeysWithValues: early)\n    s1.received = received\n    s1.announcing = true\n    s1.announcedAt = nil\n    s1.taken = true\n    return failure.isEmpty ? try tick(drain(s1), now) : (fail(failure, s1), [])\n  }\n\n  private static func peerMoved(_ state: State, _ payload: [UInt8]) throws -> (State, [Frame]) {\n    let (history, rest) = try Wire.readTextList(payload, 0)\n    let (values, next) = try Wire.readTexts(1, payload, rest)\n    guard next == payload.count else { return (state, []) }\n    let destination = values[0]\n    _ = try Wire.splitAddress(destination)\n    var s1 = state\n    if let p = state.peer {\n      if history.contains(p) { s1.peer = destination }\n    } else {\n      s1.peer = destination\n    }\n    if s1.peer == destination {\n      return (\n        s1,\n        [\n          message(\n            destination, \"moved-ack\", try Descriptors.encode(Wire.textType, .text(destination), [:])\n          )\n        ]\n      )\n    }\n    return (s1, [])\n  }\n\n  private static func arriving(_ state: State, _ frame: Frame, _ now: Int64) throws -> (\n    State, [Frame]\n  ) {\n    if frame.kind == \"take\" { return try give(state, frame.payload) }\n    if let moved = state.moved {\n      var f = frame\n      f.to = moved\n      return (state, [f])\n    }\n    if state.taking != nil && !state.taken {\n      return frame.kind == \"state\" ? try install(state, frame.payload, now) : (state, [])\n    }\n    switch frame.kind {\n    case \"chan\" where state.failure != nil:\n      return (state, [])\n    case \"ack\":\n      var s = state\n      s.unacked[try Wire.readSequence(frame.payload)] = nil\n      return (s, [])\n    case \"moved\":\n      return try peerMoved(state, frame.payload)\n    case \"moved-ack\":\n      let (values, next) = try Wire.readTexts(1, frame.payload, 0)\n      if next == frame.payload.count && values[0] == state.address {\n        var s = state\n        s.confirmed = true\n        return (s, [])\n      }\n      return (state, [])\n    case \"chan\":\n      let (sequence, sender, body) = try Wire.readChannel(frame.payload)\n      _ = try Wire.splitAddress(sender)\n      var updated = state\n      if sequence == -1 {\n        try check(body == hello)\n        if state.peer == nil { updated.peer = sender }\n      } else {\n        try check(sequence >= 0 && validBody(body))\n        try check(!state.eof || sequence < state.expected)\n        if sequence >= state.expected && state.early[sequence] == nil {\n          updated.early[sequence] = body\n          updated = drain(updated)\n        }\n      }\n      return (updated, [message(sender, \"ack\", try Wire.sequence(sequence))])\n    default:\n      return (state, [])\n    }\n  }\n\n  /// A frame for this end. Invalid frames change nothing.\n  public static func accept(_ state: State, _ frame: Frame, _ now: Int64) -> (State, [Frame]) {\n    (try? arriving(state, frame, now)) ?? (state, [])\n  }\n\n  /// Offer an unused end to another node: the address that takes it.\n  public static func offer(_ state: State, _ token: String) throws -> (String, State) {\n    try check(\n      !token.isEmpty && !state.used && !state.closed && state.moved == nil\n        && (state.taking == nil || state.taken))\n    let chosen = state.token ?? token\n    var s = state\n    s.token = chosen\n    return (state.address + \"?take=\" + chosen, s)\n  }\n\n  /// Take an offered end, by the address its offer gave.\n  public static func take(_ state: State, _ address: String, _ now: Int64) throws -> (\n    State, [Frame]\n  ) {\n    try usable(state)\n    try check(!state.used)\n    guard let range = address.range(of: \"?take=\") else {\n      throw Fail.with(\"InvalidChannelOperation\")\n    }\n    let old = String(address[..<range.lowerBound])\n    let token = String(address[range.upperBound...])\n    try check(!token.isEmpty)\n    _ = try Wire.splitAddress(old)\n    var s = state\n    s.taking = Taking(from: old, token: token, first: now, last: now - retry - 1)\n    return try tick(s, now)\n  }\n\n  /// Whether a take has finished: true or false, or the failure.\n  public static func takeStatus(_ state: State, _ now: Int64) -> Result<Bool, NodeFailure> {\n    guard let taking = state.taking else { return .success(true) }\n    if state.taken {\n      return .success(\n        state.confirmed || state.failure != nil || now - taking.first >= state.deadline)\n    }\n    if state.failure != nil || now - taking.first >= state.deadline {\n      return .failure(NodeFailure(takeFailure))\n    }\n    return .success(false)\n  }\n}\n"
swiftSource "LawSpecRuntime/Codecs.swift" = "// Conversions between portable values and the native Swift types adapters\n// use. The generated code composes these for each adapter's signature, and\n// generates one for each data type, so no reflection is involved.\n// ref:DEC-typed-core-boundary ref:DEC-native-bindings-typed-identity\n\n/// To and from a native type.\npublic struct Codec<Native>: Sendable {\n  public let toNative: @Sendable (Value) throws -> Native\n  public let fromNative: @Sendable (Native) throws -> Value\n\n  public init(\n    toNative: @escaping @Sendable (Value) throws -> Native,\n    fromNative: @escaping @Sendable (Native) throws -> Value\n  ) {\n    self.toNative = toNative\n    self.fromNative = fromNative\n  }\n}\n\npublic enum Codecs {\n  /// A value that is not of a native type's shape.\n  public static func invalid(_ expected: String, _ value: Value) -> LawSpecError {\n    wrong(expected, value)\n  }\n\n  static func wrong(_ expected: String, _ value: Value) -> LawSpecError {\n    Fail.with(\"InvalidNativeValue\", \"expected \\(expected), got \\(Recorded.debug(value))\")\n  }\n\n  static func integer(_ name: String, _ value: Value) throws -> BigInt {\n    guard case .int(let n) = value else { throw wrong(name, value) }\n    return n\n  }\n\n  private static func bounded<T: FixedWidthInteger & Sendable>(_ name: String, _ type: T.Type)\n    -> Codec<T>\n  {\n    Codec(\n      toNative: { v in\n        guard let n = try integer(name, v).exactly(T.self) else { throw wrong(name, v) }\n        return n\n      }, fromNative: { .int(BigInt($0)) })\n  }\n\n  public static let int8 = bounded(\"Int8\", Int8.self)\n  public static let int16 = bounded(\"Int16\", Int16.self)\n  public static let int32 = bounded(\"Int32\", Int32.self)\n  public static let int64 = bounded(\"Int64\", Int64.self)\n  public static let uint8 = bounded(\"UInt8\", UInt8.self)\n  public static let uint16 = bounded(\"UInt16\", UInt16.self)\n  public static let uint32 = bounded(\"UInt32\", UInt32.self)\n  public static let uint64 = bounded(\"UInt64\", UInt64.self)\n  /// IntSize: Int, checked against the profile by the schema.\n  public static let intSize = bounded(\"IntSize\", Int.self)\n  /// UIntSize and UIntPtr: UInt, checked against the profile by the schema.\n  public static let uintSize = bounded(\"UIntSize\", UInt.self)\n  public static let bigInt = Codec<BigInt>(\n    toNative: { try integer(\"Integer\", $0) }, fromNative: { .int($0) })\n\n  public static let bool = Codec<Bool>(\n    toNative: { v in\n      guard case .bool(let b) = v else { throw wrong(\"Bool\", v) }\n      return b\n    }, fromNative: { .bool($0) })\n\n  public static let unit = Codec<Unit>(\n    toNative: { v in\n      guard case .unit = v else { throw wrong(\"Unit\", v) }\n      return Unit()\n    }, fromNative: { _ in .unit })\n\n  public static let null = Codec<Null>(\n    toNative: { v in\n      guard case .null = v else { throw wrong(\"Null\", v) }\n      return Null()\n    }, fromNative: { _ in .null })\n\n  public static let undefined = Codec<Undefined>(\n    toNative: { v in\n      guard case .undefined = v else { throw wrong(\"Undefined\", v) }\n      return Undefined()\n    }, fromNative: { _ in .undefined })\n\n  public static let text = Codec<String>(\n    toNative: { v in\n      guard case .text(let s) = v else { throw wrong(\"Text\", v) }\n      return s\n    }, fromNative: { .text($0) })\n\n  public static let bytes = Codec<[UInt8]>(\n    toNative: { v in\n      guard case .bytes(let b) = v else { throw wrong(\"Bytes\", v) }\n      return b\n    }, fromNative: { .bytes($0) })\n\n  /// Char: a Unicode scalar value.\n  public static let char = Codec<Unicode.Scalar>(\n    toNative: { v in\n      guard let code = try integer(\"Char\", v).exactly(UInt32.self),\n        let scalar = Unicode.Scalar(code)\n      else { throw wrong(\"Char\", v) }\n      return scalar\n    }, fromNative: { .int(BigInt(Int($0.value))) })\n\n  public static let codePoint = bounded(\"CodePoint\", UInt32.self)\n  public static let codeUnit16 = bounded(\"CodeUnit16\", UInt16.self)\n\n  public static let codePointText = Codec<[UInt32]>(\n    toNative: { v in\n      guard case .raw(_, let units) = v else { throw wrong(\"CodePointText\", v) }\n      return units.map { UInt32(truncatingIfNeeded: $0) }\n    }, fromNative: { .raw(kind: \"CodePointText\", units: $0.map { Int($0) }) })\n\n  public static let utf16Text = Codec<[UInt16]>(\n    toNative: { v in\n      guard case .raw(_, let units) = v else { throw wrong(\"Utf16Text\", v) }\n      return units.map { UInt16(truncatingIfNeeded: $0) }\n    }, fromNative: { .raw(kind: \"Utf16Text\", units: $0.map { Int($0) }) })\n\n  public static let float32 = Codec<Float>(\n    toNative: { v in\n      guard case .float(32, let b) = v else { throw wrong(\"Float32\", v) }\n      return Float(bitPattern: UInt32(truncatingIfNeeded: b))\n    }, fromNative: { Scalar.floatFromSingle($0) })\n\n  public static let float64 = Codec<Double>(\n    toNative: { v in\n      guard case .float(64, let b) = v else { throw wrong(\"Float64\", v) }\n      return Double(bitPattern: b)\n    }, fromNative: { Scalar.floatFromDouble($0) })\n\n  public static let complex64 = Codec<Complex64>(\n    toNative: { v in\n      guard case .complex(_, let r, let i) = v else { throw wrong(\"Complex64\", v) }\n      return Complex64(real: try float32.toNative(r), imaginary: try float32.toNative(i))\n    },\n    fromNative: {\n      .complex(\n        width: 32, real: Scalar.floatFromSingle($0.real),\n        imaginary: Scalar.floatFromSingle($0.imaginary))\n    })\n\n  public static let complex128 = Codec<Complex128>(\n    toNative: { v in\n      guard case .complex(_, let r, let i) = v else { throw wrong(\"Complex128\", v) }\n      return Complex128(real: try float64.toNative(r), imaginary: try float64.toNative(i))\n    },\n    fromNative: {\n      .complex(\n        width: 64, real: Scalar.floatFromDouble($0.real),\n        imaginary: Scalar.floatFromDouble($0.imaginary))\n    })\n\n  public static let rational = Codec<Rational>(\n    toNative: { v in\n      guard case .ratio(let n, let d) = v else { throw wrong(\"Rational\", v) }\n      return Rational(n, d)\n    }, fromNative: { try Scalar.ratio($0.numerator, $0.denominator) })\n\n  public static let decimal = Codec<ExactDecimal>(\n    toNative: { v in\n      guard case .decimal(let c, let e) = v else { throw wrong(\"Decimal\", v) }\n      return ExactDecimal(coefficient: c, exponent: e)\n    }, fromNative: { .decimal($0.coefficient, $0.exponent) })\n\n  public static let symbol = Codec<Symbol>(\n    toNative: { v in\n      guard case .symbol(let id, let d) = v else { throw wrong(\"Symbol\", v) }\n      return Symbol(identity: id, description: d)\n    }, fromNative: { .symbol($0.identity, $0.symbolDescription) })\n\n  public static func list<T>(_ item: Codec<T>) -> Codec<PersistentList<T>> {\n    Codec<PersistentList<T>>(\n      toNative: { v in\n        guard case .list(let items) = v else { throw wrong(\"List\", v) }\n        return PersistentList(try items.map(item.toNative))\n      }, fromNative: { .list(try $0.map(item.fromNative)) })\n  }\n\n  public static func maybe<T>(_ item: Codec<T>) -> Codec<T?> {\n    Codec<T?>(\n      toNative: { v in\n        switch v {\n        case .data(\"Maybe::Absent\", _): return nil\n        case .data(\"Maybe::Present\", let f) where f.count == 1: return try item.toNative(f[0])\n        default: throw wrong(\"Maybe\", v)\n        }\n      },\n      fromNative: { native in\n        guard let x = native else { return .data(\"Maybe::Absent\", []) }\n        return .data(\"Maybe::Present\", [try item.fromNative(x)])\n      })\n  }\n\n  public static func either<L, R>(_ left: Codec<L>, _ right: Codec<R>) -> Codec<Either<L, R>> {\n    Codec<Either<L, R>>(\n      toNative: { v in\n        switch v {\n        case .data(\"Either::Left\", let f) where f.count == 1: return .left(try left.toNative(f[0]))\n        case .data(\"Either::Right\", let f) where f.count == 1:\n          return .right(try right.toNative(f[0]))\n        default: throw wrong(\"Either\", v)\n        }\n      },\n      fromNative: { native in\n        switch native {\n        case .left(let x): return .data(\"Either::Left\", [try left.fromNative(x)])\n        case .right(let x): return .data(\"Either::Right\", [try right.fromNative(x)])\n        }\n      })\n  }\n\n  public static func nullable<T>(_ item: Codec<T>) -> Codec<Nullable<T>> {\n    Codec<Nullable<T>>(\n      toNative: { v in\n        switch v {\n        case .presence(_, nil): return .null\n        case .presence(_, let x?): return .present(try item.toNative(x))\n        default: throw wrong(\"Nullable\", v)\n        }\n      },\n      fromNative: { native in\n        switch native {\n        case .null: return .presence(kind: \"Nullable\", value: nil)\n        case .present(let x): return .presence(kind: \"Nullable\", value: try item.fromNative(x))\n        }\n      })\n  }\n\n  /// LawSpec's Optional as Undefinable.\n  public static func optional<T>(_ item: Codec<T>) -> Codec<Undefinable<T>> {\n    Codec<Undefinable<T>>(\n      toNative: { v in\n        switch v {\n        case .presence(_, nil): return .undefined\n        case .presence(_, let x?): return .present(try item.toNative(x))\n        default: throw wrong(\"Optional\", v)\n        }\n      },\n      fromNative: { native in\n        switch native {\n        case .undefined: return .presence(kind: \"Optional\", value: nil)\n        case .present(let x): return .presence(kind: \"Optional\", value: try item.fromNative(x))\n        }\n      })\n  }\n\n  /// A handle's object crosses unchanged.\n  public static func handle<T>(_ name: String, _ type: T.Type) -> Codec<T> {\n    Codec<T>(\n      toNative: { v in\n        guard case .handle(_, let identity) = v, let native = identity.object as? T else {\n          throw wrong(name, v)\n        }\n        return native\n      }, fromNative: { native in .handle(name, HandleIdentity(native as AnyObject)) })\n  }\n\n  /// A handle no type is bound to, as AnyHandle.\n  public static func anyHandle(_ name: String) -> Codec<AnyHandle> {\n    Codec<AnyHandle>(\n      toNative: { v in\n        guard case .handle(_, let identity) = v else { throw wrong(name, v) }\n        return AnyHandle(identity.object)\n      }, fromNative: { .handle(name, HandleIdentity($0.object)) })\n  }\n\n  /// The value itself, for a type with no native form.\n  public static let portable = Codec<Value>(toNative: { $0 }, fromNative: { $0 })\n\n  /// A Set as a SortedSet: canonical (sorted, distinct) in the portable order.\n  public static func set<T: Portable>(_ item: Codec<T>) -> Codec<SortedSet<T>> {\n    Codec<SortedSet<T>>(\n      toNative: { v in\n        guard case .data(_, let f) = v, f.count == 1, case .list(let items) = f[0] else {\n          throw wrong(\"Set\", v)\n        }\n        return SortedSet(try items.map(item.toNative))\n      },\n      fromNative: { native in\n        .data(\n          \"lawspec.collections::type::Set::SetItems\", [.list(try native.items.map(item.fromNative))]\n        )\n      })\n  }\n\n  /// A KeyVal as a SortedMap, its entries in the portable order of their keys.\n  public static func keyVal<K: Portable, V>(_ key: Codec<K>, _ value: Codec<V>) -> Codec<\n    SortedMap<K, V>\n  > {\n    Codec<SortedMap<K, V>>(\n      toNative: { v in\n        guard case .data(_, let f) = v, f.count == 1, case .list(let entries) = f[0] else {\n          throw wrong(\"KeyVal\", v)\n        }\n        return SortedMap(\n          try entries.map { entry -> (K, V) in\n            guard case .data(_, let pair) = entry, pair.count == 2 else {\n              throw wrong(\"Entry\", entry)\n            }\n            return (try key.toNative(pair[0]), try value.toNative(pair[1]))\n          })\n      },\n      fromNative: { native in\n        let entries = try native.entries.map { entry -> Value in\n          .data(\n            \"lawspec.collections::type::Entry::Entry\",\n            [try key.fromNative(entry.key), try value.fromNative(entry.value)])\n        }\n        return .data(\"lawspec.collections::type::KeyVal::KeyValEntries\", [.list(entries)])\n      })\n  }\n\n  /// A Duration as Swift's Duration of whole microseconds.\n  public static let duration = Codec<Duration>(\n    toNative: { v in\n      guard case .data(_, let f) = v, f.count == 1, case .int(let micros) = f[0],\n        let n = micros.exactly(Int64.self)\n      else {\n        throw wrong(\"Duration\", v)\n      }\n      return .microseconds(n)\n    },\n    fromNative: { span in\n      let (seconds, attoseconds) = span.components\n      if attoseconds % 1_000_000_000_000 != 0 {\n        throw Fail.with(\"InvalidNativeValue\", \"a Duration is a whole number of microseconds\")\n      }\n      let micros = BigInt(seconds) * BigInt(1_000_000) + BigInt(attoseconds / 1_000_000_000_000)\n      return .data(\"lawspec.time::type::Duration::Duration\", [.int(micros)])\n    })\n}\n"
swiftSource "LawSpecRuntime/Crypto.swift" = "// lawspec.crypto's default handlers in Swift, over portable values: SHA3-256\n// and SHAKE256, ML-KEM-768 key exchange, ML-DSA-65 signatures (and SLH-DSA\n// for programs that choose it), and AES-256-GCM. The primitives come from\n// CryptoPrimitives: CryptoKit where it has the operation, the runtime's own\n// code where it does not. ref:DEC-swift-runtime-from-scratch\n\npublic enum Crypto {\n  private static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  private static func tag(_ name: String) -> String {\n    \"lawspec.crypto::type::\" + name + \"::\" + name\n  }\n  private static func wrap(_ name: String, _ bytes: [UInt8]) -> Value {\n    .data(tag(name), [.bytes(bytes)])\n  }\n  private static func pair(_ name: String, _ first: Value, _ second: Value) -> Value {\n    .data(tag(name), [first, second])\n  }\n\n  private static func unwrap(_ name: String, _ value: Value) throws -> [UInt8] {\n    guard case .data(let t, let fields) = value, t == tag(name), fields.count == 1,\n      case .bytes(let b) = fields[0]\n    else {\n      throw fail(\"InvalidCryptoValue\", name)\n    }\n    return b\n  }\n\n  private static func bytes(_ value: Value) throws -> [UInt8] {\n    guard case .bytes(let b) = value else { throw fail(\"BytesRequired\") }\n    return b\n  }\n\n  /// A primitive's failure as LawSpec's.\n  private static func checked<T>(_ body: () throws(CryptoFailure) -> T) throws -> T {\n    do {\n      return try body()\n    } catch {\n      throw fail(error.code, error.detail)\n    }\n  }\n\n  private static func signatureHandler(\n    _ make: @escaping @Sendable () -> ([UInt8], [UInt8]),\n    _ sign: @escaping @Sendable ([UInt8], [UInt8]) throws(CryptoFailure) -> [UInt8],\n    _ verify: @escaping @Sendable ([UInt8], [UInt8], [UInt8]) -> Bool\n  ) -> Effects.Handler {\n    Effects.stateless([\n      (\n        \"signingKeyPair\",\n        { _, _ in\n          let (publicKey, secret) = make()\n          return pair(\"SigningKeyPair\", wrap(\"VerifyingKey\", publicKey), wrap(\"SigningKey\", secret))\n        }\n      ),\n      (\n        \"sign\",\n        { _, args in\n          guard args.count == 2 else { throw fail(\"InvalidArguments\", \"sign\") }\n          let secret = try unwrap(\"SigningKey\", args[0])\n          let message = try bytes(args[1])\n          return wrap(\n            \"SignatureBytes\",\n            try checked { () throws(CryptoFailure) -> [UInt8] in try sign(secret, message) })\n        }\n      ),\n      (\n        \"verify\",\n        { _, args in\n          guard args.count == 3 else { throw fail(\"InvalidArguments\", \"verify\") }\n          return .bool(\n            verify(\n              try unwrap(\"VerifyingKey\", args[0]), try bytes(args[1]),\n              try unwrap(\"SignatureBytes\", args[2])))\n        }\n      ),\n    ])\n  }\n\n  /// The SLH-DSA-SHAKE-128f handler of Signature: stateless hash-based\n  /// signatures, for programs that choose them over ML-DSA.\n  public static func slhDsaSignatureHandler() -> Effects.Handler {\n    signatureHandler(\n      { CryptoPrimitives.slhKeyPair() },\n      { secret, message throws(CryptoFailure) in\n        try CryptoPrimitives.slhSign(secret, message)\n      }, { CryptoPrimitives.slhVerify($0, $1, $2) })\n  }\n\n  /// The default handler of a lawspec.crypto ability.\n  public static func handler(_ key: String) throws -> Effects.Handler {\n    switch key {\n    case \"lawspec.crypto::ability::Hash\":\n      return Effects.stateless([\n        (\"sha3\", { _, args in wrap(\"Digest\", CryptoPrimitives.sha3(try bytes(args[0]))) }),\n        (\n          \"shake\",\n          { _, args in\n            guard args.count == 2, case .int(let count) = args[1] else {\n              throw fail(\"InvalidArguments\", \"shake\")\n            }\n            let n = count > BigInt(Int(Int32.max)) ? Int(Int32.max) : (count.exactly(Int.self) ?? 0)\n            return .bytes(CryptoPrimitives.shake(try bytes(args[0]), Swift.max(0, n)))\n          }\n        ),\n      ])\n    case \"lawspec.crypto::ability::KeyExchange\":\n      return Effects.stateless([\n        (\n          \"exchangeKeyPair\",\n          { _, _ in\n            let (publicKey, secret) = CryptoPrimitives.mlkemKeyPair(\n              CryptoPrimitives.randomBytes(64))\n            return pair(\n              \"ExchangeKeyPair\", wrap(\"ExchangePublicKey\", publicKey),\n              wrap(\"ExchangeSecretKey\", secret))\n          }\n        ),\n        (\n          \"encapsulate\",\n          { _, args in\n            let publicKey = try unwrap(\"ExchangePublicKey\", args[0])\n            let (ciphertext, shared) = try checked { () throws(CryptoFailure) in\n              try CryptoPrimitives.mlkemEncapsulate(publicKey)\n            }\n            return pair(\n              \"Encapsulated\", wrap(\"Ciphertext\", ciphertext), wrap(\"SharedSecret\", shared))\n          }\n        ),\n        (\n          \"decapsulate\",\n          { _, args in\n            guard args.count == 2 else { throw fail(\"InvalidArguments\", \"decapsulate\") }\n            let secret = try unwrap(\"ExchangeSecretKey\", args[0])\n            let ciphertext = try unwrap(\"Ciphertext\", args[1])\n            return wrap(\n              \"SharedSecret\",\n              try checked { () throws(CryptoFailure) in\n                try CryptoPrimitives.mlkemDecapsulate(secret, ciphertext)\n              })\n          }\n        ),\n      ])\n    case \"lawspec.crypto::ability::Signature\":\n      return signatureHandler(\n        {\n          let seed = CryptoPrimitives.randomBytes(32)\n          return (CryptoPrimitives.mldsaPublic(seed), seed)\n        },\n        { secret, message throws(CryptoFailure) in\n          try CryptoPrimitives.mldsaSign(secret, message)\n        }, { CryptoPrimitives.mldsaVerify($0, $1, $2) })\n    case \"lawspec.crypto::ability::Aead\":\n      return Effects.stateless([\n        (\"aeadKey\", { _, _ in wrap(\"AeadKey\", CryptoPrimitives.randomBytes(32)) }),\n        (\n          \"deriveAeadKey\",\n          { _, args in\n            guard args.count == 2 else { throw fail(\"InvalidArguments\", \"deriveAeadKey\") }\n            return wrap(\n              \"AeadKey\",\n              CryptoPrimitives.deriveAeadKey(\n                try unwrap(\"SharedSecret\", args[0]), try bytes(args[1])))\n          }\n        ),\n        (\n          \"seal\",\n          { _, args in\n            guard args.count == 3 else { throw fail(\"InvalidArguments\", \"seal\") }\n            let key = try unwrap(\"AeadKey\", args[0])\n            let message = try bytes(args[1])\n            let associated = try bytes(args[2])\n            return wrap(\n              \"Sealed\",\n              try checked { () throws(CryptoFailure) in\n                try CryptoPrimitives.seal(key, message, associated)\n              })\n          }\n        ),\n        (\n          \"unseal\",\n          { _, args in\n            guard args.count == 3 else { throw fail(\"InvalidArguments\", \"unseal\") }\n            guard\n              let message = CryptoPrimitives.unseal(\n                try unwrap(\"AeadKey\", args[0]), try unwrap(\"Sealed\", args[1]), try bytes(args[2]))\n            else {\n              return .data(\"Maybe::Absent\", [])\n            }\n            return .data(\"Maybe::Present\", [.bytes(message)])\n          }\n        ),\n      ])\n    default:\n      throw fail(\"UnknownDefaultHandler\", key)\n    }\n  }\n\n  /// Make Defaults.handler answer the lawspec.crypto abilities. The generated\n  /// schema of a program that uses lawspec.crypto calls this once.\n  public static func install() {\n    Defaults.cryptoHandler.with { $0 = { key in try handler(key) } }\n  }\n}\n"
swiftSource "LawSpecRuntime/CryptoPrimitives.swift" = "// LawSpec's post-quantum crypto defaults on Swift: SHA3-256 and SHAKE256\n// (FIPS 202), ML-KEM-768 (FIPS 203), ML-DSA-65 (FIPS 204), SLH-DSA-SHAKE-128f\n// (FIPS 205) and AES-256-GCM (SP 800-38D). Keys are stored as their FIPS\n// key-generation seeds, as on every target, so the portable values are the\n// same. CryptoKit is used wherever it has the operation; the pure-Swift\n// fallbacks (Keccak, MLKEM768Fallback, MLDSA65Fallback, SLHDSAShake128f)\n// cover only what it lacks. ref:DEC-typed-core-boundary\n\nimport CryptoKit\nimport Foundation\n\n/// A crypto operation's failure: a code, as on every target, and a detail.\npublic struct CryptoFailure: Error, Sendable, CustomStringConvertible {\n  public let code: String\n  public let detail: String\n\n  public init(code: String, detail: String = \"\") {\n    self.code = code\n    self.detail = detail\n  }\n\n  public var description: String { detail.isEmpty ? code : code + \" \" + detail }\n}\n\n/// The byte-level crypto primitives behind lawspec.crypto and the secure\n/// network transport.\npublic enum CryptoPrimitives {\n  private static func fail(_ code: String, _ detail: String = \"\") -> CryptoFailure {\n    CryptoFailure(code: code, detail: detail)\n  }\n\n  /// Fresh random bytes from the operating system.\n  public static func randomBytes(_ count: Int) -> [UInt8] {\n    var generator = SystemRandomNumberGenerator()\n    return (0..<max(0, count)).map { _ in UInt8.random(in: 0...255, using: &generator) }\n  }\n\n  // MARK: FIPS 202\n\n  /// SHA3-256 of a message.\n  public static func sha3(_ message: [UInt8]) -> [UInt8] {\n    Array(SHA3_256.hash(data: message))\n  }\n\n  /// SHAKE256 of a message, a number of bytes long (none when it is not\n  /// positive). CryptoKit has no SHAKE, so this uses the Keccak fallback.\n  public static func shake(_ message: [UInt8], _ count: Int) -> [UInt8] {\n    count <= 0 ? [] : Keccak.shake256(message, count)\n  }\n\n  /// An AES-256-GCM key for a shared secret and a context.\n  public static func deriveAeadKey(_ secret: [UInt8], _ context: [UInt8]) -> [UInt8] {\n    shake(secret + context, 32)\n  }\n\n  // MARK: FIPS 203: ML-KEM-768, keys held as their 64-byte seed d || z\n\n  /// The encapsulation key and the expanded decapsulation key of a seed. The\n  /// public key is CryptoKit's; the expanded key, which CryptoKit never\n  /// exposes, is the fallback's.\n  public static func mlkemExpand(_ seed: [UInt8]) -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    precondition(seed.count == 64, \"InvalidMlKemSeed\")\n    let expanded = MLKEM768Fallback.keyGen(seed)\n    if let key = try? MLKEM768.PrivateKey(seedRepresentation: seed, publicKey: nil) {\n      return (Array(key.publicKey.rawRepresentation), expanded.privateKey)\n    }\n    return expanded\n  }\n\n  /// A key pair from a seed: the public key, and the seed it is kept as.\n  public static func mlkemKeyPair(_ seed: [UInt8]) -> (publicKey: [UInt8], seed: [UInt8]) {\n    (mlkemExpand(seed).publicKey, seed)\n  }\n\n  /// Encapsulate a fresh shared secret: the ciphertext and the secret.\n  public static func mlkemEncapsulate(_ publicKey: [UInt8]) throws(CryptoFailure) -> (\n    ciphertext: [UInt8], shared: [UInt8]\n  ) {\n    guard publicKey.count == MLKEM768Fallback.publicKeyLength,\n      let key = try? MLKEM768.PublicKey(rawRepresentation: publicKey),\n      let result = try? key.encapsulate()\n    else { throw fail(\"InvalidMlKemPublicKey\") }\n    let shared = result.sharedSecret.withUnsafeBytes { Array($0) }\n    return (Array(result.encapsulated), shared)\n  }\n\n  /// FIPS 203's deterministic encapsulation with a given 32-byte message,\n  /// for known-answer tests only. CryptoKit always draws the message at\n  /// random, so this uses the fallback.\n  public static func mlkemEncapsulateWith(_ publicKey: [UInt8], _ message: [UInt8])\n    throws(CryptoFailure) -> (ciphertext: [UInt8], shared: [UInt8])\n  {\n    guard message.count == 32 else { throw fail(\"InvalidMlKemMessage\") }\n    guard MLKEM768Fallback.validPublicKey(publicKey) else { throw fail(\"InvalidMlKemPublicKey\") }\n    return MLKEM768Fallback.encapsulate(publicKey, message)\n  }\n\n  /// Decapsulate with an expanded decapsulation key. CryptoKit cannot\n  /// import one, so this uses the fallback.\n  public static func mlkemDecapsulateExpanded(_ privateKey: [UInt8], _ ciphertext: [UInt8])\n    throws(CryptoFailure) -> [UInt8]\n  {\n    guard privateKey.count == MLKEM768Fallback.privateKeyLength else {\n      throw fail(\"InvalidMlKemPrivateKey\")\n    }\n    guard ciphertext.count == MLKEM768Fallback.ciphertextLength else {\n      throw fail(\"InvalidMlKemCiphertext\")\n    }\n    return MLKEM768Fallback.decapsulate(privateKey, ciphertext)\n  }\n\n  /// Decapsulate with a key kept as its seed.\n  public static func mlkemDecapsulate(_ seed: [UInt8], _ ciphertext: [UInt8]) throws(CryptoFailure)\n    -> [UInt8]\n  {\n    guard seed.count == 64 else { throw fail(\"InvalidMlKemSeed\") }\n    guard ciphertext.count == MLKEM768Fallback.ciphertextLength else {\n      throw fail(\"InvalidMlKemCiphertext\")\n    }\n    guard let key = try? MLKEM768.PrivateKey(seedRepresentation: seed, publicKey: nil),\n      let shared = try? key.decapsulate(ciphertext)\n    else { throw fail(\"InvalidMlKemCiphertext\") }\n    return shared.withUnsafeBytes { Array($0) }\n  }\n\n  // MARK: FIPS 204: ML-DSA-65, signing keys held as their 32-byte seed\n\n  /// The public key and the expanded private key of a seed. The public key\n  /// is CryptoKit's; the expanded key, which CryptoKit never exposes, is the\n  /// fallback's.\n  public static func mldsaExpand(_ seed: [UInt8]) -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    precondition(seed.count == 32, \"InvalidMlDsaSeed\")\n    let expanded = MLDSA65Fallback.keyGen(seed)\n    return (mldsaPublic(seed), expanded.privateKey)\n  }\n\n  /// The public key of a seed.\n  public static func mldsaPublic(_ seed: [UInt8]) -> [UInt8] {\n    precondition(seed.count == 32, \"InvalidMlDsaSeed\")\n    if let key = try? MLDSA65.PrivateKey(seedRepresentation: seed, publicKey: nil) {\n      return Array(key.publicKey.rawRepresentation)\n    }\n    return MLDSA65Fallback.keyGen(seed).publicKey\n  }\n\n  /// Sign with a context string; deterministic for known-answer tests (the\n  /// fallback, since CryptoKit always hedges), hedged otherwise (CryptoKit).\n  public static func mldsaSignWith(\n    _ seed: [UInt8], _ message: [UInt8], _ context: [UInt8], deterministic: Bool\n  ) throws(CryptoFailure) -> [UInt8] {\n    guard seed.count == 32, context.count <= 255 else { throw fail(\"InvalidMlDsaSignature\") }\n    if deterministic {\n      return MLDSA65Fallback.sign(\n        seed, message, context, randomness: [UInt8](repeating: 0, count: 32))\n    }\n    guard let key = try? MLDSA65.PrivateKey(seedRepresentation: seed, publicKey: nil),\n      let signature = try? key.signature(for: message, context: context)\n    else { throw fail(\"InvalidMlDsaSignature\") }\n    return Array(signature)\n  }\n\n  /// Sign a message (hedged, with no context).\n  public static func mldsaSign(_ seed: [UInt8], _ message: [UInt8]) throws(CryptoFailure) -> [UInt8]\n  {\n    try mldsaSignWith(seed, message, [], deterministic: false)\n  }\n\n  /// Verify a signature with a context string; a malformed key or signature\n  /// does not verify.\n  public static func mldsaVerifyWith(\n    _ publicKey: [UInt8], _ message: [UInt8], _ signature: [UInt8], _ context: [UInt8]\n  ) -> Bool {\n    guard publicKey.count == MLDSA65Fallback.publicKeyLength,\n      signature.count == MLDSA65Fallback.signatureLength,\n      context.count <= 255, let key = try? MLDSA65.PublicKey(rawRepresentation: publicKey)\n    else { return false }\n    return key.isValidSignature(signature, for: message, context: context)\n  }\n\n  public static func mldsaVerify(_ publicKey: [UInt8], _ message: [UInt8], _ signature: [UInt8])\n    -> Bool\n  {\n    mldsaVerifyWith(publicKey, message, signature, [])\n  }\n\n  // MARK: FIPS 205: SLH-DSA-SHAKE-128f, private keys of 64 bytes (fallback: CryptoKit has none)\n\n  /// A fresh key pair: the public key and the private key.\n  public static func slhKeyPair() -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    SLHDSAShake128f.keyGen(randomBytes(48))\n  }\n\n  /// The key pair of the 48 bytes SK.seed || SK.prf || PK.seed (known-answer\n  /// tests only).\n  public static func slhKeyPairOf(_ seed: [UInt8]) -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    precondition(seed.count == 48, \"InvalidSlhDsaSeed\")\n    return SLHDSAShake128f.keyGen(seed)\n  }\n\n  /// Sign with a context string, hedged with fresh randomness.\n  public static func slhSignWith(_ privateKey: [UInt8], _ message: [UInt8], _ context: [UInt8])\n    throws(CryptoFailure) -> [UInt8]\n  {\n    guard privateKey.count == SLHDSAShake128f.privateKeyLength, context.count <= 255 else {\n      throw fail(\"InvalidSlhDsaSignature\")\n    }\n    return SLHDSAShake128f.sign(\n      privateKey, message, context, additionalRandomness: randomBytes(SLHDSAShake128f.n))\n  }\n\n  public static func slhSign(_ privateKey: [UInt8], _ message: [UInt8]) throws(CryptoFailure)\n    -> [UInt8]\n  {\n    try slhSignWith(privateKey, message, [])\n  }\n\n  /// Verify with a context string; a malformed key or signature does not verify.\n  public static func slhVerifyWith(\n    _ publicKey: [UInt8], _ message: [UInt8], _ signature: [UInt8], _ context: [UInt8]\n  ) -> Bool {\n    SLHDSAShake128f.verify(publicKey, message, signature, context)\n  }\n\n  public static func slhVerify(_ publicKey: [UInt8], _ message: [UInt8], _ signature: [UInt8])\n    -> Bool\n  {\n    slhVerifyWith(publicKey, message, signature, [])\n  }\n\n  // MARK: SP 800-38D: AES-256-GCM with a 96-bit nonce and a 128-bit tag\n\n  /// The ciphertext followed by its tag.\n  public static func aes256GcmEncrypt(\n    _ key: [UInt8], _ nonce: [UInt8], _ message: [UInt8], _ associated: [UInt8]\n  ) throws(CryptoFailure) -> [UInt8] {\n    guard key.count == 32, nonce.count == 12, let gcmNonce = try? AES.GCM.Nonce(data: nonce),\n      let sealed = try? AES.GCM.seal(\n        message, using: SymmetricKey(data: key), nonce: gcmNonce, authenticating: associated)\n    else { throw fail(\"InvalidAeadKey\") }\n    return Array(sealed.ciphertext) + Array(sealed.tag)\n  }\n\n  /// The plaintext, or nil when the tag does not verify.\n  public static func aes256GcmDecrypt(\n    _ key: [UInt8], _ nonce: [UInt8], _ sealed: [UInt8], _ associated: [UInt8]\n  ) -> [UInt8]? {\n    guard key.count == 32, nonce.count == 12, sealed.count >= 16,\n      let gcmNonce = try? AES.GCM.Nonce(data: nonce)\n    else { return nil }\n    let size = sealed.count - 16\n    guard\n      let box = try? AES.GCM.SealedBox(\n        nonce: gcmNonce, ciphertext: sealed[0..<size], tag: sealed[size...]),\n      let plaintext = try? AES.GCM.open(\n        box, using: SymmetricKey(data: key), authenticating: associated)\n    else { return nil }\n    return Array(plaintext)\n  }\n\n  /// A fresh nonce, then the sealed message.\n  public static func seal(_ key: [UInt8], _ message: [UInt8], _ associated: [UInt8])\n    throws(CryptoFailure) -> [UInt8]\n  {\n    let nonce = randomBytes(12)\n    return nonce + (try aes256GcmEncrypt(key, nonce, message, associated))\n  }\n\n  /// Open what seal made, or nil.\n  public static func unseal(_ key: [UInt8], _ sealed: [UInt8], _ associated: [UInt8]) -> [UInt8]? {\n    guard sealed.count >= 12 else { return nil }\n    return aes256GcmDecrypt(key, Array(sealed[0..<12]), Array(sealed[12...]), associated)\n  }\n}\n"
swiftSource "LawSpecRuntime/Defaults.swift" = "// The default handlers of the built-in abilities in Swift: the real clock,\n// the run's seeded random sequence and the system's secure random source,\n// files, environment variables and ports, logging, and pausing. Values are\n// portable; the generated protocols convert them where native code meets\n// them. ref:DEC-typed-core-boundary ref:DEC-swift-runtime-from-scratch\n\nimport Foundation\n\npublic enum Defaults {\n  private static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  private static func just(_ v: Value) -> Value { .data(\"Maybe::Present\", [v]) }\n  private static let nothing = Value.data(\"Maybe::Absent\", [])\n\n  // The wall clock at start, then the monotonic clock: a later clock\n  // correction never moves time backwards.\n  private static let origin = Int64(Date().timeIntervalSince1970 * 1000) * 1000\n  private static let started = ContinuousClock.now\n\n  /// Microseconds since the Unix epoch, never decreasing.\n  public static func nowMicros() -> Int64 {\n    let elapsed = ContinuousClock.now - started\n    let (seconds, attoseconds) = elapsed.components\n    return origin + seconds * 1_000_000 + attoseconds / 1_000_000_000_000\n  }\n\n  /// Sleep at least a number of microseconds.\n  public static func sleepMicros(_ micros: Int64) {\n    let deadline = ContinuousClock.now + .microseconds(micros)\n    while ContinuousClock.now < deadline {\n      let left = deadline - ContinuousClock.now\n      let (seconds, attoseconds) = left.components\n      Thread.sleep(forTimeInterval: Swift.max(0.001, Double(seconds) + Double(attoseconds) / 1e18))\n    }\n  }\n\n  private static func integer(_ v: Value) throws -> BigInt {\n    guard case .int(let n) = v else { throw fail(\"IntegerRequired\", \"\\(v)\") }\n    return n\n  }\n\n  private static func text(_ v: Value) throws -> String {\n    guard case .text(let s) = v else { throw fail(\"TextRequired\", \"\\(v)\") }\n    return s\n  }\n\n  private static let mask = (BigInt.one << 64) - .one\n\n  private static func randomStep(_ s: BigInt) -> BigInt {\n    (BigInt(6_364_136_223_846_793_005) * s + BigInt(1_442_695_040_888_963_407)) & mask\n  }\n\n  private static func secureBelow(_ bound: Int64) -> Int64 {\n    if bound < 1 { return 0 }\n    var generator = SystemRandomNumberGenerator()\n    return Int64.random(in: 0..<bound, using: &generator)\n  }\n\n  private static func secureBytes(_ count: Int) -> [UInt8] {\n    var generator = SystemRandomNumberGenerator()\n    return (0..<Swift.max(0, count)).map { _ in UInt8.random(in: 0...255, using: &generator) }\n  }\n\n  private static func hex(_ bytes: [UInt8]) -> String {\n    bytes.map { String(format: \"%02x\", $0) }.joined()\n  }\n\n  private static func temporaryRoot() throws -> String {\n    let environment = ProcessInfo.processInfo.environment\n    let candidates =\n      [\"TMPDIR\", \"TMP\", \"TEMP\"].compactMap { environment[$0] }.filter { !$0.isEmpty } + [\n        NSTemporaryDirectory()\n      ]\n    var isDirectory: ObjCBool = false\n    for root in candidates\n    where FileManager.default.fileExists(atPath: root, isDirectory: &isDirectory)\n      && isDirectory.boolValue\n    {\n      return URL(fileURLWithPath: root).standardizedFileURL.path\n    }\n    throw fail(\"NoTemporaryDirectory\")\n  }\n\n  private static func temporary(_ directory: Bool, _ prefix: String) throws -> String {\n    if prefix.contains(\"\\0\") || prefix.contains(\"/\") || prefix.contains(\"\\\\\") {\n      throw fail(\"InvalidTemporaryPrefix\", prefix)\n    }\n    let manager = FileManager.default\n    for _ in 0..<100 {\n      let path = URL(fileURLWithPath: try temporaryRoot()).appendingPathComponent(\n        prefix + hex(secureBytes(16))\n      ).path\n      if manager.fileExists(atPath: path) { continue }\n      if directory {\n        try? manager.createDirectory(\n          atPath: path, withIntermediateDirectories: false, attributes: [.posixPermissions: 0o700])\n      } else {\n        _ = manager.createFile(atPath: path, contents: nil, attributes: [.posixPermissions: 0o600])\n      }\n      return path\n    }\n    throw fail(\"TemporaryNameExhausted\", prefix)\n  }\n\n  private static func validName(_ name: String) -> Bool {\n    !name.isEmpty && !name.contains(\"\\0\") && !name.contains(\"=\")\n  }\n\n  private static func restoreEnvironment(_ saved: String) throws {\n    guard let data = saved.data(using: .utf8),\n      let decoded = try? JSONSerialization.jsonObject(with: data) as? [String: String],\n      decoded.allSatisfy({ validName($0.key) && !$0.value.contains(\"\\0\") })\n    else {\n      throw fail(\"InvalidEnvironmentSnapshot\")\n    }\n    for name in ProcessInfo.processInfo.environment.keys where decoded[name] == nil {\n      unsetenv(name)\n    }\n    for (name, value) in decoded { setenv(name, value, 1) }\n  }\n\n  /// A crypto ability's default handler, set by Crypto when a program uses\n  /// lawspec.crypto.\n  public static let cryptoHandler = Locked<@Sendable (String) throws -> Effects.Handler>({ key in\n    throw Fail.with(\"UnknownDefaultHandler\", key)\n  })\n\n  /// The clause name that marks the default (real) Clock handler.\n  public static let realClockMarker = \"lawspec.realClock\"\n\n  /// The default handler of a built-in ability, by its key.\n  public static func handler(_ key: String) throws -> Effects.Handler {\n    if key.hasPrefix(\"lawspec.crypto::ability::\") { return try cryptoHandler.with { $0 }(key) }\n    switch key {\n    case \"lawspec.time::ability::Clock\":\n      return Effects.stateless([\n        // Marks the real clock, so a workflow knows its time is real.\n        (realClockMarker, { @Sendable _, _ in .unit }),\n        (\n          \"now\",\n          { _, _ in .data(\"lawspec.time::type::Instant::Instant\", [.int(BigInt(nowMicros()))]) }\n        ),\n        (\n          \"sleep\",\n          { _, args in\n            guard case .data(_, let f)? = args.first, case .int(let micros)? = f.first,\n              let n = micros.exactly(Int64.self)\n            else {\n              throw fail(\"InvalidDuration\")\n            }\n            sleepMicros(n)\n            return .unit\n          }\n        ),\n      ])\n    case \"lawspec.randomness::ability::Random\":\n      let text = ProcessInfo.processInfo.environment[\"LAWSPEC_SEED\"] ?? \"\"\n      let seed = BigInt(text) ?? .zero\n      let cell = Effects.Cell(.int(seed & mask))\n      return Effects.stateless([\n        (\n          \"randomBelow\",\n          { _, args in\n            let bound = try integer(args[0])\n            return try cell.update { state in\n              let first = randomStep(try integer(state))\n              let second = randomStep(first)\n              let bits = ((first >> 32) << 32) | (second >> 32)\n              let draw = bound.signum > 0 ? bits % bound : .zero\n              return (.int(draw), .int(second))\n            }\n          }\n        )\n      ])\n    case \"lawspec.randomness::ability::SecureRandom\":\n      return Effects.stateless([\n        (\n          \"secureBytes\",\n          { _, args in .bytes(secureBytes(try integer(args[0]).exactly(Int.self) ?? 0)) }\n        ),\n        (\n          \"secureBelow\",\n          { _, args in\n            .int(BigInt(secureBelow(try integer(args[0]).exactly(Int64.self) ?? Int64.max)))\n          }\n        ),\n        (\"secureToken\", { _, _ in .text(hex(secureBytes(32))) }),\n      ])\n    case \"lawspec.host::ability::FileSystem\":\n      return Effects.stateless([\n        (\n          \"readBytes\",\n          { _, args in\n            let p = try text(args[0])\n            var isDirectory: ObjCBool = false\n            guard FileManager.default.fileExists(atPath: p, isDirectory: &isDirectory),\n              !isDirectory.boolValue,\n              let data = FileManager.default.contents(atPath: p)\n            else { return nothing }\n            return just(.bytes([UInt8](data)))\n          }\n        ),\n        (\n          \"writeBytes\",\n          { _, args in\n            guard args.count == 2, case .text(let p) = args[0], case .bytes(let b) = args[1] else {\n              throw fail(\"InvalidArguments\", \"writeBytes\")\n            }\n            do { try Data(b).write(to: URL(fileURLWithPath: p)) } catch {\n              throw fail(\"WriteFailed\", \"\\(p): \\(error)\")\n            }\n            return .unit\n          }\n        ),\n        (\n          \"pathExists\",\n          { _, args in .bool(FileManager.default.fileExists(atPath: try text(args[0]))) }\n        ),\n        (\n          \"removePath\",\n          { _, args in\n            let p = try text(args[0])\n            if FileManager.default.fileExists(atPath: p) {\n              try? FileManager.default.removeItem(atPath: p)\n            }\n            return .unit\n          }\n        ),\n        (\"temporaryDirectory\", { _, args in .text(try temporary(true, try text(args[0]))) }),\n        (\"temporaryFile\", { _, args in .text(try temporary(false, try text(args[0]))) }),\n      ])\n    case \"lawspec.host::ability::Environment\":\n      return Effects.stateless([\n        (\n          \"environmentVariable\",\n          { _, args in\n            let name = try text(args[0])\n            guard validName(name), let value = getenv(name) else { return nothing }\n            return just(.text(String(cString: value)))\n          }\n        ),\n        (\n          \"environmentSnapshot\",\n          { _, _ in\n            let all = ProcessInfo.processInfo.environment\n            let keys = all.keys.sorted { Scalar.compareText($0, $1) < 0 }\n            let body = keys.map { jsonString($0) + \":\" + jsonString(all[$0]!) }.joined(\n              separator: \",\")\n            return .text(\"{\" + body + \"}\")\n          }\n        ),\n        (\n          \"restoreEnvironment\",\n          { _, args in\n            try restoreEnvironment(try text(args[0]))\n            return .unit\n          }\n        ),\n      ])\n    case \"lawspec.host::ability::Ports\":\n      return Effects.stateless([(\"freePort\", { _, _ in .int(BigInt(try freePort())) })])\n    case \"lawspec.logging::ability::Log\":\n      return Effects.stateless([\n        (\n          \"logMessage\",\n          { _, args in\n            guard args.count == 2, case .data(let level, _) = args[0],\n              case .text(let message) = args[1]\n            else {\n              throw fail(\"InvalidArguments\", \"logMessage\")\n            }\n            let name = Recorded.lastPart(level)\n            let line = \"[\\(name.lowercased())] \\(message)\"\n            if name == \"Warning\" || name == \"Error\" {\n              FileHandle.standardError.write(Data((line + \"\\n\").utf8))\n            } else {\n              print(line)\n            }\n            return .unit\n          }\n        )\n      ])\n    case \"lawspec.logging::ability::Trace\":\n      return Effects.stateless([\n        (\n          \"traceEvent\",\n          { _, args in\n            FileHandle.standardError.write(Data((\"lawspec: \" + (try text(args[0])) + \"\\n\").utf8))\n            return .unit\n          }\n        )\n      ])\n    case \"lawspec.concurrent::ability::Async\":\n      return Effects.stateless([\n        (\n          \"pause\",\n          { _, _ in\n            sched_yield()\n            return .unit\n          }\n        )\n      ])\n    default:\n      throw fail(\"UnknownDefaultHandler\", key)\n    }\n  }\n\n  /// A free TCP port on the loopback interface.\n  public static func freePort() throws -> Int {\n    let socket = Darwin.socket(AF_INET, SOCK_STREAM, 0)\n    if socket < 0 { throw fail(\"NoFreePort\") }\n    defer { close(socket) }\n    var address = sockaddr_in()\n    address.sin_family = sa_family_t(AF_INET)\n    address.sin_addr.s_addr = inet_addr(\"127.0.0.1\")\n    address.sin_port = 0\n    var length = socklen_t(MemoryLayout<sockaddr_in>.size)\n    let bound = withUnsafePointer(to: &address) {\n      $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { bind(socket, $0, length) }\n    }\n    if bound != 0 { throw fail(\"NoFreePort\") }\n    let named = withUnsafeMutablePointer(to: &address) {\n      $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { getsockname(socket, $0, &length) }\n    }\n    if named != 0 { throw fail(\"NoFreePort\") }\n    return Int(UInt16(bigEndian: address.sin_port))\n  }\n\n  /// A JSON string literal.\n  public static func jsonString(_ s: String) -> String {\n    var out = \"\\\"\"\n    for scalar in s.unicodeScalars {\n      switch scalar {\n      case \"\\\"\": out += \"\\\\\\\"\"\n      case \"\\\\\": out += \"\\\\\\\\\"\n      case \"\\n\": out += \"\\\\n\"\n      case \"\\r\": out += \"\\\\r\"\n      case \"\\t\": out += \"\\\\t\"\n      default:\n        if scalar.value < 0x20 {\n          out += String(format: \"\\\\u%04x\", scalar.value)\n        } else {\n          out.unicodeScalars.append(scalar)\n        }\n      }\n    }\n    return out + \"\\\"\"\n  }\n}\n"
swiftSource "LawSpecRuntime/Descriptors.swift" = "// Type descriptors and the portable generator over them: models, scenarios\n// and channels draw, shrink, render and encode their values exactly as every\n// other runtime does, so one seed replays one run on every target, and the\n// wire bytes are the same. ref:DEC-portable-seeded-generation\n// ref:DEC-distribution-canonical-wire ref:DEC-shrink-within-domain\n\nimport Foundation\n\npublic enum Descriptors {\n  /// A descriptor form: an atom, an integer, a quoted string, the hole `_`, or\n  /// a parenthesized list of forms.\n  public indirect enum Descriptor: Sendable, Equatable {\n    case atom(String)\n    case number(BigInt)\n    case quoted(String)\n    case hole\n    case forms([Descriptor])\n  }\n\n  public typealias Table = [String: Descriptor]\n\n  private static func fail(_ code: String) -> LawSpecError { Fail.with(code) }\n\n  private static func require(_ condition: Bool, _ code: String) throws {\n    if !condition { throw fail(code) }\n  }\n\n  /// Read every form of a descriptor text.\n  public static func read(_ text: String) throws -> [Descriptor] {\n    let points = Scalar.codePoints(text)\n    var i = 0\n    func isSpace(_ c: Int) -> Bool { c == 32 || c == 10 || c == 13 || c == 9 }\n    func skip() { while i < points.count && isSpace(points[i]) { i += 1 } }\n    func forms() throws -> [Descriptor] {\n      var acc = [Descriptor]()\n      skip()\n      while i < points.count && points[i] != 41 {\n        acc.append(try item())\n        skip()\n      }\n      return acc\n    }\n    func item() throws -> Descriptor {\n      if points[i] == 40 {\n        i += 1\n        let children = try forms()\n        try require(i < points.count && points[i] == 41, \"UnclosedDescriptor\")\n        i += 1\n        return .forms(children)\n      }\n      if points[i] == 34 {\n        i += 1\n        var chars = [Int]()\n        var closed = false\n        while !closed {\n          try require(i < points.count, \"UnclosedDescriptorString\")\n          let c = points[i]\n          if c == 92 && i + 1 < points.count {\n            chars.append(points[i + 1])\n            i += 2\n          } else if c == 34 {\n            closed = true\n            i += 1\n          } else {\n            chars.append(c)\n            i += 1\n          }\n        }\n        return .quoted(try Scalar.textOfPoints(chars))\n      }\n      let start = i\n      while i < points.count && !isSpace(points[i]) && points[i] != 40 && points[i] != 41 { i += 1 }\n      try require(i > start, \"EmptyDescriptorAtom\")\n      let word = try Scalar.textOfPoints(points[start..<i])\n      if word == \"_\" { return .hole }\n      if let n = numberOf(word) { return .number(n) }\n      return .atom(word)\n    }\n    let result = try forms()\n    try require(i == points.count, \"TrailingDescriptorInput\")\n    return result\n  }\n\n  /// An integer atom: an optional sign and decimal digits.\n  private static func numberOf(_ word: String) -> BigInt? {\n    var digits = Substring(word)\n    if digits.first == \"-\" || digits.first == \"+\" { digits = digits.dropFirst() }\n    guard !digits.isEmpty, digits.allSatisfy({ $0.isASCII && $0.isNumber }) else { return nil }\n    return BigInt(word)\n  }\n\n  private static func unquote(_ d: Descriptor) throws -> String {\n    switch d {\n    case .quoted(let s), .atom(let s): return s\n    default: throw fail(\"InvalidDescriptorName\")\n    }\n  }\n\n  /// The named data descriptors of a text, and its last form.\n  public static func fromText(_ text: String) throws -> (Table, Descriptor) {\n    let forms = try read(text)\n    guard let last = forms.last else { throw fail(\"EmptyDescriptor\") }\n    var table = Table()\n    for d in forms {\n      if case .forms(let parts) = d, parts.count >= 2, case .atom(\"data\") = parts[0] {\n        table[try unquote(parts[1])] = d\n      }\n    }\n    return (table, last)\n  }\n\n  /// A reference resolved through the table.\n  public static func resolve(_ d: Descriptor, _ table: Table) throws -> Descriptor {\n    if case .forms(let parts) = d, parts.count == 2, case .atom(\"ref\") = parts[0] {\n      guard let found = table[try unquote(parts[1])] else {\n        throw fail(\"UnknownDescriptorReference\")\n      }\n      return found\n    }\n    return d\n  }\n\n  private static func bound(_ d: Descriptor) throws -> BigInt? {\n    switch d {\n    case .number(let n): return n\n    case .hole: return nil\n    default: throw fail(\"InvalidDescriptorBound\")\n    }\n  }\n\n  public static func generationBounds(_ lo: BigInt?, _ hi: BigInt?) -> (BigInt, BigInt) {\n    let million = BigInt(1_000_000)\n    switch (lo, hi) {\n    case (nil, nil): return (-million, million)\n    case (nil, let h?): return (BigInt.min(-million, h - BigInt(2_000_000)), h)\n    case (let l?, nil): return (l, BigInt.max(million, l + BigInt(2_000_000)))\n    case (let l?, let h?): return (l, h)\n    }\n  }\n\n  private static func mentionsData(_ d: Descriptor) -> Bool {\n    guard case .forms(let parts) = d, let head = parts.first else { return false }\n    if case .atom(\"ref\") = head { return true }\n    if case .atom(\"data\") = head { return true }\n    return parts.dropFirst().contains(where: mentionsData)\n  }\n\n  private static func baseConstructors(_ cs: [Descriptor]) -> [Descriptor] {\n    let found = cs.filter { c in\n      if case .forms(let parts) = c, parts.count >= 2, case .atom(\"ctor\") = parts[0] {\n        return !parts.dropFirst(2).contains(where: mentionsData)\n      }\n      return false\n    }\n    return found.isEmpty ? cs : found\n  }\n\n  /// The parts of a form whose head is an atom.\n  private static func shape(_ d: Descriptor) -> (String, [Descriptor])? {\n    guard case .forms(let parts) = d, let head = parts.first, case .atom(let name) = head else {\n      return nil\n    }\n    return (name, Array(parts.dropFirst()))\n  }\n\n  /// A value drawn from a descriptor at a size, and the next state. Every draw,\n  /// including each boundary choice, follows the portable algorithm.\n  public static func generate(_ d: Descriptor, _ table: Table, _ state: Random.Seed, _ size: Int)\n    throws -> (Value, Random.Seed)\n  {\n    let resolved = try resolve(d, table)\n    guard let (name, args) = shape(resolved) else {\n      throw Fail.with(\"UnsupportedGenerationDescriptor\", \"\\(resolved)\")\n    }\n    switch (name, args.count) {\n    case (\"int\", 3):\n      let (lo, hi) = generationBounds(try bound(args[1]), try bound(args[2]))\n      let (choice, s1) = Random.below(10, state)\n      if choice < 2 {\n        let (i, s2) = Random.below(4, s1)\n        let options = [\n          lo, hi, BigInt.min(BigInt.max(.zero, lo), hi), BigInt.min(BigInt.max(.one, lo), hi),\n        ]\n        return (.int(options[i.exactly(Int.self) ?? 0]), s2)\n      }\n      let (n, s2) = Random.below(hi - lo + .one, s1)\n      return (.int(lo + n), s2)\n    case (\"bool\", 0):\n      let (n, s) = Random.below(2, state)\n      return (.bool(n == .one), s)\n    case (\"text\", 0):\n      let (count, s1) = Random.below(BigInt(size + 1), state)\n      var s = s1\n      var scalars = String.UnicodeScalarView()\n      for _ in 0..<(count.exactly(Int.self) ?? 0) {\n        let (n, next) = Random.below(95, s)\n        s = next\n        scalars.append(Unicode.Scalar(UInt8(n.exactly(Int.self)! + 32)))\n      }\n      return (.text(String(scalars)), s)\n    case (\"unit\", 0):\n      return (.unit, state)\n    case (\"list\", 1):\n      let (count, s1) = Random.below(BigInt(size + 1), state)\n      var s = s1\n      var items = [Value]()\n      for _ in 0..<(count.exactly(Int.self) ?? 0) {\n        let (v, next) = try generate(args[0], table, s, size)\n        items.append(v)\n        s = next\n      }\n      return (.list(items), s)\n    case (\"maybe\", 1):\n      let (choice, s1) = Random.below(4, state)\n      if choice.isZero { return (.data(\"Maybe::Absent\", []), s1) }\n      let (v, s2) = try generate(args[0], table, s1, size)\n      return (.data(\"Maybe::Present\", [v]), s2)\n    case (\"either\", 2):\n      let (choice, s1) = Random.below(2, state)\n      let (tag, inner) = choice.isZero ? (\"Either::Left\", args[0]) : (\"Either::Right\", args[1])\n      let (v, s2) = try generate(inner, table, s1, size)\n      return (.data(tag, [v]), s2)\n    case (\"data\", _) where args.count >= 1:\n      let cs = Array(args.dropFirst())\n      let choices = size == 0 ? baseConstructors(cs) : cs\n      let (i, s1) = Random.below(BigInt(choices.count), state)\n      guard let (head, parts) = shape(choices[i.exactly(Int.self) ?? 0]), head == \"ctor\",\n        let tag = parts.first\n      else {\n        throw fail(\"InvalidConstructorDescriptor\")\n      }\n      var s = s1\n      var values = [Value]()\n      for field in parts.dropFirst() {\n        let (v, next) = try generate(field, table, s, Swift.max(size - 1, 0))\n        values.append(v)\n        s = next\n      }\n      return (.data(try unquote(tag), values), s)\n    default:\n      throw Fail.with(\"UnsupportedGenerationDescriptor\", \"\\(resolved)\")\n    }\n  }\n\n  /// The smallest value of a descriptor.\n  public static func minimal(_ d: Descriptor, _ table: Table) throws -> Value {\n    let resolved = try resolve(d, table)\n    guard let (name, args) = shape(resolved) else {\n      throw Fail.with(\"UnsupportedGenerationDescriptor\", \"\\(resolved)\")\n    }\n    switch (name, args.count) {\n    case (\"int\", 3):\n      let (lo, hi) = generationBounds(try bound(args[1]), try bound(args[2]))\n      return .int(BigInt.min(BigInt.max(.zero, lo), hi))\n    case (\"bool\", 0): return .bool(false)\n    case (\"text\", 0): return .text(\"\")\n    case (\"unit\", 0): return .unit\n    case (\"list\", 1): return .list([])\n    case (\"maybe\", 1): return .data(\"Maybe::Absent\", [])\n    case (\"either\", 2): return .data(\"Either::Left\", [try minimal(args[0], table)])\n    case (\"data\", _) where args.count >= 1:\n      guard let first = baseConstructors(Array(args.dropFirst())).first,\n        let (head, parts) = shape(first), head == \"ctor\",\n        let tag = parts.first\n      else { throw fail(\"InvalidDataDescriptor\") }\n      return .data(try unquote(tag), try parts.dropFirst().map { try minimal($0, table) })\n    default:\n      throw Fail.with(\"UnsupportedGenerationDescriptor\", \"\\(resolved)\")\n    }\n  }\n\n  private static func shrinkSequence<T>(_ values: [T]) -> [[T]] {\n    if values.isEmpty { return [] }\n    var result: [[T]] = [[], Array(values.prefix(values.count / 2))]\n    for i in 0..<values.count {\n      var copy = values\n      copy.remove(at: i)\n      result.append(copy)\n    }\n    return result\n  }\n\n  private static func replaceShrinks(_ values: [Value], _ shrink: (Value) throws -> [Value])\n    rethrows -> [[Value]]\n  {\n    var result = [[Value]]()\n    for (i, v) in values.enumerated() {\n      for c in try shrink(v) {\n        var copy = values\n        copy[i] = c\n        result.append(copy)\n      }\n    }\n    return result\n  }\n\n  private static func constructorOf(_ tag: String, _ cs: [Descriptor]) throws -> Descriptor {\n    let found = try cs.filter { c in\n      if let (head, parts) = shape(c), head == \"ctor\", let name = parts.first {\n        return try unquote(name) == tag\n      }\n      return false\n    }\n    guard found.count == 1 else { throw Fail.with(\"ForeignWireConstructor\", tag) }\n    return found[0]\n  }\n\n  private static func fieldDescriptors(_ c: Descriptor) -> [Descriptor] {\n    guard let (head, parts) = shape(c), head == \"ctor\" else { return [] }\n    return Array(parts.dropFirst())\n  }\n\n  /// The candidates a value shrinks to, in the portable order, without\n  /// duplicates or the value itself.\n  public static func shrink(_ d: Descriptor, _ value: Value, _ table: Table) throws -> [Value] {\n    let candidates = try shrinkResolved(try resolve(d, table), value, table)\n    var seen = [value]\n    var result = [Value]()\n    for c in candidates where !seen.contains(where: { Recorded.identical($0, c) }) {\n      seen.append(c)\n      result.append(c)\n    }\n    return result\n  }\n\n  private static func shrinkResolved(_ d: Descriptor, _ value: Value, _ table: Table) throws\n    -> [Value]\n  {\n    guard let (name, args) = shape(d) else { throw fail(\"InvalidShrinkValue\") }\n    switch (name, args.count, value) {\n    case (\"int\", 3, .int(let v)):\n      guard case .int(let target) = try minimal(d, table) else { return [] }\n      if v == target { return [] }\n      let half = (v - target) / 2\n      return [.int(target), .int(v - half), .int(v - (v > target ? BigInt.one : BigInt(-1)))]\n    case (\"bool\", 0, .bool(true)): return [.bool(false)]\n    case (\"bool\", 0, .bool(false)): return []\n    case (\"text\", 0, .text(let s)):\n      return try shrinkSequence(Scalar.codePoints(s)).map { .text(try Scalar.textOfPoints($0)) }\n    case (\"list\", 1, .list(let items)):\n      return shrinkSequence(items).map { .list($0) }\n        + (try replaceShrinks(items) { try shrink(args[0], $0, table) }).map { .list($0) }\n    case (\"maybe\", 1, .data(\"Maybe::Present\", let fields)) where fields.count == 1:\n      return [.data(\"Maybe::Absent\", [])]\n        + (try shrink(args[0], fields[0], table)).map { .data(\"Maybe::Present\", [$0]) }\n    case (\"maybe\", 1, .data(\"Maybe::Absent\", _)):\n      return []\n    case (\"either\", 2, .data(let tag, let fields)) where fields.count == 1:\n      let inner = tag == \"Either::Left\" ? args[0] : args[1]\n      return try shrink(inner, fields[0], table).map { .data(tag, [$0]) }\n    case (\"data\", _, .data(let tag, let fields)) where args.count >= 1:\n      let ds = fieldDescriptors(try constructorOf(tag, Array(args.dropFirst())))\n      let recursive = Descriptor.forms([.atom(\"ref\"), args[0]])\n      var result = [try minimal(d, table)]\n      for (f, fd) in zip(fields, ds) where fd == recursive { result.append(f) }\n      for (i, fd) in ds.enumerated() where i < fields.count {\n        for c in try shrink(fd, fields[i], table) {\n          var copy = fields\n          copy[i] = c\n          result.append(.data(tag, copy))\n        }\n      }\n      return result\n    case (\"unit\", 0, .unit): return []\n    default: throw fail(\"InvalidShrinkValue\")\n    }\n  }\n\n  private static func quote(_ s: String) -> String {\n    \"\\\"\"\n      + s.replacingOccurrences(of: \"\\\\\", with: \"\\\\\\\\\").replacingOccurrences(of: \"\\\"\", with: \"\\\\\\\"\")\n      + \"\\\"\"\n  }\n\n  /// A value as the portable runtimes print it.\n  public static func render(_ value: Value) -> String {\n    switch value {\n    case .bool(true): return \"true\"\n    case .bool(false): return \"false\"\n    case .unit: return \"()\"\n    case .int(let n): return n.description\n    case .text(let s): return quote(s)\n    case .list(let items): return \"[\" + items.map(render).joined(separator: \", \") + \"]\"\n    case .data(let tag, let fields):\n      let name = Recorded.lastPart(tag)\n      return fields.isEmpty ? name : name + \"(\" + fields.map(render).joined(separator: \", \") + \")\"\n    default: return Recorded.debug(value)\n    }\n  }\n\n  // MARK: The canonical wire: zigzag varints, length-prefixed bytes,\n  // constructor indices. ref:DEC-distribution-canonical-wire\n\n  /// A non-negative integer as LEB128.\n  public static func varint(_ n: BigInt) throws -> [UInt8] {\n    if n.isNegative { throw fail(\"NegativeVarint\") }\n    var bytes = [UInt8]()\n    var rest = n\n    while true {\n      let low = UInt8((rest & BigInt(127)).exactly(Int.self)!)\n      rest = rest >> 7\n      if rest.isZero {\n        bytes.append(low)\n        return bytes\n      }\n      bytes.append(low | 128)\n    }\n  }\n\n  /// A LEB128 integer at a position, and the position after it.\n  public static func readVarint(_ bytes: [UInt8], _ start: Int) throws -> (BigInt, Int) {\n    var n = BigInt.zero\n    var shift = 0\n    var i = start\n    while true {\n      if i >= bytes.count { throw fail(\"TruncatedWireValue\") }\n      let b = bytes[i]\n      n = n | (BigInt(Int(b & 127)) << shift)\n      shift += 7\n      i += 1\n      if b < 128 { return (n, i) }\n    }\n  }\n\n  private static func checkInteger(_ v: BigInt, _ lo: Descriptor, _ hi: Descriptor) throws {\n    if let l = try bound(lo), v < l { throw fail(\"WireIntegerOutOfRange\") }\n    if let h = try bound(hi), v > h { throw fail(\"WireIntegerOutOfRange\") }\n  }\n\n  private static func put(_ d: Descriptor, _ value: Value, _ table: Table, _ out: inout [UInt8])\n    throws\n  {\n    let resolved = try resolve(d, table)\n    guard let (name, args) = shape(resolved) else {\n      throw Fail.with(\"InvalidWireValue\", \"\\(resolved)\")\n    }\n    switch (name, args.count, value) {\n    case (\"int\", 3, .int(let v)):\n      try checkInteger(v, args[1], args[2])\n      out += try varint(v.isNegative ? -v * 2 - .one : v * 2)\n    case (\"bool\", 0, .bool(let b)): out.append(b ? 1 : 0)\n    case (\"unit\", 0, .unit): break\n    case (\"text\", 0, .text(let s)), (\"end\", 0, .text(let s)):\n      let bytes = Array(s.utf8)\n      out += try varint(BigInt(bytes.count))\n      out += bytes\n    case (\"bytes\", 0, .bytes(let b)), (\"end\", 0, .bytes(let b)):\n      out += try varint(BigInt(b.count))\n      out += b\n    case (\"list\", 1, .list(let items)):\n      out += try varint(BigInt(items.count))\n      for v in items { try put(args[0], v, table, &out) }\n    case (\"maybe\", 1, .data(\"Maybe::Absent\", let f)) where f.isEmpty: out.append(0)\n    case (\"maybe\", 1, .data(\"Maybe::Present\", let f)) where f.count == 1:\n      out.append(1)\n      try put(args[0], f[0], table, &out)\n    case (\"either\", 2, .data(\"Either::Left\", let f)) where f.count == 1:\n      out.append(0)\n      try put(args[0], f[0], table, &out)\n    case (\"either\", 2, .data(\"Either::Right\", let f)) where f.count == 1:\n      out.append(1)\n      try put(args[1], f[0], table, &out)\n    case (\"data\", _, .data(let tag, let fields)) where args.count >= 1:\n      let cs = Array(args.dropFirst())\n      let c = try constructorOf(tag, cs)\n      let ds = fieldDescriptors(c)\n      try require(ds.count == fields.count, \"WireFieldCount\")\n      guard let index = cs.firstIndex(of: c) else { throw fail(\"InvalidWireConstructor\") }\n      out += try varint(BigInt(index))\n      for (fd, v) in zip(ds, fields) { try put(fd, v, table, &out) }\n    default:\n      throw Fail.with(\"InvalidWireValue\", \"\\(resolved)\")\n    }\n  }\n\n  /// A value's canonical wire bytes.\n  public static func encode(_ d: Descriptor, _ value: Value, _ table: Table) throws -> [UInt8] {\n    var out = [UInt8]()\n    try put(d, value, table, &out)\n    return out\n  }\n\n  private static func get(_ d: Descriptor, _ bytes: [UInt8], _ i: Int, _ table: Table) throws -> (\n    Value, Int\n  ) {\n    let resolved = try resolve(d, table)\n    guard let (name, args) = shape(resolved) else {\n      throw Fail.with(\"InvalidWireValue\", \"\\(resolved)\")\n    }\n    switch (name, args.count) {\n    case (\"int\", 3):\n      let (z, next) = try readVarint(bytes, i)\n      let v = z.isEven ? z / 2 : -(z + .one) / 2\n      try checkInteger(v, args[1], args[2])\n      return (.int(v), next)\n    case (\"bool\", 0):\n      try require(i < bytes.count && bytes[i] < 2, \"InvalidWireValue\")\n      return (.bool(bytes[i] == 1), i + 1)\n    case (\"unit\", 0):\n      return (.unit, i)\n    case (\"text\", 0), (\"bytes\", 0), (\"end\", 0):\n      let (count, start) = try readVarint(bytes, i)\n      guard let n = count.exactly(Int.self), start + n <= bytes.count else {\n        throw fail(\"TruncatedWireValue\")\n      }\n      let slice = Array(bytes[start..<(start + n)])\n      if name == \"bytes\" { return (.bytes(slice), start + n) }\n      guard let text = String(validating: slice, as: UTF8.self) else {\n        throw fail(\"WireInvalidUtf8\")\n      }\n      return (.text(text), start + n)\n    case (\"list\", 1):\n      let (count, start) = try readVarint(bytes, i)\n      var position = start\n      var items = [Value]()\n      for _ in 0..<(count.exactly(Int.self) ?? 0) {\n        let (v, next) = try get(args[0], bytes, position, table)\n        items.append(v)\n        position = next\n      }\n      return (.list(items), position)\n    case (\"maybe\", 1):\n      try require(i < bytes.count && bytes[i] < 2, \"InvalidWireValue\")\n      if bytes[i] == 0 { return (.data(\"Maybe::Absent\", []), i + 1) }\n      let (v, next) = try get(args[0], bytes, i + 1, table)\n      return (.data(\"Maybe::Present\", [v]), next)\n    case (\"either\", 2):\n      try require(i < bytes.count && bytes[i] < 2, \"InvalidWireValue\")\n      let (tag, inner) = bytes[i] == 0 ? (\"Either::Left\", args[0]) : (\"Either::Right\", args[1])\n      let (v, next) = try get(inner, bytes, i + 1, table)\n      return (.data(tag, [v]), next)\n    case (\"data\", _) where args.count >= 1:\n      let cs = Array(args.dropFirst())\n      let (index, start) = try readVarint(bytes, i)\n      guard let k = index.exactly(Int.self), k < cs.count else {\n        throw fail(\"InvalidWireConstructor\")\n      }\n      guard let (head, parts) = shape(cs[k]), head == \"ctor\", let tag = parts.first else {\n        throw fail(\"InvalidWireConstructor\")\n      }\n      var position = start\n      var fields = [Value]()\n      for fd in parts.dropFirst() {\n        let (v, next) = try get(fd, bytes, position, table)\n        fields.append(v)\n        position = next\n      }\n      return (.data(try unquote(tag), fields), position)\n    default:\n      throw Fail.with(\"InvalidWireValue\", \"\\(resolved)\")\n    }\n  }\n\n  /// A value from its wire bytes, and the position after it.\n  public static func decodePrefix(_ d: Descriptor, _ bytes: [UInt8], _ start: Int, _ table: Table)\n    throws -> (Value, Int)\n  {\n    try get(d, bytes, start, table)\n  }\n\n  /// A value from exactly its wire bytes.\n  public static func decode(_ d: Descriptor, _ bytes: [UInt8], _ table: Table) throws -> Value {\n    let (v, next) = try get(d, bytes, 0, table)\n    try require(next == bytes.count, \"TrailingWireBytes\")\n    return v\n  }\n\n  /// The values a descriptor text draws from a seed (the generation suite's\n  /// conformance vectors).\n  public static func generated(_ text: String, _ seed: BigInt, _ size: Int, _ count: Int) throws\n    -> [String]\n  {\n    let (table, d) = try fromText(text)\n    var state = Random.seed(seed)\n    var result = [String]()\n    for _ in 0..<Swift.max(0, count) {\n      let (v, next) = try generate(d, table, state, size)\n      state = next\n      result.append(render(v))\n    }\n    return result\n  }\n\n  /// The shrink candidates of the first value a descriptor text draws.\n  public static func shrunk(_ text: String, _ seed: BigInt, _ size: Int) throws -> [String] {\n    let (table, d) = try fromText(text)\n    let (v, _) = try generate(d, table, Random.seed(seed), size)\n    return try shrink(d, v, table).map(render)\n  }\n}\n"
swiftSource "LawSpecRuntime/Effects.swift" = "// Abilities in Swift: lexically scoped handlers, carried in the schema, and\n// typed failures. A handler is the logical view of an ability's operations;\n// native code sees the ability's generated protocol, and a native handler\n// becomes a logical one through its generated bridge. State lives in cells\n// owned by the scope that made the handler, so concurrent steps share it.\n// ref:DEC-typed-core-boundary ref:DEC-swift-runtime-from-scratch\n\nimport Foundation\n\npublic enum Effects {\n  /// An operation's clause: the schema in scope and the arguments to a result.\n  public typealias Clause = @Sendable (Schema, [Value]) throws -> Value\n\n  /// A stateful clause also takes the state, and gives back a pair of the\n  /// result and the next state.\n  public typealias StatefulClause = @Sendable (Schema, [Value], Value) throws -> Value\n\n  /// Mutable state, read and replaced under a lock.\n  public final class Cell: @unchecked Sendable {\n    private var value: Value\n    private let gate = NSRecursiveLock()\n    public init(_ initial: Value) { value = initial }\n    public func read() -> Value {\n      gate.lock()\n      defer { gate.unlock() }\n      return value\n    }\n    public func write(_ next: Value) {\n      gate.lock()\n      defer { gate.unlock() }\n      value = next\n    }\n    /// Run an update under the cell's lock.\n    public func update<R>(_ change: (Value) throws -> (R, Value)) rethrows -> R {\n      gate.lock()\n      defer { gate.unlock() }\n      let (result, next) = try change(value)\n      value = next\n      return result\n    }\n  }\n\n  /// A log of the operations a recording handler saw, in order.\n  public final class Log: @unchecked Sendable {\n    private var entries: [(String, [Value])] = []\n    private let gate = NSLock()\n    public init() {}\n    public func add(_ operation: String, _ arguments: [Value]) {\n      gate.lock()\n      defer { gate.unlock() }\n      entries.append((operation, arguments))\n    }\n    public var calls: [(String, [Value])] {\n      gate.lock()\n      defer { gate.unlock() }\n      return entries\n    }\n  }\n\n  public indirect enum Handler: Sendable {\n    case stateless([String: Clause])\n    case stateful(Cell, [String: StatefulClause])\n    case recording(Log, Handler)\n  }\n\n  /// A handler scope: it owns the handlers of several abilities made once in\n  /// it, and is closed when its body ends.\n  public final class Scope: @unchecked Sendable {\n    private var made: [String: Handler] = [:]\n    private let gate = NSRecursiveLock()\n    public init() {}\n    public func shared(_ key: String, _ make: () throws -> Handler) rethrows -> Handler {\n      gate.lock()\n      defer { gate.unlock() }\n      if let h = made[key] { return h }\n      let h = try make()\n      made[key] = h\n      return h\n    }\n  }\n\n  /// A native protocol made from a logical handler keeps it, so the handler\n  /// is recovered, with its state, when the native value crosses back.\n  public protocol Origin: AnyObject {\n    var originAbility: String { get }\n    var originSymbols: SymbolContext { get }\n    var originHandler: Handler { get }\n    var originSchema: Schema { get }\n  }\n\n  private static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  /// A handler with no state.\n  public static func stateless(_ clauses: [(String, Clause)]) -> Handler {\n    .stateless(Dictionary(clauses, uniquingKeysWith: { $1 }))\n  }\n\n  /// A handler with state, from its start.\n  public static func stateful(_ initial: Value, _ clauses: [(String, StatefulClause)]) -> Handler {\n    .stateful(Cell(initial), Dictionary(clauses, uniquingKeysWith: { $1 }))\n  }\n\n  /// A handler that logs every operation, then runs another.\n  public static func recording(_ inner: Handler) -> Handler { .recording(Log(), inner) }\n\n  /// Handlers installed in a schema, overriding outer ones.\n  public static func install(_ schema: Schema, _ handlers: [(String, Handler)]) -> Schema {\n    var installed = schema\n    for (key, h) in handlers { installed.handlers[key] = h }\n    return installed\n  }\n\n  /// The handler of an ability in scope.\n  public static func handler(_ schema: Schema, _ ability: String) throws -> Handler {\n    guard let h = schema.handlers[ability] else { throw fail(\"MissingHandler\", ability) }\n    return h\n  }\n\n  /// Run a body in a new scope with handlers made by factories. A factory\n  /// failing leaves no handler behind.\n  public static func withScope<R>(\n    _ schema: Schema, _ factories: [(String, (Schema) throws -> Handler)],\n    _ body: (Schema) throws -> R\n  ) throws -> R {\n    var based = schema\n    based.scope = Scope()\n    let handlers = try factories.map { ($0.0, try $0.1(based)) }\n    return try body(install(based, handlers))\n  }\n\n  /// A handler of several abilities is made once in a scope, so they share its\n  /// state.\n  public static func shared(_ schema: Schema, _ key: String, _ make: () throws -> Handler) throws\n    -> Handler\n  {\n    guard let scope = schema.scope else { return try make() }\n    return try scope.shared(key, make)\n  }\n\n  private static func clause<C>(_ clauses: [String: C], _ operation: String) throws -> C {\n    guard let c = clauses[operation] else { throw fail(\"MissingHandlerOperation\", operation) }\n    return c\n  }\n\n  /// Run an operation of a handler.\n  public static func invoke(\n    _ h: Handler, _ schema: Schema, _ operation: String, _ arguments: [Value]\n  ) throws -> Value {\n    switch h {\n    case .stateless(let clauses):\n      return try clause(clauses, operation)(schema, arguments)\n    case .stateful(let cell, let clauses):\n      let run = try clause(clauses, operation)\n      let identity = ObjectIdentifier(cell)\n      if schema.effectPath.contains(identity) { throw fail(\"RecursiveHandlerCall\", operation) }\n      var inner = schema\n      inner.effectPath = [identity] + schema.effectPath\n      return try cell.update { state in\n        let outcome = try run(inner, arguments, state)\n        guard case .data(_, let pair) = outcome, pair.count == 2 else {\n          throw fail(\"InvalidHandlerResult\", \"\\(outcome)\")\n        }\n        return (pair[0], pair[1])\n      }\n    case .recording(let log, let inner):\n      log.add(operation, arguments)\n      return try invoke(inner, schema, operation, arguments)\n    }\n  }\n\n  /// Perform an operation of an ability through the handler in scope.\n  public static func perform(\n    _ schema: Schema, _ ability: String, _ operation: String, _ arguments: [Value]\n  ) throws -> Value {\n    try invoke(handler(schema, ability), schema, operation, arguments)\n  }\n\n  /// How many times a recording handler saw an operation (with arguments, if\n  /// given).\n  public static func countCalls(\n    _ schema: Schema, _ ability: String, _ operation: String, _ arguments: [Value]?\n  ) throws -> Value {\n    guard case .recording(let log, _) = try handler(schema, ability) else {\n      throw fail(\"RecordingRequired\", ability)\n    }\n    let count = log.calls.filter { name, values in\n      name == operation && (arguments.map { Scalar.equal(.list(values), .list($0)) } ?? true)\n    }.count\n    return .int(BigInt(count))\n  }\n\n  /// Raise a typed failure of a Fail ability.\n  public static func raiseFailure(_ ability: String, _ failure: Value) throws -> Value {\n    throw RaisedFailure(ability, failure)\n  }\n\n  /// Catch a typed failure: Right of the body's value, or Left of the failure.\n  public static func attempt(\n    _ ability: String, _ body: () throws -> Value, _ right: (Value) throws -> Value,\n    _ left: (Value) throws -> Value\n  ) throws -> Value {\n    let outcome: Value\n    do {\n      outcome = try body()\n    } catch let raised as RaisedFailure where raised.ability == ability {\n      return try left(raised.failure)\n    }\n    return try right(outcome)\n  }\n\n  /// A native adapter's typed throw: its failure raised as the logical one.\n  public static func ofThrown<T, E: Error>(\n    _ ability: String, _ convert: (E) throws -> Value, _ body: () throws(E) -> T\n  ) throws -> T {\n    do {\n      return try body()\n    } catch {\n      throw RaisedFailure(ability, try convert(error))\n    }\n  }\n\n  /// The same, for an async adapter.\n  public static func ofThrownAsync<T: Sendable, E: Error>(\n    _ ability: String, _ convert: @escaping @Sendable (E) throws -> Value,\n    _ body: @escaping @Sendable () async throws(E) -> T\n  ) throws -> T {\n    try Runtime.await {\n      do throws(E) {\n        return try await body()\n      } catch {\n        throw RaisedFailure(ability, try convert(error))\n      }\n    }\n  }\n\n  /// Errors of mapped native types become typed failures; the others pass.\n  public static func nativeFailures(\n    _ ability: String, _ body: () throws -> Value, _ mappings: [(any Error) throws -> Value?]\n  ) throws -> Value {\n    do {\n      return try body()\n    } catch let raised as RaisedFailure {\n      throw raised\n    } catch let failure as LawSpecError {\n      throw failure\n    } catch {\n      for mapping in mappings {\n        if let failure = try mapping(error) { throw RaisedFailure(ability, failure) }\n      }\n      throw error\n    }\n  }\n\n  /// A mapping for nativeFailures: an error of type E becomes a failure.\n  public static func mapError<E: Error>(_ type: E.Type, _ make: @escaping (E) throws -> Value) -> (\n    any Error\n  ) throws -> Value? {\n    { error in\n      guard let caught = error as? E else { return nil }\n      return try make(caught)\n    }\n  }\n\n  /// A logical failure crossing to native code: thrown as its native type,\n  /// the typed throw its native form declares.\n  public static func nativeTry<T, E: Error>(\n    _ ability: String, _ convert: (Value) throws -> E, _ body: () throws -> T\n  ) throws -> T {\n    do {\n      return try body()\n    } catch let raised as RaisedFailure where raised.ability == ability {\n      throw try convert(raised.failure)\n    }\n  }\n\n  /// The handler behind a native protocol value, if it came from a logical one\n  /// with the same symbols.\n  public static func recover(\n    _ native: Any, _ ability: String, _ symbols: SymbolContext, _ make: () throws -> Handler\n  ) rethrows -> Handler {\n    if let origin = native as? Origin, origin.originAbility == ability,\n      origin.originSymbols === symbols\n    {\n      return origin.originHandler\n    }\n    return try make()\n  }\n\n  private static func stateCell(_ h: Handler) throws -> Cell {\n    switch h {\n    case .stateful(let cell, _): return cell\n    case .recording(_, let inner): return try stateCell(inner)\n    case .stateless: throw fail(\"StatelessHandler\")\n    }\n  }\n\n  /// A spec handler's state, through its native protocol value.\n  public static func handlerState(_ native: Any) throws -> (Schema, Value) {\n    guard let origin = native as? Origin else {\n      throw fail(\"StatelessHandler\", \"a native handler has no LawSpec state\")\n    }\n    return (origin.originSchema, try stateCell(origin.originHandler).read())\n  }\n\n  /// Replace a spec handler's state, through its native protocol value.\n  public static func setHandlerState(_ native: Any, _ state: Value) throws {\n    guard let origin = native as? Origin else {\n      throw fail(\"StatelessHandler\", \"a native handler has no LawSpec state\")\n    }\n    try stateCell(origin.originHandler).write(state)\n  }\n\n  /// A production handler made with a resource, asked for where no case has one.\n  public static func resourceRequired(_ ability: String) throws -> Handler {\n    throw fail(\"ResourceRequired\", ability)\n  }\n}\n\n// Calls of application code bound in lawspec.json. A bound function may or\n// may not throw, and may or may not be async: passed as a value it converts\n// to a throwing (or async throwing) function, so the generated call is the\n// same either way.\nextension Effects {\n  public static func bound<R>(_ f: () throws -> R) throws -> R { try f() }\n  public static func boundAsync<R>(_ f: () async throws -> R) async throws -> R { try await f() }\n  public static func bound<A0, R>(_ f: (A0) throws -> R, _ a0: A0) throws -> R { try f(a0) }\n  public static func boundAsync<A0, R>(_ f: (A0) async throws -> R, _ a0: A0) async throws -> R {\n    try await f(a0)\n  }\n  public static func bound<A0, A1, R>(_ f: (A0, A1) throws -> R, _ a0: A0, _ a1: A1) throws -> R {\n    try f(a0, a1)\n  }\n  public static func boundAsync<A0, A1, R>(_ f: (A0, A1) async throws -> R, _ a0: A0, _ a1: A1)\n    async throws -> R\n  { try await f(a0, a1) }\n  public static func bound<A0, A1, A2, R>(\n    _ f: (A0, A1, A2) throws -> R, _ a0: A0, _ a1: A1, _ a2: A2\n  ) throws -> R { try f(a0, a1, a2) }\n  public static func boundAsync<A0, A1, A2, R>(\n    _ f: (A0, A1, A2) async throws -> R, _ a0: A0, _ a1: A1, _ a2: A2\n  ) async throws -> R { try await f(a0, a1, a2) }\n  public static func bound<A0, A1, A2, A3, R>(\n    _ f: (A0, A1, A2, A3) throws -> R, _ a0: A0, _ a1: A1, _ a2: A2, _ a3: A3\n  ) throws -> R { try f(a0, a1, a2, a3) }\n  public static func boundAsync<A0, A1, A2, A3, R>(\n    _ f: (A0, A1, A2, A3) async throws -> R, _ a0: A0, _ a1: A1, _ a2: A2, _ a3: A3\n  ) async throws -> R { try await f(a0, a1, a2, a3) }\n  public static func bound<A0, A1, A2, A3, A4, R>(\n    _ f: (A0, A1, A2, A3, A4) throws -> R, _ a0: A0, _ a1: A1, _ a2: A2, _ a3: A3, _ a4: A4\n  ) throws -> R { try f(a0, a1, a2, a3, a4) }\n  public static func boundAsync<A0, A1, A2, A3, A4, R>(\n    _ f: (A0, A1, A2, A3, A4) async throws -> R, _ a0: A0, _ a1: A1, _ a2: A2, _ a3: A3, _ a4: A4\n  ) async throws -> R { try await f(a0, a1, a2, a3, a4) }\n  public static func bound<A0, A1, A2, A3, A4, A5, R>(\n    _ f: (A0, A1, A2, A3, A4, A5) throws -> R, _ a0: A0, _ a1: A1, _ a2: A2, _ a3: A3, _ a4: A4,\n    _ a5: A5\n  ) throws -> R { try f(a0, a1, a2, a3, a4, a5) }\n  public static func boundAsync<A0, A1, A2, A3, A4, A5, R>(\n    _ f: (A0, A1, A2, A3, A4, A5) async throws -> R, _ a0: A0, _ a1: A1, _ a2: A2, _ a3: A3,\n    _ a4: A4, _ a5: A5\n  ) async throws -> R { try await f(a0, a1, a2, a3, a4, a5) }\n}\n"
swiftSource "LawSpecRuntime/Endpoint.swift" = "// A reliable channel end a node owns: its protocol state, its retry timer\n// and its reader. Giving up is an ordered frame that keeps retrying after\n// the application leaves; an unused end can move to another node.\n// ref:DEC-distribution-canonical-wire ref:DEC-sessions-by-construction\n\nimport Foundation\n\n/// The bytes a reader gets, or why there are none.\npublic typealias Delivery = Result<[UInt8], NodeFailure>\n\npublic final class Endpoint: NodeService, @unchecked Sendable {\n  private final class Reader {\n    let ticket: Int64\n    let respond: @Sendable (Delivery) -> Void\n    var timer: NetworkTimer?\n\n    init(ticket: Int64, respond: @escaping @Sendable (Delivery) -> Void) {\n      self.ticket = ticket\n      self.respond = respond\n    }\n  }\n\n  private struct State {\n    var channel: ChannelProtocol.State\n    var reader: Reader?\n    var taking: (@Sendable (Result<Void, NodeFailure>) -> Void)?\n    var timer: NetworkTimer?\n    var tickets: Int64 = 0\n    var stopped = false\n  }\n\n  private let node: Node\n  private let name: String\n  public let address: String\n  private let state: Locked<State>\n\n  public init(_ node: Node, _ name: String, _ deadline: Int) throws {\n    if deadline <= 0 { throw Fail.with(\"Channel\", \"invalid_deadline\") }\n    self.node = node\n    self.name = name\n    let box = Locked<Endpoint?>(nil)\n    address = try node.registerReceiver(name) { frame in box.with { $0 }?.arrive(frame) }\n    state = Locked(State(channel: try ChannelProtocol.create(address, Int64(deadline) * 1000)))\n    box.with { $0 = self }\n    node.adopt(self)\n  }\n\n  private static func now() -> Int64 { Int64(DispatchTime.now().uptimeNanoseconds / 1000) }\n\n  private static func fail(_ reason: String) -> LawSpecError { Fail.with(\"Channel\", reason) }\n\n  /// Settle waiters and the timer; return what to do outside the lock.\n  private func wake(_ s: inout State) -> [() -> Void] {\n    var actions = [() -> Void]()\n    if let respond = s.taking {\n      switch ChannelProtocol.takeStatus(s.channel, Endpoint.now()) {\n      case .success(false): break\n      case .success(true):\n        s.taking = nil\n        actions.append { respond(.success(())) }\n      case .failure(let reason):\n        s.taking = nil\n        actions.append { respond(.failure(reason)) }\n      }\n    } else if let r = s.reader {\n      let (result, next) = ChannelProtocol.receiveBody(s.channel)\n      switch result {\n      case .empty: break\n      case .body(let b):\n        s.channel = next\n        s.reader = nil\n        r.timer?.cancel()\n        actions.append { r.respond(.success(b)) }\n      case .failed(let reason):\n        s.channel = next\n        s.reader = nil\n        r.timer?.cancel()\n        actions.append { r.respond(.failure(NodeFailure(reason))) }\n      }\n    }\n    let c = s.channel\n    let active =\n      c.failure == nil && c.moved == nil\n      && (!c.unacked.isEmpty || s.taking != nil || (c.taking != nil && !c.taken)\n        || (c.announcing && !c.confirmed && c.peer != nil))\n    if active && s.timer == nil && !s.stopped {\n      s.timer = NetworkTimer(10) { [weak self] in self?.tick() }\n    } else if !active, let t = s.timer {\n      t.cancel()\n      s.timer = nil\n    }\n    return actions\n  }\n\n  private func update(\n    _ transition: (ChannelProtocol.State) throws -> (ChannelProtocol.State, [Frame])\n  ) throws {\n    let (frames, actions) = try state.with { s in\n      let (next, frames) = try transition(s.channel)\n      s.channel = next\n      return (frames, wake(&s))\n    }\n    for frame in frames { try? node.forward(frame) }\n    for action in actions { action() }\n  }\n\n  private func tick() { try? update { try ChannelProtocol.tick($0, Endpoint.now()) } }\n\n  private func arrive(_ frame: Frame) {\n    try? update { (ChannelProtocol.accept($0, frame, Endpoint.now())) }\n  }\n\n  private func guarded<T>(_ operation: () throws -> T) throws -> T {\n    do {\n      return try operation()\n    } catch let e as LawSpecError where e.code == \"Channel\" {\n      throw e\n    } catch let e as LawSpecError where e.code == \"ChannelEndUnavailable\" {\n      throw Endpoint.fail(\"channel_end_unavailable\")\n    } catch {\n      throw Endpoint.fail(\"invalid_operation\")\n    }\n  }\n\n  private func idle(_ s: State) throws {\n    if s.taking != nil { throw Endpoint.fail(\"taking_in_progress\") }\n  }\n\n  public func connect(_ peer: String) throws {\n    try guarded {\n      try state.with { try idle($0) }\n      try update { try ChannelProtocol.connect($0, peer, Endpoint.now()) }\n    }\n  }\n\n  public func send(_ bytes: [UInt8]) throws {\n    try guarded {\n      try state.with { try idle($0) }\n      try update { try ChannelProtocol.send($0, bytes, Endpoint.now()) }\n    }\n  }\n\n  public func abandon() { try? update { try ChannelProtocol.abandon($0, Endpoint.now()) } }\n\n  /// Wait for the next value (timeout in ms, or none): its bytes, or why\n  /// there is none.\n  @discardableResult\n  public func receiveAsync(_ timeout: Int?, _ respond: @escaping @Sendable (Delivery) -> Void)\n    throws -> Int64\n  {\n    let ticket: Int64 = try state.with { s in\n      try idle(s)\n      if s.reader != nil { throw Endpoint.fail(\"already_receiving\") }\n      s.tickets += 1\n      let r = Reader(ticket: s.tickets, respond: respond)\n      s.reader = r\n      if let ms = timeout {\n        let ticket = s.tickets\n        NetworkTimer.after(ms) { [weak self] in\n          guard let self else { return }\n          let fire: Bool = self.state.with { s in\n            guard let current = s.reader, current.ticket == ticket else { return false }\n            s.reader = nil\n            return true\n          }\n          if fire { respond(.failure(NodeFailure(\"receive_timeout\"))) }\n        }\n      }\n      return s.tickets\n    }\n    try update { ($0, []) }\n    return ticket\n  }\n\n  /// Wait for the next value's bytes.\n  public func receive(_ timeout: Int?) throws -> Delivery {\n    let result = Locked<Delivery?>(nil)\n    let done = DispatchSemaphore(value: 0)\n    try receiveAsync(timeout) { delivery in\n      result.with { $0 = delivery }\n      done.signal()\n    }\n    done.wait()\n    return result.with { $0 }!\n  }\n\n  /// Stop waiting; the reader is not called.\n  public func cancel(_ ticket: Int64) {\n    state.with { s in\n      if let r = s.reader, r.ticket == ticket {\n        r.timer?.cancel()\n        s.reader = nil\n      }\n    }\n  }\n\n  /// Offer this unused end to another node; the address that takes it.\n  public func offer() throws -> String {\n    try guarded {\n      try state.with { s in\n        try idle(s)\n        if s.reader != nil { throw Endpoint.fail(\"already_receiving\") }\n        let (address, next) = try ChannelProtocol.offer(\n          s.channel, Wire.hex(CryptoPrimitives.randomBytes(32)).uppercased())\n        s.channel = next\n        return address\n      }\n    }\n  }\n\n  /// Take an offered end into this fresh one, waiting until it arrives.\n  public func take(_ offered: String) throws {\n    let result = Locked<Result<Void, NodeFailure>?>(nil)\n    let done = DispatchSemaphore(value: 0)\n    try guarded {\n      try state.with { s in\n        try idle(s)\n        if s.reader != nil { throw Endpoint.fail(\"already_receiving\") }\n        let c = s.channel\n        if c.peer != nil || !c.unacked.isEmpty || c.expected != 0 || c.taking != nil {\n          throw Endpoint.fail(\"end_not_fresh\")\n        }\n        s.taking = { outcome in\n          result.with { $0 = outcome }\n          done.signal()\n        }\n      }\n      try update { try ChannelProtocol.take($0, offered, Endpoint.now()) }\n    }\n    done.wait()\n    if case .failure(let reason) = result.with({ $0 })! { throw Endpoint.fail(reason.reason) }\n  }\n\n  /// Destroy the end (a conversation ends with abandon).\n  public func stop() {\n    let (r, t) = state.with { s in\n      s.stopped = true\n      s.timer?.cancel()\n      s.timer = nil\n      let r = s.reader\n      s.reader = nil\n      let t = s.taking\n      s.taking = nil\n      return (r, t)\n    }\n    r?.respond(.failure(NodeFailure(\"endpoint_closed\")))\n    t?(.failure(NodeFailure(\"endpoint_closed\")))\n    node.unregister(name)\n  }\n\n  public func release() { stop() }\n}\n"
swiftSource "LawSpecRuntime/Keccak.swift" = "// The Keccak-f[1600] permutation and the FIPS 202 functions built on it.\n// CryptoKit has SHA3-256 but no SHAKE, and the fallbacks for ML-KEM, ML-DSA\n// and SLH-DSA need SHAKE128, SHAKE256 and SHA3-512 as incremental sponges.\n// ref:DEC-typed-core-boundary\n\n/// A Keccak sponge: absorb bytes, then squeeze any number of bytes.\n/// CryptoKit is not used here: it has no SHAKE and no incremental squeeze.\nstruct KeccakSponge {\n  private var state = [UInt64](repeating: 0, count: 25)\n  /// The rate in bytes: 168 for SHAKE128, 136 for SHAKE256 and SHA3-256, 72 for SHA3-512.\n  private let rate: Int\n  /// The domain separation byte: 0x1F for SHAKE, 0x06 for SHA3.\n  private let suffix: UInt8\n  private var position = 0\n  private var squeezing = false\n\n  init(rate: Int, suffix: UInt8) {\n    self.rate = rate\n    self.suffix = suffix\n  }\n\n  static func shake128() -> KeccakSponge { KeccakSponge(rate: 168, suffix: 0x1F) }\n  static func shake256() -> KeccakSponge { KeccakSponge(rate: 136, suffix: 0x1F) }\n\n  private static let roundConstants: [UInt64] = [\n    0x0000_0000_0000_0001, 0x0000_0000_0000_8082, 0x8000_0000_0000_808A, 0x8000_0000_8000_8000,\n    0x0000_0000_0000_808B, 0x0000_0000_8000_0001, 0x8000_0000_8000_8081, 0x8000_0000_0000_8009,\n    0x0000_0000_0000_008A, 0x0000_0000_0000_0088, 0x0000_0000_8000_8009, 0x0000_0000_8000_000A,\n    0x0000_0000_8000_808B, 0x8000_0000_0000_008B, 0x8000_0000_0000_8089, 0x8000_0000_0000_8003,\n    0x8000_0000_0000_8002, 0x8000_0000_0000_0080, 0x0000_0000_0000_800A, 0x8000_0000_8000_000A,\n    0x8000_0000_8000_8081, 0x8000_0000_0000_8080, 0x0000_0000_8000_0001, 0x8000_0000_8000_8008,\n  ]\n\n  /// Keccak-f[1600] on 25 locals, unrolled: fast even in debug builds.\n  private mutating func permute() {\n    var a0 = state[0]\n    var a1 = state[1]\n    var a2 = state[2]\n    var a3 = state[3]\n    var a4 = state[4]\n    var a5 = state[5]\n    var a6 = state[6]\n    var a7 = state[7]\n    var a8 = state[8]\n    var a9 = state[9]\n    var a10 = state[10]\n    var a11 = state[11]\n    var a12 = state[12]\n    var a13 = state[13]\n    var a14 = state[14]\n    var a15 = state[15]\n    var a16 = state[16]\n    var a17 = state[17]\n    var a18 = state[18]\n    var a19 = state[19]\n    var a20 = state[20]\n    var a21 = state[21]\n    var a22 = state[22]\n    var a23 = state[23]\n    var a24 = state[24]\n    for round in 0..<24 {\n      let c0 = a0 ^ a5 ^ a10 ^ a15 ^ a20\n      let c1 = a1 ^ a6 ^ a11 ^ a16 ^ a21\n      let c2 = a2 ^ a7 ^ a12 ^ a17 ^ a22\n      let c3 = a3 ^ a8 ^ a13 ^ a18 ^ a23\n      let c4 = a4 ^ a9 ^ a14 ^ a19 ^ a24\n      let d0 = c4 ^ ((c1 << 1) | (c1 >> 63))\n      let d1 = c0 ^ ((c2 << 1) | (c2 >> 63))\n      let d2 = c1 ^ ((c3 << 1) | (c3 >> 63))\n      let d3 = c2 ^ ((c4 << 1) | (c4 >> 63))\n      let d4 = c3 ^ ((c0 << 1) | (c0 >> 63))\n      a0 ^= d0\n      a1 ^= d1\n      a2 ^= d2\n      a3 ^= d3\n      a4 ^= d4\n      a5 ^= d0\n      a6 ^= d1\n      a7 ^= d2\n      a8 ^= d3\n      a9 ^= d4\n      a10 ^= d0\n      a11 ^= d1\n      a12 ^= d2\n      a13 ^= d3\n      a14 ^= d4\n      a15 ^= d0\n      a16 ^= d1\n      a17 ^= d2\n      a18 ^= d3\n      a19 ^= d4\n      a20 ^= d0\n      a21 ^= d1\n      a22 ^= d2\n      a23 ^= d3\n      a24 ^= d4\n      let b0 = a0\n      let b16 = (a5 << 36) | (a5 >> 28)\n      let b7 = (a10 << 3) | (a10 >> 61)\n      let b23 = (a15 << 41) | (a15 >> 23)\n      let b14 = (a20 << 18) | (a20 >> 46)\n      let b10 = (a1 << 1) | (a1 >> 63)\n      let b1 = (a6 << 44) | (a6 >> 20)\n      let b17 = (a11 << 10) | (a11 >> 54)\n      let b8 = (a16 << 45) | (a16 >> 19)\n      let b24 = (a21 << 2) | (a21 >> 62)\n      let b20 = (a2 << 62) | (a2 >> 2)\n      let b11 = (a7 << 6) | (a7 >> 58)\n      let b2 = (a12 << 43) | (a12 >> 21)\n      let b18 = (a17 << 15) | (a17 >> 49)\n      let b9 = (a22 << 61) | (a22 >> 3)\n      let b5 = (a3 << 28) | (a3 >> 36)\n      let b21 = (a8 << 55) | (a8 >> 9)\n      let b12 = (a13 << 25) | (a13 >> 39)\n      let b3 = (a18 << 21) | (a18 >> 43)\n      let b19 = (a23 << 56) | (a23 >> 8)\n      let b15 = (a4 << 27) | (a4 >> 37)\n      let b6 = (a9 << 20) | (a9 >> 44)\n      let b22 = (a14 << 39) | (a14 >> 25)\n      let b13 = (a19 << 8) | (a19 >> 56)\n      let b4 = (a24 << 14) | (a24 >> 50)\n      a0 = b0 ^ (~b1 & b2)\n      a1 = b1 ^ (~b2 & b3)\n      a2 = b2 ^ (~b3 & b4)\n      a3 = b3 ^ (~b4 & b0)\n      a4 = b4 ^ (~b0 & b1)\n      a5 = b5 ^ (~b6 & b7)\n      a6 = b6 ^ (~b7 & b8)\n      a7 = b7 ^ (~b8 & b9)\n      a8 = b8 ^ (~b9 & b5)\n      a9 = b9 ^ (~b5 & b6)\n      a10 = b10 ^ (~b11 & b12)\n      a11 = b11 ^ (~b12 & b13)\n      a12 = b12 ^ (~b13 & b14)\n      a13 = b13 ^ (~b14 & b10)\n      a14 = b14 ^ (~b10 & b11)\n      a15 = b15 ^ (~b16 & b17)\n      a16 = b16 ^ (~b17 & b18)\n      a17 = b17 ^ (~b18 & b19)\n      a18 = b18 ^ (~b19 & b15)\n      a19 = b19 ^ (~b15 & b16)\n      a20 = b20 ^ (~b21 & b22)\n      a21 = b21 ^ (~b22 & b23)\n      a22 = b22 ^ (~b23 & b24)\n      a23 = b23 ^ (~b24 & b20)\n      a24 = b24 ^ (~b20 & b21)\n      a0 ^= KeccakSponge.roundConstants[round]\n    }\n    state[0] = a0\n    state[1] = a1\n    state[2] = a2\n    state[3] = a3\n    state[4] = a4\n    state[5] = a5\n    state[6] = a6\n    state[7] = a7\n    state[8] = a8\n    state[9] = a9\n    state[10] = a10\n    state[11] = a11\n    state[12] = a12\n    state[13] = a13\n    state[14] = a14\n    state[15] = a15\n    state[16] = a16\n    state[17] = a17\n    state[18] = a18\n    state[19] = a19\n    state[20] = a20\n    state[21] = a21\n    state[22] = a22\n    state[23] = a23\n    state[24] = a24\n  }\n\n  private mutating func xorByte(_ byte: UInt8, at index: Int) {\n    state[index >> 3] ^= UInt64(byte) << (UInt64(index & 7) * 8)\n  }\n\n  private func byte(at index: Int) -> UInt8 {\n    UInt8(truncatingIfNeeded: state[index >> 3] >> (UInt64(index & 7) * 8))\n  }\n\n  /// Absorb more input; it must come before any squeeze.\n  mutating func absorb(_ bytes: [UInt8]) {\n    precondition(!squeezing, \"absorb after squeeze\")\n    var index = 0\n    while index < bytes.count {\n      // Absorb up to the end of the block, then permute.\n      let take = min(rate - position, bytes.count - index)\n      var position = self.position\n      state.withUnsafeMutableBufferPointer { lanes in\n        bytes.withUnsafeBufferPointer { input in\n          for i in index..<(index + take) {\n            lanes[position >> 3] ^= UInt64(input[i]) << (UInt64(position & 7) * 8)\n            position += 1\n          }\n        }\n      }\n      index += take\n      if position == rate {\n        permute()\n        position = 0\n      }\n      self.position = position\n    }\n  }\n\n  mutating func absorb(_ byte: UInt8) {\n    absorb([byte])\n  }\n\n  /// The next bytes of output.\n  mutating func squeeze(_ count: Int) -> [UInt8] {\n    if !squeezing {\n      xorByte(suffix, at: position)\n      xorByte(0x80, at: rate - 1)\n      permute()\n      position = 0\n      squeezing = true\n    }\n    var out = [UInt8](repeating: 0, count: max(0, count))\n    for i in 0..<out.count {\n      if position == rate {\n        permute()\n        position = 0\n      }\n      out[i] = byte(at: position)\n      position += 1\n    }\n    return out\n  }\n}\n\n/// The FIPS 202 functions, over byte arrays.\nenum Keccak {\n  static func shake256(_ message: [UInt8], _ count: Int) -> [UInt8] {\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(message)\n    return sponge.squeeze(count)\n  }\n\n  static func shake128(_ message: [UInt8], _ count: Int) -> [UInt8] {\n    var sponge = KeccakSponge.shake128()\n    sponge.absorb(message)\n    return sponge.squeeze(count)\n  }\n\n  static func sha3_256(_ message: [UInt8]) -> [UInt8] {\n    var sponge = KeccakSponge(rate: 136, suffix: 0x06)\n    sponge.absorb(message)\n    return sponge.squeeze(32)\n  }\n\n  static func sha3_512(_ message: [UInt8]) -> [UInt8] {\n    var sponge = KeccakSponge(rate: 72, suffix: 0x06)\n    sponge.absorb(message)\n    return sponge.squeeze(64)\n  }\n}\n"
swiftSource "LawSpecRuntime/MLDSA.swift" = "// ML-DSA-65 (FIPS 204) in pure Swift: the fallback for what CryptoKit keeps\n// inside its keys. CryptoKit holds an ML-DSA key as its 32-byte seed, never\n// exposes the expanded private key, and always hedges its signatures with\n// fresh randomness. Known-answer tests need the expanded key and the\n// deterministic signature, so this module provides key generation and\n// signing; verification and hedged signing go through CryptoKit (see\n// CryptoPrimitives).\n\n/// FIPS 204's ML-DSA-65, the parts CryptoKit does not expose.\nenum MLDSA65Fallback {\n  static let q = 8_380_417\n  static let d = 13\n  static let tau = 49\n  static let challengeBytes = 48\n  static let gamma1 = 1 << 19\n  static let gamma2 = (8_380_417 - 1) / 32\n  static let k = 6\n  static let l = 5\n  static let eta = 4\n  static let beta = 196\n  static let omega = 55\n  static let publicKeyLength = 1952\n  static let privateKeyLength = 4032\n  static let signatureLength = 3309\n\n  typealias Polynomial = [Int]\n\n  /// 1753^BitRev8(i) mod q, for the NTT.\n  static let zetas: [Int] = (0..<256).map { power(1753, bitReverse8($0)) }\n\n  private static func bitReverse8(_ value: Int) -> Int {\n    var result = 0\n    for bit in 0..<8 where value & (1 << bit) != 0 {\n      result |= 1 << (7 - bit)\n    }\n    return result\n  }\n\n  private static func power(_ base: Int, _ exponent: Int) -> Int {\n    var result = 1\n    for _ in 0..<exponent {\n      result = result * base % q\n    }\n    return result\n  }\n\n  private static func reduce(_ value: Int) -> Int {\n    let r = value % q\n    return r < 0 ? r + q : r\n  }\n\n  /// The representative of r mod alpha in (-alpha/2, alpha/2].\n  private static func centered(_ r: Int, _ alpha: Int) -> Int {\n    var r0 = r % alpha\n    if r0 < 0 { r0 += alpha }\n    if r0 > alpha / 2 { r0 -= alpha }\n    return r0\n  }\n\n  private static func h(_ bytes: [UInt8], _ count: Int) -> [UInt8] { Keccak.shake256(bytes, count) }\n\n  // MARK: NTT\n\n  private static func ntt(_ input: Polynomial) -> Polynomial {\n    var w = input\n    var m = 0\n    var length = 128\n    while length >= 1 {\n      var start = 0\n      while start < 256 {\n        m += 1\n        let zeta = zetas[m]\n        for j in start..<(start + length) {\n          let t = zeta * w[j + length] % q\n          w[j + length] = reduce(w[j] - t)\n          w[j] = (w[j] + t) % q\n        }\n        start += 2 * length\n      }\n      length /= 2\n    }\n    return w\n  }\n\n  private static func inverseNTT(_ input: Polynomial) -> Polynomial {\n    var w = input\n    var m = 256\n    var length = 1\n    while length < 256 {\n      var start = 0\n      while start < 256 {\n        m -= 1\n        let zeta = q - zetas[m]\n        for j in start..<(start + length) {\n          let t = w[j]\n          w[j] = (t + w[j + length]) % q\n          w[j + length] = zeta * reduce(t - w[j + length]) % q\n        }\n        start += 2 * length\n      }\n      length *= 2\n    }\n    return w.map { $0 * 8_347_681 % q }\n  }\n\n  private static func multiply(_ f: Polynomial, _ g: Polynomial) -> Polynomial {\n    (0..<256).map { f[$0] * g[$0] % q }\n  }\n\n  private static func add(_ f: Polynomial, _ g: Polynomial) -> Polynomial {\n    (0..<256).map { (f[$0] + g[$0]) % q }\n  }\n\n  private static func subtract(_ f: Polynomial, _ g: Polynomial) -> Polynomial {\n    (0..<256).map { reduce(f[$0] - g[$0]) }\n  }\n\n  // MARK: Sampling\n\n  private static func rejectNTTPolynomial(_ seed: [UInt8]) -> Polynomial {\n    var sponge = KeccakSponge.shake128()\n    sponge.absorb(seed)\n    var result = Polynomial(repeating: 0, count: 256)\n    var count = 0\n    while count < 256 {\n      let bytes = sponge.squeeze(168)\n      var index = 0\n      while index + 3 <= bytes.count && count < 256 {\n        let value =\n          Int(bytes[index]) | Int(bytes[index + 1]) << 8 | (Int(bytes[index + 2]) & 0x7F) << 16\n        if value < q {\n          result[count] = value\n          count += 1\n        }\n        index += 3\n      }\n    }\n    return result\n  }\n\n  private static func rejectBoundedPolynomial(_ seed: [UInt8]) -> Polynomial {\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(seed)\n    var result = Polynomial(repeating: 0, count: 256)\n    var count = 0\n    while count < 256 {\n      for byte in sponge.squeeze(136) where count < 256 {\n        let low = Int(byte & 0x0F)\n        let high = Int(byte >> 4)\n        if low < 9 {\n          result[count] = reduce(eta - low)\n          count += 1\n        }\n        if high < 9 && count < 256 {\n          result[count] = reduce(eta - high)\n          count += 1\n        }\n      }\n    }\n    return result\n  }\n\n  private static func expandA(_ rho: [UInt8]) -> [[Polynomial]] {\n    (0..<k).map { r in (0..<l).map { s in rejectNTTPolynomial(rho + [UInt8(s), UInt8(r)]) } }\n  }\n\n  private static func twoBytes(_ value: Int) -> [UInt8] {\n    [UInt8(value & 0xFF), UInt8(value >> 8)]\n  }\n\n  private static func expandMask(_ rho: [UInt8], _ offset: Int) -> [Polynomial] {\n    (0..<l).map { r in\n      let bytes = h(rho + twoBytes(offset + r), 32 * 20)\n      return unpack(bytes[...], 20).map { reduce(gamma1 - $0) }\n    }\n  }\n\n  private static func sampleInBall(_ seed: [UInt8]) -> Polynomial {\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(seed)\n    let signs = sponge.squeeze(8)\n    var c = Polynomial(repeating: 0, count: 256)\n    var bit = 0\n    for i in (256 - tau)..<256 {\n      var j = Int(sponge.squeeze(1)[0])\n      while j > i {\n        j = Int(sponge.squeeze(1)[0])\n      }\n      c[i] = c[j]\n      let negative = (signs[bit >> 3] >> UInt8(bit & 7)) & 1 == 1\n      c[j] = negative ? q - 1 : 1\n      bit += 1\n    }\n    return c\n  }\n\n  // MARK: Packing\n\n  /// Values of a given bit width, packed little-endian.\n  private static func pack(_ values: [Int], _ width: Int) -> [UInt8] {\n    var out = [UInt8](repeating: 0, count: values.count * width / 8)\n    var bitIndex = 0\n    for value in values {\n      for b in 0..<width {\n        if (value >> b) & 1 == 1 {\n          out[bitIndex >> 3] |= UInt8(1) << UInt8(bitIndex & 7)\n        }\n        bitIndex += 1\n      }\n    }\n    return out\n  }\n\n  private static func unpack(_ bytes: ArraySlice<UInt8>, _ width: Int) -> [Int] {\n    let base = bytes.startIndex\n    var result = [Int](repeating: 0, count: 256)\n    var bitIndex = 0\n    for i in 0..<256 {\n      var value = 0\n      for b in 0..<width {\n        value |= (Int(bytes[base + (bitIndex >> 3)] >> UInt8(bitIndex & 7)) & 1) << b\n        bitIndex += 1\n      }\n      result[i] = value\n    }\n    return result\n  }\n\n  /// BitPack(w, a, b): each b - w, in the width of a + b.\n  private static func packBetween(_ f: Polynomial, _ upper: Int, _ width: Int) -> [UInt8] {\n    pack(f.map { upper - centered($0, q) }, width)\n  }\n\n  private static func power2Round(_ r: Int) -> (high: Int, low: Int) {\n    let low = centered(r, 1 << d)\n    return ((r - low) >> d, low)\n  }\n\n  private static func decompose(_ r: Int) -> (high: Int, low: Int) {\n    var low = centered(r, 2 * gamma2)\n    if r - low == q - 1 {\n      low -= 1\n      return (0, low)\n    }\n    return ((r - low) / (2 * gamma2), low)\n  }\n\n  private static func infinityNorm(_ f: Polynomial) -> Int {\n    f.reduce(0) { max($0, abs(centered($1, q))) }\n  }\n\n  // MARK: ML-DSA\n\n  private struct Expanded {\n    let rho: [UInt8]\n    let key: [UInt8]\n    let tr: [UInt8]\n    let s1: [Polynomial]\n    let s2: [Polynomial]\n    let t0: [Polynomial]\n    let publicKey: [UInt8]\n  }\n\n  private static func expand(_ seed: [UInt8]) -> Expanded {\n    let expanded = h(seed + [UInt8(k), UInt8(l)], 128)\n    let rho = Array(expanded[0..<32])\n    let rhoPrime = Array(expanded[32..<96])\n    let key = Array(expanded[96..<128])\n    let a = expandA(rho)\n    let s1 = (0..<l).map { rejectBoundedPolynomial(rhoPrime + twoBytes($0)) }\n    let s2 = (0..<k).map { rejectBoundedPolynomial(rhoPrime + twoBytes($0 + l)) }\n    let s1Hat = s1.map(ntt)\n    var publicKey = rho\n    var t0: [Polynomial] = []\n    for i in 0..<k {\n      var sum = Polynomial(repeating: 0, count: 256)\n      for j in 0..<l {\n        sum = add(sum, multiply(a[i][j], s1Hat[j]))\n      }\n      let t = add(inverseNTT(sum), s2[i])\n      let rounded = t.map(power2Round)\n      publicKey += pack(rounded.map { $0.high }, 10)\n      t0.append(rounded.map { reduce($0.low) })\n    }\n    return Expanded(\n      rho: rho, key: key, tr: h(publicKey, 64), s1: s1, s2: s2, t0: t0, publicKey: publicKey)\n  }\n\n  /// The public key and the expanded private key of a 32-byte seed.\n  static func keyGen(_ seed: [UInt8]) -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    let e = expand(seed)\n    var privateKey = e.rho + e.key + e.tr\n    for s in e.s1 { privateKey += packBetween(s, eta, 4) }\n    for s in e.s2 { privateKey += packBetween(s, eta, 4) }\n    for t in e.t0 { privateKey += packBetween(t, 1 << (d - 1), 13) }\n    return (e.publicKey, privateKey)\n  }\n\n  /// Sign with a context string. A deterministic signature uses 32 zero\n  /// bytes as its randomness; a hedged one uses fresh bytes.\n  static func sign(_ seed: [UInt8], _ message: [UInt8], _ context: [UInt8], randomness: [UInt8])\n    -> [UInt8]\n  {\n    let e = expand(seed)\n    let a = expandA(e.rho)\n    let s1Hat = e.s1.map(ntt)\n    let s2Hat = e.s2.map(ntt)\n    let t0Hat = e.t0.map(ntt)\n    let prefixed = [0, UInt8(context.count)] + context + message\n    let mu = h(e.tr + prefixed, 64)\n    let rhoPrimePrime = h(e.key + randomness + mu, 64)\n    var kappa = 0\n    while true {\n      let y = expandMask(rhoPrimePrime, kappa)\n      kappa += l\n      let yHat = y.map(ntt)\n      var w: [Polynomial] = []\n      for i in 0..<k {\n        var sum = Polynomial(repeating: 0, count: 256)\n        for j in 0..<l {\n          sum = add(sum, multiply(a[i][j], yHat[j]))\n        }\n        w.append(inverseNTT(sum))\n      }\n      var w1Encoded: [UInt8] = []\n      for wi in w {\n        w1Encoded += pack(wi.map { decompose($0).high }, 4)\n      }\n      let challenge = h(mu + w1Encoded, challengeBytes)\n      let cHat = ntt(sampleInBall(challenge))\n      let z = (0..<l).map { add(y[$0], inverseNTT(multiply(cHat, s1Hat[$0]))) }\n      if z.contains(where: { infinityNorm($0) >= gamma1 - beta }) { continue }\n      let r = (0..<k).map { subtract(w[$0], inverseNTT(multiply(cHat, s2Hat[$0]))) }\n      if r.contains(where: { $0.contains { abs(decompose($0).low) >= gamma2 - beta } }) { continue }\n      let ct0 = (0..<k).map { inverseNTT(multiply(cHat, t0Hat[$0])) }\n      if ct0.contains(where: { infinityNorm($0) >= gamma2 }) { continue }\n      var hints: [[Bool]] = []\n      var ones = 0\n      for i in 0..<k {\n        var row: [Bool] = []\n        let shifted = add(r[i], ct0[i])\n        for j in 0..<256 {\n          let base = shifted[j]\n          let hint = decompose(base).high != decompose(reduce(base - ct0[i][j])).high\n          if hint { ones += 1 }\n          row.append(hint)\n        }\n        hints.append(row)\n      }\n      if ones > omega { continue }\n      var signature = challenge\n      for zi in z { signature += packBetween(zi, gamma1, 20) }\n      var hintBytes = [UInt8](repeating: 0, count: omega + k)\n      var index = 0\n      for i in 0..<k {\n        for j in 0..<256 where hints[i][j] {\n          hintBytes[index] = UInt8(j)\n          index += 1\n        }\n        hintBytes[omega + i] = UInt8(index)\n      }\n      return signature + hintBytes\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/MLKEM.swift" = "// ML-KEM-768 (FIPS 203) in pure Swift: the fallback for what CryptoKit\n// keeps inside its keys. CryptoKit holds an ML-KEM key as its 64-byte seed and\n// never exposes the expanded decapsulation key, cannot decapsulate with one,\n// and always draws an encapsulation's message at random. Known-answer tests\n// need all three, so this module provides them; everything else goes through\n// CryptoKit (see CryptoPrimitives).\n\n/// FIPS 203's ML-KEM-768, the parts CryptoKit does not expose.\nenum MLKEM768Fallback {\n  static let q = 3329\n  static let k = 3\n  static let eta1 = 2\n  static let eta2 = 2\n  static let du = 10\n  static let dv = 4\n  static let publicKeyLength = 384 * 3 + 32\n  static let privateKeyLength = 768 * 3 + 96\n  static let ciphertextLength = 32 * (10 * 3 + 4)\n\n  typealias Polynomial = [Int]\n\n  /// zeta^BitRev7(i) mod q, for the NTT.\n  static let zetas: [Int] = (0..<128).map { power(17, bitReverse7($0)) }\n  /// zeta^(2 BitRev7(i) + 1) mod q, for multiplication in the NTT domain.\n  static let gammas: [Int] = (0..<128).map { power(17, 2 * bitReverse7($0) + 1) }\n\n  private static func bitReverse7(_ value: Int) -> Int {\n    var result = 0\n    for bit in 0..<7 where value & (1 << bit) != 0 {\n      result |= 1 << (6 - bit)\n    }\n    return result\n  }\n\n  private static func power(_ base: Int, _ exponent: Int) -> Int {\n    var result = 1\n    for _ in 0..<exponent {\n      result = result * base % q\n    }\n    return result\n  }\n\n  private static func reduce(_ value: Int) -> Int {\n    let r = value % q\n    return r < 0 ? r + q : r\n  }\n\n  // MARK: Hashes\n\n  private static func h(_ bytes: [UInt8]) -> [UInt8] { Keccak.sha3_256(bytes) }\n  private static func g(_ bytes: [UInt8]) -> ([UInt8], [UInt8]) {\n    let digest = Keccak.sha3_512(bytes)\n    return (Array(digest[0..<32]), Array(digest[32..<64]))\n  }\n  private static func prf(_ eta: Int, _ seed: [UInt8], _ nonce: UInt8) -> [UInt8] {\n    Keccak.shake256(seed + [nonce], 64 * eta)\n  }\n\n  // MARK: Sampling\n\n  /// A uniform polynomial in the NTT domain from a seed and two indices.\n  private static func sampleNTT(_ rho: [UInt8], _ j: UInt8, _ i: UInt8) -> Polynomial {\n    var sponge = KeccakSponge.shake128()\n    sponge.absorb(rho + [j, i])\n    var result = Polynomial(repeating: 0, count: 256)\n    var count = 0\n    while count < 256 {\n      let c = sponge.squeeze(168)\n      var index = 0\n      while index + 3 <= c.count && count < 256 {\n        let d1 = Int(c[index]) + 256 * (Int(c[index + 1]) & 0x0F)\n        let d2 = (Int(c[index + 1]) >> 4) + 16 * Int(c[index + 2])\n        if d1 < q {\n          result[count] = d1\n          count += 1\n        }\n        if d2 < q && count < 256 {\n          result[count] = d2\n          count += 1\n        }\n        index += 3\n      }\n    }\n    return result\n  }\n\n  /// A centered binomial polynomial from 64 eta bytes.\n  private static func sampleCBD(_ eta: Int, _ bytes: [UInt8]) -> Polynomial {\n    var result = Polynomial(repeating: 0, count: 256)\n    func bit(_ index: Int) -> Int { Int(bytes[index >> 3] >> UInt8(index & 7)) & 1 }\n    for i in 0..<256 {\n      var x = 0\n      var y = 0\n      for j in 0..<eta {\n        x += bit(2 * i * eta + j)\n        y += bit(2 * i * eta + eta + j)\n      }\n      result[i] = reduce(x - y)\n    }\n    return result\n  }\n\n  // MARK: NTT\n\n  private static func ntt(_ input: Polynomial) -> Polynomial {\n    var f = input\n    var index = 1\n    var length = 128\n    while length >= 2 {\n      var start = 0\n      while start < 256 {\n        let zeta = zetas[index]\n        index += 1\n        for j in start..<(start + length) {\n          let t = zeta * f[j + length] % q\n          f[j + length] = reduce(f[j] - t)\n          f[j] = (f[j] + t) % q\n        }\n        start += 2 * length\n      }\n      length /= 2\n    }\n    return f\n  }\n\n  private static func inverseNTT(_ input: Polynomial) -> Polynomial {\n    var f = input\n    var index = 127\n    var length = 2\n    while length <= 128 {\n      var start = 0\n      while start < 256 {\n        let zeta = zetas[index]\n        index -= 1\n        for j in start..<(start + length) {\n          let t = f[j]\n          f[j] = (t + f[j + length]) % q\n          f[j + length] = zeta * reduce(f[j + length] - t) % q\n        }\n        start += 2 * length\n      }\n      length *= 2\n    }\n    return f.map { $0 * 3303 % q }\n  }\n\n  private static func multiplyNTT(_ f: Polynomial, _ g: Polynomial) -> Polynomial {\n    var result = Polynomial(repeating: 0, count: 256)\n    for i in 0..<128 {\n      let a0 = f[2 * i]\n      let a1 = f[2 * i + 1]\n      let b0 = g[2 * i]\n      let b1 = g[2 * i + 1]\n      result[2 * i] = (a0 * b0 + (a1 * b1 % q) * gammas[i]) % q\n      result[2 * i + 1] = (a0 * b1 + a1 * b0) % q\n    }\n    return result\n  }\n\n  private static func add(_ f: Polynomial, _ g: Polynomial) -> Polynomial {\n    (0..<256).map { (f[$0] + g[$0]) % q }\n  }\n\n  // MARK: Encoding\n\n  private static func encode(_ d: Int, _ f: Polynomial) -> [UInt8] {\n    var out = [UInt8](repeating: 0, count: 32 * d)\n    var bitIndex = 0\n    for value in f {\n      for b in 0..<d {\n        if (value >> b) & 1 == 1 {\n          out[bitIndex >> 3] |= UInt8(1) << UInt8(bitIndex & 7)\n        }\n        bitIndex += 1\n      }\n    }\n    return out\n  }\n\n  private static func decode(_ d: Int, _ bytes: ArraySlice<UInt8>) -> Polynomial {\n    let base = bytes.startIndex\n    var result = Polynomial(repeating: 0, count: 256)\n    var bitIndex = 0\n    for i in 0..<256 {\n      var value = 0\n      for b in 0..<d {\n        let bit = Int(bytes[base + (bitIndex >> 3)] >> UInt8(bitIndex & 7)) & 1\n        value |= bit << b\n        bitIndex += 1\n      }\n      result[i] = d == 12 ? value % q : value\n    }\n    return result\n  }\n\n  private static func compress(_ d: Int, _ f: Polynomial) -> Polynomial {\n    // round(2^d x / q) mod 2^d, in integers.\n    f.map { (((($0 << d) * 2) + q) / (2 * q)) & ((1 << d) - 1) }\n  }\n\n  private static func decompress(_ d: Int, _ f: Polynomial) -> Polynomial {\n    // round(q y / 2^d), in integers.\n    f.map { ($0 * q * 2 + (1 << d)) >> (d + 1) }\n  }\n\n  // MARK: K-PKE\n\n  private static func matrix(_ rho: [UInt8]) -> [[Polynomial]] {\n    (0..<k).map { i in (0..<k).map { j in sampleNTT(rho, UInt8(j), UInt8(i)) } }\n  }\n\n  private static func pkeKeyGen(_ d: [UInt8]) -> (ek: [UInt8], dk: [UInt8]) {\n    let (rho, sigma) = g(d + [UInt8(k)])\n    let a = matrix(rho)\n    var nonce: UInt8 = 0\n    var s: [Polynomial] = []\n    var e: [Polynomial] = []\n    for _ in 0..<k {\n      s.append(ntt(sampleCBD(eta1, prf(eta1, sigma, nonce))))\n      nonce += 1\n    }\n    for _ in 0..<k {\n      e.append(ntt(sampleCBD(eta1, prf(eta1, sigma, nonce))))\n      nonce += 1\n    }\n    var ek: [UInt8] = []\n    var dk: [UInt8] = []\n    for i in 0..<k {\n      var t = e[i]\n      for j in 0..<k {\n        t = add(t, multiplyNTT(a[i][j], s[j]))\n      }\n      ek += encode(12, t)\n      dk += encode(12, s[i])\n    }\n    return (ek + rho, dk)\n  }\n\n  private static func pkeEncrypt(_ ek: [UInt8], _ message: [UInt8], _ randomness: [UInt8])\n    -> [UInt8]\n  {\n    let t = (0..<k).map { decode(12, ek[(384 * $0)..<(384 * $0 + 384)]) }\n    let rho = Array(ek[(384 * k)...])\n    let a = matrix(rho)\n    var nonce: UInt8 = 0\n    var y: [Polynomial] = []\n    for _ in 0..<k {\n      y.append(ntt(sampleCBD(eta1, prf(eta1, randomness, nonce))))\n      nonce += 1\n    }\n    var e1: [Polynomial] = []\n    for _ in 0..<k {\n      e1.append(sampleCBD(eta2, prf(eta2, randomness, nonce)))\n      nonce += 1\n    }\n    let e2 = sampleCBD(eta2, prf(eta2, randomness, nonce))\n    var c1: [UInt8] = []\n    for i in 0..<k {\n      var sum = Polynomial(repeating: 0, count: 256)\n      for j in 0..<k {\n        sum = add(sum, multiplyNTT(a[j][i], y[j]))\n      }\n      c1 += encode(du, compress(du, add(inverseNTT(sum), e1[i])))\n    }\n    var sum = Polynomial(repeating: 0, count: 256)\n    for j in 0..<k {\n      sum = add(sum, multiplyNTT(t[j], y[j]))\n    }\n    let mu = decompress(1, decode(1, message[...]))\n    let v = add(add(inverseNTT(sum), e2), mu)\n    return c1 + encode(dv, compress(dv, v))\n  }\n\n  private static func pkeDecrypt(_ dk: ArraySlice<UInt8>, _ ciphertext: [UInt8]) -> [UInt8] {\n    let base = dk.startIndex\n    let u = (0..<k).map {\n      decompress(du, decode(du, ciphertext[(32 * du * $0)..<(32 * du * ($0 + 1))]))\n    }\n    let v = decompress(dv, decode(dv, ciphertext[(32 * du * k)...]))\n    let s = (0..<k).map { decode(12, dk[(base + 384 * $0)..<(base + 384 * $0 + 384)]) }\n    var sum = Polynomial(repeating: 0, count: 256)\n    for i in 0..<k {\n      sum = add(sum, multiplyNTT(s[i], ntt(u[i])))\n    }\n    let product = inverseNTT(sum)\n    let w = (0..<256).map { reduce(v[$0] - product[$0]) }\n    return encode(1, compress(1, w))\n  }\n\n  // MARK: ML-KEM\n\n  /// The encapsulation key and the expanded decapsulation key of d || z.\n  static func keyGen(_ seed: [UInt8]) -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    let d = Array(seed[0..<32])\n    let z = Array(seed[32..<64])\n    let (ek, dkPke) = pkeKeyGen(d)\n    return (ek, dkPke + ek + h(ek) + z)\n  }\n\n  /// Whether an encapsulation key passes FIPS 203's modulus check.\n  static func validPublicKey(_ ek: [UInt8]) -> Bool {\n    guard ek.count == publicKeyLength else { return false }\n    for i in 0..<k {\n      let slice = ek[(384 * i)..<(384 * i + 384)]\n      if encode(12, decode(12, slice)) != Array(slice) { return false }\n    }\n    return true\n  }\n\n  /// Deterministic encapsulation with the 32-byte message m.\n  static func encapsulate(_ ek: [UInt8], _ message: [UInt8]) -> (\n    ciphertext: [UInt8], shared: [UInt8]\n  ) {\n    let (shared, randomness) = g(message + h(ek))\n    return (pkeEncrypt(ek, message, randomness), shared)\n  }\n\n  /// Decapsulation with an expanded decapsulation key, rejecting implicitly.\n  static func decapsulate(_ dk: [UInt8], _ ciphertext: [UInt8]) -> [UInt8] {\n    let dkPke = dk[0..<(384 * k)]\n    let ek = Array(dk[(384 * k)..<(768 * k + 32)])\n    let hash = Array(dk[(768 * k + 32)..<(768 * k + 64)])\n    let z = Array(dk[(768 * k + 64)..<(768 * k + 96)])\n    let message = pkeDecrypt(dkPke, ciphertext)\n    let (shared, randomness) = g(message + hash)\n    let rejected = Keccak.shake256(z + ciphertext, 32)\n    let again = pkeEncrypt(ek, message, randomness)\n    // Constant-time selection of the shared or the rejection secret.\n    var difference: UInt8 = 0\n    for i in 0..<ciphertext.count {\n      difference |= ciphertext[i] ^ again[i]\n    }\n    let mask = UInt8(truncatingIfNeeded: -Int(difference != 0 ? 1 : 0))\n    return (0..<32).map { (shared[$0] & ~mask) | (rejected[$0] & mask) }\n  }\n}\n"
swiftSource "LawSpecRuntime/Mailbox.swift" = "// A typed mailbox of portable values. Native conversion runs in the caller;\n// the queue never runs application code. Closing refuses new sends and lets\n// accepted values drain. A served mailbox belongs to its node, and a remote\n// send completes once the mailbox has the value.\n// ref:DEC-actors-otp-supervision ref:DEC-distribution-canonical-wire\n\nimport Foundation\n\npublic final class Mailbox: NodeService, @unchecked Sendable {\n  private final class Waiter {\n    let done = DispatchSemaphore(value: 0)\n    var result: Result<Value, LawSpecError>?\n  }\n\n  private struct State {\n    var queue: [Value] = []\n    var closed = false\n    var stopped = false\n    var reader: Waiter?\n  }\n\n  private let network: (Node, String, Descriptors.Table, Descriptors.Descriptor)?\n  private let state = Locked(State())\n  private var served: String?\n\n  private static func fail(_ reason: String) -> LawSpecError { Fail.with(\"Mailbox\", reason) }\n\n  /// A local mailbox.\n  public init() { network = nil }\n\n  private init(\n    _ node: Node, _ name: String, _ table: Descriptors.Table, _ d: Descriptors.Descriptor\n  ) throws {\n    network = (node, name, table, d)\n    let box = Locked<Mailbox?>(nil)\n    served = try node.registerReceiver(name) { frame in box.with { $0 }?.incoming(frame) }\n    box.with { $0 = self }\n    node.adopt(self)\n  }\n\n  /// A mailbox served at a name on a node, of values of a descriptor text.\n  public static func serve(_ node: Node, _ name: String, _ descriptor: String) throws -> Mailbox {\n    let (table, d) = try Descriptors.fromText(descriptor)\n    return try Mailbox(node, name, table, d)\n  }\n\n  private func incoming(_ frame: Frame) {\n    guard let (node, _, table, d) = network else { return }\n    let (status, body): (Int, String)\n    if state.with({ $0.closed }) {\n      (status, body) = (2, \"the mailbox is closed\")\n    } else if frame.kind != \"mail\" {\n      (status, body) = (3, \"not a mailbox request\")\n    } else if let value = try? Descriptors.decode(d, frame.payload, table) {\n      enqueue(value)\n      (status, body) = (0, \"\")\n    } else {\n      (status, body) = (3, \"not a message of this mailbox\")\n    }\n    if frame.id != 0 { try? node.reply(frame.source, frame.id, status, Array(body.utf8)) }\n  }\n\n  private func enqueue(_ value: Value) {\n    let waiting: Waiter? = state.with { s in\n      if let r = s.reader {\n        s.reader = nil\n        return r\n      }\n      s.queue.append(value)\n      return nil\n    }\n    if let r = waiting {\n      r.result = .success(value)\n      r.done.signal()\n    }\n  }\n\n  /// The served mailbox's address.\n  public func address() throws -> String {\n    guard let served else { throw Mailbox.fail(\"local_mailbox\") }\n    return served\n  }\n\n  /// Add a value, unless the mailbox is closed.\n  public func send(_ value: Value) throws {\n    try state.with { s in if s.closed || s.stopped { throw Mailbox.fail(\"closed\") } }\n    enqueue(value)\n  }\n\n  /// The next value, waiting until a deadline (seconds from now) or for\n  /// ever: nil when the time passed.\n  private func wait(_ seconds: Double?) throws -> Value? {\n    let pending: Either = try state.with { s in\n      if s.reader != nil { throw Mailbox.fail(\"already_receiving\") }\n      if !s.queue.isEmpty { return .value(s.queue.removeFirst()) }\n      if s.closed || s.stopped { throw Mailbox.fail(\"closed\") }\n      let r = Waiter()\n      s.reader = r\n      return .waiter(r)\n    }\n    guard case .waiter(let r) = pending else {\n      if case .value(let v) = pending { return v }\n      return nil\n    }\n    let finished: Bool\n    if let seconds {\n      finished = seconds > 0 && r.done.wait(timeout: .now() + seconds) == .success\n    } else {\n      r.done.wait()\n      finished = true\n    }\n    if !finished {\n      let raced: Bool = state.with { s in\n        if let current = s.reader, current === r {\n          s.reader = nil\n          return false\n        }\n        return true\n      }\n      if !raced { return nil }\n      r.done.wait()\n    }\n    return try r.result!.get()\n  }\n\n  private enum Either {\n    case value(Value)\n    case waiter(Waiter)\n  }\n\n  /// The next value, waiting for one.\n  public func receive() throws -> Value {\n    guard let value = try wait(nil) else { throw Mailbox.fail(\"closed\") }\n    return value\n  }\n\n  /// The next value within some microseconds, or none (a Maybe).\n  public func receiveWithin(_ micros: BigInt) throws -> Value {\n    let seconds = max(0, micros.doubleValue) / 1_000_000\n    if let value = try wait(seconds) { return .data(\"Maybe::Present\", [value]) }\n    return .data(\"Maybe::Absent\", [])\n  }\n\n  /// As receiveWithin, timed by the Clock in scope: the real clock waits;\n  /// any other clock (the virtual one) takes what is there, then sleeps.\n  public func receiveWithClock(_ micros: BigInt, _ schema: Schema) throws -> Value {\n    func real(_ h: Effects.Handler) -> Bool {\n      switch h {\n      case .recording(_, let inner): return real(inner)\n      case .stateful: return false\n      case .stateless: return true\n      }\n    }\n    let handler = try Effects.handler(schema, \"lawspec.time::ability::Clock\")\n    if real(handler) { return try receiveWithin(micros) }\n    if let value = try wait(0) { return .data(\"Maybe::Present\", [value]) }\n    let duration = Value.data(\n      \"lawspec.time::type::Duration::Duration\", [.int(micros.isNegative ? BigInt(0) : micros)])\n    _ = try Effects.invoke(handler, schema, \"sleep\", [duration])\n    return .data(\"Maybe::Absent\", [])\n  }\n\n  /// The next value within a time, or nil.\n  public func receive(within timeout: Duration) throws -> Value? {\n    try wait(max(0, Timeouts.seconds(timeout)))\n  }\n\n  private func settle(_ r: Waiter?) {\n    if let r {\n      r.result = .failure(Mailbox.fail(\"closed\"))\n      r.done.signal()\n    }\n  }\n\n  /// Refuse new values; accepted ones still drain.\n  public func close() {\n    settle(\n      state.with { s in\n        s.closed = true\n        guard s.queue.isEmpty else { return nil }\n        let r = s.reader\n        s.reader = nil\n        return r\n      })\n  }\n\n  public func release() { stop() }\n\n  /// Stop the mailbox: a waiting reader fails, and a served one leaves its node.\n  public func stop() {\n    settle(\n      state.with { s in\n        s.stopped = true\n        let r = s.reader\n        s.reader = nil\n        return r\n      })\n    if let (node, name, _, _) = network { node.unregister(name) }\n  }\n}\n\n/// Sending to a mailbox on another node.\npublic final class MailboxSender: Sendable {\n  private let node: Node\n  private let address: String\n  private let table: Descriptors.Table\n  private let descriptor: Descriptors.Descriptor\n  private let timeout: Int\n\n  public init(_ node: Node, _ address: String, _ descriptor: String, _ timeout: Int) throws {\n    if timeout <= 0 { throw Fail.with(\"Mailbox\", \"invalid_sender\") }\n    self.node = node\n    self.address = address\n    (table, self.descriptor) = try Descriptors.fromText(descriptor)\n    self.timeout = timeout\n  }\n\n  /// Send, waiting until the mailbox has the value.\n  public func send(_ value: Value) throws {\n    let (status, body) = try node.request(\n      address, \"mail\", try Descriptors.encode(descriptor, value, table), timeout)\n    switch status {\n    case 0: return\n    case 2: throw Fail.with(\"Mailbox\", \"closed\")\n    default: throw Fail.with(\"Mailbox\", \"remote \\(status) \" + String(decoding: body, as: UTF8.self))\n    }\n  }\n}\n\n/// Mailboxes, as generated code opens and uses them.\npublic enum Mailboxes {\n  public static func open() -> Mailbox { Mailbox() }\n\n  /// A mailbox for a body, stopped after it.\n  public static func withMailbox<T>(_ body: (Mailbox) throws -> T) rethrows -> T {\n    let box = Mailbox()\n    defer { box.stop() }\n    return try body(box)\n  }\n\n  public static func serve(_ node: Node, _ name: String, _ descriptor: String) throws -> Mailbox {\n    try Mailbox.serve(node, name, descriptor)\n  }\n\n  public static func connect(_ node: Node, _ address: String, _ descriptor: String, _ timeout: Int)\n    throws -> MailboxSender\n  {\n    try MailboxSender(node, address, descriptor, timeout)\n  }\n}\n\n/// LawSpec Durations as the waits the network and mailboxes take.\npublic enum Timeouts {\n  /// A duration in seconds.\n  public static func seconds(_ d: Duration) -> Double {\n    let (s, atto) = d.components\n    return Double(s) + Double(atto) / 1e18\n  }\n\n  /// A duration in whole milliseconds, at least 0.\n  public static func milliseconds(_ d: Duration) -> Int {\n    let (s, atto) = d.components\n    return max(0, Int(s) * 1000 + Int(atto / 1_000_000_000_000_000))\n  }\n}\n"
swiftSource "LawSpecRuntime/MemoryNetwork.swift" = "// An owned in-memory packet transport with seeded loss, duplication and\n// delay. Frames can overtake each other; reliability belongs to the node and\n// the channel protocol above it, and no application code runs here.\n// ref:DEC-distribution-canonical-wire ref:DEC-portable-seeded-generation\n\nimport Foundation\n\n/// What happened to a frame sent on a memory network.\npublic struct MemoryEvent: Sendable {\n  public let source: String\n  public let to: String\n  public let frame: [UInt8]\n  public let outcome: String\n  /// The delay slots of each copy (two when the frame was duplicated).\n  public let delaySlots: [Int]\n}\n\n/// The options of an in-memory network: a seed for its faults, the chances\n/// of losing and of duplicating a frame, the most a frame is delayed (in\n/// seconds), and whether it records every frame.\npublic struct MemoryOptions: Sendable {\n  public var seed: BigInt\n  public var loss: Double\n  public var duplicate: Double\n  public var delay: Double\n  public var record: Bool\n\n  public init(\n    seed: BigInt = .zero, loss: Double = 0, duplicate: Double = 0, delay: Double = 0,\n    record: Bool = false\n  ) {\n    self.seed = seed\n    self.loss = loss\n    self.duplicate = duplicate\n    self.delay = delay\n    self.record = record\n  }\n}\n\n/// A receiver of a packet's source and bytes.\npublic typealias PacketReceiver = @Sendable (String, [UInt8]) -> Void\n\npublic final class MemoryNetwork: @unchecked Sendable {\n  private struct State {\n    var random: Random.Seed\n    var generation: Int64 = 0\n    // Each registered address: its receiver and the generation it was registered at.\n    var nodes: [String: (PacketReceiver, Int64)] = [:]\n    var groups: [[String]]? = nil\n    var trace: [MemoryEvent] = []\n    var closed = false\n  }\n\n  private let options: MemoryOptions\n  private let state: Locked<State>\n\n  public init(_ options: MemoryOptions) throws {\n    try Fail.require(\n      options.loss >= 0 && options.loss <= 1, \"MemoryNetwork\", \"invalid loss probability\")\n    try Fail.require(\n      options.duplicate >= 0 && options.duplicate <= 1, \"MemoryNetwork\",\n      \"invalid duplicate probability\")\n    try Fail.require(\n      options.delay >= 0 && options.delay <= 4_294_967, \"MemoryNetwork\", \"invalid delay\")\n    self.options = options\n    state = Locked(State(random: Random.seed(options.seed)))\n  }\n\n  /// mem://name for a bare name.\n  public static func addressOf(_ name: String) throws -> String {\n    if name.hasPrefix(\"mem://\") { return name }\n    try Fail.require(!name.isEmpty, \"MemoryNetwork\", \"an empty node name\")\n    return \"mem://\" + name\n  }\n\n  private func chance(_ probability: Double, _ s: inout State) -> Bool {\n    if probability <= 0 { return false }\n    let (draw, next) = Random.below(BigInt(1 << 30), s.random)\n    s.random = next\n    return draw.doubleValue < probability * Double(1 << 30)\n  }\n\n  private func remember(_ event: MemoryEvent, _ s: inout State) {\n    if options.record { s.trace.append(event) }\n  }\n\n  /// Register a receiver at an address: nil, or the reason it was refused.\n  public func register(_ address: String, _ receiver: @escaping PacketReceiver) throws -> String? {\n    let address = try MemoryNetwork.addressOf(address)\n    return state.with { s in\n      if s.closed { return \"network_closed\" }\n      if s.nodes[address] != nil { return \"already_registered\" }\n      s.generation += 1\n      s.nodes[address] = (receiver, s.generation)\n      return nil\n    }\n  }\n\n  public func unregister(_ address: String) {\n    guard let address = try? MemoryNetwork.addressOf(address) else { return }\n    state.with { s in s.nodes[address] = nil }\n  }\n\n  /// Send bytes from one registered address to another: nil, or the reason it failed.\n  public func send(_ source: String, _ destination: String, _ bytes: [UInt8]) throws -> String? {\n    let source = try MemoryNetwork.addressOf(source)\n    let destination = try MemoryNetwork.addressOf(destination)\n    let outcome: Result<[(Int, Int64)], NetworkFailure> = state.with { s in\n      func event(_ outcome: String, _ slots: [Int] = []) -> MemoryEvent {\n        MemoryEvent(\n          source: source, to: destination, frame: bytes, outcome: outcome, delaySlots: slots)\n      }\n      if s.closed || s.nodes[source] == nil { return .failure(NetworkFailure(\"not_node_owner\")) }\n      guard let (_, registered) = s.nodes[destination] else {\n        remember(event(\"unreachable\"), &s)\n        return .failure(NetworkFailure(\"unreachable \" + destination))\n      }\n      let reachable =\n        s.groups.map { gs in gs.contains { $0.contains(source) && $0.contains(destination) } }\n        ?? true\n      if !reachable {\n        remember(event(\"partitioned\"), &s)\n        return .success([])\n      }\n      if chance(options.loss, &s) {\n        remember(event(\"lost\"), &s)\n        return .success([])\n      }\n      let copies = chance(options.duplicate, &s) ? 2 : 1\n      var slots = [Int]()\n      for _ in 0..<copies {\n        let (slot, next) = Random.below(BigInt(1001), s.random)\n        s.random = next\n        slots.append(slot.exactly(Int.self) ?? 0)\n      }\n      remember(event(\"sent\", slots), &s)\n      return .success(slots.map { (Int((Double($0) * options.delay).rounded(.up)), registered) })\n    }\n    switch outcome {\n    case .failure(let reason): return reason.reason\n    case .success(let copies):\n      for (delay, registered) in copies {\n        let deliver: @Sendable () -> Void = { [self] in\n          let receiver: PacketReceiver? = state.with { s in\n            if let (r, g) = s.nodes[destination], g == registered, !s.closed { return r }\n            return nil\n          }\n          receiver?(source, bytes)\n        }\n        if delay <= 0 {\n          DispatchQueue.global().async(execute: deliver)\n        } else {\n          NetworkTimer.after(delay, deliver)\n        }\n      }\n      return nil\n    }\n  }\n\n  /// Only nodes in one group reach each other until healed.\n  public func partition(_ groups: [[String]]) throws {\n    let addressed = try groups.map { try $0.map(MemoryNetwork.addressOf) }\n    state.with { s in s.groups = addressed }\n  }\n\n  public func heal() { state.with { s in s.groups = nil } }\n\n  /// Every frame sent, in order, when recording.\n  public func recorded() -> [[UInt8]] { state.with { s in s.trace.map(\\.frame) } }\n\n  public func trace() -> [MemoryEvent] { state.with { s in s.trace } }\n\n  public func close() {\n    state.with { s in\n      s.closed = true\n      s.nodes.removeAll()\n    }\n  }\n}\n\n/// A failure's reason, as a transport reports it.\nstruct NetworkFailure: Error {\n  let reason: String\n  init(_ reason: String) { self.reason = reason }\n}\n"
swiftSource "LawSpecRuntime/Native.swift" = "// The Swift types LawSpec values take at the native boundary, where Swift has\n// no exact counterpart: exact fractions and decimals, complex numbers, the\n// two kinds of presence, Either, the unit, null and undefined values, symbols\n// and handles. Every other LawSpec type maps to a Swift type directly (Int8\n// ... UInt64, BigInt, String, [UInt8], arrays, optionals, Unicode.Scalar).\n// ref:DEC-swift-runtime-from-scratch ref:DEC-idiomatic-generated-types\n\n/// An exact fraction in lowest terms, with a positive denominator.\npublic struct Rational: Sendable, Hashable, CustomStringConvertible {\n  public let numerator: BigInt\n  public let denominator: BigInt\n\n  /// The fraction numerator / denominator, normalized. The denominator\n  /// must not be zero.\n  public init(_ numerator: BigInt, _ denominator: BigInt) {\n    precondition(!denominator.isZero, \"a rational's denominator is not zero\")\n    let g = BigInt.gcd(numerator, denominator)\n    let sign: BigInt = denominator.isNegative ? -1 : 1\n    self.numerator = sign * numerator / g\n    self.denominator = denominator.magnitude / g\n  }\n\n  public var description: String { \"\\(numerator)/\\(denominator)\" }\n}\n\n/// coefficient * 10 ^ exponent, exactly; 1.50 keeps its two places.\npublic struct ExactDecimal: Sendable, Hashable, CustomStringConvertible {\n  public var coefficient: BigInt\n  public var exponent: Int\n\n  public init(coefficient: BigInt, exponent: Int) {\n    self.coefficient = coefficient\n    self.exponent = exponent\n  }\n\n  public var description: String { \"\\(coefficient)e\\(exponent)\" }\n\n  /// Both decimals at the smaller exponent.\n  private static func aligned(_ a: ExactDecimal, _ b: ExactDecimal) -> (BigInt, BigInt, Int) {\n    let e = Swift.min(a.exponent, b.exponent)\n    func scale(_ d: ExactDecimal) -> BigInt { d.coefficient * BigInt(10).power(d.exponent - e) }\n    return (scale(a), scale(b), e)\n  }\n\n  /// Exact sum, at the finer of the two scales.\n  public static func + (a: ExactDecimal, b: ExactDecimal) -> ExactDecimal {\n    let (x, y, e) = aligned(a, b)\n    return ExactDecimal(coefficient: x + y, exponent: e)\n  }\n\n  /// Exact difference, at the finer of the two scales.\n  public static func - (a: ExactDecimal, b: ExactDecimal) -> ExactDecimal {\n    let (x, y, e) = aligned(a, b)\n    return ExactDecimal(coefficient: x - y, exponent: e)\n  }\n\n  /// Exact product.\n  public static func * (a: ExactDecimal, b: ExactDecimal) -> ExactDecimal {\n    ExactDecimal(coefficient: a.coefficient * b.coefficient, exponent: a.exponent + b.exponent)\n  }\n}\n\n/// A complex number of two single precision floats.\npublic struct Complex64: Sendable, Hashable, CustomStringConvertible {\n  public var real: Float\n  public var imaginary: Float\n  public init(real: Float, imaginary: Float) {\n    self.real = real\n    self.imaginary = imaginary\n  }\n  public static func == (a: Complex64, b: Complex64) -> Bool {\n    a.real.bitPattern == b.real.bitPattern && a.imaginary.bitPattern == b.imaginary.bitPattern\n  }\n  public func hash(into hasher: inout Hasher) {\n    hasher.combine(real.bitPattern)\n    hasher.combine(imaginary.bitPattern)\n  }\n  public var description: String { \"(\\(real), \\(imaginary))\" }\n}\n\n/// A complex number of two double precision floats.\npublic struct Complex128: Sendable, Hashable, CustomStringConvertible {\n  public var real: Double\n  public var imaginary: Double\n  public init(real: Double, imaginary: Double) {\n    self.real = real\n    self.imaginary = imaginary\n  }\n  public static func == (a: Complex128, b: Complex128) -> Bool {\n    a.real.bitPattern == b.real.bitPattern && a.imaginary.bitPattern == b.imaginary.bitPattern\n  }\n  public func hash(into hasher: inout Hasher) {\n    hasher.combine(real.bitPattern)\n    hasher.combine(imaginary.bitPattern)\n  }\n  public var description: String { \"(\\(real), \\(imaginary))\" }\n}\n\n/// A value that may be null, distinct from an undefined Undefinable.\npublic enum Nullable<Wrapped>: CustomStringConvertible {\n  case null\n  case present(Wrapped)\n  public var description: String {\n    switch self {\n    case .null: return \"null\"\n    case .present(let value): return \"present(\\(value))\"\n    }\n  }\n}\n\n/// A value that may be undefined (LawSpec's Optional), distinct from a null\n/// Nullable.\npublic enum Undefinable<Wrapped>: CustomStringConvertible {\n  case undefined\n  case present(Wrapped)\n  public var description: String {\n    switch self {\n    case .undefined: return \"undefined\"\n    case .present(let value): return \"present(\\(value))\"\n    }\n  }\n}\n\n/// Either of two values; left conventionally the failure.\npublic enum Either<Left, Right>: CustomStringConvertible {\n  case left(Left)\n  case right(Right)\n  public var description: String {\n    switch self {\n    case .left(let value): return \"left(\\(value))\"\n    case .right(let value): return \"right(\\(value))\"\n    }\n  }\n}\n\nextension Nullable: Sendable where Wrapped: Sendable {}\nextension Undefinable: Sendable where Wrapped: Sendable {}\nextension Either: Sendable where Left: Sendable, Right: Sendable {}\nextension Nullable: Equatable where Wrapped: Equatable {}\nextension Undefinable: Equatable where Wrapped: Equatable {}\nextension Either: Equatable where Left: Equatable, Right: Equatable {}\nextension Nullable: Hashable where Wrapped: Hashable {}\nextension Undefinable: Hashable where Wrapped: Hashable {}\nextension Either: Hashable where Left: Hashable, Right: Hashable {}\n\n/// LawSpec's Unit value.\npublic struct Unit: Sendable, Hashable, Comparable, CustomStringConvertible {\n  public init() {}\n  public static func < (_: Unit, _: Unit) -> Bool { false }\n  public var description: String { \"()\" }\n}\n\n/// LawSpec's Null value.\npublic struct Null: Sendable, Hashable, Comparable, CustomStringConvertible {\n  public init() {}\n  public static func < (_: Null, _: Null) -> Bool { false }\n  public var description: String { \"null\" }\n}\n\n/// LawSpec's Undefined value.\npublic struct Undefined: Sendable, Hashable, Comparable, CustomStringConvertible {\n  public init() {}\n  public static func < (_: Undefined, _: Undefined) -> Bool { false }\n  public var description: String { \"undefined\" }\n}\n\n/// A symbol: equal only to itself.\npublic struct Symbol: Sendable, Hashable, CustomStringConvertible {\n  public let identity: SymbolIdentity\n  public let symbolDescription: String\n  public init(_ description: String) {\n    self.identity = SymbolIdentity()\n    self.symbolDescription = description\n  }\n  public init(identity: SymbolIdentity, description: String) {\n    self.identity = identity\n    self.symbolDescription = description\n  }\n  public static func == (a: Symbol, b: Symbol) -> Bool { a.identity === b.identity }\n  public func hash(into hasher: inout Hasher) { hasher.combine(ObjectIdentifier(identity)) }\n  public var description: String { \"Symbol(\\(symbolDescription))\" }\n}\n\n/// A handle no application type is bound to: a native object LawSpec passes\n/// along unopened, equal only to itself.\npublic struct AnyHandle: @unchecked Sendable, Hashable, CustomStringConvertible {\n  public let object: AnyObject\n  public init(_ object: AnyObject) { self.object = object }\n  public static func == (a: AnyHandle, b: AnyHandle) -> Bool { a.object === b.object }\n  public func hash(into hasher: inout Hasher) { hasher.combine(ObjectIdentifier(object)) }\n  public var description: String { \"handle(\\(type(of: object)))\" }\n}\n"
swiftSource "LawSpecRuntime/NetworkApi.swift" = "// The public network API (lawspec_network on BEAM): node options and\n// identities, transports, in-memory networks and owned nodes.\n// ref:DEC-distribution-canonical-wire\n\npublic enum Network {\n  /// Options with no identity (a new one per node, or the configured one)\n  /// and the configured trust.\n  public static func options() -> NetworkOptions { NetworkConfig.empty }\n\n  public static func withIdentity(_ options: NetworkOptions, _ identity: NodeIdentity)\n    -> NetworkOptions\n  {\n    var o = options\n    o.identity = identity\n    return o\n  }\n\n  /// Trust exactly these fingerprints.\n  public static func withTrusted(_ options: NetworkOptions, _ fingerprints: [String])\n    -> NetworkOptions\n  {\n    var o = options\n    o.trusted = fingerprints\n    o.trustGiven = true\n    return o\n  }\n\n  /// Trust any peer whose handshake verifies.\n  public static func trustOnFirstUse(_ options: NetworkOptions) -> NetworkOptions {\n    var o = options\n    o.trusted = nil\n    o.trustGiven = true\n    return o\n  }\n\n  public static func identityFromSeed(_ seed: [UInt8]) throws -> NodeIdentity {\n    try NetworkRecords.identity(seed)\n  }\n\n  public static func newIdentity() throws -> NodeIdentity {\n    try identityFromSeed(CryptoPrimitives.randomBytes(32))\n  }\n\n  public static func publicKey(_ identity: NodeIdentity) -> [UInt8] { identity.publicKey }\n\n  public static func fingerprint(_ identity: NodeIdentity) -> String {\n    NetworkRecords.fingerprint(identity)\n  }\n\n  public static func tcp(_ host: String, _ port: Int) -> Transport { Transports.tcp(host, port) }\n\n  public static func http(_ host: String, _ port: Int) -> Transport { Transports.http(host, port) }\n\n  public static func advertise(_ transport: Transport, _ host: String) throws -> Transport {\n    try Transports.advertise(transport, host)\n  }\n\n  /// Memory network options: seed, loss and duplicate chances, the most\n  /// delay in seconds, and whether to record frames.\n  public static func memoryOptions(\n    _ seed: BigInt, _ loss: Double, _ duplicate: Double, _ delay: Double, _ record: Bool\n  ) -> MemoryOptions {\n    MemoryOptions(seed: seed, loss: loss, duplicate: duplicate, delay: delay, record: record)\n  }\n\n  public static func memory(_ options: MemoryOptions) throws -> MemoryNetwork {\n    try MemoryNetwork(options)\n  }\n\n  public static func withMemory<T>(_ options: MemoryOptions, _ body: (MemoryNetwork) throws -> T)\n    throws -> T\n  {\n    let network = try memory(options)\n    defer { network.close() }\n    return try body(network)\n  }\n\n  public static func closeMemory(_ network: MemoryNetwork) { network.close() }\n\n  public static func memoryTransport(_ network: MemoryNetwork, _ name: String) -> Transport {\n    Transports.memory(network, name)\n  }\n\n  /// A memory transport without the secure layer, for tests only.\n  public static func insecureMemoryTransportForTests(_ network: MemoryNetwork, _ name: String)\n    -> Transport\n  {\n    Transports.insecureMemoryForTests(network, name)\n  }\n\n  public static func partition(_ network: MemoryNetwork, _ groups: [[String]]) throws {\n    try network.partition(groups)\n  }\n\n  public static func heal(_ network: MemoryNetwork) { network.heal() }\n\n  public static func recorded(_ network: MemoryNetwork) -> [[UInt8]] { network.recorded() }\n\n  public static func openNode(_ transport: Transport, _ options: NetworkOptions) throws -> Node {\n    do {\n      return try Node(transport, options)\n    } catch let e as LawSpecError where e.code != \"Network\" {\n      throw Fail.with(\"Network\", e.detail.isEmpty ? e.code : e.code + \": \" + e.detail)\n    }\n  }\n\n  public static func close(_ node: Node) { node.close() }\n\n  public static func withNode<T>(\n    _ transport: Transport, _ options: NetworkOptions, _ body: (Node) throws -> T\n  ) throws -> T {\n    let node = try openNode(transport, options)\n    defer { node.close() }\n    return try body(node)\n  }\n\n  public static func address(_ node: Node) -> String { node.address }\n\n  public static func nodeFingerprint(_ node: Node) throws -> String { try node.identity() }\n\n  /// The wire encodings, in hexadecimal, of count values a descriptor text\n  /// draws from a seed at a size (the distribution suite's vectors).\n  public static func wireEncoded(_ text: String, _ seed: BigInt, _ size: Int, _ count: Int) throws\n    -> [String]\n  {\n    let (table, d) = try Descriptors.fromText(text)\n    var state = Random.seed(seed)\n    var out = [String]()\n    for _ in 0..<max(0, count) {\n      let (v, next) = try Descriptors.generate(d, table, state, size)\n      state = next\n      out.append(Wire.hex(try Descriptors.encode(d, v, table)))\n    }\n    return out\n  }\n\n  /// Whether count values a descriptor text draws decode to themselves.\n  public static func wireRoundTrips(_ text: String, _ seed: BigInt, _ size: Int, _ count: Int)\n    throws -> Bool\n  {\n    let (table, d) = try Descriptors.fromText(text)\n    var state = Random.seed(seed)\n    var all = true\n    for _ in 0..<max(0, count) {\n      let (v, next) = try Descriptors.generate(d, table, state, size)\n      state = next\n      let back = try Descriptors.decode(d, try Descriptors.encode(d, v, table), table)\n      if Descriptors.render(back) != Descriptors.render(v) { all = false }\n    }\n    return all\n  }\n\n  /// Whether this runtime's secure handshake gives a cross-target vector's\n  /// bytes: the hello and welcome hashes, the session key and a sealed frame\n  /// (all in hexadecimal) from the two identities' and the KEM key's seeds.\n  public static func handshakeVector(\n    _ initiatorSeed: String, _ responderSeed: String, _ kemSeed: String, _ session: String,\n    _ initiator: String,\n    _ responder: String, _ ciphertext: String, _ nonce: String, _ frame: String,\n    _ helloHash: String,\n    _ welcomeHash: String, _ key: String, _ record: String\n  ) -> Bool {\n    guard let first = Wire.unhex(initiatorSeed), let second = Wire.unhex(responderSeed),\n      let kemSeedBytes = Wire.unhex(kemSeed),\n      let sessionBytes = Wire.unhex(session), let ciphertextBytes = Wire.unhex(ciphertext),\n      let nonceBytes = Wire.unhex(nonce),\n      let frameBytes = Wire.unhex(frame)\n    else { return false }\n    do {\n      let a = try NetworkRecords.identity(first)\n      let b = try NetworkRecords.identity(second)\n      let (kemPublic, kemSecret) = CryptoPrimitives.mlkemKeyPair(kemSeedBytes)\n      let hello = NetworkRecords.hello(sessionBytes, initiator, a.publicKey, kemPublic)\n      let welcome = NetworkRecords.welcome(\n        sessionBytes, responder, b.publicKey, ciphertextBytes, hello)\n      let derived = NetworkRecords.key(\n        try NetworkRecords.decapsulate(kemSecret, ciphertextBytes), hello, welcome)\n      let sealedRecord = try NetworkRecords.sealWith(\n        derived, sessionBytes, 0, frameBytes, nonceBytes)\n      let sealedBytes =\n        nonceBytes\n        + (try CryptoPrimitives.aes256GcmEncrypt(\n          derived, nonceBytes, frameBytes,\n          Array(\"lawspec-frame-v1\".utf8) + sessionBytes + [0]))\n      return Wire.hex(CryptoPrimitives.sha3(hello)) == helloHash\n        && Wire.hex(CryptoPrimitives.sha3(welcome)) == welcomeHash\n        && Wire.hex(derived) == key\n        && Wire.hex(sealedRecord) == record\n        && NetworkRecords.openSealed(derived, sessionBytes, 0, sealedBytes) == frameBytes\n    } catch {\n      return false\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/NetworkCrypto.swift" = "// The secure transport's version 1 records (\"LS\" 1): a node's ML-DSA-65\n// identity, the signed hello and welcome of the ML-KEM-768 handshake, the\n// session key derived with SHAKE256, and AES-256-GCM sealed frames. Every\n// target writes the same bytes for the same seeds, so nodes interoperate.\n// ref:DEC-distribution-canonical-wire\n\n/// A node's identity: its ML-DSA-65 seed and public key.\npublic struct NodeIdentity: Sendable {\n  public let seed: [UInt8]\n  public let publicKey: [UInt8]\n}\n\npublic enum NetworkRecords {\n  private static let bytesType = Wire.bytesType\n\n  public static func fields(_ values: [[UInt8]]) -> [UInt8] {\n    var out = [UInt8]()\n    // Byte strings always encode.\n    for v in values { out += (try? Descriptors.encode(bytesType, .bytes(v), [:])) ?? [] }\n    return out\n  }\n\n  public static func readFields(_ count: Int, _ bytes: [UInt8], _ start: Int) throws -> (\n    [[UInt8]], Int\n  ) {\n    let (values, next) = try Wire.readFields(\n      Array(repeating: bytesType, count: count), bytes, start)\n    return (\n      try values.map { v in\n        guard case .bytes(let b) = v else { throw Fail.with(\"InvalidSecureRecord\") }\n        return b\n      }, next\n    )\n  }\n\n  public static func identity(_ seed: [UInt8]) throws -> NodeIdentity {\n    try Fail.require(seed.count == 32, \"InvalidNodeIdentity\")\n    return NodeIdentity(seed: seed, publicKey: CryptoPrimitives.mldsaPublic(seed))\n  }\n\n  public static func fingerprint(_ identity: NodeIdentity) -> String {\n    Wire.hex(CryptoPrimitives.sha3(identity.publicKey))\n  }\n\n  public static func hello(\n    _ session: [UInt8], _ address: String, _ publicKey: [UInt8], _ kem: [UInt8]\n  ) -> [UInt8] {\n    fields([session, Array(address.utf8), publicKey, kem])\n  }\n\n  public static func welcome(\n    _ session: [UInt8], _ address: String, _ publicKey: [UInt8], _ ciphertext: [UInt8],\n    _ helloBody: [UInt8]\n  ) -> [UInt8] {\n    fields([session, Array(address.utf8), publicKey, ciphertext, CryptoPrimitives.sha3(helloBody)])\n  }\n\n  public static func key(_ shared: [UInt8], _ helloBody: [UInt8], _ welcomeBody: [UInt8]) -> [UInt8]\n  {\n    CryptoPrimitives.shake(\n      shared + Array(\"lawspec-session-v1\".utf8) + CryptoPrimitives.sha3(helloBody)\n        + CryptoPrimitives.sha3(welcomeBody), 32)\n  }\n\n  public static func record(_ kind: UInt8, _ body: [UInt8], _ signature: [UInt8]) -> [UInt8] {\n    [76, 83, 1, kind] + body + fields([signature])\n  }\n\n  /// A parsed record.\n  public enum Record {\n    case handshake(kind: Int, values: [[UInt8]], body: [UInt8], signature: [UInt8])\n    case sealed(session: [UInt8], direction: Int, sealedBytes: [UInt8])\n  }\n\n  public static func read(_ bytes: [UInt8]) throws -> Record {\n    let invalid = Fail.with(\"InvalidSecureRecord\")\n    guard bytes.count >= 4, bytes[0] == 76, bytes[1] == 83, bytes[2] == 1 else { throw invalid }\n    switch bytes[3] {\n    case 1, 2:\n      let (values, rest) = try readFields(bytes[3] == 1 ? 4 : 5, bytes, 4)\n      let (signature, next) = try readFields(1, bytes, rest)\n      guard next == bytes.count else { throw invalid }\n      return .handshake(\n        kind: Int(bytes[3]), values: values, body: Array(bytes[4..<rest]), signature: signature[0])\n    case 3:\n      let (session, at) = try readFields(1, bytes, 4)\n      guard at < bytes.count else { throw invalid }\n      let direction = Int(bytes[at])\n      let (sealedBytes, next) = try readFields(1, bytes, at + 1)\n      guard next == bytes.count else { throw invalid }\n      return .sealed(session: session[0], direction: direction, sealedBytes: sealedBytes[0])\n    default:\n      throw invalid\n    }\n  }\n\n  private static func associated(_ session: [UInt8], _ direction: Int) -> [UInt8] {\n    Array(\"lawspec-frame-v1\".utf8) + session + [UInt8(truncatingIfNeeded: direction)]\n  }\n\n  /// A frame sealed under a session key with a given nonce.\n  public static func sealWith(\n    _ key: [UInt8], _ session: [UInt8], _ direction: Int, _ frame: [UInt8], _ nonce: [UInt8]\n  ) throws -> [UInt8] {\n    let sealedBytes: [UInt8]\n    do {\n      sealedBytes =\n        nonce\n        + (try CryptoPrimitives.aes256GcmEncrypt(key, nonce, frame, associated(session, direction)))\n    } catch {\n      throw Fail.with(\"InvalidSecureRecord\", error.description)\n    }\n    return [76, 83, 1, 3] + fields([session]) + [UInt8(truncatingIfNeeded: direction)]\n      + fields([sealedBytes])\n  }\n\n  public static func seal(_ key: [UInt8], _ session: [UInt8], _ direction: Int, _ frame: [UInt8])\n    throws -> [UInt8]\n  {\n    try sealWith(key, session, direction, frame, CryptoPrimitives.randomBytes(12))\n  }\n\n  public static func openSealed(\n    _ key: [UInt8], _ session: [UInt8], _ direction: Int, _ sealedBytes: [UInt8]\n  ) -> [UInt8]? {\n    if sealedBytes.count < 12 + 16 { return nil }\n    return CryptoPrimitives.aes256GcmDecrypt(\n      key, Array(sealedBytes[0..<12]), Array(sealedBytes[12...]), associated(session, direction))\n  }\n\n  /// Signing and the KEM, as LawSpec failures.\n  static func sign(_ seed: [UInt8], _ message: [UInt8]) throws -> [UInt8] {\n    do { return try CryptoPrimitives.mldsaSign(seed, message) } catch {\n      throw Fail.with(\"SecureNetwork\", error.description)\n    }\n  }\n\n  static func encapsulate(_ publicKey: [UInt8]) throws -> ([UInt8], [UInt8]) {\n    do {\n      let (c, s) = try CryptoPrimitives.mlkemEncapsulate(publicKey)\n      return (c, s)\n    } catch { throw Fail.with(\"InvalidHello\", error.description) }\n  }\n\n  static func decapsulate(_ seed: [UInt8], _ ciphertext: [UInt8]) throws -> [UInt8] {\n    do { return try CryptoPrimitives.mlkemDecapsulate(seed, ciphertext) } catch {\n      throw Fail.with(\"InvalidWelcome\", error.description)\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Node.swift" = "// A node: named entities reached by frames, and reliable request and reply\n// over a transport. Requests are deduplicated by sender and identity, even\n// while their handler runs, and retried until answered or out of time.\n// Handlers run on threads the node owns. Status codes: 0 ok, 1 failed,\n// 2 stopped, 3 rejected.\n// ref:DEC-distribution-canonical-wire\n\nimport Foundation\n\n/// Something registered at a node under a name: a handler, whose answer the\n/// node sends as the reply, or a receiver that answers later with reply.\npublic enum Entity: Sendable {\n  case handler(@Sendable (Frame) throws -> (Int, [UInt8]))\n  case receiver(@Sendable (Frame) -> Void)\n}\n\n/// A reply's status and body, or why there was none.\npublic typealias Reply = Result<(Int, [UInt8]), NodeFailure>\n\n/// Why a request got no reply.\npublic struct NodeFailure: Error, Sendable {\n  public let reason: String\n  public init(_ reason: String) { self.reason = reason }\n}\n\n/// Something a node closes when it closes.\npublic protocol NodeService: AnyObject, Sendable {\n  /// Stop the service: its node is closing.\n  func release()\n}\n\npublic final class Node: @unchecked Sendable {\n  private struct Seen {\n    var response: [UInt8]?\n    let entity: String\n    let fingerprint: [UInt8]\n  }\n\n  private struct SeenKey: Hashable {\n    let source: String\n    let id: UInt64\n  }\n\n  private enum Arrival {\n    case resend([UInt8])\n    case ignore\n    case missing\n    case dispatch(Entity)\n  }\n\n  private final class Pending {\n    let peer: String\n    let deadline: Date\n    let respond: @Sendable (Reply) -> Void\n    var timer: NetworkTimer?\n\n    init(peer: String, deadline: Date, respond: @escaping @Sendable (Reply) -> Void) {\n      self.peer = peer\n      self.deadline = deadline\n      self.respond = respond\n    }\n  }\n\n  private struct State {\n    var entities: [String: Entity] = [:]\n    var seen: [SeenKey: Seen] = [:]\n    var pending: [UInt64: Pending] = [:]\n    var services: [any NodeService] = []\n    var jobs = 0\n    var closed = false\n    var nextId: UInt64\n  }\n\n  private let state: Locked<State>\n  private var secure: SecureLayer?\n  private var raw: (any PacketTransport)?\n\n  public init(_ transport: Transport, _ options: NetworkOptions) throws {\n    var first = UInt64(0)\n    for b in CryptoPrimitives.randomBytes(8) { first = first << 8 | UInt64(b) }\n    state = Locked(State(nextId: options.firstId ?? ((first & ((1 << 61) - 1)) + 1)))\n    let receive: PacketReceiver = { [weak self] _, bytes in self?.packet(bytes) }\n    if case .memory(_, _, true) = transport {\n      raw = try Transports.open(transport, receive)\n    } else {\n      secure = try SecureLayer(transport, options, receive)\n    }\n  }\n\n  private static func fail(_ reason: String) -> LawSpecError { Fail.with(\"Network\", reason) }\n\n  /// The node's address: mem://name, tcp://host:port or http://host:port.\n  public var address: String { secure?.address ?? raw!.address }\n\n  /// The fingerprint of the node's identity (secure nodes only).\n  public func identity() throws -> String {\n    guard let secure else { throw Node.fail(\"insecure_node\") }\n    return secure.fingerprint\n  }\n\n  private func fingerprint(_ frame: Frame) -> [UInt8] {\n    CryptoPrimitives.sha3(\n      (try? Wire.encode(frame.kind, frame.to, frame.source, frame.id, frame.payload)) ?? [])\n  }\n\n  private func wire(_ peer: String, _ bytes: [UInt8]) -> String? {\n    if let secure { return secure.send(peer, bytes) }\n    return raw!.send(peer, bytes)\n  }\n\n  @discardableResult\n  private func transmit(_ frame: Frame) throws -> String? {\n    let (peer, name) = try Wire.splitAddress(frame.to)\n    let source = frame.source.isEmpty ? address : frame.source\n    return wire(peer, try Wire.encode(frame.kind, name, source, frame.id, frame.payload))\n  }\n\n  private func validate(_ frame: Frame) throws {\n    do {\n      _ = try Wire.splitAddress(frame.to)\n      _ = try Wire.encode(frame.kind, \"\", frame.source, frame.id, frame.payload)\n    } catch {\n      throw Node.fail(\"invalid_frame\")\n    }\n  }\n\n  private func sendReply(_ source: String, _ identity: UInt64, _ payload: [UInt8]) {\n    _ = try? transmit(\n      Frame(kind: \"reply\", to: source + \"/\", source: \"\", id: identity, payload: payload))\n  }\n\n  private func answer(_ key: SeenKey, _ status: Int, _ body: [UInt8]) {\n    let payload = [UInt8(truncatingIfNeeded: status)] + body\n    let send: Bool = state.with { s in\n      guard var entry = s.seen[key], entry.response == nil else { return false }\n      entry.response = payload\n      s.seen[key] = entry\n      return true\n    }\n    if send { sendReply(key.source, key.id, payload) }\n  }\n\n  private func finish(_ identity: UInt64, _ result: Reply?) {\n    let found: Pending? = state.with { s in\n      guard let p = s.pending.removeValue(forKey: identity) else { return nil }\n      p.timer?.cancel()\n      return p\n    }\n    if let p = found, let r = result { p.respond(r) }\n  }\n\n  /// A packet from the transport.\n  func packet(_ bytes: [UInt8]) {\n    if let frame = Wire.read(bytes) { arrive(frame) }\n  }\n\n  private func arrive(_ frame: Frame) {\n    if frame.kind == \"reply\" {\n      guard let status = frame.payload.first else { return }\n      let matches = state.with { s in s.pending[frame.id]?.peer == frame.source }\n      if matches { finish(frame.id, .success((Int(status), Array(frame.payload.dropFirst())))) }\n      return\n    }\n    let key = SeenKey(source: frame.source, id: frame.id)\n    let action: Arrival = state.with { s in\n      if frame.id != 0, let entry = s.seen[key] {\n        if fingerprint(frame) != entry.fingerprint {\n          return .resend([3] + Array(\"a request identity was reused for different content\".utf8))\n        }\n        if let response = entry.response { return .resend(response) }\n        return .ignore\n      }\n      guard let entity = s.entities[frame.to] else {\n        if frame.id == 0 { return .ignore }\n        s.seen[key] = Seen(response: nil, entity: frame.to, fingerprint: fingerprint(frame))\n        return .missing\n      }\n      if frame.id != 0 {\n        s.seen[key] = Seen(response: nil, entity: frame.to, fingerprint: fingerprint(frame))\n      }\n      return .dispatch(entity)\n    }\n    switch action {\n    case .resend(let payload): sendReply(frame.source, frame.id, payload)\n    case .ignore: return\n    case .missing: answer(key, 3, Array((\"nothing is registered as \" + frame.to).utf8))\n    case .dispatch(.receiver(let receive)): receive(frame)\n    case .dispatch(.handler(let handle)):\n      state.with { $0.jobs += 1 }\n      LawThread.start { [self] in\n        var status: Int\n        var body: [UInt8]\n        do {\n          (status, body) = try handle(frame)\n          if status < 0 || status > 255 { (status, body) = (1, Array(\"invalid reply\".utf8)) }\n        } catch {\n          (status, body) = (1, Array(Node.message(error).utf8))\n        }\n        if frame.id != 0 { answer(key, status, body) }\n        state.with { $0.jobs -= 1 }\n      }\n    }\n  }\n\n  /// An error's message, as a failed reply carries it.\n  static func message(_ error: any Error) -> String {\n    if let e = error as? LawSpecError {\n      return e.detail.isEmpty ? e.code : e.code + \": \" + e.detail\n    }\n    return String(describing: error)\n  }\n\n  private func register(_ name: String, _ entity: Entity) throws -> String {\n    if name.isEmpty || name.contains(\"/\") { throw Node.fail(\"invalid_entity_name\") }\n    try state.with { s in\n      if s.closed { throw Node.fail(\"node_closed\") }\n      if s.entities[name] != nil { throw Node.fail(\"already_registered \" + name) }\n      s.entities[name] = entity\n    }\n    return address + \"/\" + name\n  }\n\n  /// Serve requests to a name with a handler of each frame; its answer is\n  /// the reply's status and body. The entity's address.\n  @discardableResult\n  public func registerHandler(\n    _ name: String, _ handler: @escaping @Sendable (Frame) throws -> (Int, [UInt8])\n  ) throws -> String {\n    try register(name, .handler(handler))\n  }\n\n  /// Deliver each frame for a name to a receiver, which answers with reply.\n  @discardableResult\n  public func registerReceiver(_ name: String, _ receiver: @escaping @Sendable (Frame) -> Void)\n    throws -> String\n  {\n    try register(name, .receiver(receiver))\n  }\n\n  /// A service the node closes when it closes.\n  public func adopt(_ service: any NodeService) { state.with { $0.services.append(service) } }\n\n  /// Remove a name; requests to it still waiting are answered as stopped.\n  public func unregister(_ name: String) {\n    let waiting: [SeenKey] = state.with { s in\n      guard s.entities.removeValue(forKey: name) != nil else { return [] }\n      return s.seen.filter { $0.value.entity == name && $0.value.response == nil }.map(\\.key)\n    }\n    for key in waiting { answer(key, 2, Array(\"the receiving entity has stopped\".utf8)) }\n  }\n\n  /// Send a frame of a kind to an address, with no reply.\n  public func send(_ address: String, _ kind: String, _ payload: [UInt8]) throws {\n    let frame = Wire.frameTo(address, kind, payload)\n    try validate(frame)\n    try transmit(frame)\n  }\n\n  /// Send a frame as given (an endpoint's protocol frames).\n  public func forward(_ frame: Frame) throws {\n    try validate(frame)\n    try transmit(frame)\n  }\n\n  /// Request: retried every 100 ms until a reply or the timeout (ms). The\n  /// callback gets the reply's status and body, or the failure. Returns\n  /// the request's identity.\n  @discardableResult\n  public func requestAsync(\n    _ address: String, _ kind: String, _ payload: [UInt8], _ timeout: Int,\n    _ respond: @escaping @Sendable (Reply) -> Void\n  ) throws -> UInt64 {\n    if timeout < 0 { throw Node.fail(\"invalid_timeout\") }\n    let (peer, _) = try Wire.splitAddress(address)\n    let (identity, frame): (UInt64, Frame) = try state.with { s in\n      if s.closed { throw Node.fail(\"node_closed\") }\n      let identity = s.nextId\n      s.nextId += 1\n      let frame = Frame(kind: kind, to: address, source: \"\", id: identity, payload: payload)\n      try validate(frame)\n      let p = Pending(\n        peer: peer, deadline: Date().addingTimeInterval(Double(timeout) / 1000), respond: respond)\n      s.pending[identity] = p\n      let period = max(1, min(100, timeout))\n      p.timer = NetworkTimer(period) { [weak self] in\n        guard let self else { return }\n        let resend: Bool? = self.state.with { s in\n          guard let q = s.pending[identity] else { return nil }\n          return Date() < q.deadline\n        }\n        switch resend {\n        case .some(true): _ = try? self.transmit(frame)\n        case .some(false): self.finish(identity, .failure(NodeFailure(\"unreachable \" + address)))\n        case .none: return\n        }\n      }\n      return (identity, frame)\n    }\n    try transmit(frame)\n    return identity\n  }\n\n  /// Request and wait for the reply's status and body.\n  public func request(_ address: String, _ kind: String, _ payload: [UInt8], _ timeout: Int) throws\n    -> (Int, [UInt8])\n  {\n    let result = Locked<Reply?>(nil)\n    let done = DispatchSemaphore(value: 0)\n    try requestAsync(address, kind, payload, timeout) { reply in\n      result.with { $0 = reply }\n      done.signal()\n    }\n    done.wait()\n    switch result.with({ $0 })! {\n    case .success(let reply): return reply\n    case .failure(let failure): throw Node.fail(failure.reason)\n    }\n  }\n\n  /// Forget a request; its callback is not called.\n  public func cancel(_ identity: UInt64) { finish(identity, nil) }\n\n  /// Answer a request a receiver was given.\n  public func reply(_ source: String, _ identity: UInt64, _ status: Int, _ body: [UInt8]) throws {\n    if status < 0 || status > 255 { throw Node.fail(\"invalid_reply\") }\n    if identity != 0 { answer(SeenKey(source: source, id: identity), status, body) }\n  }\n\n  /// Close the node: its services, its waiting requests and its transport.\n  public func close() {\n    let (waiting, services): ([Pending], [any NodeService]) = state.with { s in\n      if s.closed { return ([], []) }\n      s.closed = true\n      let all = Array(s.pending.values)\n      s.pending.removeAll()\n      let services = s.services\n      s.services.removeAll()\n      return (all, services)\n    }\n    for service in services { service.release() }\n    for p in waiting {\n      p.timer?.cancel()\n      p.respond(.failure(NodeFailure(\"node_closed\")))\n    }\n    let deadline = Date().addingTimeInterval(5)\n    while state.with({ $0.jobs }) > 0 && Date() < deadline { usleep(2000) }\n    if let secure { secure.close() } else { raw?.close() }\n  }\n}\n"
swiftSource "LawSpecRuntime/PersistentList.swift" = "// LawSpec's List in Swift: a persistent singly linked list. Prepending, the\n// first item and the rest take constant time and share the rest, as a\n// recursive definition over a list expects; Swift's Array would copy the\n// whole list at each step. It is a Sequence, so for-in, map, filter and\n// Array(list) work, and an array literal makes one. ref:DEC-swift-persistent-list\n\n/// An immutable list whose prepend and rest share structure.\npublic struct PersistentList<Element> {\n  @usableFromInline\n  final class Node {\n    @usableFromInline let head: Element\n    @usableFromInline var tail: Node?\n\n    @inlinable\n    init(_ head: Element, _ tail: Node?) {\n      self.head = head\n      self.tail = tail\n    }\n\n    // Releasing a long list one node at a time, not recursively, so\n    // dropping a list of a million items never exhausts the stack.\n    deinit {\n      var next = tail\n      tail = nil\n      while next != nil && isKnownUniquelyReferenced(&next!) {\n        let after = next!.tail\n        next!.tail = nil\n        next = after\n      }\n    }\n  }\n\n  @usableFromInline let node: Node?\n  /// The number of items, kept so counting takes constant time.\n  public let count: Int\n\n  @inlinable\n  init(node: Node?, count: Int) {\n    self.node = node\n    self.count = count\n  }\n\n  /// The empty list.\n  @inlinable\n  public init() { self.init(node: nil, count: 0) }\n\n  /// A list of a sequence's items, in order.\n  public init<S: Sequence>(_ items: S) where S.Element == Element {\n    let array = Array(items)\n    var node: Node? = nil\n    for item in array.reversed() { node = Node(item, node) }\n    self.init(node: node, count: array.count)\n  }\n\n  /// Whether the list has no items.\n  @inlinable\n  public var isEmpty: Bool { node == nil }\n\n  /// The first item, if any.\n  @inlinable\n  public var first: Element? { node?.head }\n\n  /// The list after its first item, shared, not copied; empty when the list is.\n  @inlinable\n  public var rest: PersistentList<Element> {\n    guard let node else { return self }\n    return PersistentList(node: node.tail, count: count - 1)\n  }\n\n  /// The list with an item before its first.\n  @inlinable\n  public func prepending(_ item: Element) -> PersistentList<Element> {\n    PersistentList(node: Node(item, node), count: count + 1)\n  }\n\n  /// The item at a position from 0, if the list is that long.\n  public func item(at index: Int) -> Element? {\n    guard index >= 0, index < count else { return nil }\n    var current = node\n    for _ in 0..<index { current = current?.tail }\n    return current?.head\n  }\n\n  /// The items from one position up to, not including, another.\n  public func slice(_ from: Int, _ until: Int) -> PersistentList<Element> {\n    guard from < until else { return PersistentList() }\n    var current = node\n    for _ in 0..<from { current = current?.tail }\n    var items = [Element]()\n    items.reserveCapacity(until - from)\n    while items.count < until - from, let n = current {\n      items.append(n.head)\n      current = n.tail\n    }\n    return PersistentList(items)\n  }\n\n  /// One list's items, then another's: the second list is shared.\n  public static func + (a: PersistentList<Element>, b: PersistentList<Element>) -> PersistentList<\n    Element\n  > {\n    if b.isEmpty { return a }\n    var node = b.node\n    for item in Array(a).reversed() { node = Node(item, node) }\n    return PersistentList(node: node, count: a.count + b.count)\n  }\n\n  /// The list in reverse order.\n  public func reversed() -> PersistentList<Element> {\n    var node: Node? = nil\n    var current = self.node\n    while let n = current {\n      node = Node(n.head, node)\n      current = n.tail\n    }\n    return PersistentList(node: node, count: count)\n  }\n}\n\nextension PersistentList: Sequence {\n  /// Walks the items in order.\n  public struct Iterator: IteratorProtocol {\n    @usableFromInline var current: Node?\n\n    @inlinable\n    init(current: Node?) { self.current = current }\n\n    @inlinable\n    public mutating func next() -> Element? {\n      guard let node = current else { return nil }\n      current = node.tail\n      return node.head\n    }\n  }\n\n  @inlinable\n  public func makeIterator() -> Iterator { Iterator(current: node) }\n\n  @inlinable\n  public var underestimatedCount: Int { count }\n}\n\nextension PersistentList: ExpressibleByArrayLiteral {\n  public init(arrayLiteral items: Element...) { self.init(items) }\n}\n\nextension PersistentList: CustomStringConvertible {\n  public var description: String { \"[\" + map { \"\\($0)\" }.joined(separator: \", \") + \"]\" }\n}\n\n// The nodes are immutable once the list is built (only deinit unlinks\n// them), so a list of Sendable items is Sendable.\nextension PersistentList: @unchecked Sendable where Element: Sendable {}\n\nextension PersistentList: Equatable where Element: Equatable {\n  public static func == (a: PersistentList<Element>, b: PersistentList<Element>) -> Bool {\n    a.count == b.count && a.elementsEqual(b)\n  }\n}\n\nextension PersistentList: Hashable where Element: Hashable {\n  public func hash(into hasher: inout Hasher) {\n    hasher.combine(count)\n    for item in self { hasher.combine(item) }\n  }\n}\n\nextension PersistentList: Portable where Element: Portable {\n  public static func portableEqual(_ a: PersistentList<Element>, _ b: PersistentList<Element>)\n    -> Bool\n  {\n    a.count == b.count && zip(a, b).allSatisfy { Element.portableEqual($0, $1) }\n  }\n\n  public static func portableCompare(_ a: PersistentList<Element>, _ b: PersistentList<Element>)\n    -> Int\n  {\n    for (x, y) in zip(a, b) {\n      let c = Element.portableCompare(x, y)\n      if c != 0 { return c }\n    }\n    return a.count < b.count ? -1 : (a.count == b.count ? 0 : 1)\n  }\n\n  public func portableHash(into hasher: inout Hasher) {\n    hasher.combine(count)\n    for item in self { item.portableHash(into: &hasher) }\n  }\n}\n"
swiftSource "LawSpecRuntime/Policy.swift" = "// Workflow policies as values: retry strategies and their delays, jitter\n// drawn from an explicit SplitMix64 state, the gates a stage passes\n// (breakers, rate limits, bulkheads) and the logical failures a stage gives.\n// Durations are whole microseconds. The policy's random stream is separate\n// from the Random ability's. ref:DEC-domain-modeling-primitives ref:splitmix\n// ref:DEC-typed-core-boundary\n\npublic enum Policy {\n  /// How long to wait before each retry.\n  public enum Strategy {\n    case immediate\n    case fixed(delay: Int64)\n    case linear(delay: Int64, step: Int64)\n    case exponential(delay: Int64, factor: Int64, cap: Int64?)\n    case fibonacci(delay: Int64)\n    /// A checked definition decides: attempt (Int), error, previous delay\n    /// (a Duration) to a RetryDecision.\n    case custom((Value, Value, Value) throws -> Value)\n  }\n\n  /// How a delay is randomized.\n  public enum Jitter {\n    case none\n    case full\n    case equal\n    case decorrelated\n  }\n\n  /// Attempts count the first try; zero attempts retries without a bound.\n  public struct Retry {\n    public let strategy: Strategy\n    public let attempts: Int64\n    public let jitter: Jitter\n    /// Whether an error is worth retrying (a portable Bool).\n    public let condition: ((Value) throws -> Value)?\n  }\n\n  public enum GateKind: Hashable {\n    case breaker\n    case limit\n    case bulkhead\n  }\n\n  /// How long a stage may wait at a gate that answers WaitFor.\n  public enum Wait: Equatable {\n    case noWait\n    case forever\n    case within(Int64)\n  }\n\n  /// A gate: its state starts at a time, admits at a time (giving the next\n  /// state and a Gate decision), and may record how an admitted call ended.\n  /// Times are portable Ints, the outcome a portable Bool.\n  public struct Gate {\n    public let kind: GateKind\n    public let start: (Value) throws -> Value\n    public let admit: (Value, Value) throws -> Value\n    public let finish: ((Value, Value, Value) throws -> Value)?\n    public let wait: Wait\n  }\n\n  /// A stage's policies, as a definition with a policy declares them.\n  public struct StagePolicy {\n    public let key: String\n    public let stage: String\n    public let retry: Retry?\n    public let timeout: Int64?\n    public let gates: [Gate]\n    public let cache: Int64?\n    public let compensate: ((Value) throws -> Value)?\n    public let wraps: Bool\n    /// A further attempt starts after the delay, up to most in all.\n    public let hedge: (Int64, Int64)?\n  }\n\n  /// A delay as an Int64 of microseconds, or RetryDelayOverflow: the\n  /// delays are exact, as on every target, never wrapped.\n  private static func exactDelay(_ value: BigInt) throws -> Int64 {\n    guard let delay = value.exactly(Int64.self) else {\n      throw Fail.with(\"RetryDelayOverflow\", value.description)\n    }\n    return delay\n  }\n\n  /// The delay before an attempt (from the second) of a strategy.\n  public static func retryDelay(_ strategy: Strategy, _ attempt: Int64) throws -> Int64 {\n    if attempt < 2 { throw Fail.with(\"InvalidRetryAttempt\", String(attempt)) }\n    let n = BigInt(attempt) - BigInt(2)\n    switch strategy {\n    case .immediate: return 0\n    case .fixed(let delay): return delay\n    case .linear(let delay, let step): return try exactDelay(BigInt(delay) + BigInt(step) * n)\n    case .exponential(let delay, let factor, let cap):\n      // Multiply up only until the cap, or past any Int64, is reached.\n      let limit = BigInt(cap ?? Int64.max)\n      var value = BigInt(delay)\n      var remaining = attempt - 2\n      while remaining > 0 && value.magnitude <= limit.magnitude {\n        value = value * BigInt(factor)\n        remaining -= 1\n      }\n      if let cap, value > BigInt(cap) { return cap }\n      return try exactDelay(value)\n    case .fibonacci(let delay):\n      var (a, b) = (BigInt(1), BigInt(1))\n      var remaining = attempt - 2\n      let limit = BigInt(Int64.max)\n      while remaining > 0 && a <= limit {\n        (a, b) = (b, a + b)\n        remaining -= 1\n      }\n      return try exactDelay(BigInt(delay) * a)\n    case .custom: throw Fail.with(\"CustomRetryDelay\", \"a custom strategy decides its own delays\")\n    }\n  }\n\n  private static func below(_ bound: Int64, _ state: Random.Seed) -> (Int64, Random.Seed) {\n    let (n, next) = Random.below(BigInt(bound), state)\n    return (n.exactly(Int64.self) ?? 0, next)\n  }\n\n  /// A jittered delay and the next random state.\n  public static func jitter(\n    _ kind: Jitter, _ delay: Int64, _ previous: Int64, _ baseDelay: Int64, _ state: Random.Seed\n  ) -> (Int64, Random.Seed) {\n    switch kind {\n    case .none:\n      return (delay, state)\n    case .full:\n      return below(delay + 1, state)\n    case .equal:\n      let half = delay / 2\n      let (r, next) = below(delay - half + 1, state)\n      return (half + r, next)\n    case .decorrelated:\n      let high = Swift.max(baseDelay, previous * 3)\n      let (r, next) = below(high - baseDelay + 1, state)\n      return (Swift.min(delay, baseDelay + r), next)\n    }\n  }\n\n  /// A custom strategy's RetryDecision: a delay to wait, or nil to stop.\n  public static func retryDecision(_ decision: Value) throws -> Int64? {\n    switch decision {\n    case .data(\"lawspec.time::type::RetryDecision::RetryAfter\", let fields) where fields.count == 1:\n      if case .data(_, let inner) = fields[0], inner.count == 1, case .int(let delay) = inner[0],\n        let d = delay.exactly(Int64.self)\n      {\n        return d\n      }\n    case .data(\"lawspec.time::type::RetryDecision::Stop\", let fields) where fields.isEmpty:\n      return nil\n    default:\n      break\n    }\n    throw Fail.with(\"InvalidRetryDecision\", \"\\(decision)\")\n  }\n\n  /// Whether a stage's result is a failure (a Left).\n  public static func failed(_ result: Value) -> Bool {\n    if case .data(\"Either::Left\", let fields) = result, fields.count == 1 { return true }\n    return false\n  }\n\n  /// A stage's own failure: TimedOut, RateLimited, CircuitOpen or Saturated.\n  public static func stageFailure(_ kind: String) -> Value {\n    .data(\"Either::Left\", [.data(\"lawspec.resilience::type::StageFailure::\" + kind, [])])\n  }\n\n  // MARK: Builders, as generated code writes a policy\n\n  public static func immediate() -> Strategy { .immediate }\n  public static func fixedDelay(_ delay: Int64) -> Strategy { .fixed(delay: delay) }\n  public static func linear(_ delay: Int64, _ step: Int64) -> Strategy {\n    .linear(delay: delay, step: step)\n  }\n  public static func exponential(_ delay: Int64, _ factor: Int64, _ cap: Int64?) -> Strategy {\n    .exponential(delay: delay, factor: factor, cap: cap)\n  }\n  public static func fibonacciDelay(_ delay: Int64) -> Strategy { .fibonacci(delay: delay) }\n  public static func custom(_ decide: @escaping (Value, Value, Value) throws -> Value) -> Strategy {\n    .custom(decide)\n  }\n\n  /// A jitter by name: none, full, equal or decorrelated.\n  public static func jitterOf(_ name: String) -> Jitter {\n    switch name {\n    case \"full\": return .full\n    case \"equal\": return .equal\n    case \"decorrelated\": return .decorrelated\n    default: return .none\n    }\n  }\n\n  public static func retry(\n    _ strategy: Strategy, _ attempts: Int64, _ jitter: Jitter,\n    _ condition: ((Value) throws -> Value)?\n  ) -> Retry {\n    Retry(strategy: strategy, attempts: attempts, jitter: jitter, condition: condition)\n  }\n\n  public static func noWait() -> Wait { .noWait }\n  public static func forever() -> Wait { .forever }\n  public static func within(_ micros: Int64) -> Wait { .within(micros) }\n\n  public static func breaker(\n    _ start: @escaping (Value) throws -> Value, _ admit: @escaping (Value, Value) throws -> Value,\n    _ finish: @escaping (Value, Value, Value) throws -> Value\n  ) -> Gate {\n    Gate(kind: .breaker, start: start, admit: admit, finish: finish, wait: .noWait)\n  }\n\n  public static func limit(\n    _ start: @escaping (Value) throws -> Value, _ admit: @escaping (Value, Value) throws -> Value,\n    _ wait: Wait\n  ) -> Gate {\n    Gate(kind: .limit, start: start, admit: admit, finish: nil, wait: wait)\n  }\n\n  public static func bulkhead(\n    _ start: @escaping (Value) throws -> Value, _ admit: @escaping (Value, Value) throws -> Value,\n    _ finish: @escaping (Value, Value, Value) throws -> Value, _ wait: Wait\n  ) -> Gate {\n    Gate(kind: .bulkhead, start: start, admit: admit, finish: finish, wait: wait)\n  }\n\n  /// A stage's policy.\n  public static func stage(\n    _ key: String, _ stage: String, _ retry: Retry?, _ timeout: Int64?, _ gates: [Gate],\n    _ cache: Int64?, _ compensate: ((Value) throws -> Value)?, _ wraps: Bool,\n    _ hedge: (Int64, Int64)?\n  ) -> StagePolicy {\n    StagePolicy(\n      key: key, stage: stage, retry: retry, timeout: timeout, gates: gates, cache: cache,\n      compensate: compensate, wraps: wraps, hedge: hedge)\n  }\n}\n"
swiftSource "LawSpecRuntime/Portable.swift" = "// LawSpec's portable equality, hash and order over native Swift values. The\n// generated structs and enums use it, so a native value orders as its\n// portable value does on every target: text by code point (Swift compares a\n// String by canonical equivalence), constructors by their identities, fields\n// left to right. Floats compare by their bits for equality, so it is\n// reflexive, as Swift's collections require. ref:DEC-portable-exact-arithmetic\n// ref:DEC-idiomatic-generated-types\n\n/// A native type with LawSpec's equality, hash and order.\npublic protocol Portable: Sendable {\n  /// Whether two values are the same LawSpec value.\n  static func portableEqual(_ a: Self, _ b: Self) -> Bool\n  /// LawSpec's order of two values: -1, 0 or 1.\n  static func portableCompare(_ a: Self, _ b: Self) -> Int\n  /// A hash consistent with portableEqual.\n  func portableHash(into hasher: inout Hasher)\n}\n\n/// The order of two comparable values, as -1, 0 or 1.\n@inlinable func order<T: Comparable>(_ a: T, _ b: T) -> Int { a < b ? -1 : (a == b ? 0 : 1) }\n\nextension Portable where Self: Comparable {\n  public static func portableEqual(_ a: Self, _ b: Self) -> Bool { a == b }\n  public static func portableCompare(_ a: Self, _ b: Self) -> Int { order(a, b) }\n}\n\nextension Portable where Self: Hashable {\n  public func portableHash(into hasher: inout Hasher) { hasher.combine(self) }\n}\n\nextension Bool: Portable {\n  public static func portableEqual(_ a: Bool, _ b: Bool) -> Bool { a == b }\n  public static func portableCompare(_ a: Bool, _ b: Bool) -> Int { a == b ? 0 : (a ? 1 : -1) }\n}\nextension Int8: Portable {}\nextension Int16: Portable {}\nextension Int32: Portable {}\nextension Int64: Portable {}\nextension Int: Portable {}\nextension UInt8: Portable {}\nextension UInt16: Portable {}\nextension UInt32: Portable {}\nextension UInt64: Portable {}\nextension UInt: Portable {}\nextension BigInt: Portable {}\nextension Unit: Portable {}\nextension Null: Portable {}\nextension Undefined: Portable {}\nextension Duration: Portable {}\n\nextension Unicode.Scalar: Portable {\n  public static func portableEqual(_ a: Unicode.Scalar, _ b: Unicode.Scalar) -> Bool {\n    a.value == b.value\n  }\n  public static func portableCompare(_ a: Unicode.Scalar, _ b: Unicode.Scalar) -> Int {\n    order(a.value, b.value)\n  }\n  public func portableHash(into hasher: inout Hasher) { hasher.combine(value) }\n}\n\nextension String: Portable {\n  /// Equal code point by code point: Swift's own == treats canonically\n  /// equivalent texts (e + U+0301 and U+00E9) as equal; LawSpec does not.\n  public static func portableEqual(_ a: String, _ b: String) -> Bool {\n    a.unicodeScalars.elementsEqual(b.unicodeScalars)\n  }\n  public static func portableCompare(_ a: String, _ b: String) -> Int { Scalar.compareText(a, b) }\n  public func portableHash(into hasher: inout Hasher) {\n    for scalar in unicodeScalars { hasher.combine(scalar.value) }\n    hasher.combine(-1)\n  }\n}\n\nextension Float: Portable {\n  public static func portableEqual(_ a: Float, _ b: Float) -> Bool { a.bitPattern == b.bitPattern }\n  /// Floats have no portable order; natively they order by IEEE's total order.\n  public static func portableCompare(_ a: Float, _ b: Float) -> Int {\n    a.bitPattern == b.bitPattern ? 0 : (a.isTotallyOrdered(belowOrEqualTo: b) ? -1 : 1)\n  }\n  public func portableHash(into hasher: inout Hasher) { hasher.combine(bitPattern) }\n}\n\nextension Double: Portable {\n  public static func portableEqual(_ a: Double, _ b: Double) -> Bool {\n    a.bitPattern == b.bitPattern\n  }\n  /// Floats have no portable order; natively they order by IEEE's total order.\n  public static func portableCompare(_ a: Double, _ b: Double) -> Int {\n    a.bitPattern == b.bitPattern ? 0 : (a.isTotallyOrdered(belowOrEqualTo: b) ? -1 : 1)\n  }\n  public func portableHash(into hasher: inout Hasher) { hasher.combine(bitPattern) }\n}\n\nextension Complex64: Portable {\n  public static func portableEqual(_ a: Complex64, _ b: Complex64) -> Bool { a == b }\n  public static func portableCompare(_ a: Complex64, _ b: Complex64) -> Int {\n    let c = Float.portableCompare(a.real, b.real)\n    return c != 0 ? c : Float.portableCompare(a.imaginary, b.imaginary)\n  }\n}\n\nextension Complex128: Portable {\n  public static func portableEqual(_ a: Complex128, _ b: Complex128) -> Bool { a == b }\n  public static func portableCompare(_ a: Complex128, _ b: Complex128) -> Int {\n    let c = Double.portableCompare(a.real, b.real)\n    return c != 0 ? c : Double.portableCompare(a.imaginary, b.imaginary)\n  }\n}\n\nextension Rational: Portable {\n  public static func portableEqual(_ a: Rational, _ b: Rational) -> Bool { a == b }\n  public static func portableCompare(_ a: Rational, _ b: Rational) -> Int {\n    BigInt.compare(a.numerator * b.denominator, b.numerator * a.denominator)\n  }\n}\n\nextension ExactDecimal: Portable {\n  public static func portableEqual(_ a: ExactDecimal, _ b: ExactDecimal) -> Bool { a == b }\n  /// By value; 1.0 and 1.00 order alike but are distinct decimals.\n  public static func portableCompare(_ a: ExactDecimal, _ b: ExactDecimal) -> Int {\n    let e = Swift.min(a.exponent, b.exponent)\n    let x = a.coefficient * BigInt(10).power(a.exponent - e)\n    let y = b.coefficient * BigInt(10).power(b.exponent - e)\n    let c = BigInt.compare(x, y)\n    return c != 0 ? c : order(a.exponent, b.exponent)\n  }\n}\n\nextension Symbol: Portable {\n  public static func portableEqual(_ a: Symbol, _ b: Symbol) -> Bool { a == b }\n  /// Symbols have no portable order; natively they order by identity.\n  public static func portableCompare(_ a: Symbol, _ b: Symbol) -> Int {\n    order(ObjectIdentifier(a.identity), ObjectIdentifier(b.identity))\n  }\n}\n\nextension AnyHandle: Portable {\n  public static func portableEqual(_ a: AnyHandle, _ b: AnyHandle) -> Bool { a == b }\n  /// Handles have no portable order; natively they order by identity.\n  public static func portableCompare(_ a: AnyHandle, _ b: AnyHandle) -> Int {\n    order(ObjectIdentifier(a.object), ObjectIdentifier(b.object))\n  }\n}\n\nextension Array: Portable where Element: Portable {\n  public static func portableEqual(_ a: [Element], _ b: [Element]) -> Bool {\n    a.count == b.count && zip(a, b).allSatisfy { Element.portableEqual($0, $1) }\n  }\n  public static func portableCompare(_ a: [Element], _ b: [Element]) -> Int {\n    for (x, y) in zip(a, b) {\n      let c = Element.portableCompare(x, y)\n      if c != 0 { return c }\n    }\n    return order(a.count, b.count)\n  }\n  public func portableHash(into hasher: inout Hasher) {\n    hasher.combine(count)\n    for item in self { item.portableHash(into: &hasher) }\n  }\n}\n\nextension Optional: Portable where Wrapped: Portable {\n  public static func portableEqual(_ a: Wrapped?, _ b: Wrapped?) -> Bool {\n    switch (a, b) {\n    case (nil, nil): return true\n    case (let x?, let y?): return Wrapped.portableEqual(x, y)\n    default: return false\n    }\n  }\n  /// Absent before Present, as LawSpec orders Maybe.\n  public static func portableCompare(_ a: Wrapped?, _ b: Wrapped?) -> Int {\n    switch (a, b) {\n    case (nil, nil): return 0\n    case (nil, _): return -1\n    case (_, nil): return 1\n    case (let x?, let y?): return Wrapped.portableCompare(x, y)\n    }\n  }\n  public func portableHash(into hasher: inout Hasher) {\n    switch self {\n    case nil: hasher.combine(0)\n    case let x?:\n      hasher.combine(1)\n      x.portableHash(into: &hasher)\n    }\n  }\n}\n\nextension Nullable: Portable where Wrapped: Portable {\n  public static func portableEqual(_ a: Nullable, _ b: Nullable) -> Bool {\n    switch (a, b) {\n    case (.null, .null): return true\n    case (.present(let x), .present(let y)): return Wrapped.portableEqual(x, y)\n    default: return false\n    }\n  }\n  public static func portableCompare(_ a: Nullable, _ b: Nullable) -> Int {\n    switch (a, b) {\n    case (.null, .null): return 0\n    case (.null, _): return -1\n    case (_, .null): return 1\n    case (.present(let x), .present(let y)): return Wrapped.portableCompare(x, y)\n    }\n  }\n  public func portableHash(into hasher: inout Hasher) {\n    switch self {\n    case .null: hasher.combine(0)\n    case .present(let x):\n      hasher.combine(1)\n      x.portableHash(into: &hasher)\n    }\n  }\n}\n\nextension Undefinable: Portable where Wrapped: Portable {\n  public static func portableEqual(_ a: Undefinable, _ b: Undefinable) -> Bool {\n    switch (a, b) {\n    case (.undefined, .undefined): return true\n    case (.present(let x), .present(let y)): return Wrapped.portableEqual(x, y)\n    default: return false\n    }\n  }\n  public static func portableCompare(_ a: Undefinable, _ b: Undefinable) -> Int {\n    switch (a, b) {\n    case (.undefined, .undefined): return 0\n    case (.undefined, _): return -1\n    case (_, .undefined): return 1\n    case (.present(let x), .present(let y)): return Wrapped.portableCompare(x, y)\n    }\n  }\n  public func portableHash(into hasher: inout Hasher) {\n    switch self {\n    case .undefined: hasher.combine(0)\n    case .present(let x):\n      hasher.combine(1)\n      x.portableHash(into: &hasher)\n    }\n  }\n}\n\nextension Either: Portable where Left: Portable, Right: Portable {\n  public static func portableEqual(_ a: Either, _ b: Either) -> Bool {\n    switch (a, b) {\n    case (.left(let x), .left(let y)): return Left.portableEqual(x, y)\n    case (.right(let x), .right(let y)): return Right.portableEqual(x, y)\n    default: return false\n    }\n  }\n  /// Left before Right, as their constructors' identities order.\n  public static func portableCompare(_ a: Either, _ b: Either) -> Int {\n    switch (a, b) {\n    case (.left(let x), .left(let y)): return Left.portableCompare(x, y)\n    case (.right(let x), .right(let y)): return Right.portableCompare(x, y)\n    case (.left, .right): return -1\n    case (.right, .left): return 1\n    }\n  }\n  public func portableHash(into hasher: inout Hasher) {\n    switch self {\n    case .left(let x):\n      hasher.combine(0)\n      x.portableHash(into: &hasher)\n    case .right(let x):\n      hasher.combine(1)\n      x.portableHash(into: &hasher)\n    }\n  }\n}\n\n/// Helpers the generated data types use for their constructors' fields.\npublic enum PortableData {\n  /// Compare two constructors' ranks and then their fields, given as\n  /// comparisons in order.\n  public static func compare(_ rankA: Int, _ rankB: Int, _ fields: () -> [Int]) -> Int {\n    if rankA != rankB { return order(rankA, rankB) }\n    for c in fields() where c != 0 { return c }\n    return 0\n  }\n}\n\nextension Value: Portable {\n  /// Values compare as LawSpec does; a value with no portable order (a\n  /// float, a symbol) orders natively by its debug text.\n  public static func portableEqual(_ a: Value, _ b: Value) -> Bool { Recorded.identical(a, b) }\n  public static func portableCompare(_ a: Value, _ b: Value) -> Int {\n    if let c = try? Scalar.compareValues(a, b) { return c }\n    return Scalar.compareText(Recorded.debug(a), Recorded.debug(b))\n  }\n  public func portableHash(into hasher: inout Hasher) { hasher.combine(Recorded.debug(self)) }\n}\n"
swiftSource "LawSpecRuntime/Random.swift" = "// The portable SplitMix64 sequence. Its state is passed explicitly, so\n// concurrent callers never draw from one another's stream, and the same seed\n// replays the same run on every target. ref:splitmix\n// ref:DEC-portable-seeded-generation\n\npublic enum Random {\n  /// A SplitMix64 state.\n  public struct Seed: Sendable, Hashable {\n    public let state: UInt64\n    public init(state: UInt64) { self.state = state }\n  }\n\n  /// The state for a seed (any integer, reduced to 64 bits).\n  public static func seed(_ n: BigInt) -> Seed { Seed(state: n.truncated(UInt64.self)) }\n\n  /// The next output and state.\n  public static func next(_ seed: Seed) -> (UInt64, Seed) {\n    let s = seed.state &+ 0x9e37_79b9_7f4a_7c15\n    let a = (s ^ (s >> 30)) &* 0xbf58_476d_1ce4_e5b9\n    let b = (a ^ (a >> 27)) &* 0x94d0_49bb_1331_11eb\n    return (b ^ (b >> 31), Seed(state: s))\n  }\n\n  /// A draw below a bound (0 for a bound that is not positive), as every\n  /// runtime reduces it: the output modulo the bound.\n  public static func below(_ bound: BigInt, _ state: Seed) -> (BigInt, Seed) {\n    if bound.signum <= 0 { return (.zero, state) }\n    let (n, following) = next(state)\n    return (BigInt(n) % bound, following)\n  }\n\n  /// Two independent states from one, for generators that branch.\n  public static func split(_ state: Seed) -> (Seed, Seed) {\n    let (a, s1) = next(state)\n    let (b, _) = next(s1)\n    return (Seed(state: a), Seed(state: b))\n  }\n}\n"
swiftSource "LawSpecRuntime/Recorded.swift" = "// Typed text for recorded values. Every target writes a recording the same\n// way, so one recorded file checks every implementation. Identities (symbols\n// and handles) are numbered within one recording. ref:REQ-law-primitives\n// ref:DEC-portable-exact-arithmetic\n\nimport Foundation\n\npublic enum Recorded {\n  static func quote(_ s: String) -> String {\n    \"\\\"\"\n      + s.replacingOccurrences(of: \"\\\\\", with: \"\\\\\\\\\").replacingOccurrences(of: \"\\\"\", with: \"\\\\\\\"\")\n      + \"\\\"\"\n  }\n\n  /// The last part of a constructor tag: Shape for example.shapes::type::Shape::Shape.\n  public static func lastPart(_ tag: String) -> String {\n    guard let range = tag.range(of: \"::\", options: .backwards) else { return tag }\n    return String(tag[range.upperBound...])\n  }\n\n  private static func trimDecimal(_ c: BigInt, _ e: Int) -> (BigInt, Int) {\n    if c.isZero { return (.zero, 0) }\n    var coefficient = c\n    var exponent = e\n    while true {\n      let (q, r) = coefficient.quotientAndRemainder(dividingBy: 10)\n      if !r.isZero { return (coefficient, exponent) }\n      coefficient = q\n      exponent += 1\n    }\n  }\n\n  private static func hex(_ bits: UInt64, _ digits: Int) -> String {\n    let text = String(bits, radix: 16)\n    return String(repeating: \"0\", count: Swift.max(0, digits - text.count)) + text\n  }\n\n  private static func floatText(_ value: Value) throws -> String {\n    guard case .float(let w, let bits) = value else {\n      throw Fail.with(\"InvalidRecordedScalar\", \"float\")\n    }\n    let name = \"float\\(w)\"\n    if try Scalar.floatClass(value) == \"nan\" { return name + \"NaN\" }\n    return name + \"Bits(\\\"\" + hex(bits, w == 32 ? 8 : 16) + \"\\\")\"\n  }\n\n  private static func units<S: Sequence>(_ name: String, _ values: S) -> String\n  where S.Element == Int {\n    name + \"([\" + values.map(String.init).joined(separator: \", \") + \"])\"\n  }\n\n  private static func scalar(_ value: Value, _ t: String) throws -> String {\n    switch (t, value) {\n    case (\"Bool\", .bool(let b)): return b ? \"true\" : \"false\"\n    case (\"Unit\", .unit): return \"()\"\n    case (\"Null\", .null): return \"null\"\n    case (\"Undefined\", .undefined): return \"undefined\"\n    case (\"Text\", .text(let s)): return quote(s)\n    case (\"Char\", .int(let n)):\n      guard let code = n.exactly(UInt32.self), let scalar = Unicode.Scalar(code) else {\n        throw Fail.with(\"InvalidRecordedScalar\", t)\n      }\n      return quote(String(Character(scalar)))\n    case (\"CodePoint\", .int(let n)), (\"CodeUnit16\", .int(let n)): return n.description\n    case (\"Bytes\", .bytes(let b)): return units(\"bytes\", b.map(Int.init))\n    case (\"CodePointText\", .raw(_, let us)): return units(\"codePoints\", us)\n    case (\"Utf16Text\", .raw(_, let us)): return units(\"utf16\", us)\n    case (\"Decimal\", .decimal(let c, let e)):\n      let (tc, te) = trimDecimal(c, e)\n      return tc.description + \"e\" + String(te)\n    case (\"Rational\", .ratio(let n, let d)): return \"rational(\\(n), \\(d))\"\n    case (\"Float32\", .float), (\"Float64\", .float): return try floatText(value)\n    case (\"Complex64\", .complex(_, let r, let i)):\n      return \"Complex64(\" + (try floatText(r)) + \", \" + (try floatText(i)) + \")\"\n    case (\"Complex128\", .complex(_, let r, let i)):\n      return \"Complex128(\" + (try floatText(r)) + \", \" + (try floatText(i)) + \")\"\n    case (_, .int(let n)) where Scalar.isIntegerType(t): return n.description\n    default: throw Fail.with(\"InvalidRecordedScalar\", t)\n    }\n  }\n\n  /// Identities numbered within one recording, by kind.\n  private struct Ids {\n    var symbols: [ObjectIdentifier] = []\n    var handles: [String: [ObjectIdentifier]] = [:]\n  }\n\n  private static func render(_ value: Value, _ t: TypeRef, _ schema: Schema?, _ ids: inout Ids)\n    throws -> String\n  {\n    switch (t, value) {\n    case (.named(\"List\", let args), .list(let items)) where args.count == 1:\n      return \"[\" + (try items.map { try render($0, args[0], schema, &ids) }).joined(separator: \", \")\n        + \"]\"\n    case (.named(let kind, let args), .presence(_, nil)) where args.count == 1:\n      return kind == \"Nullable\" ? \"null\" : \"undefined\"\n    case (.named(let kind, let args), .presence(_, let v?)) where args.count == 1:\n      return (kind == \"Nullable\" ? \"nullable(\" : \"optional(\")\n        + (try render(v, args[0], schema, &ids)) + \")\"\n    case (.named(\"Symbol\", let args), .symbol(let id, let description)) where args.isEmpty:\n      let key = ObjectIdentifier(id)\n      if !ids.symbols.contains(key) { ids.symbols.append(key) }\n      let n = ids.symbols.firstIndex(of: key)! + 1\n      return \"symbol(\\(n), \" + quote(description) + \")\"\n    case (.named(let name, let args), .handle(_, let id)) where args.isEmpty:\n      let key = ObjectIdentifier(id.object)\n      var known = ids.handles[name] ?? []\n      if !known.contains(key) { known.append(key) }\n      ids.handles[name] = known\n      return lastPart(name) + \"#\\(known.firstIndex(of: key)! + 1)\"\n    case (_, .data(let tag, let fields)):\n      var types = [TypeRef]()\n      switch (t, tag) {\n      case (_, \"Maybe::Absent\"): types = []\n      case (.named(\"Maybe\", let a), _) where a.count == 1: types = [a[0]]\n      case (.named(\"Either\", let a), \"Either::Left\") where a.count == 2: types = [a[0]]\n      case (.named(\"Either\", let a), \"Either::Right\") where a.count == 2: types = [a[1]]\n      default:\n        guard let s = schema else { throw Fail.with(\"RecordingNeedsSchema\", tag) }\n        types = try Schema.fieldTypes(value, t, s)\n      }\n      let parts = try zip(fields, types).map { try render($0.0, $0.1, schema, &ids) }\n      return parts.isEmpty\n        ? lastPart(tag) : lastPart(tag) + \"(\" + parts.joined(separator: \", \") + \")\"\n    case (.named(let name, let args), _) where args.isEmpty:\n      return try scalar(value, name)\n    default:\n      throw Fail.with(\"InvalidRecordedValue\", Scalar.typeKey(t))\n    }\n  }\n\n  /// A value's recorded text at its type.\n  public static func text(_ value: Value, _ t: TypeRef, _ schema: Schema?) throws -> String {\n    var ids = Ids()\n    return try render(value, t, schema, &ids)\n  }\n\n  /// The untyped rendering a model's recorded state uses.\n  public static func renderPlain(_ value: Value) -> String {\n    switch value {\n    case .bool(true): return \"true\"\n    case .bool(false): return \"false\"\n    case .unit: return \"()\"\n    case .int(let n): return n.description\n    case .text(let s): return quote(s)\n    case .list(let items): return \"[\" + items.map(renderPlain).joined(separator: \", \") + \"]\"\n    case .data(let tag, let fields) where fields.isEmpty: return lastPart(tag)\n    case .data(let tag, let fields):\n      return lastPart(tag) + \"(\" + fields.map(renderPlain).joined(separator: \", \") + \")\"\n    default: return debug(value)\n    }\n  }\n\n  /// Any value, as a diagnostic shows it.\n  public static func debug(_ value: Value) -> String {\n    switch value {\n    case .bool(let b): return \"Bool \\(b)\"\n    case .int(let n): return \"Int \\(n)\"\n    case .ratio(let n, let d): return \"Ratio (\\(n), \\(d))\"\n    case .decimal(let c, let e): return \"Decimal (\\(c), \\(e))\"\n    case .float(let w, let b): return \"Float (\\(w), \\(b))\"\n    case .complex(let w, let r, let i): return \"Complex (\\(w), \\(debug(r)), \\(debug(i)))\"\n    case .text(let s): return \"Text \" + quote(s)\n    case .bytes(let b): return \"Bytes [|\" + b.map { \"\\($0)uy\" }.joined(separator: \"; \") + \"|]\"\n    case .raw(let kind, let units):\n      return \"Raw (\\\"\\(kind)\\\", [\" + units.map(String.init).joined(separator: \"; \") + \"])\"\n    case .unit: return \"Unit\"\n    case .null: return \"Null\"\n    case .undefined: return \"Undefined\"\n    case .symbol(_, let description): return \"Symbol \" + quote(description)\n    case .list(let items): return \"List [\" + items.map(debug).joined(separator: \"; \") + \"]\"\n    case .data(let tag, let fields):\n      return \"Data (\\\"\\(tag)\\\", [\" + fields.map(debug).joined(separator: \"; \") + \"])\"\n    case .presence(let kind, nil): return \"Presence (\\\"\\(kind)\\\", None)\"\n    case .presence(let kind, let v?): return \"Presence (\\\"\\(kind)\\\", Some (\\(debug(v))))\"\n    case .handle(let name, _): return \"Handle \\\"\\(name)\\\"\"\n    }\n  }\n\n  /// Structural identity of two values: floats by their bits, symbols and\n  /// handles by identity.\n  public static func identical(_ a: Value, _ b: Value) -> Bool {\n    switch (a, b) {\n    case (.bool(let x), .bool(let y)): return x == y\n    case (.int(let x), .int(let y)): return x == y\n    case (.ratio(let n1, let d1), .ratio(let n2, let d2)): return n1 == n2 && d1 == d2\n    case (.decimal(let c1, let e1), .decimal(let c2, let e2)): return c1 == c2 && e1 == e2\n    case (.float(let w1, let b1), .float(let w2, let b2)): return w1 == w2 && b1 == b2\n    case (.complex(let w1, let r1, let i1), .complex(let w2, let r2, let i2)):\n      return w1 == w2 && identical(r1, r2) && identical(i1, i2)\n    case (.text(let x), .text(let y)): return String.portableEqual(x, y)\n    case (.bytes(let x), .bytes(let y)): return x == y\n    case (.raw(let k1, let u1), .raw(let k2, let u2)): return k1 == k2 && u1 == u2\n    case (.unit, .unit), (.null, .null), (.undefined, .undefined): return true\n    case (.symbol(let x, let d1), .symbol(let y, let d2)): return x === y && d1 == d2\n    case (.list(let x), .list(let y)):\n      return x.count == y.count && zip(x, y).allSatisfy { identical($0, $1) }\n    case (.data(let t1, let f1), .data(let t2, let f2)):\n      return t1 == t2 && f1.count == f2.count && zip(f1, f2).allSatisfy { identical($0, $1) }\n    case (.presence(let k1, nil), .presence(let k2, nil)): return k1 == k2\n    case (.presence(let k1, let x?), .presence(let k2, let y?)): return k1 == k2 && identical(x, y)\n    case (.handle(let n1, let i1), .handle(let n2, let i2)):\n      return n1 == n2 && HandleIdentity.same(i1, i2)\n    default: return false\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Regex.swift" = "// LawSpec's portable regex grammar, on Unicode scalar values rather than\n// Swift's regex engine and its character classes. A match covers the whole\n// text, and matching tracks reachable positions, so an ambiguous repeat\n// never backtracks exponentially. ref:DEC-typed-core-boundary\n\npublic enum Regex {\n  /// A compiled pattern.\n  public indirect enum Node: Sendable {\n    /// A character set: negated, and items each (negated, ranges).\n    case set(negated: Bool, items: [(Bool, [(Int, Int)])])\n    case sequence([Node])\n    case alternatives([Node])\n    case repeated(Node, low: Int, high: Int?)\n  }\n\n  private static func fail(_ reason: String) -> LawSpecError {\n    Fail.with(\"NonPortableRegex\", reason)\n  }\n\n  private static func require(_ condition: Bool, _ reason: String) throws {\n    if !condition { throw fail(reason) }\n  }\n\n  private static func code(_ c: Character) -> Int { Int(c.unicodeScalars.first!.value) }\n\n  private static func contains(_ text: String, _ c: Int) -> Bool {\n    text.unicodeScalars.contains { Int($0.value) == c }\n  }\n\n  /// A parser over a pattern's code points.\n  private struct Parser {\n    let cs: [Int]\n    var i = 0\n\n    var current: Int? { i < cs.count ? cs[i] : nil }\n    func peek(_ k: Int) -> Int? { i + k < cs.count ? cs[i + k] : nil }\n\n    mutating func escape() throws -> (Bool, [(Int, Int)]) {\n      guard let c = current else { throw Regex.fail(\"TrailingEscape\") }\n      i += 1\n      switch c {\n      case code(\"d\"), code(\"D\"): return (c == code(\"D\"), [(48, 57)])\n      case code(\"w\"), code(\"W\"): return (c == code(\"W\"), [(48, 57), (65, 90), (95, 95), (97, 122)])\n      case code(\"s\"), code(\"S\"): return (c == code(\"S\"), [(9, 13), (32, 32)])\n      case code(\"n\"): return (false, [(10, 10)])\n      case code(\"t\"): return (false, [(9, 9)])\n      case code(\"r\"): return (false, [(13, 13)])\n      case code(\"f\"): return (false, [(12, 12)])\n      case code(\"v\"): return (false, [(11, 11)])\n      default:\n        try Regex.require(Regex.contains(\"\\\\.^$|?*+()[]{}-/\", c), \"UnsupportedEscape\")\n        return (false, [(c, c)])\n      }\n    }\n\n    mutating func classItem() throws -> (Bool, [(Int, Int)]) {\n      guard let c = current else { throw Regex.fail(\"UnclosedClass\") }\n      if c == code(\"\\\\\") {\n        i += 1\n        return try escape()\n      }\n      if c == code(\"[\") { throw Regex.fail(\"UnescapedClassOpen\") }\n      i += 1\n      return (false, [(c, c)])\n    }\n\n    mutating func charClass(_ negated: Bool) throws -> Node {\n      var acc = [(Bool, [(Int, Int)])]()\n      while true {\n        guard let c = current else { throw Regex.fail(\"UnclosedClass\") }\n        if c == code(\"]\") {\n          if acc.isEmpty { throw Regex.fail(\"EmptyClass\") }\n          i += 1\n          return .set(negated: negated, items: acc)\n        }\n        let item = try classItem()\n        if !item.0, item.1.count == 1, item.1[0].0 == item.1[0].1,\n          current == code(\"-\"), let next = peek(1), next != code(\"]\")\n        {\n          let lo = item.1[0].0\n          i += 1\n          let hiItem = try classItem()\n          guard !hiItem.0, hiItem.1.count == 1, hiItem.1[0].0 == hiItem.1[0].1, hiItem.1[0].0 >= lo\n          else {\n            throw Regex.fail(\"InvalidClassRange\")\n          }\n          acc.append((false, [(lo, hiItem.1[0].0)]))\n        } else {\n          acc.append(item)\n        }\n      }\n    }\n\n    mutating func count() throws -> Int {\n      var value = 0\n      var digits = 0\n      while let c = current, c >= code(\"0\"), c <= code(\"9\") {\n        value = value * 10 + (c - code(\"0\"))\n        digits += 1\n        i += 1\n      }\n      try Regex.require(digits > 0, \"MissingRepetitionCount\")\n      return value\n    }\n\n    mutating func repeated(_ node: Node, _ low: Int, _ high: Int?) throws -> Node {\n      try Regex.require(\n        low <= 1000 && (high.map { $0 <= 1000 && $0 >= low } ?? true), \"InvalidRepetitionCount\")\n      if let c = current { try Regex.require(!Regex.contains(\"*+?{\", c), \"RepeatedQuantifier\") }\n      return .repeated(node, low: low, high: high)\n    }\n\n    mutating func quantified(_ node: Node) throws -> Node {\n      guard let c = current else { return node }\n      switch c {\n      case code(\"*\"):\n        i += 1\n        return try repeated(node, 0, nil)\n      case code(\"+\"):\n        i += 1\n        return try repeated(node, 1, nil)\n      case code(\"?\"):\n        i += 1\n        return try repeated(node, 0, 1)\n      case code(\"{\"):\n        i += 1\n        let low = try count()\n        if current == code(\"}\") {\n          i += 1\n          return try repeated(node, low, low)\n        }\n        if current == code(\",\"), peek(1) == code(\"}\") {\n          i += 2\n          return try repeated(node, low, nil)\n        }\n        if current == code(\",\") {\n          i += 1\n          let high = try count()\n          guard current == code(\"}\") else { throw Regex.fail(\"UnclosedRepetition\") }\n          i += 1\n          return try repeated(node, low, high)\n        }\n        throw Regex.fail(\"InvalidRepetition\")\n      default:\n        return node\n      }\n    }\n\n    mutating func alternatives() throws -> Node {\n      var branches = [try sequence()]\n      while current == code(\"|\") {\n        i += 1\n        branches.append(try sequence())\n      }\n      return branches.count == 1 ? branches[0] : .alternatives(branches)\n    }\n\n    mutating func sequence() throws -> Node {\n      var acc = [Node]()\n      while let c = current, c != code(\")\"), c != code(\"|\") {\n        let a = try atom()\n        acc.append(try quantified(a))\n      }\n      return .sequence(acc)\n    }\n\n    mutating func atom() throws -> Node {\n      guard let c = current else { throw Regex.fail(\"MissingAtom\") }\n      if c == code(\"(\") {\n        if peek(1) == code(\"?\") {\n          if peek(2) == code(\":\") {\n            i += 3\n            return try group()\n          }\n          throw Regex.fail(\"UnsupportedGroup\")\n        }\n        i += 1\n        return try group()\n      }\n      if c == code(\"[\") {\n        if peek(1) == code(\"^\") {\n          i += 2\n          return try charClass(true)\n        }\n        i += 1\n        return try charClass(false)\n      }\n      if c == code(\".\") {\n        i += 1\n        return .set(negated: true, items: [(false, [(10, 10)])])\n      }\n      if c == code(\"\\\\\") {\n        i += 1\n        return .set(negated: false, items: [try escape()])\n      }\n      try Regex.require(!Regex.contains(\"*+?{^$]}\", c), \"UnexpectedCharacter\")\n      i += 1\n      return .set(negated: false, items: [(false, [(c, c)])])\n    }\n\n    mutating func group() throws -> Node {\n      let node = try alternatives()\n      guard current == code(\")\") else { throw Regex.fail(\"UnclosedGroup\") }\n      i += 1\n      return node\n    }\n  }\n\n  private static let cache = Locked([String: Node]())\n\n  /// Compile a pattern once; compiled patterns are shared.\n  public static func compile(_ pattern: String) throws -> Node {\n    if let known = cache.with({ $0[pattern] }) { return known }\n    var parser = Parser(cs: Scalar.codePoints(pattern))\n    let node = try parser.alternatives()\n    try require(parser.i == parser.cs.count, \"UnmatchedClosingParenthesis\")\n    cache.with { $0[pattern] = node }\n    return node\n  }\n\n  private static func inSet(_ c: Int, _ items: [(Bool, [(Int, Int)])]) -> Bool {\n    items.contains { negated, ranges in negated != ranges.contains { c >= $0.0 && c <= $0.1 } }\n  }\n\n  private static func reach(_ node: Node, _ text: [Int], _ positions: Set<Int>) -> Set<Int> {\n    switch node {\n    case .set(let negated, let items):\n      return Set(\n        positions.filter { $0 < text.count && inSet(text[$0], items) != negated }.map { $0 + 1 })\n    case .sequence(let nodes):\n      return nodes.reduce(positions) { reach($1, text, $0) }\n    case .alternatives(let nodes):\n      return nodes.reduce(into: Set<Int>()) { $0.formUnion(reach($1, text, positions)) }\n    case .repeated(let inner, let low, let high):\n      var required = positions\n      var i = 0\n      while i < low && !required.isEmpty {\n        required = reach(inner, text, required)\n        i += 1\n      }\n      var seen = required\n      var frontier = required\n      var remaining = high.map { $0 - low }\n      while !frontier.isEmpty && remaining != 0 {\n        let next = reach(inner, text, frontier).subtracting(seen)\n        seen.formUnion(next)\n        frontier = next\n        remaining = remaining.map { $0 - 1 }\n      }\n      return seen\n    }\n  }\n\n  /// Whether a compiled pattern matches the whole text.\n  public static func run(_ node: Node, _ text: String) -> Bool {\n    let points = Scalar.codePoints(text)\n    return reach(node, points, [0]).contains(points.count)\n  }\n\n  /// Whether a pattern matches the whole text.\n  public static func matches(_ pattern: String, _ text: String) throws -> Bool {\n    run(try compile(pattern), text)\n  }\n}\n"
swiftSource "LawSpecRuntime/Remote.swift" = "// Actors and checked definitions answer the same canonical requests: a\n// selector (a message name, or a definition's content hash) and its\n// arguments, each in the canonical wire encoding; the reply is the result.\n// ref:DEC-distribution-canonical-wire\n\n/// One selectable remote function: its arguments' and result's descriptor\n/// texts, and (on the serving side) its body over portable values.\npublic struct RemoteEntry: @unchecked Sendable {\n  public let arguments: [String]\n  public let result: String\n  public let invoke: (([Value]) throws -> Value)?\n\n  public init(_ arguments: [String], _ result: String, _ invoke: (([Value]) throws -> Value)?) {\n    self.arguments = arguments\n    self.result = result\n    self.invoke = invoke\n  }\n}\n\n/// A connection to a remote service: a node, the service's address, its\n/// request kind, the signatures by selector, and the timeout in ms.\npublic struct RemoteClient: Sendable {\n  typealias Typed = (Descriptors.Table, Descriptors.Descriptor)\n  let node: Node\n  let address: String\n  let kind: String\n  let signatures: [String: ([Typed], Typed)]\n  let timeout: Int\n}\n\npublic enum Remote {\n  private static func fail(_ reason: String) -> LawSpecError { Fail.with(\"Remote\", reason) }\n\n  private static func compile(_ entry: RemoteEntry) throws -> (\n    [RemoteClient.Typed], RemoteClient.Typed\n  ) {\n    (try entry.arguments.map(Descriptors.fromText), try Descriptors.fromText(entry.result))\n  }\n\n  /// Serve a table of selectors at a name on a node (\"call\" for actors,\n  /// \"eval\" for definitions); the service's address.\n  @discardableResult\n  public static func serve(\n    _ node: Node, _ name: String, _ kind: String, _ table: [(String, RemoteEntry)]\n  ) throws -> String {\n    if kind != \"call\" && kind != \"eval\" { throw fail(\"invalid_kind\") }\n    var compiled = [\n      String: (([RemoteClient.Typed], RemoteClient.Typed), ([Value]) throws -> Value)\n    ]()\n    for (selector, entry) in table {\n      guard let invoke = entry.invoke else { throw fail(\"invalid_remote_function\") }\n      compiled[selector] = (try compile(entry), invoke)\n    }\n    let services = UncheckedBox(compiled)\n    return try node.registerHandler(name) { frame in\n      if frame.kind != kind {\n        return (3, Array(\"this service does not handle that request kind\".utf8))\n      }\n      func parse() throws -> ([Value], RemoteClient.Typed, ([Value]) throws -> Value)? {\n        guard\n          case (.text(let selector), let start) = try Descriptors.decodePrefix(\n            Wire.textType, frame.payload, 0, [:]),\n          let ((arguments, result), invoke) = services.value[selector]\n        else { return nil }\n        var at = start\n        var values = [Value]()\n        for (t, d) in arguments {\n          let (v, next) = try Descriptors.decodePrefix(d, frame.payload, at, t)\n          values.append(v)\n          at = next\n        }\n        return at == frame.payload.count ? (values, result, invoke) : nil\n      }\n      guard let (values, (t, d), invoke) = (try? parse()) ?? nil else {\n        return (3, Array(\"unknown selector or malformed remote arguments\".utf8))\n      }\n      do {\n        return (0, try Descriptors.encode(d, try invoke(values), t))\n      } catch let e as LawSpecError where e.code == \"ActorStopped\" {\n        return (2, Array(\"the actor has stopped\".utf8))\n      } catch {\n        return (1, Array(Node.message(error).utf8))\n      }\n    }\n  }\n\n  /// A client of a remote service.\n  public static func connect(\n    _ node: Node, _ address: String, _ kind: String, _ signatures: [(String, RemoteEntry)],\n    _ timeout: Int\n  ) throws -> RemoteClient {\n    if timeout < 0 { throw fail(\"invalid_timeout\") }\n    _ = try Wire.splitAddress(address)\n    var compiled = [String: ([RemoteClient.Typed], RemoteClient.Typed)]()\n    for (selector, entry) in signatures { compiled[selector] = try compile(entry) }\n    return RemoteClient(\n      node: node, address: address, kind: kind, signatures: compiled, timeout: timeout)\n  }\n\n  /// Call a selector with portable arguments; its portable result.\n  public static func call(_ client: RemoteClient, _ selector: String, _ arguments: [Value]) throws\n    -> Value\n  {\n    guard let (types, (resultTable, resultType)) = client.signatures[selector] else {\n      throw fail(\"unknown_selector \" + selector)\n    }\n    if types.count != arguments.count { throw fail(\"argument_count\") }\n    var payload = try Descriptors.encode(Wire.textType, .text(selector), [:])\n    for ((t, d), v) in zip(types, arguments) { payload += try Descriptors.encode(d, v, t) }\n    let (status, body) = try client.node.request(\n      client.address, client.kind, payload, client.timeout)\n    let message = String(decoding: body, as: UTF8.self)\n    switch status {\n    case 0: return try Descriptors.decode(resultType, body, resultTable)\n    case 1: throw fail(\"failed \" + message)\n    case 2: throw fail(\"stopped \" + message)\n    case 3: throw fail(\"rejected \" + message)\n    default: throw fail(\"invalid_reply_status \" + String(status))\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Runtime.swift" = "// Services the generated definitions and laws share: contracts, equations,\n// helpers, recordings and concurrent groups. Values stay portable until a\n// native boundary. ref:DEC-typed-core-boundary\n\nimport Foundation\n\npublic enum Runtime {\n  /// A portable boolean as a Swift one.\n  public static func truth(_ value: Value) throws -> Bool {\n    guard case .bool(let b) = value else { throw Fail.with(\"BoolRequired\", \"\\(value)\") }\n    return b\n  }\n\n  public static func not(_ value: Value) throws -> Value { .bool(!(try truth(value))) }\n\n  /// The item of a list of values at a position.\n  public static func item(_ index: Int, _ values: [Value]) -> Value { values[index] }\n\n  /// A data value's field at a position (a list's head and tail).\n  public static func field(_ value: Value, _ index: Int) throws -> Value {\n    switch (value, index) {\n    case (.data(_, let fields), _) where index < fields.count: return fields[index]\n    case (.list(let items), 0) where !items.isEmpty: return items[0]\n    case (.list(let items), 1) where !items.isEmpty: return .list(Array(items.dropFirst()))\n    default: throw Fail.with(\"ExpectedData\", \"\\(value)\")\n    }\n  }\n\n  /// Whether a value was built by a constructor.\n  public static func hasTag(_ tag: String, _ value: Value) -> Bool {\n    switch value {\n    case .data(let t, _): return t == tag\n    case .list(let items): return tag == (items.isEmpty ? \"List::Nil\" : \"List::Cons\")\n    default: return false\n    }\n  }\n\n  /// A match no branch covers.\n  public static func noMatch(_ value: Value) throws -> Value {\n    throw Fail.with(\"MatchFailure\", \"\\(value)\")\n  }\n\n  /// Whether every element of a list satisfies a predicate.\n  public static func allElements(_ value: Value, _ predicate: (Value) throws -> Value) throws\n    -> Value\n  {\n    guard case .list(let items) = value else { throw Fail.with(\"ListRequired\") }\n    for item in items where !(try truth(predicate(item))) { return .bool(false) }\n    return .bool(true)\n  }\n\n  /// Whether every payload of a container satisfies its parameter's predicate.\n  public static func allPayloads(\n    _ value: Value, _ t: TypeRef, _ predicates: [(Value) throws -> Value], _ schema: Schema\n  ) throws -> Value {\n    .bool(try Schema.allPayloads(value, t, predicates.map { p in { try truth(p($0)) } }, schema))\n  }\n\n  /// Nullable or Optional, absent.\n  public static func absent(_ kind: String) -> Value { .presence(kind: kind, value: nil) }\n\n  /// Nullable or Optional, present.\n  public static func present(_ kind: String, _ value: Value) -> Value {\n    .presence(kind: kind, value: value)\n  }\n\n  /// Fail a contract unless it holds.\n  public static func require(_ holds: Value, _ context: String) throws {\n    switch holds {\n    case .bool(true): return\n    case .bool(false): throw Fail.with(\"ContractFailed\", context)\n    default: throw Fail.with(\"NonBooleanContract\", context)\n    }\n  }\n\n  /// Where two unequal values first differ: the path to the item or field,\n  /// and both values there.\n  private static func difference(_ actual: Value, _ expected: Value) -> String {\n    func walk(_ a: Value, _ b: Value, _ path: [String]) -> ([String], String, String)? {\n      switch (a, b) {\n      case (.list(let xs), .list(let ys)):\n        if let i = Array(zip(xs, ys)).firstIndex(where: {\n          Recorded.renderPlain($0) != Recorded.renderPlain($1)\n        }) {\n          return walk(xs[i], ys[i], path + [\"item \\(i + 1)\"])\n        }\n        if xs.count == ys.count { return nil }\n        return (path + [\"length\"], String(xs.count), String(ys.count))\n      case (.data(let tx, let fx), .data(let ty, let fy)) where tx == ty && fx.count == fy.count:\n        let name = Recorded.lastPart(tx)\n        guard\n          let i = Array(zip(fx, fy)).firstIndex(where: {\n            Recorded.renderPlain($0) != Recorded.renderPlain($1)\n          })\n        else { return nil }\n        return walk(fx[i], fy[i], path + [\"field \\(i + 1) of \\(name)\"])\n      default:\n        if path.isEmpty { return nil }\n        return (path, Recorded.renderPlain(a), Recorded.renderPlain(b))\n      }\n    }\n    guard let (path, shownActual, shownExpected) = walk(actual, expected, []) else { return \"\" }\n    return\n      \" | first difference at \\(path.joined(separator: \", \")): expected \\(shownExpected), actual \\(shownActual)\"\n  }\n\n  /// An equation of a law: both sides are kept for the report.\n  public static func assertEqual(_ actual: Value, _ expected: Value, _ label: String) throws\n    -> Value\n  {\n    if Scalar.equal(actual, expected) { return .bool(true) }\n    throw Fail.with(\n      \"EquationFailed\",\n      \"\\(label): actual \\(Recorded.renderPlain(actual)), expected \\(Recorded.renderPlain(expected))\\(difference(actual, expected))\"\n    )\n  }\n\n  /// Name the definition or law a LawSpec failure happened in.\n  public static func contextual<T>(_ identity: String, _ body: () throws -> T) throws -> T {\n    do {\n      return try body()\n    } catch let failure as LawSpecError {\n      throw failure.within(identity)\n    }\n  }\n\n  private static func recordedRoot() -> String {\n    if let given = ProcessInfo.processInfo.environment[\"LAWSPEC_RECORDED\"], !given.isEmpty {\n      return given\n    }\n    let manager = FileManager.default\n    let start = manager.currentDirectoryPath\n    var folder = URL(fileURLWithPath: start)\n    while true {\n      if manager.fileExists(atPath: folder.appendingPathComponent(\"lawspec.json\").path)\n        || manager.fileExists(atPath: folder.appendingPathComponent(\"recorded\").path)\n      {\n        return folder.appendingPathComponent(\"recorded\").path\n      }\n      let parent = folder.deletingLastPathComponent()\n      if parent.path == folder.path {\n        return URL(fileURLWithPath: start).appendingPathComponent(\"recorded\").path\n      }\n      folder = parent\n    }\n  }\n\n  /// Compare a value's text with its recording, or record it under\n  /// LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded).\n  public static func recordedText(_ key: String, _ text: String) throws -> Value {\n    var url = URL(fileURLWithPath: recordedRoot())\n    for part in key.split(separator: \"/\") { url.appendPathComponent(String(part)) }\n    let manager = FileManager.default\n    if ProcessInfo.processInfo.environment[\"LAWSPEC_UPDATE_RECORDED\"] == \"1\" {\n      try? manager.createDirectory(\n        at: url.deletingLastPathComponent(), withIntermediateDirectories: true)\n      do { try (text + \"\\n\").write(to: url, atomically: true, encoding: .utf8) } catch {\n        throw Fail.with(\"RecordingFailed\", \"recorded/\\(key): \\(error)\")\n      }\n      return .bool(true)\n    }\n    if manager.fileExists(atPath: url.path) {\n      var stored = (try? String(contentsOf: url, encoding: .utf8)) ?? \"\"\n      if stored.hasSuffix(\"\\n\") { stored.removeLast() }\n      if String.portableEqual(stored, text) { return .bool(true) }\n      throw Fail.with(\n        \"RecordingDiffers\",\n        \"recorded/\\(key) differs: expected \\(stored), actual \\(text) (lawspec test --update-recorded records the new value)\"\n      )\n    }\n    throw Fail.with(\n      \"RecordingMissing\",\n      \"no recording recorded/\\(key); run lawspec test --update-recorded to record \\(text)\")\n  }\n\n  /// A recorded value, at its type.\n  public static func recorded(_ key: Value, _ value: Value, _ t: TypeRef, _ schema: Schema) throws\n    -> Value\n  {\n    guard case .text(let k) = key else { throw Fail.with(\"TextRequired\", \"recorded\") }\n    return try recordedText(k, Recorded.text(value, t, schema))\n  }\n\n  /// A built-in helper by name.\n  public static func helper(_ name: String, _ values: [Value], _ types: [String], _ bits: Int)\n    throws -> Value\n  {\n    switch (name, values.count) {\n    case (\"incompleteSearch\", 1):\n      if case .text(let reason) = values[0] {\n        throw Fail.with(\"QuantifierSearchIncomplete\", reason)\n      }\n      throw Fail.with(\"QuantifierSearchIncomplete\")\n    case (\"unreachable\", _): throw Fail.with(\"Unreachable\")\n    case (\"regexMatches\", 2):\n      if case .text(let pattern) = values[0], case .text(let text) = values[1] {\n        return .bool(try Regex.matches(pattern, text))\n      }\n    case (\"recorded\", 2):\n      if case .text(let key) = values[0], types.count < 2 {\n        return try recordedText(key, Recorded.renderPlain(values[1]))\n      }\n      return try recorded(\n        values[0], values[1], Scalar.typeOf(types[1]), Schema.create([], [], bits))\n    default:\n      break\n    }\n    return try Scalar.helper(name, values, types, bits)\n  }\n\n  /// Run steps concurrently, each on its own thread, and return their values\n  /// in source order. Every step finishes before the first failure in source\n  /// order is raised.\n  public static func concurrently(_ steps: [() throws -> Value]) throws -> [Value] {\n    let results = Locked([Result<Value, any Error>?](repeating: nil, count: steps.count))\n    let group = DispatchGroup()\n    for (i, step) in steps.enumerated() {\n      group.enter()\n      let work = UncheckedBox(step)\n      LawThread.start {\n        let outcome = Result { try work.value() }\n        results.with { $0[i] = outcome }\n        group.leave()\n      }\n    }\n    group.wait()\n    return try results.with { $0 }.map { try $0!.get() }\n  }\n\n  /// Wait, on this thread, for an async adapter's result.\n  public static func await<T>(_ body: @escaping @Sendable () async throws -> T) throws -> T {\n    let result = Locked<Result<T, any Error>?>(nil)\n    let done = DispatchSemaphore(value: 0)\n    Task.detached {\n      let outcome: Result<T, any Error>\n      do { outcome = .success(try await body()) } catch { outcome = .failure(error) }\n      result.with { $0 = outcome }\n      done.signal()\n    }\n    done.wait()\n    return try result.with { $0 }!.get()\n  }\n\n  /// Discard a value computed for its checks.\n  public static func ignore(_ value: Value) {}\n\n  /// An integer value from its digits.\n  public static func integer(_ digits: String) throws -> Value { try Scalar.integerLiteral(digits) }\n}\n\n/// A value moved to another thread by code that knows it is used there alone.\npublic struct UncheckedBox<T>: @unchecked Sendable {\n  public let value: T\n  public init(_ value: T) { self.value = value }\n}\n\n/// Threads with a large stack for the synchronous runtime: laws, concurrent\n/// steps and timed tests run on them, never on Swift's cooperative pool, so\n/// waiting for an async adapter never starves the pool.\npublic enum LawThread {\n  /// The stack each thread gets: deep recursion over values needs more than\n  /// a secondary thread's default.\n  public static let stackSize = 64 << 20\n\n  /// Start a body on a new thread.\n  public static func start(_ body: @escaping @Sendable () -> Void) {\n    // The new thread sees this one's ambient context (Ambient).\n    let context = UncheckedBox(Ambient.capture())\n    let thread = Thread {\n      Ambient.restore(context.value)\n      body()\n    }\n    thread.stackSize = stackSize\n    thread.start()\n  }\n\n  /// Run a synchronous body on a new thread and wait for it, without\n  /// blocking the caller's thread: what a generated test calls.\n  public static func run<T: Sendable>(_ body: @escaping @Sendable () throws -> T) async throws -> T\n  {\n    try await withCheckedThrowingContinuation { continuation in\n      start {\n        do { continuation.resume(returning: try body()) } catch {\n          continuation.resume(throwing: error)\n        }\n      }\n    }\n  }\n\n  /// Run a synchronous body on a new thread and wait for it, blocking.\n  public static func runBlocking<T>(_ body: @escaping () throws -> T) throws -> T {\n    let result = Locked<Result<T, any Error>?>(nil)\n    let done = DispatchSemaphore(value: 0)\n    let work = UncheckedBox(body)\n    start {\n      let outcome = Result { try work.value() }\n      result.with { $0 = outcome }\n      done.signal()\n    }\n    done.wait()\n    return try result.with { $0 }!.get()\n  }\n}\n\nextension Runtime {\n  /// Wait, on this thread, for an async adapter called by a boxed closure\n  /// (its captures need not be Sendable: only this call uses them).\n  public static func awaitBoxed<T>(_ body: UncheckedBox<() async throws -> T>) throws -> T {\n    try Runtime.await { try await body.value() }\n  }\n}\n\n/// How the embedding API runs the runtime for native callers: a LawSpec\n/// failure inside is a broken contract, a programmer error, so it traps, as\n/// Swift's own checked arithmetic does; a definition's declared failure is\n/// its typed throw.\npublic enum Embedding {\n  private static func trap(_ error: any Error) -> Never {\n    fatalError(\"LawSpec: \\(error)\")\n  }\n\n  /// Run a definition with no failure.\n  public static func run<T>(_ body: @escaping () throws -> T) -> T {\n    do {\n      return try LawThread.runBlocking(body)\n    } catch {\n      trap(error)\n    }\n  }\n\n  /// Run typed code on this thread: it calls no async adapter, so it needs\n  /// no runtime thread of its own.\n  public static func inline<T>(_ body: () throws -> T) -> T {\n    do {\n      return try body()\n    } catch {\n      trap(error)\n    }\n  }\n\n  /// Run typed code that fails with E on this thread.\n  public static func inlineFailing<T, E: Error>(\n    _ ability: String, _ convert: (Value) throws -> E, _ body: () throws -> T\n  ) throws(E) -> T {\n    do {\n      return try body()\n    } catch let raised as RaisedFailure where raised.ability == ability {\n      do {\n        throw try convert(raised.failure)\n      } catch let failure as E {\n        throw failure\n      } catch {\n        trap(error)\n      }\n    } catch {\n      trap(error)\n    }\n  }\n\n  /// Run a definition that fails with E: its failure is thrown as E.\n  public static func runFailing<T, E: Error>(\n    _ ability: String, _ convert: @escaping (Value) throws -> E, _ body: @escaping () throws -> T\n  ) throws(E) -> T {\n    let outcome: Result<T, any Error> = Result { try LawThread.runBlocking(body) }\n    switch outcome {\n    case .success(let value):\n      return value\n    case .failure(let raised as RaisedFailure) where raised.ability == ability:\n      do {\n        throw try convert(raised.failure)\n      } catch let failure as E {\n        throw failure\n      } catch {\n        trap(error)\n      }\n    case .failure(let error):\n      trap(error)\n    }\n  }\n\n  /// Run an async definition with no failure, on a runtime thread.\n  public static func runAsync<T>(_ body: UncheckedBox<() throws -> T>) async -> T {\n    do {\n      return try await LawThread.run { UncheckedBox(try body.value()) }.value\n    } catch {\n      trap(error)\n    }\n  }\n\n  /// Run an async definition that fails with E.\n  public static func runFailingAsync<T, E: Error>(\n    _ ability: String, _ convert: @escaping (Value) throws -> E,\n    _ body: UncheckedBox<() throws -> T>\n  ) async throws(E) -> T {\n    let outcome: Result<UncheckedBox<T>, any Error>\n    do {\n      outcome = .success(try await LawThread.run { UncheckedBox(try body.value()) })\n    } catch {\n      outcome = .failure(error)\n    }\n    switch outcome {\n    case .success(let value):\n      return value.value\n    case .failure(let raised as RaisedFailure) where raised.ability == ability:\n      do {\n        throw try convert(raised.failure)\n      } catch let failure as E {\n        throw failure\n      } catch {\n        trap(error)\n      }\n    case .failure(let error):\n      trap(error)\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/SLHDSA.swift" = "// SLH-DSA-SHAKE-128f (FIPS 205) in pure Swift. CryptoKit has no stateless\n// hash-based signatures, so this whole module is a fallback: key generation\n// from the three seeds, hedged or deterministic signing with a context, and\n// verification.\n\n/// FIPS 205's SLH-DSA-SHAKE-128f.\nenum SLHDSAShake128f {\n  static let n = 16\n  static let fullHeight = 66\n  static let layers = 22\n  static let treeHeight = 3\n  static let forsHeight = 6\n  static let forsTrees = 33\n  static let w = 16\n  static let len1 = 32\n  static let len2 = 3\n  static let len = 35\n  static let messageDigestLength = 34\n  static let publicKeyLength = 32\n  static let privateKeyLength = 64\n  static let signatureLength = 17088\n\n  /// A hash address: 32 bytes of layer, tree, type and position fields.\n  private struct Address {\n    var bytes = [UInt8](repeating: 0, count: 32)\n\n    static let wotsHash: UInt32 = 0\n    static let wotsPublicKey: UInt32 = 1\n    static let tree: UInt32 = 2\n    static let forsTree: UInt32 = 3\n    static let forsRoots: UInt32 = 4\n    static let wotsPRF: UInt32 = 5\n    static let forsPRF: UInt32 = 6\n\n    private mutating func setWord(_ offset: Int, _ value: UInt32) {\n      bytes[offset] = UInt8(truncatingIfNeeded: value >> 24)\n      bytes[offset + 1] = UInt8(truncatingIfNeeded: value >> 16)\n      bytes[offset + 2] = UInt8(truncatingIfNeeded: value >> 8)\n      bytes[offset + 3] = UInt8(truncatingIfNeeded: value)\n    }\n\n    private func word(_ offset: Int) -> UInt32 {\n      UInt32(bytes[offset]) << 24 | UInt32(bytes[offset + 1]) << 16 | UInt32(bytes[offset + 2]) << 8\n        | UInt32(bytes[offset + 3])\n    }\n\n    mutating func setLayer(_ layer: Int) { setWord(0, UInt32(layer)) }\n\n    mutating func setTree(_ tree: UInt64) {\n      for i in 4..<8 { bytes[i] = 0 }\n      for i in 0..<8 { bytes[8 + i] = UInt8(truncatingIfNeeded: tree >> UInt64(8 * (7 - i))) }\n    }\n\n    mutating func setTypeAndClear(_ type: UInt32) {\n      setWord(16, type)\n      for i in 20..<32 { bytes[i] = 0 }\n    }\n\n    mutating func setKeyPair(_ value: Int) { setWord(20, UInt32(value)) }\n    var keyPair: Int { Int(word(20)) }\n    mutating func setChain(_ value: Int) { setWord(24, UInt32(value)) }\n    mutating func setTreeHeight(_ value: Int) { setWord(24, UInt32(value)) }\n    mutating func setHash(_ value: Int) { setWord(28, UInt32(value)) }\n    mutating func setTreeIndex(_ value: Int) { setWord(28, UInt32(value)) }\n    var treeIndex: Int { Int(word(28)) }\n  }\n\n  /// The tweakable hash F, H and T: SHAKE256 of the public seed, the\n  /// address and the message.\n  private static func tweak(_ seed: [UInt8], _ address: Address, _ message: [UInt8]) -> [UInt8] {\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(seed)\n    sponge.absorb(address.bytes)\n    sponge.absorb(message)\n    return sponge.squeeze(n)\n  }\n\n  private static func prf(_ publicSeed: [UInt8], _ secretSeed: [UInt8], _ address: Address)\n    -> [UInt8]\n  {\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(publicSeed)\n    sponge.absorb(address.bytes)\n    sponge.absorb(secretSeed)\n    return sponge.squeeze(n)\n  }\n\n  private static func baseTwoB(_ x: [UInt8], _ b: Int, _ count: Int) -> [Int] {\n    var input = 0\n    var bits = 0\n    var total = 0\n    var out: [Int] = []\n    out.reserveCapacity(count)\n    for _ in 0..<count {\n      while bits < b {\n        total = (total << 8) | Int(x[input])\n        input += 1\n        bits += 8\n      }\n      bits -= b\n      out.append((total >> bits) & ((1 << b) - 1))\n      total &= (1 << bits) - 1\n    }\n    return out\n  }\n\n  // MARK: WOTS+\n\n  private static func chain(\n    _ x: [UInt8], _ start: Int, _ steps: Int, _ seed: [UInt8], _ address: inout Address\n  ) -> [UInt8] {\n    var value = x\n    for j in start..<(start + steps) {\n      address.setHash(j)\n      value = tweak(seed, address, value)\n    }\n    return value\n  }\n\n  private static func wotsDigits(_ message: [UInt8]) -> [Int] {\n    var digits = baseTwoB(message, 4, len1)\n    var checksum = digits.reduce(0) { $0 + (w - 1 - $1) }\n    checksum <<= 4\n    digits += baseTwoB(\n      [UInt8(truncatingIfNeeded: checksum >> 8), UInt8(truncatingIfNeeded: checksum)], 4, len2)\n    return digits\n  }\n\n  private static func wotsSecret(\n    _ secretSeed: [UInt8], _ publicSeed: [UInt8], _ address: Address, _ chainIndex: Int\n  ) -> [UInt8] {\n    var secretAddress = address\n    secretAddress.setTypeAndClear(Address.wotsPRF)\n    secretAddress.setKeyPair(address.keyPair)\n    secretAddress.setChain(chainIndex)\n    return prf(publicSeed, secretSeed, secretAddress)\n  }\n\n  private static func wotsCompress(_ parts: [UInt8], _ seed: [UInt8], _ address: Address) -> [UInt8]\n  {\n    var publicAddress = address\n    publicAddress.setTypeAndClear(Address.wotsPublicKey)\n    publicAddress.setKeyPair(address.keyPair)\n    return tweak(seed, publicAddress, parts)\n  }\n\n  private static func wotsPublicKey(\n    _ secretSeed: [UInt8], _ publicSeed: [UInt8], _ address: inout Address\n  ) -> [UInt8] {\n    var parts: [UInt8] = []\n    for i in 0..<len {\n      let secret = wotsSecret(secretSeed, publicSeed, address, i)\n      address.setChain(i)\n      parts += chain(secret, 0, w - 1, publicSeed, &address)\n    }\n    return wotsCompress(parts, publicSeed, address)\n  }\n\n  private static func wotsSign(\n    _ message: [UInt8], _ secretSeed: [UInt8], _ publicSeed: [UInt8], _ address: inout Address\n  ) -> [UInt8] {\n    var signature: [UInt8] = []\n    for (i, digit) in wotsDigits(message).enumerated() {\n      let secret = wotsSecret(secretSeed, publicSeed, address, i)\n      address.setChain(i)\n      signature += chain(secret, 0, digit, publicSeed, &address)\n    }\n    return signature\n  }\n\n  private static func wotsPublicKeyFromSignature(\n    _ signature: ArraySlice<UInt8>, _ message: [UInt8], _ seed: [UInt8], _ address: inout Address\n  ) -> [UInt8] {\n    let base = signature.startIndex\n    var parts: [UInt8] = []\n    for (i, digit) in wotsDigits(message).enumerated() {\n      address.setChain(i)\n      parts += chain(\n        Array(signature[(base + i * n)..<(base + i * n + n)]), digit, w - 1 - digit, seed, &address)\n    }\n    return wotsCompress(parts, seed, address)\n  }\n\n  // MARK: XMSS and the hypertree\n\n  private static func xmssNode(\n    _ secretSeed: [UInt8], _ index: Int, _ height: Int, _ publicSeed: [UInt8],\n    _ address: inout Address\n  ) -> [UInt8] {\n    if height == 0 {\n      address.setTypeAndClear(Address.wotsHash)\n      address.setKeyPair(index)\n      return wotsPublicKey(secretSeed, publicSeed, &address)\n    }\n    let left = xmssNode(secretSeed, 2 * index, height - 1, publicSeed, &address)\n    let right = xmssNode(secretSeed, 2 * index + 1, height - 1, publicSeed, &address)\n    address.setTypeAndClear(Address.tree)\n    address.setTreeHeight(height)\n    address.setTreeIndex(index)\n    return tweak(publicSeed, address, left + right)\n  }\n\n  private static func xmssSign(\n    _ message: [UInt8], _ secretSeed: [UInt8], _ index: Int, _ publicSeed: [UInt8],\n    _ address: inout Address\n  ) -> [UInt8] {\n    var authentication: [UInt8] = []\n    for j in 0..<treeHeight {\n      authentication += xmssNode(secretSeed, (index >> j) ^ 1, j, publicSeed, &address)\n    }\n    address.setTypeAndClear(Address.wotsHash)\n    address.setKeyPair(index)\n    return wotsSign(message, secretSeed, publicSeed, &address) + authentication\n  }\n\n  private static func xmssRoot(\n    _ index: Int, _ signature: ArraySlice<UInt8>, _ message: [UInt8], _ seed: [UInt8],\n    _ address: inout Address\n  ) -> [UInt8] {\n    let base = signature.startIndex\n    address.setTypeAndClear(Address.wotsHash)\n    address.setKeyPair(index)\n    var node = wotsPublicKeyFromSignature(\n      signature[base..<(base + len * n)], message, seed, &address)\n    address.setTypeAndClear(Address.tree)\n    address.setTreeIndex(index)\n    for k in 0..<treeHeight {\n      let start = base + len * n + k * n\n      let sibling = Array(signature[start..<(start + n)])\n      address.setTreeHeight(k + 1)\n      if (index >> k) & 1 == 0 {\n        address.setTreeIndex(address.treeIndex / 2)\n        node = tweak(seed, address, node + sibling)\n      } else {\n        address.setTreeIndex((address.treeIndex - 1) / 2)\n        node = tweak(seed, address, sibling + node)\n      }\n    }\n    return node\n  }\n\n  private static let xmssSignatureLength = (len + treeHeight) * n\n\n  private static func hypertreeSign(\n    _ message: [UInt8], _ secretSeed: [UInt8], _ publicSeed: [UInt8], _ tree: UInt64, _ leaf: Int\n  ) -> [UInt8] {\n    var address = Address()\n    var treeIndex = tree\n    var leafIndex = leaf\n    address.setTree(treeIndex)\n    var part = xmssSign(message, secretSeed, leafIndex, publicSeed, &address)\n    var signature = part\n    var root = xmssRoot(leafIndex, part[...], message, publicSeed, &address)\n    for j in 1..<layers {\n      leafIndex = Int(treeIndex & UInt64((1 << treeHeight) - 1))\n      treeIndex >>= UInt64(treeHeight)\n      address.setLayer(j)\n      address.setTree(treeIndex)\n      part = xmssSign(root, secretSeed, leafIndex, publicSeed, &address)\n      signature += part\n      if j < layers - 1 {\n        root = xmssRoot(leafIndex, part[...], root, publicSeed, &address)\n      }\n    }\n    return signature\n  }\n\n  private static func hypertreeVerify(\n    _ message: [UInt8], _ signature: ArraySlice<UInt8>, _ seed: [UInt8], _ tree: UInt64,\n    _ leaf: Int, _ root: [UInt8]\n  ) -> Bool {\n    let base = signature.startIndex\n    var address = Address()\n    var treeIndex = tree\n    var leafIndex = leaf\n    address.setTree(treeIndex)\n    var node = xmssRoot(\n      leafIndex, signature[base..<(base + xmssSignatureLength)], message, seed, &address)\n    for j in 1..<layers {\n      leafIndex = Int(treeIndex & UInt64((1 << treeHeight) - 1))\n      treeIndex >>= UInt64(treeHeight)\n      address.setLayer(j)\n      address.setTree(treeIndex)\n      let start = base + j * xmssSignatureLength\n      node = xmssRoot(\n        leafIndex, signature[start..<(start + xmssSignatureLength)], node, seed, &address)\n    }\n    return node == root\n  }\n\n  // MARK: FORS\n\n  private static func forsSecret(\n    _ secretSeed: [UInt8], _ publicSeed: [UInt8], _ address: Address, _ index: Int\n  ) -> [UInt8] {\n    var secretAddress = address\n    secretAddress.setTypeAndClear(Address.forsPRF)\n    secretAddress.setKeyPair(address.keyPair)\n    secretAddress.setTreeIndex(index)\n    return prf(publicSeed, secretSeed, secretAddress)\n  }\n\n  private static func forsNode(\n    _ secretSeed: [UInt8], _ index: Int, _ height: Int, _ publicSeed: [UInt8],\n    _ address: inout Address\n  ) -> [UInt8] {\n    if height == 0 {\n      let secret = forsSecret(secretSeed, publicSeed, address, index)\n      address.setTreeHeight(0)\n      address.setTreeIndex(index)\n      return tweak(publicSeed, address, secret)\n    }\n    let left = forsNode(secretSeed, 2 * index, height - 1, publicSeed, &address)\n    let right = forsNode(secretSeed, 2 * index + 1, height - 1, publicSeed, &address)\n    address.setTreeHeight(height)\n    address.setTreeIndex(index)\n    return tweak(publicSeed, address, left + right)\n  }\n\n  private static func forsSign(\n    _ digest: [UInt8], _ secretSeed: [UInt8], _ publicSeed: [UInt8], _ address: inout Address\n  ) -> [UInt8] {\n    var signature: [UInt8] = []\n    for (i, index) in baseTwoB(digest, forsHeight, forsTrees).enumerated() {\n      signature += forsSecret(secretSeed, publicSeed, address, (i << forsHeight) + index)\n      for j in 0..<forsHeight {\n        let sibling = (index >> j) ^ 1\n        signature += forsNode(\n          secretSeed, (i << (forsHeight - j)) + sibling, j, publicSeed, &address)\n      }\n    }\n    return signature\n  }\n\n  private static func forsPublicKey(\n    _ signature: ArraySlice<UInt8>, _ digest: [UInt8], _ seed: [UInt8], _ address: inout Address\n  ) -> [UInt8] {\n    let base = signature.startIndex\n    var roots: [UInt8] = []\n    for (i, index) in baseTwoB(digest, forsHeight, forsTrees).enumerated() {\n      let start = base + i * (forsHeight + 1) * n\n      address.setTreeHeight(0)\n      address.setTreeIndex((i << forsHeight) + index)\n      var node = tweak(seed, address, Array(signature[start..<(start + n)]))\n      for j in 0..<forsHeight {\n        let siblingStart = start + (j + 1) * n\n        let sibling = Array(signature[siblingStart..<(siblingStart + n)])\n        address.setTreeHeight(j + 1)\n        if (index >> j) & 1 == 0 {\n          address.setTreeIndex(address.treeIndex / 2)\n          node = tweak(seed, address, node + sibling)\n        } else {\n          address.setTreeIndex((address.treeIndex - 1) / 2)\n          node = tweak(seed, address, sibling + node)\n        }\n      }\n      roots += node\n    }\n    var rootsAddress = address\n    rootsAddress.setTypeAndClear(Address.forsRoots)\n    rootsAddress.setKeyPair(address.keyPair)\n    return tweak(seed, rootsAddress, roots)\n  }\n\n  private static let forsSignatureLength = forsTrees * (forsHeight + 1) * n\n\n  // MARK: SLH-DSA\n\n  /// The key pair of SK.seed || SK.prf || PK.seed: the 32-byte public key\n  /// and the 64-byte private key.\n  static func keyGen(_ seed: [UInt8]) -> (publicKey: [UInt8], privateKey: [UInt8]) {\n    let secretSeed = Array(seed[0..<n])\n    let publicSeed = Array(seed[(2 * n)..<(3 * n)])\n    var address = Address()\n    address.setLayer(layers - 1)\n    let root = xmssNode(secretSeed, 0, treeHeight, publicSeed, &address)\n    return (publicSeed + root, seed + root)\n  }\n\n  /// The message digest's FORS part, tree index and leaf index.\n  private static func split(_ digest: [UInt8]) -> (fors: [UInt8], tree: UInt64, leaf: Int) {\n    let fors = Array(digest[0..<25])\n    var tree: UInt64 = 0\n    for byte in digest[25..<33] { tree = tree << 8 | UInt64(byte) }\n    tree &= (UInt64(1) << 63) - 1\n    let leaf = Int(digest[33]) & ((1 << treeHeight) - 1)\n    return (fors, tree, leaf)\n  }\n\n  private static func messageDigest(\n    _ randomizer: [UInt8], _ publicKey: ArraySlice<UInt8>, _ message: [UInt8]\n  ) -> [UInt8] {\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(randomizer)\n    sponge.absorb(Array(publicKey))\n    sponge.absorb(message)\n    return sponge.squeeze(messageDigestLength)\n  }\n\n  /// Sign with a context string; the additional randomness is n fresh bytes\n  /// for a hedged signature, or the public seed for a deterministic one.\n  static func sign(\n    _ privateKey: [UInt8], _ message: [UInt8], _ context: [UInt8], additionalRandomness: [UInt8]\n  ) -> [UInt8] {\n    let secretSeed = Array(privateKey[0..<n])\n    let secretPRF = Array(privateKey[n..<(2 * n)])\n    let publicSeed = Array(privateKey[(2 * n)..<(3 * n)])\n    let prefixed = [0, UInt8(context.count)] + context + message\n    var sponge = KeccakSponge.shake256()\n    sponge.absorb(secretPRF)\n    sponge.absorb(additionalRandomness)\n    sponge.absorb(prefixed)\n    let randomizer = sponge.squeeze(n)\n    let (fors, tree, leaf) = split(\n      messageDigest(randomizer, privateKey[(2 * n)..<(4 * n)], prefixed))\n    var address = Address()\n    address.setTree(tree)\n    address.setTypeAndClear(Address.forsTree)\n    address.setKeyPair(leaf)\n    let forsSignature = forsSign(fors, secretSeed, publicSeed, &address)\n    let forsKey = forsPublicKey(forsSignature[...], fors, publicSeed, &address)\n    return randomizer + forsSignature + hypertreeSign(forsKey, secretSeed, publicSeed, tree, leaf)\n  }\n\n  /// Verify a signature with a context string.\n  static func verify(\n    _ publicKey: [UInt8], _ message: [UInt8], _ signature: [UInt8], _ context: [UInt8]\n  ) -> Bool {\n    guard publicKey.count == publicKeyLength, signature.count == signatureLength,\n      context.count <= 255\n    else { return false }\n    let publicSeed = Array(publicKey[0..<n])\n    let root = Array(publicKey[n..<(2 * n)])\n    let prefixed = [0, UInt8(context.count)] + context + message\n    let randomizer = Array(signature[0..<n])\n    let (fors, tree, leaf) = split(messageDigest(randomizer, publicKey[...], prefixed))\n    var address = Address()\n    address.setTree(tree)\n    address.setTypeAndClear(Address.forsTree)\n    address.setKeyPair(leaf)\n    let forsKey = forsPublicKey(\n      signature[n..<(n + forsSignatureLength)], fors, publicSeed, &address)\n    return hypertreeVerify(\n      forsKey, signature[(n + forsSignatureLength)...], publicSeed, tree, leaf, root)\n  }\n}\n"
swiftSource "LawSpecRuntime/Scalar.swift" = "// LawSpec's scalar domain in Swift. Exact arithmetic never goes through a\n// native float, and IEEE values are rounded once, from an exact ratio, to\n// nearest with ties to even. Every generated law and dynamic definition uses\n// these operations, so Swift agrees with the other targets.\n// ref:DEC-portable-exact-arithmetic ref:ieee-754 ref:DEC-explicit-machine-profile\n\nimport Foundation\n\n/// A value guarded by a lock, for the runtime's few shared caches.\npublic final class Locked<State>: @unchecked Sendable {\n  private var state: State\n  private let lock = NSLock()\n  public init(_ state: State) { self.state = state }\n  /// Run a body with the state, under the lock.\n  public func with<R>(_ body: (inout State) throws -> R) rethrows -> R {\n    lock.lock()\n    defer { lock.unlock() }\n    return try body(&state)\n  }\n}\n\npublic enum Scalar {\n  // MARK: Type keys\n\n  private static func tokenize(_ text: String) -> [String] {\n    var tokens = [String]()\n    var word = \"\"\n    for c in text {\n      switch c {\n      case \"(\", \")\":\n        if !word.isEmpty {\n          tokens.append(word)\n          word = \"\"\n        }\n        tokens.append(String(c))\n      case \" \", \"\\t\":\n        if !word.isEmpty {\n          tokens.append(word)\n          word = \"\"\n        }\n      default:\n        word.append(c)\n      }\n    }\n    if !word.isEmpty { tokens.append(word) }\n    return tokens\n  }\n\n  private static func application(_ parts: [TypeRef]) throws -> TypeRef {\n    guard let first = parts.first else { throw Fail.with(\"InvalidTypeKey\") }\n    if parts.count == 1 { return first }\n    guard case .named(let name, let args) = first, args.isEmpty else {\n      throw Fail.with(\"InvalidTypeKey\")\n    }\n    if [\"List\", \"Maybe\", \"Optional\", \"Nullable\"].contains(name) {\n      return .named(name, [try application(Array(parts.dropFirst()))])\n    }\n    return .named(name, Array(parts.dropFirst()))\n  }\n\n  private static func parts(_ tokens: [String], _ start: Int) throws -> ([TypeRef], Int) {\n    var acc = [TypeRef]()\n    var i = start\n    while i < tokens.count {\n      let token = tokens[i]\n      if token == \")\" { return (acc, i) }\n      if token == \"(\" {\n        let (inner, after) = try parts(tokens, i + 1)\n        guard after < tokens.count, tokens[after] == \")\" else { throw Fail.with(\"InvalidTypeKey\") }\n        acc.append(try application(inner))\n        i = after + 1\n      } else if token.hasPrefix(\"$\") {\n        guard let index = Int(token.dropFirst()) else { throw Fail.with(\"InvalidTypeKey\", token) }\n        acc.append(.parameter(index))\n        i += 1\n      } else {\n        acc.append(.named(token, []))\n        i += 1\n      }\n    }\n    return (acc, i)\n  }\n\n  private static let typeCache = Locked([String: TypeRef]())\n\n  /// The type a key names: `Either (Int8) (Text)`, `List Int8`, `Maybe (List Text)`.\n  /// Parentheses keep nested Either and presence arguments apart.\n  public static func typeOf(_ key: String) throws -> TypeRef {\n    if let known = typeCache.with({ $0[key] }) { return known }\n    let tokens = tokenize(key)\n    let (found, rest) = try parts(tokens, 0)\n    if rest != tokens.count { throw Fail.with(\"InvalidTypeKey\", key) }\n    let t = try application(found)\n    typeCache.with { $0[key] = t }\n    return t\n  }\n\n  /// The key of a type, as typeOf reads it.\n  public static func typeKey(_ t: TypeRef) -> String {\n    switch t {\n    case .named(let name, let args) where args.isEmpty: return name\n    case .named(let name, let args): return name + args.map { \" (\" + typeKey($0) + \")\" }.joined()\n    case .parameter(let i): return \"$\\(i)\"\n    }\n  }\n\n  // MARK: Integers\n\n  private static let integerTypes: Set<String> = [\n    \"Int8\", \"Int16\", \"Int32\", \"Int64\", \"UInt8\", \"UInt16\", \"UInt32\", \"UInt64\",\n    \"IntSize\", \"UIntSize\", \"UIntPtr\", \"Integer\", \"BigInt\", \"BigUInt\",\n  ]\n\n  /// Whether a scalar name is one of LawSpec's integer types.\n  public static func isIntegerType(_ name: String) -> Bool { integerTypes.contains(name) }\n\n  static func pow2(_ n: Int) -> BigInt { BigInt.one << n }\n\n  private static func signed(_ width: Int) -> (BigInt?, BigInt?) {\n    (-pow2(width - 1), pow2(width - 1) - .one)\n  }\n\n  /// An integer type's inclusive bounds under a machine profile (32 or 64 bits).\n  public static func bounds(_ name: String, _ bits: Int) throws -> (BigInt?, BigInt?) {\n    if bits != 32 && bits != 64 { throw Fail.with(\"InvalidMachineBits\", \"\\(bits)\") }\n    switch name {\n    case \"Integer\", \"BigInt\": return (nil, nil)\n    case \"BigUInt\": return (.zero, nil)\n    case \"IntSize\": return signed(bits)\n    case \"UIntSize\", \"UIntPtr\": return (.zero, pow2(bits) - .one)\n    default:\n      if name.hasPrefix(\"UInt\"), let width = Int(name.dropFirst(4)) {\n        return (.zero, pow2(width) - .one)\n      }\n      if name.hasPrefix(\"Int\"), let width = Int(name.dropFirst(3)) { return signed(width) }\n      throw Fail.with(\"UnknownInteger\", name)\n    }\n  }\n\n  private static func checkBounds(_ value: BigInt, _ name: String, _ bits: Int) throws -> Value {\n    let (lo, hi) = try bounds(name, bits)\n    if let l = lo, value < l { throw Fail.with(\"IntegerOutOfRange\", \"\\(name) \\(value)\") }\n    if let h = hi, value > h { throw Fail.with(\"IntegerOutOfRange\", \"\\(name) \\(value)\") }\n    return .int(value)\n  }\n\n  // MARK: Exact numbers\n\n  /// A normalized fraction.\n  public static func ratio(_ n: BigInt, _ d: BigInt) throws -> Value {\n    if d.isZero { throw Fail.with(\"InvalidRational\", \"zero denominator\") }\n    let (a, b) = normalized(n, d)\n    return .ratio(a, b)\n  }\n\n  static func normalized(_ n: BigInt, _ d: BigInt) -> (BigInt, BigInt) {\n    let g = BigInt.gcd(n, d)\n    let s: BigInt = d.isNegative ? -1 : 1\n    return (s * n / g, d.magnitude / g)\n  }\n\n  static func pow10(_ n: Int) -> BigInt { BigInt(10).power(n) }\n\n  // IEEE layouts: fraction bits, exponent bits, bias.\n  private static func format(_ width: Int) throws -> (Int, Int, Int) {\n    switch width {\n    case 32: return (23, 8, 127)\n    case 64: return (52, 11, 1023)\n    default: throw Fail.with(\"InvalidIeeeWidth\", \"\\(width)\")\n    }\n  }\n\n  private enum Decoded {\n    case finite(sign: Int, mantissa: BigInt, exponent: Int)\n    case infinity(sign: Int)\n    case nan\n  }\n\n  private static func decode(_ width: Int, _ bits: UInt64) throws -> Decoded {\n    let (p, e, bias) = try format(width)\n    let sign = Int((bits >> UInt64(width - 1)) & 1)\n    let exponent = Int((bits >> UInt64(p)) & ((1 << UInt64(e)) - 1))\n    let fraction = bits & ((1 << UInt64(p)) - 1)\n    let top = (1 << e) - 1\n    if exponent == top { return fraction == 0 ? .infinity(sign: sign) : .nan }\n    if exponent == 0 {\n      return .finite(sign: sign, mantissa: BigInt(fraction), exponent: 1 - bias - p)\n    }\n    return .finite(\n      sign: sign, mantissa: BigInt((1 << UInt64(p)) + fraction), exponent: exponent - bias - p)\n  }\n\n  /// The exact ratio of an exact number or a finite float.\n  public static func exact(_ value: Value) throws -> (BigInt, BigInt) {\n    switch value {\n    case .int(let n): return (n, .one)\n    case .ratio(let n, let d): return (n, d)\n    case .decimal(let c, _) where c.isZero: return (.zero, .one)\n    case .decimal(let c, let e) where e >= 0: return (c * pow10(e), .one)\n    case .decimal(let c, let e): return normalized(c, pow10(-e))\n    case .float(let w, let b):\n      switch try decode(w, b) {\n      case .finite(let sign, let m, let e):\n        let signedM = sign == 0 ? m : -m\n        return e >= 0 ? (signedM << e, .one) : normalized(signedM, pow2(-e))\n      default:\n        throw Fail.with(\"NonFiniteExactConversion\")\n      }\n    default:\n      throw Fail.with(\"ExactNumberRequired\", \"\\(value)\")\n    }\n  }\n\n  static func isExact(_ value: Value) -> Bool {\n    switch value {\n    case .int, .ratio, .decimal: return true\n    default: return false\n    }\n  }\n\n  private static func factors(_ n: BigInt, _ factor: BigInt) -> (BigInt, Int) {\n    var rest = n\n    var count = 0\n    while true {\n      let (q, r) = rest.quotientAndRemainder(dividingBy: factor)\n      if !r.isZero { return (rest, count) }\n      rest = q\n      count += 1\n    }\n  }\n\n  /// A decimal for an exact ratio, when its expansion terminates in base ten.\n  static func finiteDecimal(_ n: BigInt, _ d: BigInt) throws -> Value {\n    let (rn, rd) = normalized(n, d)\n    let (d2, twos) = factors(rd, 2)\n    let (d5, fives) = factors(d2, 5)\n    if d5 != .one { throw Fail.with(\"NonTerminatingDecimal\") }\n    let scale = Swift.max(twos, fives)\n    return .decimal(rn * BigInt(2).power(scale - twos) * BigInt(5).power(scale - fives), -scale)\n  }\n\n  // MARK: IEEE floats\n\n  private static func floatValue(_ width: Int, _ bits: UInt64) throws -> Value {\n    if width == 32 && bits > 0xFFFF_FFFF { throw Fail.with(\"InvalidIeeeBits\") }\n    return .float(width: width, bits: bits)\n  }\n\n  private static func zero(_ width: Int, _ sign: Int) -> Value {\n    .float(width: width, bits: UInt64(sign) << UInt64(width - 1))\n  }\n\n  private static func infinity(_ width: Int, _ sign: Int) -> Value {\n    let (p, e) = width == 32 ? (23, 8) : (52, 11)\n    return .float(\n      width: width,\n      bits: (UInt64(sign) << UInt64(width - 1)) | (((1 << UInt64(e)) - 1) << UInt64(p)))\n  }\n\n  private static func nan(_ width: Int) -> Value {\n    let p = width == 32 ? 23 : 52\n    guard case .float(_, let inf) = infinity(width, 0) else { return .float(width: width, bits: 0) }\n    return .float(width: width, bits: inf | (1 << UInt64(p - 1)))\n  }\n\n  private static func floorLog2(_ n: BigInt, _ d: BigInt) -> Int {\n    let guess = n.bitLength - d.bitLength\n    let below = guess >= 0 ? n < (d << guess) : (n << -guess) < d\n    return below ? guess - 1 : guess\n  }\n\n  static func roundRatio(_ n: BigInt, _ d: BigInt) -> BigInt {\n    let (q, r) = n.quotientAndRemainder(dividingBy: d)\n    let twice = BigInt(2) * r\n    if twice > d || (twice == d && !q.isEven) { return q + .one }\n    return q\n  }\n\n  /// The float of a width nearest an exact ratio; a zero takes the given sign.\n  public static func floatFromRatio(_ width: Int, _ n: BigInt, _ d: BigInt, _ zeroSign: Int) throws\n    -> Value\n  {\n    if d.isZero { throw Fail.with(\"ZeroDenominator\") }\n    if n.isZero { return zero(width, zeroSign) }\n    let (p, _, bias) = try format(width)\n    let s = (n.isNegative != d.isNegative) ? 1 : 0\n    let an = n.magnitude\n    let ad = d.magnitude\n    let exponent = Swift.max(1 - bias, floorLog2(an, ad))\n    let shift = p - exponent\n    let mantissa = shift >= 0 ? roundRatio(an << shift, ad) : roundRatio(an, ad << -shift)\n    var m = mantissa\n    var e = exponent\n    if mantissa >= pow2(p + 1) {\n      m = mantissa >> 1\n      e = exponent + 1\n    }\n    if e > bias { return infinity(width, s) }\n    let encoded: UInt64 = m < pow2(p) ? 0 : UInt64(e + bias)\n    let fraction = (m & (pow2(p) - .one)).exactly(UInt64.self) ?? 0\n    return .float(\n      width: width, bits: (UInt64(s) << UInt64(width - 1)) | (encoded << UInt64(p)) | fraction)\n  }\n\n  /// A float's class: \"nan\", \"infinity\", \"zero\" or \"finite\".\n  public static func floatClass(_ value: Value) throws -> String {\n    guard case .float(let w, let b) = value else { throw Fail.with(\"FloatRequired\") }\n    switch try decode(w, b) {\n    case .nan: return \"nan\"\n    case .infinity: return \"infinity\"\n    case .finite(_, let m, _) where m.isZero: return \"zero\"\n    case .finite: return \"finite\"\n    }\n  }\n\n  static func floatSign(_ value: Value) -> Int {\n    guard case .float(let w, let b) = value else { return 0 }\n    return Int((b >> UInt64(w - 1)) & 1)\n  }\n\n  /// A value as a float of a width: exact numbers round once, floats keep NaN\n  /// and infinity and otherwise round their exact value.\n  public static func toFloat(_ value: Value, _ width: Int) throws -> Value {\n    if case .float(let w, let b) = value {\n      if w == width { return value }\n      switch try decode(w, b) {\n      case .nan: return nan(width)\n      case .infinity(let s): return infinity(width, s)\n      default:\n        let (n, d) = try exact(value)\n        return try floatFromRatio(width, n, d, floatSign(value))\n      }\n    }\n    let (n, d) = try exact(value)\n    return try floatFromRatio(width, n, d, 0)\n  }\n\n  /// A complex literal of two floats of a width.\n  public static func complexOf(_ width: Int, _ real: Value, _ imaginary: Value) -> Value {\n    .complex(width: width, real: real, imaginary: imaginary)\n  }\n\n  public static func floatFromSingle(_ value: Float) -> Value {\n    .float(width: 32, bits: UInt64(value.bitPattern))\n  }\n  public static func floatFromDouble(_ value: Double) -> Value {\n    .float(width: 64, bits: value.bitPattern)\n  }\n\n  public static func toSingle(_ value: Value) throws -> Float {\n    guard case .float(_, let b) = try toFloat(value, 32) else { return 0 }\n    return Float(bitPattern: UInt32(truncatingIfNeeded: b))\n  }\n\n  public static func toDouble(_ value: Value) throws -> Double {\n    guard case .float(_, let b) = try toFloat(value, 64) else { return 0 }\n    return Double(bitPattern: b)\n  }\n\n  private static func negateFloat(_ value: Value) -> Value {\n    guard case .float(let w, let b) = value else { return value }\n    return .float(width: w, bits: b ^ (1 << UInt64(w - 1)))\n  }\n\n  private static func floatOp(_ op: String, _ width: Int, _ a: Value, _ b: Value) throws -> Value {\n    let ca = try floatClass(a)\n    let cb = try floatClass(b)\n    if ca == \"nan\" || cb == \"nan\" { return nan(width) }\n    switch op {\n    case \"-\": return try floatOp(\"+\", width, a, negateFloat(b))\n    case \"+\" where ca == \"infinity\" && cb == \"infinity\":\n      return floatSign(a) == floatSign(b) ? a : nan(width)\n    case \"+\" where ca == \"infinity\": return a\n    case \"+\" where cb == \"infinity\": return b\n    case \"*\" where (ca == \"infinity\" && cb == \"zero\") || (ca == \"zero\" && cb == \"infinity\"):\n      return nan(width)\n    case \"*\" where ca == \"infinity\" || cb == \"infinity\":\n      return infinity(width, floatSign(a) ^ floatSign(b))\n    case \"/\" where ca == \"infinity\" && cb == \"infinity\": return nan(width)\n    case \"/\" where ca == \"zero\" && cb == \"zero\": return nan(width)\n    case \"/\" where ca == \"infinity\": return infinity(width, floatSign(a) ^ floatSign(b))\n    case \"/\" where cb == \"zero\": return infinity(width, floatSign(a) ^ floatSign(b))\n    case \"/\" where cb == \"infinity\": return zero(width, floatSign(a) ^ floatSign(b))\n    default:\n      let (an, ad) = try exact(a)\n      let (bn, bd) = try exact(b)\n      switch op {\n      case \"+\":\n        return try floatFromRatio(width, an * bd + bn * ad, ad * bd, floatSign(a) & floatSign(b))\n      case \"*\": return try floatFromRatio(width, an * bn, ad * bd, floatSign(a) ^ floatSign(b))\n      case \"/\": return try floatFromRatio(width, an * bd, ad * bn, floatSign(a) ^ floatSign(b))\n      default: throw Fail.with(\"UnknownFloatOperation\", op)\n      }\n    }\n  }\n\n  /// IEEE arithmetic at the wider of the two widths.\n  public static func floatBinary(_ op: String, _ a: Value, _ b: Value) throws -> Value {\n    guard case .float(let wa, _) = a, case .float(let wb, _) = b else {\n      throw Fail.with(\"FloatRequired\", op)\n    }\n    let w = Swift.max(wa, wb)\n    return try floatOp(op, w, toFloat(a, w), toFloat(b, w))\n  }\n\n  private static func compareRatios(_ x: (BigInt, BigInt), _ y: (BigInt, BigInt)) -> Int {\n    BigInt.compare(x.0 * y.1, y.0 * x.1)\n  }\n\n  /// The order of two floats, or nil when one is NaN.\n  public static func floatCompare(_ a: Value, _ b: Value) throws -> Int? {\n    guard case .float(let wa, let ba) = a, case .float(let wb, let bb) = b else {\n      throw Fail.with(\"FloatRequired\")\n    }\n    switch (try decode(wa, ba), try decode(wb, bb)) {\n    case (.nan, _), (_, .nan): return nil\n    case (.infinity(let s), .infinity(let t)) where s == t: return 0\n    case (.infinity(1), _): return -1\n    case (_, .infinity(1)): return 1\n    case (.infinity, _): return 1\n    case (_, .infinity): return -1\n    default: return compareRatios(try exact(a), try exact(b))\n    }\n  }\n\n  private static func toComplex(_ value: Value, _ width: Int) throws -> Value {\n    if case .complex(_, let r, let i) = value {\n      return .complex(width: width, real: try toFloat(r, width), imaginary: try toFloat(i, width))\n    }\n    return .complex(width: width, real: try toFloat(value, width), imaginary: zero(width, 0))\n  }\n\n  // MARK: Text\n\n  /// Whether a string is well-formed: a Swift String always is.\n  public static func isWellFormed(_ text: String) -> Bool { true }\n\n  /// A text's Unicode scalar values.\n  public static func codePoints(_ text: String) -> [Int] {\n    text.unicodeScalars.map { Int($0.value) }\n  }\n\n  private static func validUnit(_ kind: String, _ n: Int) -> Bool {\n    switch kind {\n    case \"Bytes\": return n >= 0 && n <= 255\n    case \"CodeUnit16\", \"Utf16Text\": return n >= 0 && n <= 65535\n    case \"CodePoint\", \"CodePointText\": return n >= 0 && n <= 0x10FFFF\n    default: return n >= 0 && n <= 0x10FFFF && (n < 0xD800 || n > 0xDFFF)\n    }\n  }\n\n  private static func checkedUnit(_ kind: String, _ n: Int) throws -> Int {\n    if !validUnit(kind, n) { throw Fail.with(\"InvalidCharacter\", kind) }\n    return n\n  }\n\n  /// The text of Unicode scalar values.\n  public static func textOfPoints<S: Sequence>(_ points: S) throws -> String\n  where S.Element == Int {\n    var scalars = String.UnicodeScalarView()\n    for p in points {\n      guard let scalar = Unicode.Scalar(UInt32(try checkedUnit(\"Text\", p))) else {\n        throw Fail.with(\"InvalidCharacter\", \"Text\")\n      }\n      scalars.append(scalar)\n    }\n    return String(scalars)\n  }\n\n  /// Compare two strings by code point, which is UTF-8's byte order and\n  /// LawSpec's text order.\n  public static func compareText(_ a: String, _ b: String) -> Int {\n    var x = a.utf8.makeIterator()\n    var y = b.utf8.makeIterator()\n    while true {\n      switch (x.next(), y.next()) {\n      case (nil, nil): return 0\n      case (nil, _): return -1\n      case (_, nil): return 1\n      case (let p?, let q?): if p != q { return p < q ? -1 : 1 }\n      }\n    }\n  }\n\n  /// Compare two byte arrays as unsigned octets.\n  public static func compareBytes(_ a: [UInt8], _ b: [UInt8]) -> Int {\n    for (x, y) in zip(a, b) where x != y { return x < y ? -1 : 1 }\n    return order(a.count, b.count)\n  }\n\n  // MARK: Validation and conversion\n\n  /// Check that a value belongs to a scalar or built-in container type under a\n  /// machine profile, and return it.\n  public static func validate(_ value: Value, _ t: TypeRef, _ bits: Int) throws -> Value {\n    guard case .named(let name, let args) = t else { throw Fail.with(\"InvalidValue\", typeKey(t)) }\n    switch (name, args.count, value) {\n    case (\"Bool\", 0, .bool), (\"Text\", 0, .text), (\"Bytes\", 0, .bytes), (\"Decimal\", 0, .decimal),\n      (\"Symbol\", 0, .symbol), (\"Unit\", 0, .unit), (\"Null\", 0, .null), (\"Undefined\", 0, .undefined):\n      return value\n    case (\"Char\", 0, .int(let n)), (\"CodePoint\", 0, .int(let n)), (\"CodeUnit16\", 0, .int(let n)):\n      guard let small = n.exactly(Int.self), small >= 0, small <= 0x10FFFF else {\n        throw Fail.with(\"InvalidCharacter\", name)\n      }\n      _ = try checkedUnit(name, small)\n      return value\n    case (\"CodePointText\", 0, .raw(let kind, let units)),\n      (\"Utf16Text\", 0, .raw(let kind, let units)):\n      guard kind == name else { break }\n      for u in units { _ = try checkedUnit(name, u) }\n      return value\n    case (\"Rational\", 0, .ratio(let n, let d)):\n      return try ratio(n, d)\n    case (\"Float32\", 0, .float(32, _)), (\"Float64\", 0, .float(64, _)):\n      return value\n    case (\"Complex64\", 0, .complex(32, let r, let i)):\n      return .complex(\n        width: 32, real: try validate(r, .named(\"Float32\", []), bits),\n        imaginary: try validate(i, .named(\"Float32\", []), bits))\n    case (\"Complex128\", 0, .complex(64, let r, let i)):\n      return .complex(\n        width: 64, real: try validate(r, .named(\"Float64\", []), bits),\n        imaginary: try validate(i, .named(\"Float64\", []), bits))\n    case (_, 0, .int(let n)) where isIntegerType(name):\n      return try checkBounds(n, name, bits)\n    case (\"List\", 1, .list(let items)):\n      return .list(try items.map { try validate($0, args[0], bits) })\n    case (\"Maybe\", 1, .data(\"Maybe::Absent\", let fields)) where fields.isEmpty:\n      return value\n    case (\"Maybe\", 1, .data(\"Maybe::Present\", let fields)) where fields.count == 1:\n      return .data(\"Maybe::Present\", [try validate(fields[0], args[0], bits)])\n    case (\"Either\", 2, .data(\"Either::Left\", let fields)) where fields.count == 1:\n      return .data(\"Either::Left\", [try validate(fields[0], args[0], bits)])\n    case (\"Either\", 2, .data(\"Either::Right\", let fields)) where fields.count == 1:\n      return .data(\"Either::Right\", [try validate(fields[0], args[1], bits)])\n    case (\"Nullable\", 1, .presence(let kind, let present)),\n      (\"Optional\", 1, .presence(let kind, let present)):\n      guard kind == name else { break }\n      return .presence(kind: kind, value: try present.map { try validate($0, args[0], bits) })\n    default:\n      break\n    }\n    throw Fail.with(\"InvalidValue\", typeKey(t))\n  }\n\n  /// An explicit conversion (`x :: T`): exact numbers convert exactly or fail,\n  /// floats round once, and anything else is validated.\n  public static func convert(_ value: Value, _ t: TypeRef, _ bits: Int) throws -> Value {\n    guard case .named(let name, let args) = t else { return try validate(value, t, bits) }\n    switch (name, args.count) {\n    case (\"Rational\", 0):\n      let (n, d) = try exact(value)\n      return try ratio(n, d)\n    case (\"Decimal\", 0):\n      let (n, d) = try exact(value)\n      return try finiteDecimal(n, d)\n    case (\"Float32\", 0): return try toFloat(value, 32)\n    case (\"Float64\", 0): return try toFloat(value, 64)\n    case (\"Complex64\", 0): return try toComplex(value, 32)\n    case (\"Complex128\", 0): return try toComplex(value, 64)\n    case (_, 0) where isIntegerType(name):\n      let (n, d) = try exact(value)\n      let (q, r) = n.quotientAndRemainder(dividingBy: d)\n      if !r.isZero { throw Fail.with(\"FractionalConversion\", name) }\n      return try checkBounds(q, name, bits)\n    case (\"Nullable\", 1), (\"Optional\", 1):\n      if name == \"Nullable\", case .null = value { return .presence(kind: \"Nullable\", value: nil) }\n      if name == \"Optional\", case .undefined = value {\n        return .presence(kind: \"Optional\", value: nil)\n      }\n      if case .presence(let kind, let present) = value, kind == name {\n        return .presence(kind: kind, value: try present.map { try convert($0, args[0], bits) })\n      }\n      return try validate(value, t, bits)\n    default:\n      return try validate(value, t, bits)\n    }\n  }\n\n  // MARK: Equality, order and arithmetic\n\n  /// LawSpec equality: structural, exact across exact numbers, and false for a\n  /// NaN, even inside a container.\n  public static func equal(_ a: Value, _ b: Value) -> Bool {\n    switch (a, b) {\n    case (.float, .float): return ((try? floatCompare(a, b)) ?? nil) == 0\n    case (.complex(_, let r1, let i1), .complex(_, let r2, let i2)):\n      return equal(r1, r2) && equal(i1, i2)\n    case (.complex(let w, let r, let i), .float): return equal(r, b) && equal(i, zero(w, 0))\n    case (.float, .complex): return equal(b, a)\n    case (.symbol(let x, _), .symbol(let y, _)): return x === y\n    case (.presence(let k1, let x?), .presence(let k2, let y?)): return k1 == k2 && equal(x, y)\n    case (.presence(let k1, nil), .presence(let k2, nil)): return k1 == k2\n    case (.data(let t1, let f1), .data(let t2, let f2))\n    where t1 == \"lawspec.collections::type::EqSet::EqSetItems\" && t2 == t1:\n      guard f1.count == 1, f2.count == 1, case .list(let x) = f1[0], case .list(let y) = f2[0]\n      else { return false }\n      return x.allSatisfy { value in y.contains { equal(value, $0) } }\n        && y.allSatisfy { value in x.contains { equal(value, $0) } }\n    case (.data(let t1, let f1), .data(let t2, let f2)): return t1 == t2 && equalLists(f1, f2)\n    case (.list(let x), .list(let y)): return equalLists(x, y)\n    case _ where isExact(a) && isExact(b):\n      guard let x = try? exact(a), let y = try? exact(b) else { return false }\n      return compareRatios(x, y) == 0\n    case (.bytes(let x), .bytes(let y)): return x == y\n    case (.raw(let k1, let u1), .raw(let k2, let u2)): return k1 == k2 && u1 == u2\n    case (.handle(let n1, let i1), .handle(let n2, let i2)):\n      return n1 == n2 && HandleIdentity.same(i1, i2)\n    case (.bool(let x), .bool(let y)): return x == y\n    case (.text(let x), .text(let y)): return String.portableEqual(x, y)\n    case (.unit, .unit), (.null, .null), (.undefined, .undefined): return true\n    default: return false\n    }\n  }\n\n  public static func distinctMembers(_ items: [Value]) -> Bool {\n    for (index, value) in items.enumerated() {\n      if items[..<index].contains(where: { equal(value, $0) }) { return false }\n    }\n    return true\n  }\n\n  private static func equalLists(_ xs: [Value], _ ys: [Value]) -> Bool {\n    xs.count == ys.count && zip(xs, ys).allSatisfy { equal($0, $1) }\n  }\n\n  /// LawSpec's portable total order of keys. Floats, symbols and distinct\n  /// handles have no portable order.\n  public static func compareValues(_ a: Value, _ b: Value) throws -> Int {\n    switch (a, b) {\n    case (.bool(let x), .bool(let y)): return x == y ? 0 : (x ? 1 : -1)\n    case (.text(let x), .text(let y)): return compareText(x, y)\n    case (.bytes(let x), .bytes(let y)): return compareBytes(x, y)\n    case (.raw(let k1, let x), .raw(let k2, let y)) where k1 == k2:\n      return [Int].portableCompare(x, y)\n    case (.presence(let k1, nil), .presence(let k2, nil)) where k1 == k2: return 0\n    case (.presence(let k1, nil), .presence(let k2, _?)) where k1 == k2: return -1\n    case (.presence(let k1, _?), .presence(let k2, nil)) where k1 == k2: return 1\n    case (.presence(let k1, let x?), .presence(let k2, let y?)) where k1 == k2:\n      return try compareValues(x, y)\n    case (.data(\"Maybe::Absent\", let f), .data(\"Maybe::Present\", _)) where f.isEmpty: return -1\n    case (.data(\"Maybe::Present\", _), .data(\"Maybe::Absent\", let f)) where f.isEmpty: return 1\n    case (.data(let t1, let f1), .data(let t2, let f2)) where t1 == t2:\n      return try compareLists(f1, f2)\n    case (.data(let t1, _), .data(let t2, _)): return compareText(t1, t2)\n    case (.list(let x), .list(let y)): return try compareLists(x, y)\n    case (.handle(let n1, let i1), .handle(let n2, let i2))\n    where n1 == n2 && HandleIdentity.same(i1, i2): return 0\n    case (.unit, .unit), (.null, .null), (.undefined, .undefined): return 0\n    case _ where isExact(a) && isExact(b): return compareRatios(try exact(a), try exact(b))\n    default: throw Fail.with(\"NoPortableOrder\")\n    }\n  }\n\n  private static func compareLists(_ xs: [Value], _ ys: [Value]) throws -> Int {\n    for (x, y) in zip(xs, ys) {\n      let c = try compareValues(x, y)\n      if c != 0 { return c }\n    }\n    return order(xs.count, ys.count)\n  }\n\n  /// A value's negation.\n  public static func negate(_ value: Value) throws -> Value {\n    switch value {\n    case .int(let n): return .int(-n)\n    case .ratio(let n, let d): return try ratio(-n, d)\n    case .decimal(let c, let e): return .decimal(-c, e)\n    case .float: return negateFloat(value)\n    case .complex(let w, let r, let i):\n      return .complex(width: w, real: try negate(r), imaginary: try negate(i))\n    default: throw Fail.with(\"NumberRequired\", \"negate\")\n    }\n  }\n\n  private static func inexactWidth(_ key: String) -> Int {\n    switch key {\n    case \"Float32\", \"Complex64\": return 32\n    case \"Float64\", \"Complex128\": return 64\n    default: return 0\n    }\n  }\n\n  private static func isComplexType(_ key: String) -> Bool {\n    key == \"Complex64\" || key == \"Complex128\"\n  }\n\n  private static func relation(_ op: String, _ ordering: Int?) throws -> Bool {\n    guard let n = ordering else { return false }\n    switch op {\n    case \"<\": return n < 0\n    case \"<=\": return n <= 0\n    case \">\": return n > 0\n    case \">=\": return n >= 0\n    default: throw Fail.with(\"UnknownRelation\", op)\n    }\n  }\n\n  private static func exactBinary(_ op: String, _ a: Value, _ b: Value, _ ta: String, _ tb: String)\n    throws -> Value\n  {\n    if case .int(let x) = a, case .int(let y) = b {\n      switch op {\n      case \"pow\" where !y.isNegative:\n        guard let e = y.exactly(Int.self), e <= Int(Int32.max) else {\n          throw Fail.with(\"InvalidExactOperation\", op)\n        }\n        return .int(x.power(e))\n      case \"quot\" where !y.isZero: return .int(x / y)\n      case \"rem\" where !y.isZero: return .int(x % y)\n      default: break\n      }\n    }\n    let (an, ad) = try exact(a)\n    let (bn, bd) = try exact(b)\n    let n: BigInt\n    let d: BigInt\n    switch op {\n    case \"+\": (n, d) = (an * bd + bn * ad, ad * bd)\n    case \"-\": (n, d) = (an * bd - bn * ad, ad * bd)\n    case \"*\": (n, d) = (an * bn, ad * bd)\n    case \"/\": (n, d) = (an * bd, ad * bn)\n    default: throw Fail.with(\"InvalidExactOperation\", op)\n    }\n    let r = try ratio(n, d)\n    if op == \"/\" || ta == \"Rational\" || tb == \"Rational\" { return r }\n    if ta == \"Decimal\" || tb == \"Decimal\" { return try finiteDecimal(n, d) }\n    if case .ratio(let i, _) = r { return .int(i) }\n    return r\n  }\n\n  private static func complexBinary(_ op: String, _ a: Value, _ b: Value) throws -> Value {\n    guard case .complex(let w, let x, let y) = a, case .complex(_, let u, let v) = b else {\n      throw Fail.with(\"ComplexRequired\", op)\n    }\n    let f = floatBinary\n    let r: Value\n    let i: Value\n    switch op {\n    case \"+\", \"-\":\n      r = try f(op, x, u)\n      i = try f(op, y, v)\n    case \"*\":\n      r = try f(\"-\", f(\"*\", x, u), f(\"*\", y, v))\n      i = try f(\"+\", f(\"*\", x, v), f(\"*\", y, u))\n    case \"/\":\n      let den = try f(\"+\", f(\"*\", u, u), f(\"*\", v, v))\n      r = try f(\"/\", f(\"+\", f(\"*\", x, u), f(\"*\", y, v)), den)\n      i = try f(\"/\", f(\"-\", f(\"*\", y, u), f(\"*\", x, v)), den)\n    default:\n      throw Fail.with(\"UnknownComplexOperation\", op)\n    }\n    return .complex(width: w, real: r, imaginary: i)\n  }\n\n  /// A binary operator on two values of the given types (by key).\n  public static func binary(_ op: String, _ a: Value, _ b: Value, _ ta: String, _ tb: String) throws\n    -> Value\n  {\n    switch op {\n    case \"==\": return .bool(equal(a, b))\n    case \"!=\": return .bool(!equal(a, b))\n    case \"<\", \"<=\", \">\", \">=\":\n      let ordering =\n        (inexactWidth(ta) > 0 || inexactWidth(tb) > 0)\n        ? try floatCompare(a, b) : try compareValues(a, b)\n      return .bool(try relation(op, ordering))\n    default:\n      if (inexactWidth(ta) > 0) != (inexactWidth(tb) > 0) {\n        throw Fail.with(\"ExactInexactMixing\", op)\n      }\n      let width = Swift.max(inexactWidth(ta), inexactWidth(tb))\n      if width == 0 { return try exactBinary(op, a, b, ta, tb) }\n      if isComplexType(ta) || isComplexType(tb) {\n        return try complexBinary(op, toComplex(a, width), toComplex(b, width))\n      }\n      return try floatBinary(op, a, b)\n    }\n  }\n\n  // MARK: Helpers\n\n  private static func sequenceItems(_ value: Value, _ kind: String) throws -> [Value] {\n    switch value {\n    case .list(let items): return items\n    case .text(let s) where kind == \"Text\":\n      return s.unicodeScalars.map { .int(BigInt(Int($0.value))) }\n    case .text(let s): return s.utf8.map { .int(BigInt(Int($0))) }\n    case .bytes(let b): return b.map { .int(BigInt(Int($0))) }\n    default: throw Fail.with(\"SequenceRequired\", kind)\n    }\n  }\n\n  private static func sequenceLike(_ value: Value, _ kind: String, _ items: [Value]) throws -> Value\n  {\n    // Only text and bytes are made of integers; a list keeps its items.\n    func ints() throws -> [Int] {\n      try items.map { item in\n        guard case .int(let n) = item, let small = n.exactly(Int.self) else {\n          throw Fail.with(\"SequenceRequired\", kind)\n        }\n        return small\n      }\n    }\n    switch value {\n    case .list: return .list(items)\n    case .text where kind == \"Text\": return .text(try textOfPoints(ints()))\n    default: return .bytes(try ints().map { UInt8(truncatingIfNeeded: $0) })\n    }\n  }\n\n  private static func integer(_ value: Value) throws -> BigInt {\n    guard case .int(let n) = value else { throw Fail.with(\"IntegerRequired\") }\n    return n\n  }\n\n  private static func text(_ value: Value) throws -> String {\n    guard case .text(let s) = value else { throw Fail.with(\"TextRequired\") }\n    return s\n  }\n\n  private static func clamp(_ n: BigInt, _ lo: BigInt, _ hi: BigInt) -> BigInt {\n    n < lo ? lo : (n > hi ? hi : n)\n  }\n\n  /// A built-in helper by name, with its arguments and their type keys.\n  public static func helper(_ name: String, _ values: [Value], _ types: [String], _ bits: Int)\n    throws -> Value\n  {\n    switch (name, values.count) {\n    case (\"isNaN\", 1): return .bool(try floatClass(values[0]) == \"nan\")\n    case (\"isInfinite\", 1): return .bool(try floatClass(values[0]) == \"infinity\")\n    case (\"isFinite\", 1):\n      let c = try floatClass(values[0])\n      return .bool(c == \"finite\" || c == \"zero\")\n    case (\"isNegativeZero\", 1):\n      return .bool(try floatClass(values[0]) == \"zero\" && floatSign(values[0]) == 1)\n    case (\"length\", 1):\n      switch values[0] {\n      case .list(let items): return .int(BigInt(items.count))\n      case .bytes(let b): return .int(BigInt(b.count))\n      case .text(let s): return .int(BigInt(s.unicodeScalars.count))\n      case .raw(_, let units): return .int(BigInt(units.count))\n      default: break\n      }\n    case (\"real\", 1):\n      if case .complex(_, let r, _) = values[0] { return r }\n    case (\"imag\", 1), (\"imaginary\", 1):\n      if case .complex(_, _, let i) = values[0] { return i }\n    case (\"conjugate\", 1):\n      if case .complex(let w, let r, let i) = values[0] {\n        return .complex(width: w, real: r, imaginary: try negate(i))\n      }\n    case (\"abs\", 1):\n      if isExact(values[0]) {\n        return try exact(values[0]).0.isNegative ? try negate(values[0]) : values[0]\n      }\n      if case .float(let w, let b) = values[0] {\n        return .float(width: w, bits: b & ((1 << UInt64(w - 1)) - 1))\n      }\n    case (\"round\", 2):\n      if case .int(let placesValue) = values[1], let places = placesValue.exactly(Int.self) {\n        let (n, d) = try exact(values[0])\n        let (sn, sd) = places >= 0 ? (n * pow10(places), d) : (n, d * pow10(-places))\n        let q = roundRatio(sn.magnitude, sd)\n        return .decimal(sn.isNegative ? -q : q, -places)\n      }\n    case (\"startsWith\", 2):\n      if case .text(let t) = values[0], case .text(let p) = values[1] {\n        return .bool(t.unicodeScalars.starts(with: p.unicodeScalars))\n      }\n    case (\"endsWith\", 2):\n      if case .text(let t) = values[0], case .text(let s) = values[1] {\n        return .bool(t.unicodeScalars.reversed().starts(with: s.unicodeScalars.reversed()))\n      }\n    case (\"textContains\", 2):\n      if case .text(let t) = values[0], case .text(let p) = values[1] {\n        return .bool(Typed.contains(t, p))\n      }\n    case (\"checked\", 1): return .bool(true)\n    case (\"select\", 3):\n      if case .bool(let c) = values[0] { return c ? values[1] : values[2] }\n    case (\"compare\", 2):\n      let c = try compareValues(values[0], values[1])\n      let tag = c < 0 ? \"Less\" : (c == 0 ? \"Equal\" : \"Greater\")\n      return .data(\"lawspec.collections::type::Ordering::\" + tag, [])\n    case (\"isPresent\", 1):\n      if case .presence(_, let p) = values[0] { return .bool(p != nil) }\n    case (\"presentValue\", 1):\n      if case .presence(_, let p) = values[0] {\n        guard let v = p else { throw Fail.with(\"AbsentPresenceValue\") }\n        return v\n      }\n    case (\"negate\", 1): return try negate(values[0])\n    case (\"append\", 2):\n      switch (values[0], values[1]) {\n      case (.list(let a), .list(let b)): return .list(a + b)\n      case (.text(let a), .text(let b)): return .text(a + b)\n      case (.bytes(let a), .bytes(let b)): return .bytes(a + b)\n      default: break\n      }\n    case (\"slice\", 3):\n      if case .int(let from) = values[1], case .int(let until) = values[2] {\n        let kind = types.first ?? \"\"\n        let items = try sequenceItems(values[0], kind)\n        let count = BigInt(items.count)\n        let i = clamp(from, .zero, count)\n        let j = clamp(until, i, count)\n        let lo = i.exactly(Int.self) ?? 0\n        let hi = j.exactly(Int.self) ?? 0\n        return try sequenceLike(values[0], kind, Array(items[lo..<hi]))\n      }\n    case (\"at\", 2):\n      if case .int(let i) = values[1] {\n        let items = try sequenceItems(values[0], types.first ?? \"\")\n        if !i.isNegative, let k = i.exactly(Int.self), k < items.count {\n          return .data(\"Maybe::Present\", [items[k]])\n        }\n        return .data(\"Maybe::Absent\", [])\n      }\n    case (\"range\", 2):\n      if case .int(let lo) = values[0], case .int(let hi) = values[1] {\n        var result = [Value]()\n        var n = lo\n        while n < hi {\n          result.append(.int(n))\n          n += .one\n        }\n        return .list(result)\n      }\n    case (\"octets\", 1):\n      if case .bytes(let b) = values[0] { return .list(b.map { .int(BigInt(Int($0))) }) }\n    case (\"bytesOf\", 1):\n      if case .list(let items) = values[0] {\n        return .bytes(\n          try items.map { UInt8(truncatingIfNeeded: try integer($0).truncated(Int.self)) })\n      }\n    case (\"utf8\", 1):\n      if case .text(let t) = values[0] { return .bytes(Array(t.utf8)) }\n    case (\"textOf\", 1):\n      if case .int(let n) = values[0] { return .text(n.description) }\n    case (\"join\", 2):\n      if case .text(let separator) = values[0], case .list(let parts) = values[1] {\n        return .text(try parts.map(text).joined(separator: separator))\n      }\n    case (\"quot\", 2), (\"rem\", 2), (\"pow\", 2):\n      return try binary(name, values[0], values[1], types[0], types[1])\n    default:\n      break\n    }\n    if values.count == 1 { return try convert(values[0], typeOf(name), bits) }\n    throw Fail.with(\"UnknownHelper\", name)\n  }\n\n  // MARK: Symbols\n\n  /// A fresh symbol with a description.\n  public static func newSymbol(_ description: String) -> Value {\n    .symbol(SymbolIdentity(), description)\n  }\n\n  /// A literal symbol, interned in its context.\n  public static func symbol(_ context: SymbolContext, _ id: String, _ description: String) -> Value\n  {\n    .symbol(context.identity(id), description)\n  }\n\n  // MARK: Literals, as the generated code writes them\n\n  public static func integerLiteral(_ digits: String) throws -> Value {\n    guard let n = BigInt(digits) else { throw Fail.with(\"InvalidIntegerLiteral\", digits) }\n    return .int(n)\n  }\n\n  public static func decimalOf(_ coefficient: String, _ exponent: Int) throws -> Value {\n    guard let c = BigInt(coefficient) else { throw Fail.with(\"InvalidDecimalLiteral\", coefficient) }\n    return .decimal(c, exponent)\n  }\n\n  public static func rationalOf(_ numerator: String, _ denominator: String) throws -> Value {\n    guard let n = BigInt(numerator), let d = BigInt(denominator) else {\n      throw Fail.with(\"InvalidRationalLiteral\")\n    }\n    return try ratio(n, d)\n  }\n\n  public static func floatBits(_ width: Int, _ hex: String) throws -> Value {\n    guard let bits = UInt64(hex, radix: 16) else { throw Fail.with(\"InvalidIeeeBits\", hex) }\n    return try floatValue(width, bits)\n  }\n\n  public static func textUnits(_ points: [Int]) throws -> Value { .text(try textOfPoints(points)) }\n\n  public static func bytesOf(_ units: [Int]) throws -> Value {\n    .bytes(try units.map { UInt8(try checkedUnit(\"Bytes\", $0)) })\n  }\n\n  public static func rawOf(_ kind: String, _ units: [Int]) throws -> Value {\n    .raw(kind: kind, units: try units.map { try checkedUnit(kind, $0) })\n  }\n}\n\n/// Literal symbols share identities within one context (a law's run).\npublic final class SymbolContext: Sendable {\n  private let symbols = Locked([String: SymbolIdentity]())\n  public init() {}\n  public func identity(_ id: String) -> SymbolIdentity {\n    symbols.with { table in\n      if let known = table[id] { return known }\n      let made = SymbolIdentity()\n      table[id] = made\n      return made\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Schema.swift" = "// The checked shapes of a program's data: constructors, field types, GADT\n// equations, existential witnesses, index guards and field contracts, all\n// checked by one walk. The schema also carries the handlers in scope.\n// ref:DEC-typed-core-boundary ref:DEC-gadts-and-index-arithmetic\n\n/// A constructor field's predicate: the schema, the type's arguments and the\n/// fields to whether they hold.\npublic typealias FieldPredicate = @Sendable (Schema, [TypeRef], [Value]) throws -> Bool\n\n/// A constructor field's generation hints, from the fields drawn before it.\npublic typealias FieldGenerator = @Sendable (Schema, [TypeRef], [Value]) throws -> Schema.FieldHints\n\n/// A program's data definitions, as the runtime checks them, and the handlers\n/// in scope. A schema is a value: installing handlers makes another.\npublic struct Schema: Sendable {\n  /// Bounds and hints that steer the generation of one constructor field from\n  /// the fields drawn before it. ref:DEC-shrink-within-domain\n  public struct FieldHints: Sendable {\n    public let bounds: [(String, Value)]\n    public let lengths: [(String, Value)]\n    public let hints: [Value]\n  }\n\n  /// A data constructor; arguments and witness values are filled in when it\n  /// is instantiated at a type.\n  public struct Constructor: Sendable {\n    public let tag: String\n    public var fields: [(String, TypeRef)]\n    public var predicates: [FieldPredicate] = []\n    /// By field position, from 1.\n    public var generators: [Int: FieldGenerator] = [:]\n    public var indices: [String] = []\n    public var refinements: [(Int, TypeRef)] = []\n    public var existentials = 0\n    public var witnesses: [Int] = []\n    public var arguments: [TypeRef] = []\n    public var witnessValues: [Value] = []\n  }\n\n  public struct DataDefinition: Sendable {\n    public let name: String\n    public let parameters: Int\n    public let constructors: [Constructor]\n    public let handle: Bool\n  }\n\n  /// The program's data: shared by every schema made from it.\n  public final class Program: Sendable {\n    public let definitions: [String: DataDefinition]\n    public let arities: [String: Int]\n    public let bits: Int\n    init(definitions: [String: DataDefinition], arities: [String: Int], bits: Int) {\n      self.definitions = definitions\n      self.arities = arities\n      self.bits = bits\n    }\n  }\n\n  public let program: Program\n  /// The handlers in scope, by ability key (Effects).\n  public var handlers: [String: Effects.Handler] = [:]\n  /// The innermost handler scope, which owns handler state.\n  public var scope: Effects.Scope? = nil\n  /// The stateful handlers whose operations are running, innermost first.\n  public var effectPath: [ObjectIdentifier] = []\n\n  public var definitions: [String: DataDefinition] { program.definitions }\n  public var bits: Int { program.bits }\n\n  init(program: Program) { self.program = program }\n\n  private static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  /// A constructor with only a tag and fields; the generated schema adds the rest.\n  public static func constructor(_ tag: String, _ fields: [(String, TypeRef)]) -> Constructor {\n    Constructor(tag: tag, fields: fields)\n  }\n\n  /// The type parameters' types, by position.\n  public static func substitute(_ t: TypeRef, _ known: [Int: TypeRef]) -> TypeRef {\n    switch t {\n    case .parameter(let i): return known[i] ?? t\n    case .named(let name, let args): return .named(name, args.map { substitute($0, known) })\n    }\n  }\n\n  private static func checkScope(_ t: TypeRef, _ scope: Int, _ schema: Schema) throws {\n    switch t {\n    case .parameter(let i):\n      if i < 0 || i >= scope { throw fail(\"UnboundSchemaParameter\", \"\\(i)\") }\n    case .named(let name, let args):\n      guard let arity = schema.program.arities[name], arity == args.count else {\n        throw fail(\"UnknownTypeOrArity\", name)\n      }\n      for a in args { try checkScope(a, scope, schema) }\n    }\n  }\n\n  /// Check that a closed type is known, with the right number of arguments.\n  public static func checkType(_ t: TypeRef, _ schema: Schema) throws {\n    try checkScope(t, 0, schema)\n  }\n\n  private static let builtins: [(String, Int)] = [\n    (\"List\", 1), (\"Maybe\", 1), (\"Either\", 2), (\"Nullable\", 1), (\"Optional\", 1),\n  ]\n\n  /// A program's schema, from its data definitions and the scalar names.\n  public static func create(_ definitions: [DataDefinition], _ primitives: [String], _ bits: Int)\n    throws -> Schema\n  {\n    if bits != 32 && bits != 64 { throw fail(\"InvalidMachineBits\", \"\\(bits)\") }\n    let names = definitions.map { $0.name } + primitives + builtins.map { $0.0 }\n    if Set(names).count != names.count { throw fail(\"DuplicateType\") }\n    var arities = [String: Int]()\n    for p in primitives { arities[p] = 0 }\n    for (name, arity) in builtins { arities[name] = arity }\n    for d in definitions { arities[d.name] = d.parameters }\n    var table = [String: DataDefinition]()\n    for d in definitions { table[d.name] = d }\n    let schema = Schema(program: Program(definitions: table, arities: arities, bits: bits))\n    let tags = definitions.flatMap { $0.constructors.map { $0.tag } }\n    if Set(tags).count != tags.count { throw fail(\"DuplicateConstructor\") }\n    for d in definitions {\n      for c in d.constructors {\n        for (_, t) in c.fields { try checkScope(t, d.parameters + c.existentials, schema) }\n      }\n    }\n    return schema\n  }\n\n  private static func unify(_ pattern: TypeRef, _ actual: TypeRef, _ known: [Int: TypeRef]?)\n    -> [Int: TypeRef]?\n  {\n    guard var k = known else { return nil }\n    switch pattern {\n    case .parameter(let i):\n      if let t = k[i] { return t == actual ? k : nil }\n      k[i] = actual\n      return k\n    case .named(let name, let ps):\n      guard case .named(let n, let xs) = actual, n == name, ps.count == xs.count else { return nil }\n      return zip(ps, xs).reduce(k as [Int: TypeRef]?) { unify($1.0, $1.1, $0) }\n    }\n  }\n\n  private static func instantiate(_ c: Constructor, _ args: [TypeRef]) -> Constructor? {\n    var known = [Int: TypeRef]()\n    for (i, a) in args.enumerated() { known[i] = a }\n    var bound: [Int: TypeRef]? = known\n    for (i, pattern) in c.refinements where i < args.count {\n      bound = unify(pattern, args[i], bound)\n    }\n    guard let b = bound else { return nil }\n    var made = c\n    made.arguments = args\n    made.fields = c.fields.map { ($0.0, substitute($0.1, b)) }\n    return made\n  }\n\n  private static func builtinConstructors(_ name: String, _ args: [TypeRef]) -> [Constructor]? {\n    switch (name, args.count) {\n    case (\"Maybe\", 1):\n      return [\n        constructor(\"Maybe::Absent\", []), constructor(\"Maybe::Present\", [(\"value\", args[0])]),\n      ]\n    case (\"Either\", 2):\n      return [\n        constructor(\"Either::Left\", [(\"value\", args[0])]),\n        constructor(\"Either::Right\", [(\"value\", args[1])]),\n      ]\n    default: return nil\n    }\n  }\n\n  /// The constructors of a data type at its arguments, or nil for a scalar or\n  /// a list. A GADT constructor whose equations the arguments refute is absent.\n  public static func constructors(_ t: TypeRef, _ schema: Schema) throws -> [Constructor]? {\n    try checkType(t, schema)\n    guard case .named(let name, let args) = t else { return nil }\n    guard let d = schema.program.definitions[name] else { return builtinConstructors(name, args) }\n    return d.constructors.compactMap { instantiate($0, args) }\n  }\n\n  /// Each instance of a constructor's free existentials over Core's finite\n  /// witness pool (Bool and Int32).\n  public static func witnessInstances(_ c: Constructor) -> [Constructor] {\n    let pool: [TypeRef] = [.named(\"Bool\", []), .named(\"Int32\", [])]\n    var assignments: [[Int: TypeRef]] = [[:]]\n    for i in c.witnesses {\n      assignments = assignments.flatMap { known in pool.map { t in known.merging([i: t]) { $1 } } }\n    }\n    let kept = c.fields.count - c.witnesses.count\n    return assignments.map { known in\n      var made = c\n      made.fields = c.fields.prefix(kept).map { ($0.0, substitute($0.1, known)) }\n      made.witnessValues = c.witnesses.map { .text(Scalar.typeKey(known[$0]!)) }\n      return made\n    }\n  }\n\n  private static func findConstructor(_ tag: String, _ cs: [Constructor]) throws -> Constructor {\n    let found = cs.filter { $0.tag == tag }\n    guard found.count == 1 else { throw fail(\"ForeignConstructor\", tag) }\n    return found[0]\n  }\n\n  private static func witnessed(_ c: Constructor, _ values: [Value], _ schema: Schema) throws -> [(\n    String, TypeRef\n  )] {\n    let texts = values.suffix(c.witnesses.count)\n    var known = [Int: TypeRef]()\n    for (i, v) in zip(c.witnesses, texts) {\n      guard case .text(let key) = v else { throw fail(\"InvalidWitness\") }\n      let t = try Scalar.typeOf(key)\n      try checkType(t, schema)\n      known[i] = t\n    }\n    return c.fields.map { ($0.0, substitute($0.1, known)) }\n  }\n\n  // MARK: Index terms\n\n  private static func tokens(_ text: String) -> [String] {\n    text.split(separator: \" \").map(String.init)\n  }\n\n  private static func isGuard(_ tokens: [String]) -> Bool {\n    tokens.first == \"==\" || tokens.first == \">=\"\n  }\n\n  private static func indexBinary(_ op: String, _ a: BigInt?, _ b: BigInt?) -> BigInt? {\n    guard let a, let b else { return nil }\n    switch op {\n    case \"+\": return a + b\n    case \"-\" where a >= b: return a - b\n    case \"*\": return a * b\n    case \"div\" where b.signum > 0: return a / b\n    case \"mod\" where b.signum > 0: return a % b\n    case \"^\" where b.signum >= 0 && b <= 64: return a.power(b.exactly(Int.self)!)\n    default: return nil\n    }\n  }\n\n  private static func evalIndex(\n    _ terms: ArraySlice<String>, _ c: Constructor, _ values: [Value], _ schema: Schema\n  ) throws -> (BigInt?, ArraySlice<String>) {\n    guard let term = terms.first else { throw fail(\"InvalidIndexTerm\") }\n    let rest = terms.dropFirst()\n    if term.hasPrefix(\"c\") {\n      guard let n = BigInt(String(term.dropFirst())) else { throw fail(\"InvalidIndexTerm\", term) }\n      return (n, rest)\n    }\n    if term.hasPrefix(\"f\") || term.hasPrefix(\"p\") {\n      let parts = term.dropFirst().split(separator: \".\", omittingEmptySubsequences: false)\n      guard parts.count <= 2, let positions = parts.first else {\n        throw fail(\"InvalidIndexTerm\", term)\n      }\n      let path = positions.split(separator: \"/\", omittingEmptySubsequences: false).map { Int($0) }\n      guard path.allSatisfy({ $0 != nil && $0! >= 0 }), !path.isEmpty,\n        !term.hasPrefix(\"f\") || path.count == 1\n      else { throw fail(\"InvalidIndexTerm\", term) }\n      let inner = parts.count == 2 ? Int(parts[1]) : 0\n      guard let inner, inner >= 0 else { throw fail(\"InvalidIndexTerm\", term) }\n      return (try indexAtPath(c.fields, values, path.map { $0! }[...], inner, schema), rest)\n    }\n    let (a, next) = try evalIndex(rest, c, values, schema)\n    let (b, after) = try evalIndex(next, c, values, schema)\n    return (indexBinary(term, a, b), after)\n  }\n\n  private static func indexAtPath(\n    _ types: [(String, TypeRef)], _ values: [Value], _ path: ArraySlice<Int>, _ inner: Int,\n    _ schema: Schema\n  ) throws -> BigInt {\n    guard let position = path.first, position >= 0, position < types.count, position < values.count\n    else { throw fail(\"InvalidIndexPath\") }\n    let (type, value) = (types[position].1, values[position])\n    if path.count == 1 { return try index(value, type, inner, schema) }\n    guard case .named(let name, _) = type, name.hasPrefix(\"lawspec::structural::record::\"),\n      case .data(let tag, let fields) = value, let constructors = try constructors(type, schema),\n      constructors.count == 1, constructors[0].tag == tag\n    else { throw fail(\"InvalidIndexPath\") }\n    return try indexAtPath(constructors[0].fields, fields, path.dropFirst(), inner, schema)\n  }\n\n  /// The index at a position of an indexed family's value.\n  public static func index(_ value: Value, _ t: TypeRef, _ position: Int, _ schema: Schema) throws\n    -> BigInt\n  {\n    guard case .data(let tag, let values) = value, let cs = try constructors(t, schema) else {\n      throw fail(\"IndexedTypeRequiresData\", Scalar.typeKey(t))\n    }\n    var c = try findConstructor(tag, cs)\n    c.fields = try witnessed(c, values, schema)\n    let terms = c.indices.map(tokens).filter { !isGuard($0) }\n    if position < 0 || position >= terms.count { throw fail(\"NoIndex\") }\n    let (v, rest) = try evalIndex(terms[position][...], c, values, schema)\n    guard let found = v, rest.isEmpty else { throw fail(\"UndefinedIndex\", tag) }\n    return found\n  }\n\n  private static func checkIndices(_ c: Constructor, _ values: [Value], _ schema: Schema) throws {\n    for text in c.indices {\n      let parts = tokens(text)\n      guard let op = parts.first, op == \"==\" || op == \">=\" else { continue }\n      let (a, next) = try evalIndex(parts.dropFirst(), c, values, schema)\n      let (b, _) = try evalIndex(next, c, values, schema)\n      var holds = false\n      if let a, let b { holds = op == \"==\" ? a == b : a >= b }\n      if !holds { throw fail(\"RefinementViolation\", \"index guard \" + text) }\n    }\n  }\n\n  // MARK: Validation\n\n  private static func strictOrder(_ values: [Value]) throws -> Bool {\n    for (a, b) in zip(values, values.dropFirst()) where try Scalar.compareValues(a, b) != -1 {\n      return false\n    }\n    return true\n  }\n\n  private static func checkCollection(_ name: String, _ fields: [Value]) throws {\n    switch (name, fields.first) {\n    case (\"lawspec.collections::type::EqSet\", .list(let items)?):\n      if !Scalar.distinctMembers(items) {\n        throw fail(\"RefinementViolation\", \"Eq-only set: duplicate equal elements\")\n      }\n    case (\"lawspec.collections::type::Set\", .list(let items)?):\n      if !(try strictOrder(items)) { throw fail(\"RefinementViolation\", name) }\n    case (\"lawspec.collections::type::KeyVal\", .list(let entries)?):\n      let keys = try entries.map { entry -> Value in\n        guard case .data(_, let pair) = entry, pair.count == 2 else {\n          throw fail(\"InvalidValue\", name)\n        }\n        return pair[0]\n      }\n      if !(try strictOrder(keys)) { throw fail(\"RefinementViolation\", name) }\n    default:\n      break\n    }\n  }\n\n  private static func checkPredicates(\n    _ c: Constructor, _ args: [TypeRef], _ values: [Value], _ schema: Schema\n  ) throws {\n    for predicate in c.predicates where !(try predicate(schema, args, values)) {\n      throw fail(\"RefinementViolation\", c.tag)\n    }\n  }\n\n  /// Check a value against a type: shape, field contracts, index guards and the\n  /// canonical order of collections. Returns the value.\n  public static func validate(_ value: Value, _ t: TypeRef, _ schema: Schema) throws -> Value {\n    try checkType(t, schema)\n    return try walk(value, t, schema, true)\n  }\n\n  private static func walk(_ value: Value, _ t: TypeRef, _ schema: Schema, _ deep: Bool) throws\n    -> Value\n  {\n    switch (t, value) {\n    case (.named(\"List\", let args), .list(let items)) where args.count == 1:\n      return .list(try items.map { try walk($0, args[0], schema, deep) })\n    case (.named(let kind, let args), .presence(let k, let present))\n    where args.count == 1 && (kind == \"Optional\" || kind == \"Nullable\") && k == kind:\n      return .presence(kind: kind, value: try present.map { try walk($0, args[0], schema, deep) })\n    case (.named(let name, _), _):\n      if let d = schema.program.definitions[name], d.handle {\n        if case .handle(let n, _) = value, n == name { return value }\n        throw fail(\"InvalidHandle\", name)\n      }\n      guard let cs = try constructors(t, schema) else {\n        return try Scalar.validate(value, t, schema.bits)\n      }\n      return try walkData(value, t, cs, schema, deep)\n    case (.parameter, _):\n      throw fail(\"UnboundSchemaParameter\")\n    }\n  }\n\n  private static func walkData(\n    _ value: Value, _ t: TypeRef, _ cs: [Constructor], _ schema: Schema, _ deep: Bool\n  ) throws -> Value {\n    guard case .data(let tag, let fields) = value else {\n      throw fail(\"ExpectedData\", Scalar.typeKey(t))\n    }\n    var c = try findConstructor(tag, cs)\n    if fields.count != c.fields.count { throw fail(\"WrongFieldCount\", tag) }\n    let typed = try witnessed(c, fields, schema)\n    let converted =\n      deep ? try zip(fields, typed).map { try walk($0.0, $0.1.1, schema, deep) } : fields\n    var args = [TypeRef]()\n    var name = \"\"\n    if case .named(let n, let a) = t {\n      args = a\n      name = n\n    }\n    try checkPredicates(c, args, converted, schema)\n    c.fields = typed\n    try checkIndices(c, converted, schema)\n    try checkCollection(name, converted)\n    return .data(tag, converted)\n  }\n\n  /// Build a value from checked fields: the fields are not walked again, but\n  /// the constructor's contracts are checked.\n  public static func construct(_ tag: String, _ fields: [Value], _ t: TypeRef, _ schema: Schema)\n    throws -> Value\n  {\n    if tag == \"List::Nil\" && fields.isEmpty { return .list([]) }\n    if tag == \"List::Cons\", fields.count == 2, case .list(let tail) = fields[1] {\n      return .list([fields[0]] + tail)\n    }\n    try checkType(t, schema)\n    guard let cs = try constructors(t, schema) else {\n      throw fail(\"ExpectedData\", Scalar.typeKey(t))\n    }\n    return try walkData(.data(tag, fields), t, cs, schema, false)\n  }\n\n  /// The field types of a checked data value (a recording uses them to tell Text\n  /// from Bytes and Char from an integer).\n  public static func fieldTypes(_ value: Value, _ t: TypeRef, _ schema: Schema) throws -> [TypeRef]\n  {\n    guard case .data(let tag, let values) = value, let cs = try constructors(t, schema) else {\n      throw fail(\"ExpectedData\", Scalar.typeKey(t))\n    }\n    return try witnessed(try findConstructor(tag, cs), values, schema).map { $0.1 }\n  }\n\n  // MARK: Payloads\n\n  private indirect enum Recipe {\n    case noPayload\n    case predicate((Value) throws -> Bool)\n    case container(String, [Recipe])\n  }\n\n  private static func recipe(_ t: TypeRef, _ args: [Recipe]) -> Recipe {\n    switch t {\n    case .parameter(let i): return i < args.count ? args[i] : .noPayload\n    case .named(let name, let fields):\n      let children = fields.map { recipe($0, args) }\n      if children.allSatisfy({ if case .noPayload = $0 { return true } else { return false } }) {\n        return .noPayload\n      }\n      return .container(name, children)\n    }\n  }\n\n  private static func payload(_ r: Recipe, _ value: Value, _ schema: Schema) throws -> Bool {\n    switch (r, value) {\n    case (.noPayload, _): return true\n    case (.predicate(let p), _): return try p(value)\n    case (.container(\"List\", let inner), .list(let items)) where inner.count == 1:\n      return try items.allSatisfy { try payload(inner[0], $0, schema) }\n    case (.container(_, let inner), .presence(_, nil)) where inner.count == 1: return true\n    case (.container(_, let inner), .presence(_, let v?)) where inner.count == 1:\n      return try payload(inner[0], v, schema)\n    case (.container(\"Maybe\", _), .data(\"Maybe::Absent\", _)): return true\n    case (.container(\"Maybe\", let inner), .data(\"Maybe::Present\", let f))\n    where inner.count == 1 && f.count == 1:\n      return try payload(inner[0], f[0], schema)\n    case (.container(\"Either\", let inner), .data(\"Either::Left\", let f))\n    where inner.count == 2 && f.count == 1:\n      return try payload(inner[0], f[0], schema)\n    case (.container(\"Either\", let inner), .data(\"Either::Right\", let f))\n    where inner.count == 2 && f.count == 1:\n      return try payload(inner[1], f[0], schema)\n    case (.container(let name, let args), .data(let tag, let values)):\n      guard let d = schema.program.definitions[name] else { throw fail(\"InvalidPayload\") }\n      let c = try findConstructor(tag, d.constructors)\n      return try zip(c.fields, values).allSatisfy {\n        try payload(recipe($0.0.1, args), $0.1, schema)\n      }\n    default:\n      throw fail(\"InvalidPayload\")\n    }\n  }\n\n  /// Whether every payload of a container (each value at a type parameter)\n  /// satisfies that parameter's predicate.\n  public static func allPayloads(\n    _ value: Value, _ t: TypeRef, _ predicates: [(Value) throws -> Bool], _ schema: Schema\n  ) throws -> Bool {\n    guard case .named(let name, let args) = t else { throw fail(\"UnboundSchemaParameter\") }\n    if args.count != predicates.count { throw fail(\"PayloadArityMismatch\", name) }\n    _ = try validate(value, t, schema)\n    return try payload(.container(name, predicates.map { .predicate($0) }), value, schema)\n  }\n\n  // MARK: Builders, as the generated schema module writes a program's data\n\n  /// A field's name and type (by key).\n  public static func field(_ name: String, _ key: String) throws -> (String, TypeRef) {\n    (name, try Scalar.typeOf(key))\n  }\n\n  /// A data definition.\n  public static func definition(\n    _ name: String, _ parameters: Int, _ constructors: [Constructor], _ handle: Bool\n  ) -> DataDefinition {\n    DataDefinition(name: name, parameters: parameters, constructors: constructors, handle: handle)\n  }\n\n  public static func withPredicates(_ predicates: [FieldPredicate], _ c: Constructor) -> Constructor\n  {\n    var made = c\n    made.predicates = predicates\n    return made\n  }\n\n  public static func withGenerators(_ generators: [(Int, FieldGenerator)], _ c: Constructor)\n    -> Constructor\n  {\n    var made = c\n    made.generators = Dictionary(generators, uniquingKeysWith: { $1 })\n    return made\n  }\n\n  public static func withIndices(_ indices: [String], _ c: Constructor) -> Constructor {\n    var made = c\n    made.indices = indices\n    return made\n  }\n\n  public static func withRefinements(_ refinements: [(Int, TypeRef)], _ c: Constructor)\n    -> Constructor\n  {\n    var made = c\n    made.refinements = refinements\n    return made\n  }\n\n  public static func withExistentials(_ count: Int, _ c: Constructor) -> Constructor {\n    var made = c\n    made.existentials = count\n    return made\n  }\n\n  public static func withWitnesses(_ witnesses: [Int], _ c: Constructor) -> Constructor {\n    var made = c\n    made.witnesses = witnesses\n    return made\n  }\n\n  /// A refinement of a parameter, by position, to a type (by key).\n  public static func refinement(_ index: Int, _ key: String) throws -> (Int, TypeRef) {\n    (index, try Scalar.typeOf(key))\n  }\n\n  /// A constructor contract's known parameter types, by position.\n  public static func known(_ types: [TypeRef]) -> [Int: TypeRef] {\n    Dictionary(uniqueKeysWithValues: types.enumerated().map { ($0.offset, $0.element) })\n  }\n\n  /// A field's generation hints.\n  public static func hints(\n    _ bounds: [(String, Value)], _ lengths: [(String, Value)], _ values: [Value]\n  ) -> FieldHints {\n    FieldHints(bounds: bounds, lengths: lengths, hints: values)\n  }\n}\n"
swiftSource "LawSpecRuntime/SecureNetwork.swift" = "// One owned security layer per node: signed ML-KEM handshakes, address-pinned\n// ML-DSA identities, and authenticated encrypted frames. Frames reach the\n// node only after they open under a session's key.\n// ref:DEC-distribution-canonical-wire\n\nimport Foundation\n\n/// A node's identity and the fingerprints it trusts (nil: trust on first use).\npublic struct NetworkOptions: Sendable {\n  public var identity: NodeIdentity?\n  public var identitySeed: [UInt8]?\n  public var trusted: [String]?\n  /// Whether trusted was given (so the configuration file is not read for it).\n  public var trustGiven: Bool\n  public var firstId: UInt64?\n\n  public init(\n    identity: NodeIdentity? = nil, identitySeed: [UInt8]? = nil, trusted: [String]? = nil,\n    trustGiven: Bool = false, firstId: UInt64? = nil\n  ) {\n    self.identity = identity\n    self.identitySeed = identitySeed\n    self.trusted = trusted\n    self.trustGiven = trustGiven\n    self.firstId = firstId\n  }\n}\n\n/// Node identities and trust from options, then lawspec-network.conf (found\n/// from the working directory up, or named by LAWSPEC_NETWORK_CONF), whose\n/// `identity` line names a file of the seed in hexadecimal and whose\n/// `trusted` line names a file of fingerprints.\npublic enum NetworkConfig {\n  public static let empty = NetworkOptions()\n\n  private static func locate() -> String? {\n    if let file = ProcessInfo.processInfo.environment[\"LAWSPEC_NETWORK_CONF\"], !file.isEmpty {\n      return URL(fileURLWithPath: file).standardizedFileURL.path\n    }\n    var directory = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)\n      .standardizedFileURL\n    while true {\n      let path = directory.appendingPathComponent(\"lawspec-network.conf\").path\n      if FileManager.default.fileExists(atPath: path) { return path }\n      let parent = directory.deletingLastPathComponent()\n      if parent.path == directory.path { return nil }\n      directory = parent\n    }\n  }\n\n  public static func configured() throws -> ([UInt8]?, [String]?) {\n    guard let path = locate(), FileManager.default.fileExists(atPath: path) else {\n      return (nil, nil)\n    }\n    let directory = URL(fileURLWithPath: path).deletingLastPathComponent()\n    var identity: [UInt8]? = nil\n    var trusted: [String]? = nil\n    let text = try String(contentsOfFile: path, encoding: .utf8)\n    for line in text.components(separatedBy: \"\\n\") {\n      let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)\n      for kind in [\"identity\", \"trusted\"] {\n        guard trimmed.hasPrefix(kind), trimmed.count > kind.count,\n          trimmed[trimmed.index(trimmed.startIndex, offsetBy: kind.count)].isWhitespace\n        else { continue }\n        let name = String(trimmed.dropFirst(kind.count)).trimmingCharacters(in: .whitespaces)\n        let content = try String(\n          contentsOfFile: directory.appendingPathComponent(name).path, encoding: .utf8)\n        if kind == \"identity\" {\n          guard let seed = Wire.unhex(content.trimmingCharacters(in: .whitespacesAndNewlines))\n          else {\n            throw Fail.with(\"InvalidNodeIdentity\")\n          }\n          identity = seed\n        } else {\n          trusted = content.components(separatedBy: .whitespacesAndNewlines).filter { !$0.isEmpty }\n        }\n      }\n    }\n    return (identity, trusted)\n  }\n\n  public static func fingerprint(_ value: String) throws -> String {\n    try Fail.require(\n      value.utf8.count == 64 && Wire.unhex(value) != nil, \"InvalidTrustedFingerprint\")\n    return value.lowercased()\n  }\n\n  /// The identity and the trusted set to use.\n  public static func resolve(_ options: NetworkOptions) throws -> (NodeIdentity, Set<String>?) {\n    let (fileIdentity, fileTrusted) =\n      (options.identity != nil || options.identitySeed != nil) && options.trustGiven\n      ? (nil, nil) : try configured()\n    let identity: NodeIdentity\n    if let given = options.identity {\n      identity = given\n    } else if let seed = options.identitySeed ?? fileIdentity {\n      identity = try NetworkRecords.identity(seed)\n    } else {\n      identity = try NetworkRecords.identity(CryptoPrimitives.randomBytes(32))\n    }\n    let trusted = options.trustGiven ? options.trusted : fileTrusted\n    return (identity, try trusted.map { Set(try $0.map(fingerprint)) })\n  }\n}\n\nfinal class SecureLayer: @unchecked Sendable {\n  private final class Pending {\n    let session: [UInt8]\n    let seed: [UInt8]\n    let body: [UInt8]\n    let hello: [UInt8]\n    var queue: [[UInt8]]\n    var timer: NetworkTimer?\n\n    init(session: [UInt8], seed: [UInt8], body: [UInt8], hello: [UInt8], queue: [[UInt8]]) {\n      self.session = session\n      self.seed = seed\n      self.body = body\n      self.hello = hello\n      self.queue = queue\n    }\n  }\n\n  private struct State {\n    var known: [String: String] = [:]\n    var sessions: [[UInt8]: (String, [UInt8], Int)] = [:]\n    var outbound: [String: [UInt8]] = [:]\n    var pending: [String: Pending] = [:]\n    var welcomes: [[UInt8]: ([UInt8], [UInt8], String)] = [:]\n    var closed = false\n  }\n\n  private let identity: NodeIdentity\n  private let trusted: Set<String>?\n  private let deliver: PacketReceiver\n  private let state = Locked(State())\n  private var connection: (any PacketTransport)!\n\n  init(_ transport: Transport, _ options: NetworkOptions, _ deliver: @escaping PacketReceiver)\n    throws\n  {\n    (identity, trusted) = try NetworkConfig.resolve(options)\n    self.deliver = deliver\n    connection = try Transports.open(transport) { [weak self] _, bytes in\n      guard let self else { return }\n      try? self.incoming(bytes)\n    }\n  }\n\n  var address: String { connection.address }\n\n  /// The SHA3-256 fingerprint of this node's public key.\n  var fingerprint: String { NetworkRecords.fingerprint(identity) }\n\n  private func accept(_ peer: String, _ publicKey: [UInt8], _ s: inout State) throws {\n    let fingerprint = Wire.hex(CryptoPrimitives.sha3(publicKey))\n    if let set = trusted, !set.contains(fingerprint) { throw Fail.with(\"UntrustedPeer\", peer) }\n    if let existing = s.known[peer], existing != fingerprint {\n      throw Fail.with(\"PeerIdentityChanged\", peer)\n    }\n    s.known[peer] = fingerprint\n  }\n\n  private func validPeer(_ peer: String) throws {\n    let (node, name) = try Wire.splitAddress(peer + \"/\")\n    if node != peer || !name.isEmpty { throw Fail.with(\"InvalidPeer\", peer) }\n  }\n\n  private func signed(_ kind: UInt8, _ prefix: String, _ body: [UInt8]) throws -> [UInt8] {\n    NetworkRecords.record(\n      kind, body, try NetworkRecords.sign(identity.seed, Array(prefix.utf8) + body))\n  }\n\n  private func wire(_ peer: String, _ bytes: [UInt8]) -> String? { connection.send(peer, bytes) }\n\n  private func incoming(_ record: [UInt8]) throws {\n    var outgoing = [(String, [UInt8])]()\n    var received = [(String, [UInt8])]()\n    try state.with { s in\n      switch try NetworkRecords.read(record) {\n      case .handshake(1, let values, let body, let signature) where values.count == 4:\n        let (session, peerBytes, publicKey, kem) = (values[0], values[1], values[2], values[3])\n        if session.count != 16 || kem.count != 1184 { throw Fail.with(\"InvalidHello\") }\n        let peer = String(decoding: peerBytes, as: UTF8.self)\n        try validPeer(peer)\n        if let (hello, answer, from) = s.welcomes[session] {\n          if from == peer && hello == record { outgoing.append((peer, answer)) }\n          return\n        }\n        if s.sessions[session] != nil || s.pending.values.contains(where: { $0.session == session })\n        {\n          throw Fail.with(\"DuplicateSession\")\n        }\n        if !CryptoPrimitives.mldsaVerify(\n          publicKey, Array(\"lawspec-handshake-v1-hello\".utf8) + body, signature)\n        {\n          throw Fail.with(\"BadSignature\")\n        }\n        try accept(peer, publicKey, &s)\n        let (ciphertext, shared) = try NetworkRecords.encapsulate(kem)\n        let welcomeBody = NetworkRecords.welcome(\n          session, connection.address, identity.publicKey, ciphertext, body)\n        let answer = try signed(2, \"lawspec-handshake-v1-welcome\", welcomeBody)\n        let sessionKey = NetworkRecords.key(shared, body, welcomeBody)\n        s.welcomes[session] = (record, answer, peer)\n        s.sessions[session] = (peer, sessionKey, 1)\n        outgoing.append((peer, answer))\n      case .handshake(2, let values, let body, let signature) where values.count == 5:\n        let (session, peerBytes, publicKey, ciphertext, hash) = (\n          values[0], values[1], values[2], values[3], values[4]\n        )\n        let peer = String(decoding: peerBytes, as: UTF8.self)\n        guard let p = s.pending[peer], p.session == session else { return }\n        if ciphertext.count != 1088 || hash != CryptoPrimitives.sha3(p.body) {\n          throw Fail.with(\"InvalidWelcome\")\n        }\n        if !CryptoPrimitives.mldsaVerify(\n          publicKey, Array(\"lawspec-handshake-v1-welcome\".utf8) + body, signature)\n        {\n          throw Fail.with(\"BadSignature\")\n        }\n        try accept(peer, publicKey, &s)\n        let sessionKey = NetworkRecords.key(\n          try NetworkRecords.decapsulate(p.seed, ciphertext), p.body, body)\n        p.timer?.cancel()\n        s.pending[peer] = nil\n        s.sessions[session] = (peer, sessionKey, 0)\n        s.outbound[peer] = session\n        for frame in p.queue {\n          outgoing.append((peer, try NetworkRecords.seal(sessionKey, session, 0, frame)))\n        }\n      case .sealed(let session, let direction, let sealedBytes):\n        guard let (peer, sessionKey, own) = s.sessions[session], direction == 1 - own else {\n          return\n        }\n        if let frame = NetworkRecords.openSealed(sessionKey, session, direction, sealedBytes) {\n          received.append((peer, frame))\n          if s.outbound[peer] == nil { s.outbound[peer] = session }\n        }\n      default:\n        return\n      }\n    }\n    for (peer, bytes) in outgoing { _ = wire(peer, bytes) }\n    for (peer, frame) in received { deliver(peer, frame) }\n  }\n\n  private enum Action {\n    case send([UInt8])\n    case done(String?)\n  }\n\n  /// Seal a frame for a peer, after a handshake if there is no session yet.\n  /// Nil, or why it failed.\n  func send(_ peer: String, _ frame: [UInt8]) -> String? {\n    let action: Action\n    do {\n      action = try state.with { s throws -> Action in\n        if s.closed { return .done(\"transport_closed\") }\n        if let session = s.outbound[peer], let (_, sessionKey, direction) = s.sessions[session] {\n          return .send(try NetworkRecords.seal(sessionKey, session, direction, frame))\n        }\n        if let p = s.pending[peer] {\n          if p.queue.count < 4096 {\n            p.queue.append(frame)\n            return .done(nil)\n          }\n          return .done(\"handshake_queue_full\")\n        }\n        let session = CryptoPrimitives.randomBytes(16)\n        let (kem, seed) = CryptoPrimitives.mlkemKeyPair(CryptoPrimitives.randomBytes(64))\n        let body = NetworkRecords.hello(session, connection.address, identity.publicKey, kem)\n        let hello = try signed(1, \"lawspec-handshake-v1-hello\", body)\n        let deadline = Date().addingTimeInterval(5)\n        let p = Pending(session: session, seed: seed, body: body, hello: hello, queue: [frame])\n        s.pending[peer] = p\n        let handle = UncheckedBox(p)\n        p.timer = NetworkTimer(100) { [weak self] in\n          guard let self else { return }\n          let resend: Bool = self.state.with { s in\n            guard let q = s.pending[peer], q === handle.value else { return false }\n            if Date() >= deadline {\n              q.timer?.cancel()\n              s.pending[peer] = nil\n              return false\n            }\n            return true\n          }\n          if resend { _ = self.wire(peer, hello) }\n        }\n        return .send(hello)\n      }\n    } catch {\n      return \"secure_layer_failed\"\n    }\n    switch action {\n    case .send(let bytes): return wire(peer, bytes)\n    case .done(let result): return result\n    }\n  }\n\n  func close() {\n    state.with { s in\n      s.closed = true\n      for p in s.pending.values { p.timer?.cancel() }\n      s.pending.removeAll()\n    }\n    connection.close()\n  }\n}\n"
swiftSource "LawSpecRuntime/Sessions.swift" = "// One protocol conversation: a pair of affine ends. Each step consumes an\n// end and gives the next one, so a spent end fails. An end may be sent over\n// another channel (delegation); on a network, an end that has not been used\n// moves with its state, and a local one is relayed by its node.\n// ref:DEC-sessions-by-construction ref:DEC-distribution-canonical-wire\n\nimport Foundation\n\n/// What a protocol step carries: a value (with its wire descriptor text, if\n/// it has one), or an end of another protocol.\npublic enum SessionPart: Sendable {\n  case value(String?)\n  case end(String)\n}\n\n/// A step of a protocol, as its first end sees it.\npublic struct SessionStep: Sendable {\n  public let firstSends: Bool\n  public let part: SessionPart\n\n  public init(_ firstSends: Bool, _ part: SessionPart) {\n    self.firstSends = firstSends\n    self.part = part\n  }\n}\n\n/// A protocol to open, with the catalogue of every protocol its steps name,\n/// and the network deadline (ms) of its ends.\npublic struct SessionSpec: Sendable {\n  public let id: String\n  public let protocols: [String: [SessionStep]]\n  public let deadline: Int\n\n  public init(_ id: String, _ protocols: [String: [SessionStep]], _ deadline: Int) {\n    self.id = id\n    self.protocols = protocols\n    self.deadline = deadline\n  }\n\n  func with(id: String) -> SessionSpec { SessionSpec(id, protocols, deadline) }\n}\n\nenum SessionItem {\n  case item(Value)\n  case delegated(SessionEnd)\n}\n\n/// A waiter for one item, settled once.\nfinal class SessionWaiter: @unchecked Sendable {\n  private let done = DispatchSemaphore(value: 0)\n  private var result: Result<SessionItem, LawSpecError>?\n\n  func settle(_ outcome: Result<SessionItem, LawSpecError>) {\n    result = outcome\n    done.signal()\n  }\n\n  func wait() -> Result<SessionItem, LawSpecError> {\n    done.wait()\n    return result!\n  }\n}\n\nfinal class SideState {\n  var generation: Int64\n  var step = 0\n  var closed = false\n  var queue: [SessionItem] = []\n  var reader: SessionWaiter?\n\n  init(_ generation: Int64) { self.generation = generation }\n}\n\npublic final class SessionChannel: @unchecked Sendable {\n  private static let generations = Locked<Int64>(0)\n  private static let custody = Locked<[ObjectIdentifier: SessionChannel]>([:])\n  let gate = NSRecursiveLock()\n  public let spec: SessionSpec\n  let steps: [SessionStep]\n  let network: (Node, Endpoint, Int)?\n  private var sides: [SideState]\n\n  static func fresh() -> Int64 {\n    generations.with {\n      $0 += 1\n      return $0\n    }\n  }\n\n  init(_ spec: SessionSpec, _ network: (Node, Endpoint, Int)?) {\n    self.spec = spec\n    steps = spec.protocols[spec.id] ?? []\n    self.network = network\n    sides = [SideState(SessionChannel.fresh()), SideState(SessionChannel.fresh())]\n    if let (_, _, own) = network { sides[1 - own].step = steps.count }\n  }\n\n  static func fail(_ reason: String) -> LawSpecError { Fail.with(\"Session\", reason) }\n\n  func locked<T>(_ body: () throws -> T) rethrows -> T {\n    gate.lock()\n    defer { gate.unlock() }\n    return try body()\n  }\n\n  func side(_ n: Int) -> SideState { sides[n] }\n\n  func handle(_ n: Int) -> SessionEnd { SessionEnd(self, n, sides[n].generation, sides[n].step) }\n\n  /// The ends of a new local channel.\n  static func open(_ spec: SessionSpec) -> (SessionEnd, SessionEnd) {\n    let channel = SessionChannel(spec, nil)\n    return (channel.handle(0), channel.handle(1))\n  }\n\n  @discardableResult\n  func check(_ e: SessionEnd) throws -> SideState {\n    guard e.channel === self else { throw SessionChannel.fail(\"invalid_end\") }\n    let s = sides[e.side]\n    if s.generation != e.generation || s.step != e.step {\n      throw SessionChannel.fail(\"spent_end: this end was already used\")\n    }\n    if s.closed { throw SessionChannel.fail(\"abandoned_end\") }\n    return s\n  }\n\n  func part(_ e: SessionEnd, _ sending: Bool) throws -> SessionPart {\n    try locked {\n      let s = try check(e)\n      if s.step >= steps.count { throw SessionChannel.fail(\"protocol_complete\") }\n      let step = steps[s.step]\n      let sends = e.side == 0 ? step.firstSends : !step.firstSends\n      if sends != sending { throw SessionChannel.fail(\"wrong_step\") }\n      return step.part\n    }\n  }\n\n  /// Check an end and give the next one.\n  func advance(_ e: SessionEnd) throws -> SessionEnd {\n    try locked {\n      try check(e)\n      sides[e.side].step += 1\n      return handle(e.side)\n    }\n  }\n\n  /// A new handle of an end, spending the old one (a transfer).\n  func reissue(_ e: SessionEnd) throws -> SessionEnd {\n    try locked {\n      try check(e)\n      sides[e.side].generation = SessionChannel.fresh()\n      return handle(e.side)\n    }\n  }\n\n  private func wake(_ n: Int) -> [() -> Void] {\n    let s = sides[n]\n    guard let reader = s.reader else { return [] }\n    if !s.queue.isEmpty {\n      s.reader = nil\n      let item = s.queue.removeFirst()\n      return [{ reader.settle(.success(item)) }]\n    }\n    if sides[1 - n].closed && network == nil {\n      s.reader = nil\n      s.closed = true\n      return [{ reader.settle(.failure(SessionChannel.fail(\"peer_failed\"))) }]\n    }\n    return []\n  }\n\n  func enqueue(_ n: Int, _ item: SessionItem) {\n    let actions: [() -> Void] = locked {\n      if sides[n].closed {\n        if case .delegated(let e) = item { return [{ SessionChannel.discard(e) }] }\n        return []\n      }\n      sides[n].queue.append(item)\n      return wake(n)\n    }\n    for a in actions { a() }\n  }\n\n  /// Wait for the next item of a side.\n  func await(_ n: Int) throws -> SessionItem {\n    let reader = SessionWaiter()\n    let actions: [() -> Void] = locked {\n      sides[n].reader = reader\n      return wake(n)\n    }\n    for a in actions { a() }\n    return try reader.wait().get()\n  }\n\n  /// Close a side: its queue's delegated ends are discarded, and a local\n  /// peer's reader learns the peer gave up.\n  func closeSide(_ n: Int) {\n    let actions: [() -> Void] = locked {\n      let s = sides[n]\n      if s.closed { return [] }\n      s.closed = true\n      var out = [() -> Void]()\n      for item in s.queue {\n        if case .delegated(let e) = item { out.append { SessionChannel.discard(e) } }\n      }\n      s.queue.removeAll()\n      if let r = s.reader {\n        s.reader = nil\n        out.append { r.settle(.failure(SessionChannel.fail(\"abandoned_end\"))) }\n      }\n      if network != nil { sides[1 - n].closed = true } else { out += wake(1 - n) }\n      return out\n    }\n    SessionChannel.release(self)\n    if let (_, endpoint, own) = network, own == n { endpoint.abandon() }\n    for a in actions { a() }\n  }\n\n  /// Give up an end if it is still current (whoever holds it).\n  static func discard(_ e: SessionEnd) {\n    let current = e.channel.locked {\n      let s = e.channel.sides[e.side]\n      return s.generation == e.generation && !s.closed\n    }\n    if current { e.channel.closeSide(e.side) }\n  }\n\n  /// Queue custody is a forest: moving a channel's first end into another\n  /// channel fails if it would make a cycle.\n  static func move(_ child: SessionChannel, _ parent: SessionChannel) throws {\n    try custody.with { c in\n      var at: SessionChannel? = parent\n      while let node = at {\n        if node === child { throw SessionChannel.fail(\"cyclic_delegation\") }\n        at = c[ObjectIdentifier(node)]\n      }\n      c[ObjectIdentifier(child)] = parent\n    }\n  }\n\n  static func release(_ child: SessionChannel) {\n    custody.with { $0[ObjectIdentifier(child)] = nil }\n  }\n}\n\n/// An end of a channel at a step. Using it spends it.\npublic final class SessionEnd: @unchecked Sendable, CustomStringConvertible {\n  let channel: SessionChannel\n  let side: Int\n  let generation: Int64\n  let step: Int\n\n  init(_ channel: SessionChannel, _ side: Int, _ generation: Int64, _ step: Int) {\n    self.channel = channel\n    self.side = side\n    self.generation = generation\n    self.step = step\n  }\n\n  public var description: String { \"session end \\(side) of \\(channel.spec.id) at step \\(step)\" }\n}\n\n/// The ends a task holds: given up if the task fails or is cancelled.\nfinal class OwnedEnds: @unchecked Sendable {\n  private let gate = NSLock()\n  private var ends: [SessionEnd] = []\n\n  init(_ ends: [SessionEnd]) { self.ends = ends }\n\n  func add(_ e: SessionEnd) {\n    gate.lock()\n    ends.append(e)\n    gate.unlock()\n  }\n\n  func remove(_ e: SessionEnd) {\n    gate.lock()\n    ends.removeAll { $0.channel === e.channel && $0.side == e.side }\n    gate.unlock()\n  }\n\n  /// Give up every end still held.\n  func discardAll() {\n    gate.lock()\n    let held = ends\n    gate.unlock()\n    for e in held { SessionChannel.discard(e) }\n  }\n}\n\n/// A task that runs a body with an end it was given; joined for its result.\npublic final class SessionTask: @unchecked Sendable {\n  let owned: OwnedEnds\n  private let done = DispatchSemaphore(value: 0)\n  private var outcome: Result<Value, any Error>?\n\n  init(_ owned: OwnedEnds) { self.owned = owned }\n\n  func settle(_ result: Result<Value, any Error>) {\n    outcome = result\n    done.signal()\n  }\n\n  /// The result, waiting for it; at most `seconds` when given.\n  func wait(_ seconds: Double?) -> Result<Value, any Error>? {\n    if let seconds {\n      guard done.wait(timeout: .now() + seconds) == .success else { return nil }\n    } else {\n      done.wait()\n    }\n    done.signal()\n    return outcome\n  }\n}\n\n/// Session operations, as the generated typed ends call them.\n/// ref:DEC-sessions-by-construction ref:DEC-async-native-tasks\npublic enum Sessions {\n  private static let ownedKey = \"lawspec.sessions.owned\"\n\n  /// Note that the running task now holds an end.\n  @discardableResult\n  private static func track(_ e: SessionEnd) -> SessionEnd {\n    (Ambient.get(ownedKey) as? OwnedEnds)?.add(e)\n    return e\n  }\n\n  /// Note that the running task no longer holds an end.\n  private static func untrack(_ e: SessionEnd) { (Ambient.get(ownedKey) as? OwnedEnds)?.remove(e) }\n\n  /// Run a body that owns some ends; if it fails, the ends it holds are given up.\n  public static func withOwned<T>(_ ends: [SessionEnd], _ body: () throws -> T) throws -> T {\n    let owned = OwnedEnds(ends)\n    return try Ambient.with(ownedKey, owned) {\n      do {\n        return try body()\n      } catch {\n        owned.discardAll()\n        throw error\n      }\n    }\n  }\n\n  /// Start a task with an end it now owns.\n  public static func spawn(\n    _ e: SessionEnd, _ body: @escaping @Sendable (SessionEnd) throws -> Value\n  ) throws -> SessionTask {\n    let moved = try transfer(e)\n    let task = SessionTask(OwnedEnds([moved]))\n    LawThread.start {\n      Ambient.set(ownedKey, task.owned)\n      do {\n        task.settle(.success(try body(moved)))\n      } catch {\n        task.owned.discardAll()\n        task.settle(.failure(error))\n      }\n    }\n    return task\n  }\n\n  /// Wait for a task's result; its failure is thrown here.\n  public static func join(_ task: SessionTask) throws -> Value { try task.wait(nil)!.get() }\n\n  /// Cancel a task: the ends it still owns are given up, so it stops at its next step.\n  public static func cancel(_ task: SessionTask) {\n    task.owned.discardAll()\n    _ = task.wait(5)\n  }\n\n  private static let names = Locked<Int64>(0)\n  private static let textType = Wire.textType\n\n  private static func fail(_ reason: String) -> LawSpecError { SessionChannel.fail(reason) }\n\n  private static func encode(_ part: SessionPart, _ value: Value) throws -> [UInt8] {\n    switch part {\n    case .value(.some(let text)):\n      let (table, d) = try Descriptors.fromText(text)\n      return try Descriptors.encode(d, value, table)\n    case .value(.none): throw fail(\"non_wire_payload\")\n    case .end: return try Descriptors.encode(textType, value, [:])\n    }\n  }\n\n  private static func decode(_ part: SessionPart, _ bytes: [UInt8]) throws -> Value {\n    switch part {\n    case .value(.some(let text)):\n      let (table, d) = try Descriptors.fromText(text)\n      return try Descriptors.decode(d, bytes, table)\n    case .value(.none): throw fail(\"non_wire_payload\")\n    case .end: return try Descriptors.decode(textType, bytes, [:])\n    }\n  }\n\n  /// A name no other session end on the node has.\n  public static func freshName() -> String {\n    \"session-\"\n      + String(\n        names.with {\n          $0 += 1\n          return $0\n        })\n  }\n\n  /// Whether every protocol a network end may carry has a wire form.\n  public static func validate(_ spec: SessionSpec) throws {\n    func go(_ id: String, _ seen: [String]) throws {\n      if seen.contains(id) { return }\n      let steps = spec.protocols[id] ?? []\n      if steps.isEmpty { throw fail(\"empty_network_protocol\") }\n      for step in steps {\n        switch step.part {\n        case .end(let other): try go(other, [id] + seen)\n        case .value(.none): throw fail(\"non_wire_payload\")\n        case .value(.some(let text)): _ = try Descriptors.fromText(text)\n        }\n      }\n    }\n    try go(spec.id, [])\n  }\n\n  /// A new local channel's two ends.\n  public static func openPair(_ spec: SessionSpec) -> (SessionEnd, SessionEnd) {\n    SessionChannel.open(spec)\n  }\n\n  /// A channel end on a node over the network, connected to a peer's\n  /// address if given.\n  public static func networkStart(\n    _ spec: SessionSpec, _ node: Node, _ name: String, _ side: Int, _ connection: String?\n  ) throws -> SessionEnd {\n    try validate(spec)\n    let endpoint = try Endpoint(node, name, spec.deadline)\n    let channel = SessionChannel(spec, (node, endpoint, side))\n    let e = channel.handle(side)\n    do {\n      if let peer = connection { try endpoint.connect(peer) }\n      return track(e)\n    } catch {\n      endpoint.stop()\n      throw error\n    }\n  }\n\n  /// Listen on a node: the first end, at its address.\n  public static func listen(_ node: Node, _ name: String, _ spec: SessionSpec) throws -> SessionEnd\n  {\n    try networkStart(spec, node, name, 0, nil)\n  }\n\n  /// Dial a listening end: the second end.\n  public static func dial(_ node: Node, _ address: String, _ spec: SessionSpec) throws -> SessionEnd\n  {\n    try networkStart(spec, node, freshName(), 1, address)\n  }\n\n  private static func endpointOf(_ e: SessionEnd) throws -> Endpoint {\n    try e.channel.locked { _ = try e.channel.check(e) }\n    guard let (_, endpoint, _) = e.channel.network else { throw fail(\"local_end\") }\n    return endpoint\n  }\n\n  /// A network end's address.\n  public static func address(_ e: SessionEnd) throws -> String { try endpointOf(e).address }\n\n  /// Send a value; the next end.\n  public static func send(_ e: SessionEnd, _ value: Value) throws -> SessionEnd {\n    let channel = e.channel\n    let part = try channel.part(e, true)\n    if case .end = part { throw fail(\"expected_delegation\") }\n    if let (_, endpoint, _) = channel.network {\n      let bytes = try encode(part, value)\n      let next = try channel.advance(e)\n      try endpoint.send(bytes)\n      untrack(e)\n      return track(next)\n    }\n    let next = try channel.advance(e)\n    channel.enqueue(1 - e.side, .item(value))\n    untrack(e)\n    return track(next)\n  }\n\n  private static func failedPeer(_ channel: SessionChannel, _ side: Int, _ reason: String)\n    -> LawSpecError\n  {\n    channel.closeSide(side)\n    return fail(\"peer_failed \" + reason)\n  }\n\n  /// Receive a value; it and the next end.\n  public static func receiveValue(_ e: SessionEnd) throws -> (Value, SessionEnd) {\n    let channel = e.channel\n    let part = try channel.part(e, false)\n    if case .end = part { throw fail(\"wrong_receive_kind\") }\n    let next = try channel.advance(e)\n    untrack(e)\n    track(next)\n    if let (_, endpoint, _) = channel.network {\n      switch try endpoint.receive(channel.spec.deadline) {\n      case .success(let bytes):\n        guard let value = try? decode(part, bytes) else {\n          throw failedPeer(channel, e.side, \"invalid_payload\")\n        }\n        return (value, next)\n      case .failure(let reason):\n        throw failedPeer(channel, e.side, reason.reason)\n      }\n    }\n    switch try channel.await(e.side) {\n    case .item(let value): return (value, next)\n    case .delegated: throw fail(\"wrong_receive_kind\")\n    }\n  }\n\n  /// Give up an end.\n  public static func abandon(_ e: SessionEnd) throws {\n    try e.channel.locked { _ = try e.channel.check(e) }\n    e.channel.closeSide(e.side)\n    untrack(e)\n  }\n\n  /// The protocol an end follows.\n  public static func specification(_ e: SessionEnd) -> SessionSpec { e.channel.spec }\n\n  /// Move an end to another holder: the old handle is spent.\n  public static func transfer(_ e: SessionEnd) throws -> SessionEnd {\n    let moved = try e.channel.reissue(e)\n    untrack(e)\n    return moved\n  }\n\n  private static func unusedFirst(_ e: SessionEnd, _ expected: String) throws {\n    try e.channel.locked { _ = try e.channel.check(e) }\n    if e.side != 0 || e.step != 0 { throw fail(\"not_an_unused_first_end\") }\n    if e.channel.spec.id != expected { throw fail(\"different_protocol\") }\n  }\n\n  /// The address a delegated end is reached at from another node: a network\n  /// end moves (its offer); a local end stays, and this node relays it.\n  public static func offer(_ node: Node, _ e: SessionEnd, _ expected: String) throws -> String {\n    try unusedFirst(e, expected)\n    guard let (_, endpoint, _) = e.channel.network else { return try relay(node, e) }\n    let address = try endpoint.offer()\n    // The end now belongs to its taker: spend this handle without abandoning.\n    e.channel.locked {\n      let s = e.channel.side(e.side)\n      s.generation = -s.generation\n      s.closed = true\n    }\n    untrack(e)\n    return address\n  }\n\n  private static func relay(_ node: Node, _ e: SessionEnd) throws -> String {\n    let spec = e.channel.spec\n    try validate(spec)\n    let remote = try networkStart(spec, node, freshName(), 1, nil)\n    let addressOfRemote = try address(remote)\n    let local = try transfer(e)\n    let remoteMoved = try transfer(remote)\n    let steps = spec.protocols[spec.id] ?? []\n    LawThread.start {\n      var l = local\n      var r = remoteMoved\n      do {\n        for step in steps {\n          switch (step.firstSends, step.part) {\n          case (true, .value):\n            let (v, next) = try receiveValue(r)\n            r = next\n            l = try send(l, v)\n          case (false, .value):\n            let (v, next) = try receiveValue(l)\n            l = next\n            r = try send(r, v)\n          case (true, .end):\n            let (v, next) = try receiveEnd(r)\n            r = next\n            l = try sendEnd(l, v)\n          case (false, .end):\n            let (v, next) = try receiveEnd(l)\n            l = next\n            r = try sendEnd(r, v)\n          }\n        }\n      } catch {\n        SessionChannel.discard(l)\n        SessionChannel.discard(r)\n      }\n    }\n    return addressOfRemote\n  }\n\n  /// The end a delegation's address names, taken on this node.\n  public static func take(_ node: Node, _ address: String, _ spec: SessionSpec) throws -> SessionEnd\n  {\n    let moving = address.contains(\"?take=\")\n    let e = try networkStart(spec, node, freshName(), 0, moving ? nil : address)\n    do {\n      if moving { try endpointOf(e).take(address) }\n      return e\n    } catch {\n      try? abandon(e)\n      throw error\n    }\n  }\n\n  /// Send an unused first end of another protocol; the next end.\n  public static func sendEnd(_ e: SessionEnd, _ other: SessionEnd) throws -> SessionEnd {\n    let channel = e.channel\n    guard case .end(let expected) = try channel.part(e, true) else { throw fail(\"expected_value\") }\n    if other.side != 0 || other.step != 0 { throw fail(\"not_an_unused_first_end\") }\n    if other.channel === channel { throw fail(\"cyclic_delegation\") }\n    if let (node, endpoint, _) = channel.network {\n      let addressText = try offer(node, other, expected)\n      let next = try channel.advance(e)\n      try endpoint.send(try encode(.end(expected), .text(addressText)))\n      untrack(e)\n      return track(next)\n    }\n    try unusedFirst(other, expected)\n    try SessionChannel.move(other.channel, channel)\n    let moved = try transfer(other)\n    let next = try channel.advance(e)\n    channel.enqueue(1 - e.side, .delegated(moved))\n    untrack(e)\n    return track(next)\n  }\n\n  /// Receive an end; it and the next end.\n  public static func receiveEnd(_ e: SessionEnd) throws -> (SessionEnd, SessionEnd) {\n    let channel = e.channel\n    guard case .end(let proto) = try channel.part(e, false) else {\n      throw fail(\"wrong_receive_kind\")\n    }\n    let next = try channel.advance(e)\n    untrack(e)\n    track(next)\n    if let (node, endpoint, _) = channel.network {\n      switch try endpoint.receive(channel.spec.deadline) {\n      case .success(let bytes):\n        guard case .text(let addressText)? = try? decode(.end(proto), bytes) else {\n          throw failedPeer(channel, e.side, \"invalid_payload\")\n        }\n        do {\n          return (track(try take(node, addressText, channel.spec.with(id: proto))), next)\n        } catch {\n          throw failedPeer(channel, e.side, Node.message(error))\n        }\n      case .failure(let reason):\n        throw failedPeer(channel, e.side, reason.reason)\n      }\n    }\n    switch try channel.await(e.side) {\n    case .delegated(let other):\n      SessionChannel.release(other.channel)\n      return (track(other), next)\n    case .item:\n      throw fail(\"wrong_receive_kind\")\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/SocketTransport.swift" = "// TCP and HTTP packet transports over POSIX sockets. A TCP record is a\n// 4-byte big-endian length then the bytes; HTTP is one POST /lawspec per\n// connection, answered 204, with replies travelling to the peer's own\n// listener. Parsing never needs a socket, so malformed input can be checked\n// whole and at every boundary.\n// ref:DEC-distribution-canonical-wire\n\nimport Foundation\n\n#if canImport(Darwin)\n  import Darwin\n#else\n  import Glibc\n#endif\n\n/// TCP or HTTP.\npublic enum SocketKind: Sendable {\n  case tcp\n  case http\n\n  public var scheme: String { self == .tcp ? \"tcp\" : \"http\" }\n}\n\npublic enum SocketProtocol {\n  private static func isIp(_ h: String) -> Bool {\n    var v4 = in_addr()\n    var v6 = in6_addr()\n    return inet_pton(AF_INET, h, &v4) == 1 || inet_pton(AF_INET6, h, &v6) == 1\n  }\n\n  private static func isHostName(_ h: String) -> Bool {\n    let chars = Array(h.utf8)\n    func alnum(_ c: UInt8) -> Bool {\n      (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122)\n    }\n    guard let first = chars.first, let last = chars.last, alnum(first), alnum(last) else {\n      return false\n    }\n    return chars.allSatisfy { alnum($0) || $0 == 46 || $0 == 45 }\n  }\n\n  /// Whether text is an IP address or a host name.\n  public static func host(_ h: String) -> Bool {\n    !h.isEmpty && h.utf8.count <= 253 && (isIp(h) || isHostName(h))\n  }\n\n  /// A listener's address: tcp://host:port, with IPv6 hosts in brackets.\n  public static func address(_ kind: SocketKind, _ h: String, _ port: Int) -> String {\n    let name = h.contains(\":\") ? \"[\" + h + \"]\" : h\n    return kind.scheme + \"://\" + name + \":\" + String(port)\n  }\n\n  /// The host and port of a peer's address of the right kind, or nil.\n  public static func endpoint(_ kind: SocketKind, _ peer: String) -> (String, Int)? {\n    let prefix = kind.scheme + \"://\"\n    guard peer.hasPrefix(prefix) else { return nil }\n    let authority = String(peer.dropFirst(prefix.count))\n    guard !authority.isEmpty, !authority.contains(\"/\"), !authority.contains(\"?\"),\n      !authority.contains(\"@\"),\n      !authority.contains(\"#\"), let colon = authority.lastIndex(of: \":\")\n    else { return nil }\n    var h = String(authority[..<colon])\n    let portText = String(authority[authority.index(after: colon)...])\n    guard !portText.isEmpty, portText.utf8.count <= 5,\n      portText.utf8.allSatisfy({ $0 >= 48 && $0 <= 57 }),\n      let port = Int(portText), port > 0, port <= 65535\n    else { return nil }\n    if h.hasPrefix(\"[\") {\n      guard h.hasSuffix(\"]\") else { return nil }\n      h = String(h.dropFirst().dropLast())\n    } else if h.contains(\":\") {\n      return nil\n    }\n    return host(h) ? (h, port) : nil\n  }\n\n  public static func request(_ peer: String, _ bytes: [UInt8]) -> [UInt8] {\n    let authority = String(peer.dropFirst(\"http://\".count))\n    let head =\n      \"POST /lawspec HTTP/1.1\\r\\nHost: \" + authority\n      + \"\\r\\nContent-Type: application/octet-stream\\r\\nContent-Length: \"\n      + String(bytes.count) + \"\\r\\nConnection: close\\r\\n\\r\\n\"\n    return Array(head.utf8) + bytes\n  }\n\n  public static func response(_ code: Int) -> [UInt8] {\n    let reason: String\n    switch code {\n    case 204: reason = \"No Content\"\n    case 400: reason = \"Bad Request\"\n    case 404: reason = \"Not Found\"\n    case 405: reason = \"Method Not Allowed\"\n    case 411: reason = \"Length Required\"\n    case 413: reason = \"Content Too Large\"\n    case 417: reason = \"Expectation Failed\"\n    default: reason = \"Request Header Fields Too Large\"\n    }\n    return Array(\n      (\"HTTP/1.1 \" + String(code) + \" \" + reason\n        + \"\\r\\nContent-Length: 0\\r\\nConnection: close\\r\\n\\r\\n\").utf8)\n  }\n\n  /// The parse of an HTTP head so far.\n  public enum Head: Equatable {\n    case more\n    case failed(Int)\n    case body(size: Int, rest: [UInt8])\n  }\n\n  private static func headEnd(_ bytes: [UInt8]) -> Int {\n    var i = 0\n    while i + 3 < bytes.count {\n      if bytes[i] == 13 && bytes[i + 1] == 10 && bytes[i + 2] == 13 && bytes[i + 3] == 10 {\n        return i\n      }\n      i += 1\n    }\n    return -1\n  }\n\n  private static func lines(_ bytes: [UInt8], _ end: Int) -> [String] {\n    let text = String(decoding: bytes[0..<end].map { $0 < 128 ? $0 : 63 }, as: UTF8.self)\n    return text.components(separatedBy: \"\\r\\n\")\n  }\n\n  private static func headers(_ lines: ArraySlice<String>) -> [String: String]? {\n    if lines.count > 101 { return nil }\n    var fields = [String: String]()\n    for line in lines {\n      guard let at = line.firstIndex(of: \":\") else { return nil }\n      let name = line[..<at].trimmingCharacters(in: .whitespaces).lowercased()\n      if name.isEmpty || name.contains(\" \") { return nil }\n      if fields[name] != nil && (name == \"content-length\" || name == \"transfer-encoding\") {\n        return nil\n      }\n      if fields[name] == nil {\n        fields[name] = line[line.index(after: at)...].trimmingCharacters(in: .whitespaces)\n      }\n    }\n    return fields\n  }\n\n  /// A request's head: the body size and the bytes after the head.\n  public static func header(_ bytes: [UInt8], _ maximum: Int) -> Head {\n    let at = headEnd(bytes)\n    if at < 0 { return bytes.count < 16384 ? .more : .failed(431) }\n    if at + 4 > 16384 { return .failed(431) }\n    let all = lines(bytes, at)\n    let parts = all[0].components(separatedBy: \" \")\n    let rest = Array(bytes[(at + 4)...])\n    if parts.count != 3 || !(parts[2] == \"HTTP/1.1\" || parts[2] == \"HTTP/1.0\") {\n      return .failed(400)\n    }\n    if parts[0] != \"POST\" { return .failed(405) }\n    if parts[1] != \"/lawspec\" { return .failed(404) }\n    guard let fields = headers(all[1...]) else { return .failed(400) }\n    if fields[\"transfer-encoding\"] != nil { return .failed(400) }\n    if fields[\"expect\"] != nil { return .failed(417) }\n    guard let v = fields[\"content-length\"] else { return .failed(411) }\n    guard !v.isEmpty, v.utf8.count <= 10, v.utf8.allSatisfy({ $0 >= 48 && $0 <= 57 }),\n      let size = Int64(v)\n    else { return .failed(400) }\n    return size <= Int64(maximum) ? .body(size: Int(size), rest: rest) : .failed(413)\n  }\n\n  /// Whether a reply head is a 204: nil for more, or the answer.\n  public static func reply(_ bytes: [UInt8]) -> Bool? {\n    let at = headEnd(bytes)\n    if at < 0 { return bytes.count < 16384 ? nil : false }\n    let all = lines(bytes, at)\n    let parts = all[0].components(separatedBy: \" \")\n    return parts.count >= 2 && parts[0].hasPrefix(\"HTTP/1.\") && parts[1] == \"204\"\n      && headers(all[1...]) != nil\n  }\n}\n\n/// Blocking POSIX socket calls, each bounded by a timeout or a stop check.\nenum Sockets {\n  static func close(_ fd: Int32) { _ = Darwin.close(fd) }\n\n  private static func noSignal(_ fd: Int32) {\n    var one: Int32 = 1\n    _ = setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, socklen_t(MemoryLayout<Int32>.size))\n    _ = setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &one, socklen_t(MemoryLayout<Int32>.size))\n  }\n\n  /// The addresses of a host and port.\n  private static func resolve(_ host: String, _ port: Int, passive: Bool) -> [(Int32, Data)] {\n    var hints = addrinfo()\n    hints.ai_socktype = SOCK_STREAM\n    hints.ai_family = AF_UNSPEC\n    if passive { hints.ai_flags = AI_PASSIVE }\n    var list: UnsafeMutablePointer<addrinfo>?\n    guard getaddrinfo(host, String(port), &hints, &list) == 0, let first = list else { return [] }\n    defer { freeaddrinfo(first) }\n    var out = [(Int32, Data)]()\n    var cursor: UnsafeMutablePointer<addrinfo>? = first\n    while let entry = cursor {\n      if let addr = entry.pointee.ai_addr {\n        out.append(\n          (entry.pointee.ai_family, Data(bytes: addr, count: Int(entry.pointee.ai_addrlen))))\n      }\n      cursor = entry.pointee.ai_next\n    }\n    // IPv4 first, as the other targets bind it.\n    return out.filter { $0.0 == AF_INET } + out.filter { $0.0 != AF_INET }\n  }\n\n  /// A listening socket and its port.\n  static func listen(_ host: String, _ port: Int) throws -> (Int32, Int) {\n    for (family, address) in resolve(host, port, passive: true) {\n      let fd = socket(family, SOCK_STREAM, 0)\n      if fd < 0 { continue }\n      var one: Int32 = 1\n      _ = setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, socklen_t(MemoryLayout<Int32>.size))\n      let bound = address.withUnsafeBytes { raw in\n        bind(fd, raw.baseAddress!.assumingMemoryBound(to: sockaddr.self), socklen_t(address.count))\n      }\n      if bound != 0 || Darwin.listen(fd, 128) != 0 {\n        close(fd)\n        continue\n      }\n      var storage = sockaddr_storage()\n      var length = socklen_t(MemoryLayout<sockaddr_storage>.size)\n      let actual: Int = withUnsafeMutablePointer(to: &storage) { pointer in\n        pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {\n          _ = getsockname(fd, $0, &length)\n        }\n        if Int32(pointer.pointee.ss_family) == AF_INET {\n          return pointer.withMemoryRebound(to: sockaddr_in.self, capacity: 1) {\n            Int(UInt16(bigEndian: $0.pointee.sin_port))\n          }\n        }\n        return pointer.withMemoryRebound(to: sockaddr_in6.self, capacity: 1) {\n          Int(UInt16(bigEndian: $0.pointee.sin6_port))\n        }\n      }\n      return (fd, actual)\n    }\n    throw Fail.with(\"InvalidTransportOptions\", \"cannot listen on \" + host + \":\" + String(port))\n  }\n\n  /// Wait until a socket is readable (or writable): whether it is, within a timeout.\n  static func wait(_ fd: Int32, _ events: Int16, _ timeout: Int) -> Bool {\n    var entry = pollfd(fd: fd, events: events, revents: 0)\n    let n = poll(&entry, 1, Int32(timeout))\n    return n > 0\n  }\n\n  /// An accepted connection, or nil after a moment with none.\n  static func accept(_ fd: Int32) -> Int32? {\n    guard wait(fd, Int16(POLLIN), 100) else { return nil }\n    let client = Darwin.accept(fd, nil, nil)\n    if client < 0 { return nil }\n    noSignal(client)\n    return client\n  }\n\n  /// A connected socket, within a timeout.\n  static func connect(_ host: String, _ port: Int, _ timeout: Int) -> Int32? {\n    for (family, address) in resolve(host, port, passive: false) {\n      let fd = socket(family, SOCK_STREAM, 0)\n      if fd < 0 { continue }\n      noSignal(fd)\n      let flags = fcntl(fd, F_GETFL, 0)\n      _ = fcntl(fd, F_SETFL, flags | O_NONBLOCK)\n      let started = address.withUnsafeBytes { raw in\n        Darwin.connect(\n          fd, raw.baseAddress!.assumingMemoryBound(to: sockaddr.self), socklen_t(address.count))\n      }\n      var ok = started == 0\n      if !ok && errno == EINPROGRESS && wait(fd, Int16(POLLOUT), timeout) {\n        var error: Int32 = 0\n        var length = socklen_t(MemoryLayout<Int32>.size)\n        ok = getsockopt(fd, SOL_SOCKET, SO_ERROR, &error, &length) == 0 && error == 0\n      }\n      _ = fcntl(fd, F_SETFL, flags)\n      if ok { return fd }\n      close(fd)\n    }\n    return nil\n  }\n\n  /// Write every byte: whether it was written within the timeout.\n  static func write(_ fd: Int32, _ bytes: [UInt8], _ timeout: Int) -> Bool {\n    var sent = 0\n    while sent < bytes.count {\n      guard wait(fd, Int16(POLLOUT), timeout) else { return false }\n      let n = bytes.withUnsafeBytes { raw in\n        send(fd, raw.baseAddress! + sent, bytes.count - sent, 0)\n      }\n      if n <= 0 {\n        if n < 0 && (errno == EINTR || errno == EAGAIN) { continue }\n        return false\n      }\n      sent += n\n    }\n    return true\n  }\n\n  /// Up to count bytes, waiting while the stop check allows: nil at the end\n  /// of the stream, on an error or when stopped.\n  static func read(_ fd: Int32, _ count: Int, _ stop: () -> Bool) -> [UInt8]? {\n    while !stop() {\n      if !wait(fd, Int16(POLLIN), 100) { continue }\n      var buffer = [UInt8](repeating: 0, count: count)\n      let n = buffer.withUnsafeMutableBytes { raw in recv(fd, raw.baseAddress!, count, 0) }\n      if n > 0 { return Array(buffer[0..<n]) }\n      if n < 0 && (errno == EINTR || errno == EAGAIN) { continue }\n      return nil\n    }\n    return nil\n  }\n\n  /// Exactly count bytes, or nil.\n  static func readExactly(_ fd: Int32, _ count: Int, _ stop: () -> Bool) -> [UInt8]? {\n    var out = [UInt8]()\n    out.reserveCapacity(count)\n    while out.count < count {\n      guard let chunk = read(fd, min(65536, count - out.count), stop) else { return nil }\n      out += chunk\n    }\n    return out\n  }\n}\n\n/// An owned TCP or HTTP packet listener with per-peer writers that keep each\n/// peer's order without blocking the sender. Only the security layer opens\n/// these. ref:DEC-distribution-canonical-wire\npublic final class SocketTransport: @unchecked Sendable {\n  static let maxRecord = 67_108_864\n  static let ioTimeout = 5000\n\n  private final class Writer: @unchecked Sendable {\n    var queue: [[UInt8]] = []\n  }\n\n  private struct State {\n    var writers: [String: Writer] = [:]\n    var closed = false\n    var running = 0\n  }\n\n  private let kind: SocketKind\n  private let receive: @Sendable ([UInt8]) -> Void\n  private let listener: Int32\n  public let address: String\n  private let state = Locked(State())\n  private let signal = NSCondition()\n\n  public init(\n    _ kind: SocketKind, _ host: String, _ port: Int, _ advertise: String,\n    _ receive: @escaping @Sendable ([UInt8]) -> Void\n  ) throws {\n    try Fail.require(\n      port >= 0 && port <= 65535 && SocketProtocol.host(host) && SocketProtocol.host(advertise),\n      \"InvalidTransportOptions\")\n    self.kind = kind\n    self.receive = receive\n    let (fd, actual) = try Sockets.listen(host, port)\n    listener = fd\n    address = SocketProtocol.address(kind, advertise, actual)\n    work { [self] in acceptLoop() }\n  }\n\n  private var stopped: Bool { state.with { $0.closed } }\n\n  /// Run a worker the transport waits for when it closes.\n  private func work(_ body: @escaping @Sendable () -> Void) {\n    state.with { $0.running += 1 }\n    LawThread.start { [self] in\n      body()\n      state.with { $0.running -= 1 }\n    }\n  }\n\n  private func acceptLoop() {\n    while !stopped {\n      guard let client = Sockets.accept(listener) else { continue }\n      work { [self] in\n        if kind == .tcp { serveTcp(client) } else { serveHttp(client) }\n        Sockets.close(client)\n      }\n    }\n    Sockets.close(listener)\n  }\n\n  private func serveTcp(_ client: Int32) {\n    let stop = { [self] in stopped }\n    while !stopped {\n      guard let p = Sockets.readExactly(client, 4, stop) else { return }\n      let size = Int(p[0]) << 24 | Int(p[1]) << 16 | Int(p[2]) << 8 | Int(p[3])\n      if size > SocketTransport.maxRecord { return }\n      guard let body = Sockets.readExactly(client, size, stop) else { return }\n      receive(body)\n    }\n  }\n\n  private func serveHttp(_ client: Int32) {\n    let deadline = Date().addingTimeInterval(Double(SocketTransport.ioTimeout) / 1000)\n    let stop = { [self] in stopped || Date() >= deadline }\n    var acc = [UInt8]()\n    var head = SocketProtocol.Head.more\n    while head == .more {\n      guard let chunk = Sockets.read(client, 4096, stop) else { return }\n      acc += chunk\n      head = SocketProtocol.header(acc, SocketTransport.maxRecord)\n    }\n    switch head {\n    case .body(let size, let rest):\n      var body = rest\n      if body.count < size {\n        guard let tail = Sockets.readExactly(client, size - body.count, stop) else {\n          _ = Sockets.write(client, SocketProtocol.response(400), SocketTransport.ioTimeout)\n          return\n        }\n        body += tail\n      }\n      receive(Array(body.prefix(size)))\n      _ = Sockets.write(client, SocketProtocol.response(204), SocketTransport.ioTimeout)\n    case .failed(let code):\n      _ = Sockets.write(client, SocketProtocol.response(code), SocketTransport.ioTimeout)\n    case .more:\n      return\n    }\n  }\n\n  /// The next queued record for a peer, waiting up to a minute: nil when idle or closed.\n  private func next(_ peer: String, _ writer: Writer) -> [UInt8]? {\n    let idle = Date().addingTimeInterval(60)\n    signal.lock()\n    defer { signal.unlock() }\n    while true {\n      let item: [UInt8]?? = state.with { s in\n        if s.closed {\n          s.writers[peer] = nil\n          return .some(nil)\n        }\n        if !writer.queue.isEmpty { return .some(writer.queue.removeFirst()) }\n        if Date() >= idle {\n          s.writers[peer] = nil\n          return .some(nil)\n        }\n        return nil\n      }\n      if let answer = item { return answer }\n      _ = signal.wait(until: min(idle, Date().addingTimeInterval(0.2)))\n    }\n  }\n\n  private func writeTcp(_ peer: String, _ h: String, _ p: Int, _ writer: Writer) {\n    var client: Int32? = nil\n    defer { if let c = client { Sockets.close(c) } }\n    while let bytes = next(peer, writer) {\n      let n = bytes.count\n      let record =\n        [\n          UInt8(truncatingIfNeeded: n >> 24), UInt8(truncatingIfNeeded: n >> 16),\n          UInt8(truncatingIfNeeded: n >> 8), UInt8(truncatingIfNeeded: n),\n        ] + bytes\n      var attempts = 2\n      while attempts > 0 {\n        if client == nil { client = Sockets.connect(h, p, SocketTransport.ioTimeout) }\n        if let c = client, Sockets.write(c, record, SocketTransport.ioTimeout) {\n          attempts = 0\n        } else {\n          if let c = client { Sockets.close(c) }\n          client = nil\n          attempts -= 1\n        }\n      }\n    }\n  }\n\n  private func writeHttp(_ peer: String, _ h: String, _ p: Int, _ writer: Writer) {\n    while let bytes = next(peer, writer) {\n      guard let client = Sockets.connect(h, p, SocketTransport.ioTimeout) else { continue }\n      defer { Sockets.close(client) }\n      guard Sockets.write(client, SocketProtocol.request(peer, bytes), SocketTransport.ioTimeout)\n      else { continue }\n      let deadline = Date().addingTimeInterval(Double(SocketTransport.ioTimeout) / 1000)\n      let stop = { [self] in stopped || Date() >= deadline }\n      var acc = [UInt8]()\n      while SocketProtocol.reply(acc) == nil {\n        guard let chunk = Sockets.read(client, 4096, stop) else { break }\n        acc += chunk\n      }\n    }\n  }\n\n  /// Queue bytes for a peer; its writer connects and sends in order. Nil,\n  /// or why it was not queued.\n  public func send(_ peer: String, _ bytes: [UInt8]) -> String? {\n    if bytes.count > SocketTransport.maxRecord { return \"record_too_large\" }\n    guard let (h, p) = SocketProtocol.endpoint(kind, peer) else { return \"invalid_peer_address\" }\n    signal.lock()\n    defer { signal.unlock() }\n    let outcome: (String?, Writer?) = state.with { s in\n      if s.closed { return (\"transport_closed\", nil) }\n      if let writer = s.writers[peer] {\n        if writer.queue.count >= 1024 { return (\"transport_queue_full\", nil) }\n        writer.queue.append(bytes)\n        return (nil, nil)\n      }\n      if s.writers.count >= 512 { return (\"transport_busy\", nil) }\n      let writer = Writer()\n      writer.queue.append(bytes)\n      s.writers[peer] = writer\n      return (nil, writer)\n    }\n    if let writer = outcome.1 {\n      let tcp = kind == .tcp\n      work { [self] in\n        if tcp { writeTcp(peer, h, p, writer) } else { writeHttp(peer, h, p, writer) }\n      }\n    }\n    signal.broadcast()\n    return outcome.0\n  }\n\n  public func close() {\n    state.with { $0.closed = true }\n    signal.lock()\n    signal.broadcast()\n    signal.unlock()\n    let deadline = Date().addingTimeInterval(5)\n    while state.with({ $0.running }) > 0 && Date() < deadline { usleep(5000) }\n  }\n}\n"
swiftSource "LawSpecRuntime/SortedCollections.swift" = "// Persistent sorted collections for LawSpec's Set and KeyVal: balanced trees\n// whose nodes are shared, never copied, between a collection and the ones\n// made from it, kept in LawSpec's portable order of their keys, so iteration\n// is the order every target observes. ref:DEC-typed-native-definitions\n// ref:DEC-swift-runtime-from-scratch\n\n/// A node of an AVL tree. Nodes never change once made.\n@usableFromInline final class SortedNode<Key: Portable, Element>: @unchecked Sendable {\n  @usableFromInline let key: Key\n  @usableFromInline let element: Element\n  @usableFromInline let left: SortedNode?\n  @usableFromInline let right: SortedNode?\n  @usableFromInline let height: Int\n  @usableFromInline let count: Int\n\n  @usableFromInline init(_ key: Key, _ element: Element, _ left: SortedNode?, _ right: SortedNode?)\n  {\n    self.key = key\n    self.element = element\n    self.left = left\n    self.right = right\n    self.height = Swift.max(left?.height ?? 0, right?.height ?? 0) + 1\n    self.count = (left?.count ?? 0) + (right?.count ?? 0) + 1\n  }\n}\n\n/// The tree operations both collections share.\n@usableFromInline enum SortedTree {\n  typealias Node<K: Portable, E> = SortedNode<K, E>\n\n  static func height<K, E>(_ n: Node<K, E>?) -> Int { n?.height ?? 0 }\n\n  static func balance<K, E>(_ key: K, _ element: E, _ left: Node<K, E>?, _ right: Node<K, E>?)\n    -> Node<K, E>\n  {\n    let hl = height(left)\n    let hr = height(right)\n    if hl > hr + 1, let l = left {\n      if height(l.left) >= height(l.right) {\n        return Node(l.key, l.element, l.left, Node(key, element, l.right, right))\n      }\n      let lr = l.right!\n      return Node(\n        lr.key, lr.element, Node(l.key, l.element, l.left, lr.left),\n        Node(key, element, lr.right, right))\n    }\n    if hr > hl + 1, let r = right {\n      if height(r.right) >= height(r.left) {\n        return Node(r.key, r.element, Node(key, element, left, r.left), r.right)\n      }\n      let rl = r.left!\n      return Node(\n        rl.key, rl.element, Node(key, element, left, rl.left),\n        Node(r.key, r.element, rl.right, r.right))\n    }\n    return Node(key, element, left, right)\n  }\n\n  static func insert<K, E>(_ node: Node<K, E>?, _ key: K, _ element: E) -> Node<K, E> {\n    guard let n = node else { return Node(key, element, nil, nil) }\n    let c = K.portableCompare(key, n.key)\n    if c < 0 { return balance(n.key, n.element, insert(n.left, key, element), n.right) }\n    if c > 0 { return balance(n.key, n.element, n.left, insert(n.right, key, element)) }\n    return Node(key, element, n.left, n.right)\n  }\n\n  static func removeMinimum<K, E>(_ n: Node<K, E>) -> (Node<K, E>?, Node<K, E>) {\n    guard let l = n.left else { return (n.right, n) }\n    let (rest, minimum) = removeMinimum(l)\n    return (balance(n.key, n.element, rest, n.right), minimum)\n  }\n\n  static func remove<K, E>(_ node: Node<K, E>?, _ key: K) -> Node<K, E>? {\n    guard let n = node else { return nil }\n    let c = K.portableCompare(key, n.key)\n    if c < 0 { return balance(n.key, n.element, remove(n.left, key), n.right) }\n    if c > 0 { return balance(n.key, n.element, n.left, remove(n.right, key)) }\n    guard let r = n.right else { return n.left }\n    guard n.left != nil else { return r }\n    let (rest, minimum) = removeMinimum(r)\n    return balance(minimum.key, minimum.element, n.left, rest)\n  }\n\n  static func find<K, E>(_ node: Node<K, E>?, _ key: K) -> Node<K, E>? {\n    var current = node\n    while let n = current {\n      let c = K.portableCompare(key, n.key)\n      if c == 0 { return n }\n      current = c < 0 ? n.left : n.right\n    }\n    return nil\n  }\n\n  static func inOrder<K, E>(_ node: Node<K, E>?, _ visit: (Node<K, E>) -> Void) {\n    guard let n = node else { return }\n    inOrder(n.left, visit)\n    visit(n)\n    inOrder(n.right, visit)\n  }\n\n  static func nodes<K, E>(_ node: Node<K, E>?) -> [Node<K, E>] {\n    var result = [Node<K, E>]()\n    result.reserveCapacity(node?.count ?? 0)\n    inOrder(node) { result.append($0) }\n    return result\n  }\n}\n\n/// LawSpec's Set: distinct items in their portable order. Adding or removing\n/// an item makes a new set that shares the rest.\npublic struct SortedSet<Element: Portable>: Sendable, Sequence, ExpressibleByArrayLiteral,\n  CustomStringConvertible\n{\n  @usableFromInline let root: SortedNode<Element, Unit>?\n\n  @usableFromInline init(root: SortedNode<Element, Unit>?) { self.root = root }\n\n  public init() { root = nil }\n\n  /// The set of a sequence's items.\n  public init<S: Sequence>(_ items: S) where S.Element == Element {\n    var node: SortedNode<Element, Unit>? = nil\n    for item in items { node = SortedTree.insert(node, item, Unit()) }\n    root = node\n  }\n\n  public init(arrayLiteral items: Element...) { self.init(items) }\n\n  public var count: Int { root?.count ?? 0 }\n  public var isEmpty: Bool { root == nil }\n\n  public func contains(_ item: Element) -> Bool { SortedTree.find(root, item) != nil }\n  public func inserting(_ item: Element) -> SortedSet {\n    SortedSet(root: SortedTree.insert(root, item, Unit()))\n  }\n  public func removing(_ item: Element) -> SortedSet {\n    SortedSet(root: SortedTree.remove(root, item))\n  }\n\n  public func union(_ other: SortedSet) -> SortedSet {\n    var node = root\n    for item in other { node = SortedTree.insert(node, item, Unit()) }\n    return SortedSet(root: node)\n  }\n  public func intersection(_ other: SortedSet) -> SortedSet {\n    SortedSet(filter { other.contains($0) })\n  }\n  public func subtracting(_ other: SortedSet) -> SortedSet {\n    var node = root\n    for item in other { node = SortedTree.remove(node, item) }\n    return SortedSet(root: node)\n  }\n\n  /// The items in their portable order.\n  public var items: [Element] { SortedTree.nodes(root).map { $0.key } }\n\n  public func makeIterator() -> IndexingIterator<[Element]> { items.makeIterator() }\n\n  public var description: String { \"[\" + items.map { \"\\($0)\" }.joined(separator: \", \") + \"]\" }\n}\n\nextension SortedSet: Portable {\n  public static func portableEqual(_ a: SortedSet, _ b: SortedSet) -> Bool {\n    [Element].portableEqual(a.items, b.items)\n  }\n  public static func portableCompare(_ a: SortedSet, _ b: SortedSet) -> Int {\n    [Element].portableCompare(a.items, b.items)\n  }\n  public func portableHash(into hasher: inout Hasher) { items.portableHash(into: &hasher) }\n}\n\nextension SortedSet: Equatable, Hashable {\n  public static func == (a: SortedSet, b: SortedSet) -> Bool { portableEqual(a, b) }\n  public func hash(into hasher: inout Hasher) { portableHash(into: &hasher) }\n}\n\n/// LawSpec's KeyVal: distinct keys in their portable order, each with a\n/// value. Putting or deleting a key makes a new map that shares the rest.\npublic struct SortedMap<Key: Portable, Value>: Sequence, ExpressibleByDictionaryLiteral,\n  CustomStringConvertible\n{\n  @usableFromInline let root: SortedNode<Key, Value>?\n\n  @usableFromInline init(root: SortedNode<Key, Value>?) { self.root = root }\n\n  public init() { root = nil }\n\n  /// The map of entries; a later entry's value wins.\n  public init<S: Sequence>(_ entries: S) where S.Element == (Key, Value) {\n    var node: SortedNode<Key, Value>? = nil\n    for (key, value) in entries { node = SortedTree.insert(node, key, value) }\n    root = node\n  }\n\n  public init(dictionaryLiteral entries: (Key, Value)...) { self.init(entries) }\n\n  public var count: Int { root?.count ?? 0 }\n  public var isEmpty: Bool { root == nil }\n\n  public subscript(key: Key) -> Value? { SortedTree.find(root, key)?.element }\n  public func contains(_ key: Key) -> Bool { SortedTree.find(root, key) != nil }\n  public func putting(_ key: Key, _ value: Value) -> SortedMap {\n    SortedMap(root: SortedTree.insert(root, key, value))\n  }\n  public func removing(_ key: Key) -> SortedMap { SortedMap(root: SortedTree.remove(root, key)) }\n\n  /// The entries in their keys' portable order.\n  public var entries: [(key: Key, value: Value)] {\n    SortedTree.nodes(root).map { (key: $0.key, value: $0.element) }\n  }\n  public var keys: [Key] { SortedTree.nodes(root).map { $0.key } }\n  public var values: [Value] { SortedTree.nodes(root).map { $0.element } }\n\n  public func makeIterator() -> IndexingIterator<[(key: Key, value: Value)]> {\n    entries.makeIterator()\n  }\n\n  public var description: String {\n    \"[\" + entries.map { \"\\($0.key): \\($0.value)\" }.joined(separator: \", \") + \"]\"\n  }\n}\n\nextension SortedMap: @unchecked Sendable where Value: Sendable {}\n\nextension SortedMap: Portable where Value: Portable {\n  public static func portableEqual(_ a: SortedMap, _ b: SortedMap) -> Bool {\n    a.count == b.count\n      && zip(a.entries, b.entries).allSatisfy {\n        Key.portableEqual($0.key, $1.key) && Value.portableEqual($0.value, $1.value)\n      }\n  }\n  public static func portableCompare(_ a: SortedMap, _ b: SortedMap) -> Int {\n    for (x, y) in zip(a.entries, b.entries) {\n      let k = Key.portableCompare(x.key, y.key)\n      if k != 0 { return k }\n      let v = Value.portableCompare(x.value, y.value)\n      if v != 0 { return v }\n    }\n    return order(a.count, b.count)\n  }\n  public func portableHash(into hasher: inout Hasher) {\n    hasher.combine(count)\n    for (key, value) in entries {\n      key.portableHash(into: &hasher)\n      value.portableHash(into: &hasher)\n    }\n  }\n}\n\nextension SortedMap: Equatable, Hashable where Value: Portable {\n  public static func == (a: SortedMap, b: SortedMap) -> Bool { portableEqual(a, b) }\n  public func hash(into hasher: inout Hasher) { portableHash(into: &hasher) }\n}\n"
swiftSource "LawSpecRuntime/Tasks.swift" = "// Cancellation scopes: a scope owns the work started beneath it, including\n// nested scopes, and closing it cancels that work. A running thread cannot\n// be killed, so cancellation is cooperative: work observes its scope, and a\n// closed scope never waits for work that ignores it. Ambient context (the\n// workflow runtime, the current scope) follows work onto the runtime's\n// threads. ref:DEC-async-native-tasks ref:DEC-typed-core-boundary\n\nimport Foundation\n\n/// Values each runtime thread sees, copied to the threads it starts.\npublic enum Ambient {\n  private static let key = \"lawspec.ambient\"\n\n  private final class Box {\n    var values: [String: Any]\n    init(_ values: [String: Any]) { self.values = values }\n  }\n\n  private static var box: Box {\n    if let found = Thread.current.threadDictionary[key] as? Box { return found }\n    let made = Box([:])\n    Thread.current.threadDictionary[key] = made\n    return made\n  }\n\n  public static func get(_ name: String) -> Any? { box.values[name] }\n\n  public static func set(_ name: String, _ value: Any?) { box.values[name] = value }\n\n  /// This thread's values, to give another thread.\n  public static func capture() -> [String: Any] { box.values }\n\n  /// Take another thread's values.\n  public static func restore(_ values: [String: Any]) { box.values = values }\n\n  /// Run a body with a value set, restoring the previous one after.\n  public static func with<T>(_ name: String, _ value: Any?, _ body: () throws -> T) rethrows -> T {\n    let previous = get(name)\n    set(name, value)\n    defer { set(name, previous) }\n    return try body()\n  }\n}\n\npublic enum Tasks {\n  /// A cancellation scope.\n  public final class Scope: @unchecked Sendable {\n    public let parent: Scope?\n    private var closed = false\n    private let gate = NSLock()\n\n    init(parent: Scope?) { self.parent = parent }\n\n    /// Whether this scope, or one around it, was closed.\n    public var isClosed: Bool {\n      gate.lock()\n      let mine = closed\n      gate.unlock()\n      return mine || (parent?.isClosed ?? false)\n    }\n\n    /// Cancel everything the scope owns.\n    public func close() {\n      gate.lock()\n      closed = true\n      gate.unlock()\n    }\n  }\n\n  private static let currentKey = \"lawspec.tasks.scope\"\n\n  /// The innermost scope, or nil outside any.\n  public static func currentScope() -> Scope? { Ambient.get(currentKey) as? Scope }\n\n  /// Run a body in a new scope, closing it (and cancelling its work) after.\n  public static func withScope<T>(_ body: (Scope) throws -> T) rethrows -> T {\n    let scope = Scope(parent: currentScope())\n    defer { scope.close() }\n    return try Ambient.with(currentKey, scope) { try body(scope) }\n  }\n\n  /// Fail if the current scope was closed.\n  public static func check() throws {\n    if currentScope()?.isClosed ?? false {\n      throw Fail.with(\"Cancelled\", \"the work's scope was closed\")\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Transport.swift" = "// Where a node listens: an in-memory network (optionally without the secure\n// layer, for tests only), or a TCP or HTTP listener on a host and port,\n// advertised under a host name.\n// ref:DEC-distribution-canonical-wire\n\n/// A transport to open.\npublic enum Transport: @unchecked Sendable {\n  case memory(network: MemoryNetwork, name: String, insecureForTests: Bool)\n  case socket(kind: SocketKind, host: String, port: Int, advertise: String)\n}\n\n/// An open packet transport: its address, and sending bytes to a peer node\n/// (nil, or why it failed).\nprotocol PacketTransport: AnyObject, Sendable {\n  var address: String { get }\n  func send(_ peer: String, _ bytes: [UInt8]) -> String?\n  func close()\n}\n\nprivate final class MemoryPacketTransport: PacketTransport, @unchecked Sendable {\n  let network: MemoryNetwork\n  let address: String\n\n  init(_ network: MemoryNetwork, _ address: String) {\n    self.network = network\n    self.address = address\n  }\n\n  func send(_ peer: String, _ bytes: [UInt8]) -> String? {\n    do { return try network.send(address, peer, bytes) } catch { return \"transport_closed\" }\n  }\n\n  func close() { network.unregister(address) }\n}\n\nextension SocketTransport: PacketTransport {}\n\npublic enum Transports {\n  /// A memory transport, registered as a name on a network.\n  public static func memory(_ network: MemoryNetwork, _ name: String) -> Transport {\n    .memory(network: network, name: name, insecureForTests: false)\n  }\n\n  /// A memory transport that skips the secure layer; for tests only.\n  public static func insecureMemoryForTests(_ network: MemoryNetwork, _ name: String) -> Transport {\n    .memory(network: network, name: name, insecureForTests: true)\n  }\n\n  public static func tcp(_ host: String, _ port: Int) -> Transport {\n    .socket(kind: .tcp, host: host, port: port, advertise: host)\n  }\n\n  public static func http(_ host: String, _ port: Int) -> Transport {\n    .socket(kind: .http, host: host, port: port, advertise: host)\n  }\n\n  /// A socket transport advertised under another host name.\n  public static func advertise(_ transport: Transport, _ host: String) throws -> Transport {\n    guard case .socket(let kind, let h, let p, _) = transport else {\n      throw Fail.with(\"InvalidTransportOptions\", \"only a socket transport is advertised\")\n    }\n    return .socket(kind: kind, host: h, port: p, advertise: host)\n  }\n\n  /// Open a transport for a receiver of each packet's source and bytes.\n  static func open(_ transport: Transport, _ receive: @escaping PacketReceiver) throws\n    -> any PacketTransport\n  {\n    switch transport {\n    case .memory(let network, let name, _):\n      let address = try MemoryNetwork.addressOf(name)\n      if let reason = try network.register(address, receive) {\n        throw Fail.with(\"TransportRegistration\", reason)\n      }\n      return MemoryPacketTransport(network, address)\n    case .socket(let kind, let host, let port, let advertise):\n      return try SocketTransport(kind, host, port, advertise) { bytes in receive(\"unknown\", bytes) }\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Typed.swift" = "// What typed definitions use: LawSpec's integer semantics on Swift's native\n// integers (checked, failing as the dynamic code does), text by code point,\n// and the sequence and collection helpers, over the native types the\n// generated code already uses (arrays, optionals, SortedMap and SortedSet),\n// so a typed definition never copies a value to call another.\n// ref:DEC-typed-native-definitions ref:DEC-portable-exact-arithmetic\n\npublic enum Typed {\n  /// An integer outside its type, as the dynamic code reports it.\n  public static func outOfRange(_ name: String, _ value: BigInt) -> LawSpecError {\n    Fail.with(\"IntegerOutOfRange\", \"\\(name) \\(value)\")\n  }\n\n  /// A branch the checker proved unreachable.\n  public static func unreachable<T>() throws -> T {\n    throw Fail.with(\"Unreachable\", \"unreachable branch reached\")\n  }\n\n  /// The failure a branch the checker proved unreachable raises.\n  public static func unreachableFailure() -> LawSpecError {\n    Fail.with(\"Unreachable\", \"unreachable branch reached\")\n  }\n\n  /// A failure the typed code raises: the same error the dynamic code raises.\n  public static func raiseFailure<T>(_ ability: String, _ failure: Value) throws -> T {\n    throw RaisedFailure(ability, failure)\n  }\n\n  /// An exact result narrowed to a bounded type, failing outside it.\n  public static func narrow<T: FixedWidthInteger>(\n    _ name: String, _ value: BigInt, _ type: T.Type = T.self\n  ) throws -> T {\n    guard let n = value.exactly(T.self) else { throw outOfRange(name, value) }\n    return n\n  }\n\n  /// A bounded native integer, exactly.\n  public static func exact<T: BinaryInteger>(_ value: T) -> BigInt { BigInt(value) }\n\n  /// Checked addition on one bounded type: an overflow is the same failure.\n  public static func add<T: FixedWidthInteger>(_ name: String, _ a: T, _ b: T) throws -> T {\n    let (r, overflow) = a.addingReportingOverflow(b)\n    if overflow { throw outOfRange(name, BigInt(a) + BigInt(b)) }\n    return r\n  }\n\n  public static func subtract<T: FixedWidthInteger>(_ name: String, _ a: T, _ b: T) throws -> T {\n    let (r, overflow) = a.subtractingReportingOverflow(b)\n    if overflow { throw outOfRange(name, BigInt(a) - BigInt(b)) }\n    return r\n  }\n\n  public static func multiply<T: FixedWidthInteger>(_ name: String, _ a: T, _ b: T) throws -> T {\n    let (r, overflow) = a.multipliedReportingOverflow(by: b)\n    if overflow { throw outOfRange(name, BigInt(a) * BigInt(b)) }\n    return r\n  }\n\n  /// Exact quotient, truncated towards zero; dividing by zero fails.\n  public static func quotient(_ a: BigInt, _ b: BigInt) throws -> BigInt {\n    if b.isZero { throw Fail.with(\"InvalidExactOperation\", \"quot\") }\n    return a / b\n  }\n\n  /// Exact remainder, with the dividend's sign; dividing by zero fails.\n  public static func remainder(_ a: BigInt, _ b: BigInt) throws -> BigInt {\n    if b.isZero { throw Fail.with(\"InvalidExactOperation\", \"rem\") }\n    return a % b\n  }\n\n  public static func power(_ a: BigInt, _ b: BigInt) throws -> BigInt {\n    guard !b.isNegative, let e = b.exactly(Int32.self) else {\n      throw Fail.with(\"InvalidExactOperation\", \"pow\")\n    }\n    return a.power(Int(e))\n  }\n\n  /// LawSpec's equality of two native values.\n  public static func equal<T: Portable>(_ a: T, _ b: T) -> Bool { T.portableEqual(a, b) }\n\n  /// The portable order of two native values: text by code point.\n  public static func compare<T: Portable>(_ a: T, _ b: T) -> Int { T.portableCompare(a, b) }\n\n  // MARK: Text, by code point\n\n  public static func textLength(_ s: String) -> BigInt { BigInt(s.unicodeScalars.count) }\n\n  private static func clamp(_ value: BigInt, _ lo: Int, _ hi: Int) -> Int {\n    if value < BigInt(lo) { return lo }\n    if value > BigInt(hi) { return hi }\n    return value.exactly(Int.self)!\n  }\n\n  private static func window(_ from: BigInt, _ until: BigInt, _ count: Int) -> (Int, Int) {\n    let i = clamp(from, 0, count)\n    return (i, clamp(until, i, count))\n  }\n\n  public static func sliceText(_ s: String, _ from: BigInt, _ until: BigInt) -> String {\n    let scalars = Array(s.unicodeScalars)\n    let (i, j) = window(from, until, scalars.count)\n    var view = String.UnicodeScalarView()\n    view.append(contentsOf: scalars[i..<j])\n    return String(view)\n  }\n\n  public static func sliceBytes(_ s: [UInt8], _ from: BigInt, _ until: BigInt) -> [UInt8] {\n    let (i, j) = window(from, until, s.count)\n    return Array(s[i..<j])\n  }\n\n  public static func sliceList<T>(_ xs: PersistentList<T>, _ from: BigInt, _ until: BigInt)\n    -> PersistentList<T>\n  {\n    let (i, j) = window(from, until, xs.count)\n    return xs.slice(i, j)\n  }\n\n  public static func atList<T>(_ xs: PersistentList<T>, _ i: BigInt) -> T? {\n    guard !i.isNegative, let k = i.exactly(Int.self) else { return nil }\n    return xs.item(at: k)\n  }\n\n  public static func atBytes(_ xs: [UInt8], _ i: BigInt) -> UInt8? {\n    guard !i.isNegative, let k = i.exactly(Int.self), k < xs.count else { return nil }\n    return xs[k]\n  }\n\n  /// lo, lo + 1, ..., hi - 1.\n  public static func range(_ lo: BigInt, _ hi: BigInt) -> PersistentList<BigInt> {\n    var result = [BigInt]()\n    var n = lo\n    while n < hi {\n      result.append(n)\n      n += .one\n    }\n    return PersistentList(result)\n  }\n\n  public static func utf8(_ s: String) -> [UInt8] { Array(s.utf8) }\n  public static func textOf(_ n: BigInt) -> String { n.description }\n  public static func join(_ separator: String, _ parts: PersistentList<String>) -> String {\n    parts.joined(separator: separator)\n  }\n\n  public static func startsWith(_ text: String, _ prefix: String) -> Bool {\n    text.unicodeScalars.starts(with: prefix.unicodeScalars)\n  }\n  public static func endsWith(_ text: String, _ suffix: String) -> Bool {\n    text.unicodeScalars.reversed().starts(with: suffix.unicodeScalars.reversed())\n  }\n\n  /// Whether a text holds a part, code point by code point.\n  public static func contains(_ text: String, _ part: String) -> Bool {\n    let t = Array(text.unicodeScalars.map { $0.value })\n    let p = Array(part.unicodeScalars.map { $0.value })\n    if p.isEmpty { return true }\n    if p.count > t.count { return false }\n    for i in 0...(t.count - p.count) where Array(t[i..<(i + p.count)]) == p { return true }\n    return false\n  }\n\n  // MARK: Collections\n\n  public static func keyValOf<E, K: Portable, V>(\n    _ key: (E) -> K, _ value: (E) -> V, _ entries: PersistentList<E>\n  ) -> SortedMap<K, V> {\n    SortedMap(entries.map { (key($0), value($0)) })\n  }\n\n  /// A Set's items in the portable order.\n  public static func items<T>(_ s: SortedSet<T>) -> PersistentList<T> { PersistentList(s.items) }\n  public static func keys<K, V>(_ m: SortedMap<K, V>) -> PersistentList<K> {\n    PersistentList(m.keys)\n  }\n  public static func values<K, V>(_ m: SortedMap<K, V>) -> PersistentList<V> {\n    PersistentList(m.values)\n  }\n  public static func entries<K, V, E>(_ entry: (K, V) -> E, _ m: SortedMap<K, V>) -> PersistentList<\n    E\n  > { PersistentList(m.entries.map { entry($0.key, $0.value) }) }\n\n  // MARK: Failures across the typed boundary\n\n  /// attempt: right of the body's value, or left of the failure raised with\n  /// this ability, converted to its native type.\n  public static func attempt<E, A>(\n    _ ability: String, _ failure: (Value) throws -> E, _ body: () throws -> A\n  ) throws -> Either<E, A> {\n    do {\n      return .right(try body())\n    } catch let raised as RaisedFailure where raised.ability == ability {\n      return .left(try failure(raised.failure))\n    }\n  }\n\n  /// An operation's typed throw, raised as the failure the dynamic code raises.\n  public static func performed<A, E: Error>(\n    _ ability: String, _ failure: (E) throws -> Value, _ body: () throws(E) -> A\n  ) throws -> A {\n    do {\n      return try body()\n    } catch {\n      throw RaisedFailure(ability, try failure(error))\n    }\n  }\n}\n"
swiftSource "LawSpecRuntime/Values.swift" = "// LawSpec's portable values, as the generated laws and the dynamic\n// definitions see them. Native Swift code never handles these directly:\n// generated codecs convert at the boundary to structs, enums and the Swift\n// types the adapters use. ref:DEC-swift-runtime-from-scratch\n// ref:DEC-typed-core-boundary\n\n/// A symbol's identity: two symbols are equal when they share one.\npublic final class SymbolIdentity: Sendable {\n  public init() {}\n}\n\n/// A handle's native value, compared by identity.\npublic struct HandleIdentity: @unchecked Sendable {\n  /// The native object; a handle crosses the boundary unchanged.\n  public let object: AnyObject\n  public init(_ object: AnyObject) { self.object = object }\n  public static func same(_ a: HandleIdentity, _ b: HandleIdentity) -> Bool {\n    a.object === b.object\n  }\n}\n\n/// A value in LawSpec's portable domain. Exact numbers stay exact, IEEE\n/// values keep their bits (so a NaN payload and a negative zero survive), and\n/// data is a constructor tag with its fields in declaration order.\npublic indirect enum Value: Sendable, CustomStringConvertible {\n  case bool(Bool)\n  case int(BigInt)\n  /// A normalized fraction: positive denominator, lowest terms.\n  case ratio(BigInt, BigInt)\n  /// coefficient * 10 ^ exponent, with the scale it was written with.\n  case decimal(BigInt, Int)\n  case float(width: Int, bits: UInt64)\n  case complex(width: Int, real: Value, imaginary: Value)\n  /// Unicode text; it never holds a lone surrogate.\n  case text(String)\n  case bytes([UInt8])\n  /// CodePointText and Utf16Text: their units, without validation as text.\n  case raw(kind: String, units: [Int])\n  case unit\n  case null\n  case undefined\n  /// Two symbols are equal when they share an identity.\n  case symbol(SymbolIdentity, String)\n  case list([Value])\n  case data(String, [Value])\n  /// Nullable or Optional: absent, or present with a value.\n  case presence(kind: String, value: Value?)\n  /// A handle's identity crosses the native boundary unchanged.\n  case handle(String, HandleIdentity)\n\n  public var description: String { Recorded.debug(self) }\n}\n\n/// A type as the runtime checks it: a name applied to arguments, or a data\n/// declaration's parameter by position.\npublic indirect enum TypeRef: Sendable, Hashable, CustomStringConvertible {\n  case named(String, [TypeRef])\n  case parameter(Int)\n\n  public var description: String { Scalar.typeKey(self) }\n}\n\n/// A broken contract, an unmet law or a malformed value. The code names the\n/// kind of failure (StrategyOutsideRefinement, EquationFailed, ...), so test\n/// output names it the same way on every target.\npublic struct LawSpecError: Error, Sendable, CustomStringConvertible {\n  public let code: String\n  public let detail: String\n  /// The definitions and laws it happened in, innermost first.\n  public let context: [String]\n  /// The failure that caused this one, if any.\n  public let cause: String?\n\n  public init(_ code: String, _ detail: String = \"\", context: [String] = [], cause: String? = nil) {\n    self.code = code\n    self.detail = detail\n    self.context = context\n    self.cause = cause\n  }\n\n  /// The same failure, inside one more definition or law.\n  public func within(_ identity: String) -> LawSpecError {\n    LawSpecError(code, detail, context: [identity] + context, cause: cause)\n  }\n\n  public var description: String {\n    let prefix = context.isEmpty ? \"\" : context.reversed().joined(separator: \": \") + \": \"\n    return prefix + code + (detail.isEmpty ? \"\" : \" \" + detail)\n  }\n}\n\n/// A failure an operation raised with `raise`, carrying its portable value\n/// until an `attempt` catches it. ref:DEC-typed-native-definitions\npublic struct RaisedFailure: Error, Sendable, CustomStringConvertible {\n  public let ability: String\n  public let failure: Value\n  public init(_ ability: String, _ failure: Value) {\n    self.ability = ability\n    self.failure = failure\n  }\n  public var description: String {\n    \"LawSpec failure raised by \\(ability): \\(Recorded.debug(failure))\"\n  }\n}\n\n/// Helpers for raising LawSpec's failures.\npublic enum Fail {\n  /// A LawSpec failure with a code and detail.\n  public static func with(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    LawSpecError(code, detail)\n  }\n\n  /// Fail unless the condition holds.\n  public static func require(_ condition: Bool, _ code: String, _ detail: String = \"\") throws {\n    if !condition { throw LawSpecError(code, detail) }\n  }\n\n  /// Any error as the failure a law reports: LawSpec's own pass unchanged.\n  public static func describe(_ error: any Error) -> String {\n    String(describing: error)\n  }\n}\n"
swiftSource "LawSpecRuntime/Wire.swift" = "// The distribution frame format every target shares: kind, destination,\n// source, request identity and payload, each in the canonical descriptor\n// encoding, so a node on one target talks to a node on another. A received\n// frame never names anything it did not carry.\n// ref:DEC-distribution-canonical-wire\n\nimport Foundation\n\n/// A frame: its kind (\"call\", \"chan\", \"reply\", ...), the entity it is for\n/// (on send, a full address; on the wire, the name at the peer), the source\n/// node's address, the request identity (0 for none) and the payload.\npublic struct Frame: Sendable, Equatable {\n  public var kind: String\n  public var to: String\n  public var source: String\n  public var id: UInt64\n  public var payload: [UInt8]\n\n  public init(kind: String, to: String, source: String, id: UInt64, payload: [UInt8]) {\n    self.kind = kind\n    self.to = to\n    self.source = source\n    self.id = id\n    self.payload = payload\n  }\n}\n\npublic enum Wire {\n  public typealias Descriptor = Descriptors.Descriptor\n\n  private static func atom(_ name: String) -> Descriptor { .forms([.atom(name)]) }\n  static let textType = atom(\"text\")\n  static let bytesType = atom(\"bytes\")\n  static let identityType: Descriptor = .forms([\n    .atom(\"int\"), .atom(\"UInt64\"), .number(.zero), .number(BigInt(UInt64.max)),\n  ])\n  static let sequenceType: Descriptor = .forms([\n    .atom(\"int\"), .atom(\"Int64\"), .number(BigInt(Int64.min)), .number(BigInt(Int64.max)),\n  ])\n\n  /// A frame to send: the source and identity are filled in by the node.\n  public static func frameTo(_ address: String, _ kind: String, _ payload: [UInt8]) -> Frame {\n    Frame(kind: kind, to: address, source: \"\", id: 0, payload: payload)\n  }\n\n  /// The concatenated canonical encodings of values at their descriptors.\n  public static func fields(_ types: [Descriptor], _ values: [Value]) throws -> [UInt8] {\n    try Fail.require(types.count == values.count, \"WireFieldCount\")\n    var out = [UInt8]()\n    for (d, v) in zip(types, values) { out += try Descriptors.encode(d, v, [:]) }\n    return out\n  }\n\n  /// Values read in turn from a position, and the position after them.\n  public static func readFields(_ types: [Descriptor], _ bytes: [UInt8], _ start: Int) throws -> (\n    [Value], Int\n  ) {\n    var position = start\n    var values = [Value]()\n    for d in types {\n      let (v, next) = try Descriptors.decodePrefix(d, bytes, position, [:])\n      values.append(v)\n      position = next\n    }\n    return (values, position)\n  }\n\n  static func text(_ v: Value) throws -> String {\n    guard case .text(let s) = v else { throw Fail.with(\"InvalidFrame\") }\n    return s\n  }\n\n  static func bytesOf(_ v: Value) throws -> [UInt8] {\n    guard case .bytes(let b) = v else { throw Fail.with(\"InvalidFrame\") }\n    return b\n  }\n\n  /// A frame's bytes.\n  public static func encode(\n    _ kind: String, _ to: String, _ source: String, _ identity: UInt64, _ payload: [UInt8]\n  ) throws -> [UInt8] {\n    try fields(\n      [textType, textType, textType, identityType, bytesType],\n      [.text(kind), .text(to), .text(source), .int(BigInt(identity)), .bytes(payload)])\n  }\n\n  /// A frame from exactly its bytes, or nil when they are not one.\n  public static func read(_ bytes: [UInt8]) -> Frame? {\n    guard\n      let (values, next) = try? readFields(\n        [textType, textType, textType, identityType, bytesType], bytes, 0),\n      next == bytes.count, values.count == 5,\n      case .text(let kind) = values[0], case .text(let to) = values[1],\n      case .text(let source) = values[2],\n      case .int(let identity) = values[3], let id = identity.exactly(UInt64.self),\n      case .bytes(let payload) = values[4]\n    else { return nil }\n    return Frame(kind: kind, to: to, source: source, id: id, payload: payload)\n  }\n\n  /// A channel payload: sequence number, sender address, body.\n  public static func channel(_ sequence: Int64, _ sender: String, _ body: [UInt8]) throws -> [UInt8]\n  {\n    try fields([sequenceType, textType], [.int(BigInt(sequence)), .text(sender)]) + body\n  }\n\n  public static func readChannel(_ bytes: [UInt8]) throws -> (Int64, String, [UInt8]) {\n    let (values, next) = try readFields([sequenceType, textType], bytes, 0)\n    guard case .int(let sequence) = values[0], let n = sequence.exactly(Int64.self),\n      case .text(let sender) = values[1]\n    else {\n      throw Fail.with(\"InvalidChannelPayload\")\n    }\n    return (n, sender, Array(bytes[next...]))\n  }\n\n  public static func sequence(_ n: Int64) throws -> [UInt8] {\n    try Descriptors.encode(sequenceType, .int(BigInt(n)), [:])\n  }\n\n  public static func readSequence(_ bytes: [UInt8]) throws -> Int64 {\n    guard case .int(let n) = try Descriptors.decode(sequenceType, bytes, [:]),\n      let v = n.exactly(Int64.self)\n    else {\n      throw Fail.with(\"InvalidSequence\")\n    }\n    return v\n  }\n\n  /// An address's node and entity name: tcp://host:port/name gives\n  /// (tcp://host:port, name). The node part must have a scheme.\n  public static func splitAddress(_ address: String) throws -> (String, String) {\n    guard let at = address.lastIndex(of: \"/\") else { throw Fail.with(\"InvalidAddress\", address) }\n    let node = String(address[..<at])\n    guard node.contains(\"://\") else { throw Fail.with(\"InvalidAddress\", address) }\n    return (node, String(address[address.index(after: at)...]))\n  }\n\n  /// Text fields of a payload, as the channel protocol's control frames carry them.\n  static func texts(_ values: [String]) throws -> [UInt8] {\n    try fields(values.map { _ in textType }, values.map { .text($0) })\n  }\n\n  static func readTexts(_ count: Int, _ bytes: [UInt8], _ start: Int) throws -> ([String], Int) {\n    let (values, next) = try readFields(Array(repeating: textType, count: count), bytes, start)\n    return (try values.map(text), next)\n  }\n\n  /// A list of texts and the position after it.\n  static func readTextList(_ bytes: [UInt8], _ start: Int) throws -> ([String], Int) {\n    let (n, position) = try Descriptors.readVarint(bytes, start)\n    guard let count = n.exactly(Int.self), count >= 0 else { throw Fail.with(\"InvalidFrame\") }\n    var at = position\n    var items = [String]()\n    for _ in 0..<count {\n      let (v, next) = try Descriptors.decodePrefix(textType, bytes, at, [:])\n      items.append(try text(v))\n      at = next\n    }\n    return (items, at)\n  }\n\n  static func textList(_ items: [String]) throws -> [UInt8] {\n    try Descriptors.encode(.forms([.atom(\"list\"), textType]), .list(items.map { .text($0) }), [:])\n  }\n\n  /// A list of byte strings, encoded and read.\n  static func bytesList(_ items: [[UInt8]]) throws -> [UInt8] {\n    try Descriptors.encode(\n      .forms([.atom(\"list\"), bytesType]), .list(items.map { .bytes($0) }), [:])\n  }\n\n  static func readBytesList(_ bytes: [UInt8], _ start: Int) throws -> ([[UInt8]], Int) {\n    let (n, position) = try Descriptors.readVarint(bytes, start)\n    guard let count = n.exactly(Int.self), count >= 0 else { throw Fail.with(\"InvalidFrame\") }\n    var at = position\n    var items = [[UInt8]]()\n    for _ in 0..<count {\n      let (v, next) = try Descriptors.decodePrefix(bytesType, bytes, at, [:])\n      items.append(try bytesOf(v))\n      at = next\n    }\n    return (items, at)\n  }\n\n  /// Lowercase hexadecimal of bytes.\n  public static func hex(_ bytes: [UInt8]) -> String {\n    let digits = Array(\"0123456789abcdef\".utf8)\n    var out = [UInt8]()\n    out.reserveCapacity(bytes.count * 2)\n    for b in bytes {\n      out.append(digits[Int(b >> 4)])\n      out.append(digits[Int(b & 15)])\n    }\n    return String(decoding: out, as: UTF8.self)\n  }\n\n  /// The bytes of hexadecimal text, or nil.\n  public static func unhex(_ text: String) -> [UInt8]? {\n    let chars = Array(text.utf8)\n    guard chars.count % 2 == 0 else { return nil }\n    func digit(_ c: UInt8) -> UInt8? {\n      switch c {\n      case 48...57: return c - 48\n      case 97...102: return c - 87\n      case 65...70: return c - 55\n      default: return nil\n      }\n    }\n    var out = [UInt8]()\n    out.reserveCapacity(chars.count / 2)\n    var i = 0\n    while i < chars.count {\n      guard let hi = digit(chars[i]), let lo = digit(chars[i + 1]) else { return nil }\n      out.append(hi << 4 | lo)\n      i += 2\n    }\n    return out\n  }\n\n  /// The UTF-8 bytes of text.\n  static func utf8(_ text: String) -> [UInt8] { Array(text.utf8) }\n}\n\n/// A repeating timer on a background queue, cancelled once.\nfinal class NetworkTimer: @unchecked Sendable {\n  private let source: DispatchSourceTimer\n\n  /// Call a body every period (milliseconds), first after one period.\n  init(_ period: Int, _ body: @escaping @Sendable () -> Void) {\n    source = DispatchSource.makeTimerSource(queue: .global())\n    source.schedule(deadline: .now() + .milliseconds(period), repeating: .milliseconds(period))\n    source.setEventHandler(handler: body)\n    source.resume()\n  }\n\n  func cancel() { source.cancel() }\n\n  /// Run a body once after a delay (milliseconds).\n  static func after(_ delay: Int, _ body: @escaping @Sendable () -> Void) {\n    DispatchQueue.global().asyncAfter(deadline: .now() + .milliseconds(delay), execute: body)\n  }\n}\n"
swiftSource "LawSpecRuntime/Workflow.swift" = "// Workflows in Swift: stages run under their policies (gates, retries with\n// jittered backoff, timeouts, hedges, caches) and a workflow compensates\n// the stages that succeeded when it fails. A workflow runtime owns the\n// policy state, the virtual time and the trace; it is ambient (Ambient), so\n// a test's calls and their concurrent work share it. Without one, workflows\n// share the default runtime on the real clock, and a Clock in scope supplies\n// its view of time. ref:DEC-domain-modeling-primitives\n// ref:DEC-async-native-tasks ref:DEC-portable-seeded-generation\n\nimport Foundation\n\npublic enum Workflow {\n  /// Something that happened in a stage: start, finish, sleep, wait, hedge,\n  /// cached or compensate, with the attempt (or delay) number.\n  public struct Event: Sendable {\n    public let kind: String\n    public let stage: String\n    public let number: Int64\n    public let succeeded: Bool\n  }\n\n  /// Where a runtime's time comes from.\n  public enum Clock {\n    case real\n    case virtual\n    case callbacks(now: () throws -> Int64, sleep: (Int64) throws -> Void, isVirtual: Bool)\n  }\n\n  private final class StageRecord {\n    let key: String\n    var passed: [(GateKey, Policy.Gate)] = []\n    var time: Int64\n    init(key: String, time: Int64) {\n      self.key = key\n      self.time = time\n    }\n  }\n\n  struct GateKey: Hashable {\n    let stage: String\n    let kind: Policy.GateKind\n  }\n\n  /// A runtime's policy state: virtual time, the jitter stream, the trace,\n  /// gate states, the cache, compensation frames and running stages. Every\n  /// change is under its lock; gate callbacks are pure checked definitions.\n  public final class State: @unchecked Sendable {\n    private let gate = NSRecursiveLock()\n    private var now: Int64\n    private var random: Random.Seed\n    private var trace: [Event] = []\n    private var states: [GateKey: Value] = [:]\n    private var cache: [String: [(Value, Value, Int64)]] = [:]\n    private var frames: [Int64: [(String, () throws -> Value)]] = [:]\n    private var stages: [Int64: StageRecord] = [:]\n    private var counter: Int64 = 0\n\n    init(seed: BigInt, time: Int64) {\n      now = time\n      random = Random.seed(seed)\n    }\n\n    private func locked<T>(_ body: () throws -> T) rethrows -> T {\n      gate.lock()\n      defer { gate.unlock() }\n      return try body()\n    }\n\n    public var time: Int64 { locked { now } }\n    func setTime(_ t: Int64) { locked { now = t } }\n    func sleep(_ delay: Int64) { locked { now += Swift.max(0, delay) } }\n\n    func jitter(_ kind: Policy.Jitter, _ delay: Int64, _ previous: Int64, _ baseDelay: Int64)\n      -> Int64\n    {\n      locked {\n        let (value, next) = Policy.jitter(kind, delay, previous, baseDelay, random)\n        random = next\n        return value\n      }\n    }\n\n    func event(_ e: Event) { locked { trace.append(e) } }\n    public var events: [Event] { locked { trace } }\n\n    func cached(_ key: String, _ input: Value, _ at: Int64) -> Value? {\n      locked {\n        let live = (cache[key] ?? []).filter { at < $0.2 }\n        cache[key] = live\n        return live.first { Scalar.equal($0.0, input) }?.1\n      }\n    }\n\n    func store(_ key: String, _ input: Value, _ value: Value, _ at: Int64, _ ttl: Int64) {\n      locked {\n        let live = (cache[key] ?? []).filter { at < $0.2 && !Scalar.equal($0.0, input) }\n        cache[key] = [(input, value, at + ttl)] + live\n      }\n    }\n\n    func newFrame() -> Int64 {\n      locked {\n        counter += 1\n        frames[counter] = []\n        return counter\n      }\n    }\n\n    func undo(_ frame: Int64, _ stage: String, _ undo: @escaping () throws -> Value) {\n      locked {\n        if let undos = frames[frame] { frames[frame] = [(stage, undo)] + undos }\n      }\n    }\n\n    func takeFrame(_ frame: Int64) -> [(String, () throws -> Value)] {\n      locked {\n        let undos = frames[frame] ?? []\n        frames[frame] = nil\n        return undos\n      }\n    }\n\n    func newStage(_ key: String, _ at: Int64) -> Int64 {\n      locked {\n        counter += 1\n        stages[counter] = StageRecord(key: key, time: at)\n        return counter\n      }\n    }\n\n    /// A gate's decision for a running stage, updating the gate's state.\n    func decide(_ stage: Int64, _ g: Policy.Gate, _ at: Int64) throws -> Value {\n      try locked {\n        guard let record = stages[stage] else { throw Fail.with(\"UnknownStage\") }\n        let key = GateKey(stage: record.key, kind: g.kind)\n        let before = try states[key] ?? g.start(.int(BigInt(at)))\n        let step = try g.admit(before, .int(BigInt(at)))\n        guard case .data(_, let pair) = step, pair.count == 2 else {\n          throw Fail.with(\"InvalidGateStep\", \"\\(step)\")\n        }\n        states[key] = pair[0]\n        if case .data(\"lawspec.resilience::type::Gate::Admit\", let f) = pair[1], f.isEmpty {\n          record.passed.append((key, g))\n        }\n        record.time = at\n        return pair[1]\n      }\n    }\n\n    /// A stage ended: each gate it passed records the outcome.\n    func finishStage(_ stage: Int64, _ at: Int64, _ succeeded: Bool) throws {\n      try locked {\n        guard let record = stages[stage] else { return }\n        stages[stage] = nil\n        for (key, g) in record.passed {\n          if let finish = g.finish, let state = states[key] {\n            states[key] = try finish(state, .int(BigInt(at)), .bool(succeeded))\n          }\n        }\n      }\n    }\n  }\n\n  /// A workflow runtime: its state, its clock, whether gates and caches\n  /// apply, and whether it was installed explicitly (an explicit runtime's\n  /// clock is not replaced by a Clock in scope).\n  public struct Runtime {\n    public let state: State\n    public let clock: Clock\n    public let gates: Bool\n    public let explicit: Bool\n  }\n\n  private static let ambientKey = \"lawspec.workflow.runtime\"\n  nonisolated(unsafe) private static let shared = Runtime(\n    state: State(seed: .zero, time: 0), clock: .real, gates: true, explicit: false)\n\n  private static func scoped<T>(_ runtime: Runtime, _ body: (Runtime) throws -> T) rethrows -> T {\n    try Ambient.with(ambientKey, runtime) { try body(runtime) }\n  }\n\n  private static func seedOf() -> BigInt {\n    BigInt(ProcessInfo.processInfo.environment[\"LAWSPEC_SEED\"] ?? \"\") ?? .zero\n  }\n\n  /// Run a body with its own runtime on a clock, from a seed.\n  public static func withClock<T>(_ clock: Clock, _ seed: BigInt, _ body: (Runtime) throws -> T)\n    rethrows -> T\n  {\n    try scoped(\n      Runtime(state: State(seed: seed, time: 0), clock: clock, gates: true, explicit: true), body)\n  }\n\n  /// A runtime on a virtual clock that starts at 0 and moves only when told.\n  public static func withVirtual<T>(_ seed: BigInt, _ body: (Runtime) throws -> T) rethrows -> T {\n    try withClock(.virtual, seed, body)\n  }\n\n  /// A runtime on the real clock.\n  public static func withReal<T>(_ seed: BigInt, _ body: (Runtime) throws -> T) rethrows -> T {\n    try withClock(.real, seed, body)\n  }\n\n  /// A law's runtime: virtual time and no gates or caches, from the run's\n  /// seed; a Clock in scope (`using virtual clock`) supplies the time.\n  public static func withTestRuntime<T>(_ body: () throws -> T) throws -> T {\n    try scoped(\n      Runtime(state: State(seed: seedOf(), time: 0), clock: .virtual, gates: false, explicit: false)\n    ) { _ in try body() }\n  }\n\n  private static func isRealClock(_ handler: Effects.Handler) -> Bool {\n    switch handler {\n    case .recording(_, let inner): return isRealClock(inner)\n    case .stateless(let clauses): return clauses[Defaults.realClockMarker] != nil\n    case .stateful: return false\n    }\n  }\n\n  /// The ambient runtime (the shared default outside any).\n  public static func ambient() -> Runtime { (Ambient.get(ambientKey) as? Runtime) ?? shared }\n\n  /// The runtime a stage runs under: the ambient one (or the shared default),\n  /// timed by the Clock in scope unless the runtime was installed explicitly.\n  public static func current(_ schema: Schema) -> Runtime {\n    let base = ambient()\n    guard !base.explicit, let handler = schema.handlers[\"lawspec.time::ability::Clock\"] else {\n      return base\n    }\n    let now = { () throws -> Int64 in\n      let instant = try Effects.invoke(handler, schema, \"now\", [])\n      guard case .data(_, let f) = instant, f.count == 1, case .int(let t) = f[0],\n        let micros = t.exactly(Int64.self)\n      else {\n        throw Fail.with(\"InvalidInstant\", \"\\(instant)\")\n      }\n      return micros\n    }\n    let sleep = { (delay: Int64) throws -> Void in\n      _ = try Effects.invoke(\n        handler, schema, \"sleep\",\n        [.data(\"lawspec.time::type::Duration::Duration\", [.int(BigInt(delay))])])\n    }\n    return Runtime(\n      state: base.state,\n      clock: .callbacks(now: now, sleep: sleep, isVirtual: !isRealClock(handler)),\n      gates: base.gates, explicit: base.explicit)\n  }\n\n  private static func isVirtual(_ runtime: Runtime) -> Bool {\n    switch runtime.clock {\n    case .virtual: return true\n    case .real: return false\n    case .callbacks(_, _, let v): return v\n    }\n  }\n\n  /// The runtime's time, in microseconds.\n  public static func now(_ runtime: Runtime) throws -> Int64 {\n    switch runtime.clock {\n    case .real: return Defaults.nowMicros()\n    case .virtual: return runtime.state.time\n    case .callbacks(let read, _, _): return try read()\n    }\n  }\n\n  /// Let time pass: at once on a virtual clock.\n  public static func sleep(_ runtime: Runtime, _ delay: Int64) throws {\n    guard delay > 0 else { return }\n    switch runtime.clock {\n    case .real: Defaults.sleepMicros(delay)\n    case .virtual: runtime.state.sleep(delay)\n    case .callbacks(_, let wait, _): try wait(delay)\n    }\n  }\n\n  /// Set a virtual runtime's time.\n  public static func setTime(_ runtime: Runtime, _ time: Int64) throws {\n    guard case .virtual = runtime.clock else {\n      throw Fail.with(\"NotVirtual\", \"only a virtual runtime's time is set\")\n    }\n    runtime.state.setTime(time)\n  }\n\n  /// What happened, in order.\n  public static func trace(_ runtime: Runtime) -> [Event] { runtime.state.events }\n\n  private static func event(\n    _ runtime: Runtime, _ policy: Policy.StagePolicy, _ kind: String, _ number: Int64,\n    _ succeeded: Bool\n  ) {\n    runtime.state.event(\n      Event(kind: kind, stage: policy.stage, number: number, succeeded: succeeded))\n  }\n\n  // MARK: Real-clock timeouts and hedges. ref:DEC-async-native-tasks\n\n  private static func micros() -> Int64 { Int64(DispatchTime.now().uptimeNanoseconds / 1000) }\n\n  /// The attempts running at once, and the first that ended.\n  private final class Attempts: @unchecked Sendable {\n    let condition = NSCondition()\n    var finished: [(Int, Int64, Result<Value, any Error>)] = []\n  }\n\n  /// Run attempts of a body on the real clock: a hedge starts another after\n  /// the delay, up to most; the first success wins, or the last failure after\n  /// every attempt; past the deadline the stage is TimedOut. Losing attempts\n  /// are cancelled through their scope, never awaited.\n  public static func runAttempts(\n    _ timeout: Int64?, _ hedge: (Int64, Int64)?, _ body: @escaping () throws -> Value,\n    _ onHedge: (Int64) -> Void\n  ) throws -> Value {\n    try Tasks.withScope { _ in\n      let start = micros()\n      let deadline: Int64? = timeout.flatMap { $0 > 0 ? start + $0 : nil }\n      let (delay, most): (Int64, Int64) =\n        hedge.map { (Swift.max(0, $0.0), Swift.max(1, $0.1)) } ?? (0, 1)\n      let attempts = Attempts()\n      let work = UncheckedBox(body)\n      var running: Set<Int> = []\n      func launch(_ number: Int64) {\n        if number > 1 { onHedge(number) }\n        let id = Int(number)\n        running.insert(id)\n        LawThread.start {\n          let result = Result { try work.value() }\n          attempts.condition.lock()\n          attempts.finished.append((id, micros(), result))\n          attempts.condition.signal()\n          attempts.condition.unlock()\n        }\n      }\n      launch(1)\n      var started: Int64 = 1\n      var next = start + delay\n      while true {\n        let hedgeAt: Int64? = started < most ? next : nil\n        let timer: Int64? = [deadline, hedgeAt].compactMap { $0 }.min()\n        attempts.condition.lock()\n        if attempts.finished.isEmpty {\n          if let t = timer {\n            let wait = Swift.max(0, t - micros())\n            _ = attempts.condition.wait(until: Date(timeIntervalSinceNow: Double(wait) / 1e6))\n          } else {\n            attempts.condition.wait()\n          }\n        }\n        let done = attempts.finished.isEmpty ? nil : attempts.finished.removeFirst()\n        attempts.condition.unlock()\n        if let (id, ended, result) = done {\n          running.remove(id)\n          if let d = deadline, ended > d { return Policy.stageFailure(\"TimedOut\") }\n          let value = try result.get()\n          if !Policy.failed(value) { return value }\n          if running.isEmpty && started >= most { return value }\n          if running.isEmpty {\n            if deadline == nil || micros() < deadline! {\n              started += 1\n              launch(started)\n              next = micros() + delay\n            } else {\n              return Policy.stageFailure(\"TimedOut\")\n            }\n          }\n        } else {\n          let at = micros()\n          if let d = deadline, at >= d { return Policy.stageFailure(\"TimedOut\") }\n          if started < most && at >= next {\n            started += 1\n            launch(started)\n            next = micros() + delay\n          }\n        }\n      }\n    }\n  }\n\n  // MARK: Stages and workflows\n\n  private struct Frame {\n    let state: State\n    let id: Int64\n  }\n\n  private static let frameKey = \"lawspec.workflow.frame\"\n\n  private static func virtualHedge(\n    _ hedge: (Int64, Int64)?, _ body: () throws -> Value, _ onHedge: (Int64) -> Void,\n    _ started: Int64\n  ) throws -> Value {\n    guard let (_, most) = hedge else { return try body() }\n    var count = started\n    while true {\n      let result = try body()\n      if Policy.failed(result) && count < most {\n        count += 1\n        onHedge(count)\n      } else {\n        return result\n      }\n    }\n  }\n\n  private static func timed(\n    _ runtime: Runtime, _ policy: Policy.StagePolicy, _ body: @escaping () throws -> Value\n  ) throws -> Value {\n    let onHedge = { (n: Int64) in event(runtime, policy, \"hedge\", n, true) }\n    if isVirtual(runtime) {\n      let began = try now(runtime)\n      let result = try virtualHedge(policy.hedge, body, onHedge, 1)\n      if let t = policy.timeout, t > 0, try now(runtime) - began > t {\n        return Policy.stageFailure(\"TimedOut\")\n      }\n      return result\n    }\n    if runtime.gates && (policy.timeout != nil || policy.hedge != nil) {\n      return try runAttempts(policy.timeout, policy.hedge, body, onHedge)\n    }\n    return try body()\n  }\n\n  private static func retryError(_ wraps: Bool, _ error: Value) -> Value? {\n    if !wraps { return error }\n    switch error {\n    case .data(\"lawspec.resilience::type::StageFailure::StepFailed\", let f) where f.count == 1:\n      return f[0]\n    case .data(\"lawspec.resilience::type::StageFailure::TimedOut\", let f) where f.isEmpty:\n      return error\n    default: return nil\n    }\n  }\n\n  private static func retryWait(\n    _ runtime: Runtime, _ retry: Policy.Retry, _ number: Int64, _ reason: Value, _ previous: Int64\n  ) throws -> Int64? {\n    if case .custom(let decide) = retry.strategy {\n      return try Policy.retryDecision(\n        try decide(\n          .int(BigInt(number)), reason,\n          .data(\"lawspec.time::type::Duration::Duration\", [.int(BigInt(previous))])))\n    }\n    let delay = try Policy.retryDelay(retry.strategy, number)\n    let baseDelay = try Policy.retryDelay(retry.strategy, 2)\n    return runtime.state.jitter(retry.jitter, delay, previous, baseDelay)\n  }\n\n  private static func attempts(\n    _ runtime: Runtime, _ policy: Policy.StagePolicy, _ body: @escaping () throws -> Value\n  ) throws -> Value {\n    var number: Int64 = 1\n    var previous: Int64 = 0\n    while true {\n      event(runtime, policy, \"start\", number, false)\n      let result = try timed(runtime, policy, body)\n      let isFailure = Policy.failed(result)\n      event(runtime, policy, \"finish\", number, !isFailure)\n      guard isFailure, let retry = policy.retry, case .data(_, let fields) = result,\n        fields.count == 1,\n        let reason = retryError(policy.wraps, fields[0])\n      else { return result }\n      let exhausted = retry.attempts > 0 && number >= retry.attempts\n      var refused = false\n      if let condition = retry.condition {\n        guard case .bool(let holds) = try condition(reason) else { throw Fail.with(\"BoolRequired\") }\n        refused = !holds\n      }\n      if exhausted || refused { return result }\n      guard let delay = try retryWait(runtime, retry, number + 1, reason, previous) else {\n        return result\n      }\n      event(runtime, policy, \"sleep\", delay, true)\n      try sleep(runtime, delay)\n      number += 1\n      previous = delay\n    }\n  }\n\n  private static func gateFailure(_ kind: Policy.GateKind) -> String {\n    switch kind {\n    case .breaker: return \"CircuitOpen\"\n    case .limit: return \"RateLimited\"\n    case .bulkhead: return \"Saturated\"\n    }\n  }\n\n  private static func passGate(\n    _ runtime: Runtime, _ stage: Int64, _ policy: Policy.StagePolicy, _ g: Policy.Gate\n  ) throws -> String? {\n    var waited: Int64 = 0\n    while true {\n      let decision = try runtime.state.decide(stage, g, try now(runtime))\n      switch decision {\n      case .data(\"lawspec.resilience::type::Gate::Admit\", let f) where f.isEmpty: return nil\n      case .data(\"lawspec.resilience::type::Gate::Reject\", let f) where f.isEmpty:\n        return gateFailure(g.kind)\n      case _ where g.wait == .noWait: return gateFailure(g.kind)\n      case .data(\"lawspec.resilience::type::Gate::WaitFor\", let f) where f.count == 1:\n        guard case .int(let d) = f[0], let delay = d.exactly(Int64.self) else {\n          throw Fail.with(\"InvalidGateDecision\", \"\\(decision)\")\n        }\n        if case .within(let most) = g.wait, waited + delay > most { return gateFailure(g.kind) }\n        event(runtime, policy, \"wait\", delay, true)\n        try sleep(runtime, delay)\n        waited += delay\n      default:\n        throw Fail.with(\"InvalidGateDecision\", \"\\(decision)\")\n      }\n    }\n  }\n\n  private static func rememberUndo(\n    _ runtime: Runtime, _ policy: Policy.StagePolicy, _ result: Value\n  ) {\n    guard let f = Ambient.get(frameKey) as? Frame, f.state === runtime.state,\n      let undo = policy.compensate\n    else { return }\n    var value = result\n    if case .data(\"Either::Right\", let fields) = result, fields.count == 1 { value = fields[0] }\n    let kept = value\n    runtime.state.undo(f.id, policy.stage) { try undo(kept) }\n  }\n\n  /// Run a stage of a workflow under its policy. The input is the stage's\n  /// argument, the key of its cache.\n  public static func runStage(\n    _ schema: Schema, _ policy: Policy.StagePolicy, _ body: @escaping () throws -> Value,\n    _ input: Value\n  ) throws -> Value {\n    let runtime = current(schema)\n    let caching = runtime.gates && policy.cache != nil\n    if caching, let value = runtime.state.cached(policy.key, input, try now(runtime)) {\n      event(runtime, policy, \"cached\", 0, true)\n      return value\n    }\n    let stage = runtime.state.newStage(policy.key, try now(runtime))\n    let gates = runtime.gates ? policy.gates : []\n    let outcome = Result { () throws -> Value in\n      for g in gates {\n        if let kind = try passGate(runtime, stage, policy, g) { return Policy.stageFailure(kind) }\n      }\n      return try attempts(runtime, policy, body)\n    }\n    let succeeded: Bool\n    if case .success(let v) = outcome { succeeded = !Policy.failed(v) } else { succeeded = false }\n    try runtime.state.finishStage(stage, try now(runtime), succeeded)\n    let value = try outcome.get()\n    if succeeded {\n      rememberUndo(runtime, policy, value)\n      if caching, let ttl = policy.cache {\n        runtime.state.store(policy.key, input, value, try now(runtime), ttl)\n      }\n    }\n    return value\n  }\n\n  /// Run a workflow: when it fails, undo the stages that succeeded, the\n  /// latest first.\n  public static func runWorkflow(_ schema: Schema, _ body: () throws -> Value) throws -> Value {\n    let runtime = current(schema)\n    let id = runtime.state.newFrame()\n    let outcome = Result {\n      try Ambient.with(frameKey, Frame(state: runtime.state, id: id)) { try body() }\n    }\n    let undos = runtime.state.takeFrame(id)\n    let result = try outcome.get()\n    if Policy.failed(result) {\n      for (stageName, undo) in undos {\n        runtime.state.event(Event(kind: \"compensate\", stage: stageName, number: 0, succeeded: true))\n        _ = try undo()\n      }\n    }\n    return result\n  }\n}\n"
swiftSource "LawSpecTesting/ActorHost.swift" = "// The actor runtime as an actor model's system: one permanent child under a\n// one-for-one supervisor whose restart budget is the run's length, so\n// injected crashes cannot exhaust it. ref:DEC-actors-otp-supervision\n// ref:DEC-stateful-models-linearizability\n\nimport LawSpecRuntime\n\n/// The host actor models run on.\npublic enum ActorHost {\n  /// Start one permanent child under a one-for-one supervisor that allows\n  /// the given number of restarts, run the body with the child, then stop.\n  /// start makes the first state; restart makes a state from the state at\n  /// the crash.\n  public static func withActor<R>(\n    _ restarts: Int, _ start: @escaping () throws -> Value,\n    _ restart: @escaping (Value) throws -> Value,\n    _ body: (Actors.Handle) throws -> R\n  ) throws -> R {\n    let spec = try Actors.supervisor(\n      .oneForOne, max(1, restarts), 1_000_000,\n      [\n        (\n          \"model\", .permanent,\n          Actors.actor({ try start() }, { state in try restart(state as! Value) })\n        )\n      ])\n    return try Actors.withSpec(spec) { supervisor in try body(try Actors.child(supervisor, \"model\"))\n    }\n  }\n\n  /// Run an update on the actor's state in the actor: its reply and next state.\n  public static func call(\n    _ actor: Actors.Handle, _ update: @escaping (Value) throws -> (Value, Value)\n  ) throws -> Value {\n    try Actors.call(actor) { state in\n      let (reply, next) = try update(state as! Value)\n      return (reply, next)\n    } as! Value\n  }\n\n  /// Crash the actor, waiting until its supervisor has restarted it.\n  public static func crash(_ actor: Actors.Handle) throws { try Actors.crash(actor) }\n\n  /// The actor's current state.\n  public static func state(_ actor: Actors.Handle) throws -> Value {\n    try Actors.state(actor) as! Value\n  }\n}\n\nextension ActorHost {\n  /// An actor handle as the model runner holds it.\n  final class Boxed {\n    let handle: Actors.Handle\n    init(_ handle: Actors.Handle) { self.handle = handle }\n  }\n\n  /// The actor runtime as an actor model's system.\n  struct Host: ModelActorHost {\n    func withActor<R>(\n      _ restarts: Int, _ start: @escaping () throws -> Value,\n      _ restart: @escaping (Value) throws -> Value,\n      _ body: (AnyObject) throws -> R\n    ) throws -> R {\n      try ActorHost.withActor(restarts, start, restart) { handle in try body(Boxed(handle)) }\n    }\n\n    func call(_ actor: AnyObject, _ update: @escaping (Value) throws -> (Value, Value)) throws\n      -> Value\n    {\n      try ActorHost.call((actor as! Boxed).handle, update)\n    }\n\n    func crash(_ actor: AnyObject) throws { try ActorHost.crash((actor as! Boxed).handle) }\n\n    func state(_ actor: AnyObject) throws -> Value { try ActorHost.state((actor as! Boxed).handle) }\n  }\n\n  /// The host actor models run on.\n  public static var host: any ModelActorHost { Host() }\n}\n"
swiftSource "LawSpecTesting/CryptoVectors.swift" = "// NIST known-answer checks of the default crypto primitives, over the vectors\n// every target shares (runtime/defaults/vectors.txt, provenance in\n// docs/reference/language/cryptography.md). ref:DEC-tests-cite-requirements\n\nimport LawSpecRuntime\n\n/// The known-answer checks of lawspec.crypto's primitives.\npublic enum CryptoVectors {\n  private static func fail(_ kind: String, _ detail: String) -> CryptoFailure {\n    CryptoFailure(code: \"CryptoVectorFailed\", detail: kind + \": \" + detail)\n  }\n\n  private static func hex(_ text: Substring) -> [UInt8] {\n    if text == \"-\" { return [] }\n    var bytes: [UInt8] = []\n    bytes.reserveCapacity(text.count / 2)\n    var index = text.startIndex\n    while index < text.endIndex {\n      let next = text.index(index, offsetBy: 2)\n      bytes.append(UInt8(text[index..<next], radix: 16) ?? 0)\n      index = next\n    }\n    return bytes\n  }\n\n  private static func hexText(_ bytes: [UInt8]) -> String {\n    let digits = Array(\"0123456789abcdef\")\n    return String(bytes.flatMap { [digits[Int($0 >> 4)], digits[Int($0 & 15)]] })\n  }\n\n  private static func digest(_ bytes: [UInt8]) -> String { hexText(CryptoPrimitives.sha3(bytes)) }\n\n  private static func flip(_ bytes: [UInt8]) -> [UInt8] {\n    var copy = bytes\n    copy[0] ^= 1\n    return copy\n  }\n\n  private static func same(_ kind: String, _ what: String, _ expected: [UInt8], _ actual: [UInt8])\n    throws(CryptoFailure)\n  {\n    if expected != actual { throw fail(kind, what + \" differs\") }\n  }\n\n  private static func holds(_ kind: String, _ what: String, _ condition: Bool) throws(CryptoFailure)\n  {\n    if !condition { throw fail(kind, what) }\n  }\n\n  /// Check every vector of a kind in the vectors text.\n  public static func check(_ vectors: String, _ kind: String) throws(CryptoFailure) {\n    let rows = vectors.split(separator: \"\\n\")\n      .map { $0.split(separator: \" \", omittingEmptySubsequences: true) }\n      .filter { !$0.isEmpty && $0[0] == kind }\n      .map { Array($0.dropFirst()) }\n    if rows.isEmpty { throw fail(kind, \"no vectors\") }\n    for row in rows {\n      switch (kind, row.count) {\n      case (\"sha3-256\", 2):\n        try same(kind, \"digest\", hex(row[1]), CryptoPrimitives.sha3(hex(row[0])))\n      case (\"shake256\", 3):\n        try same(kind, \"output\", hex(row[2]), CryptoPrimitives.shake(hex(row[0]), Int(row[1]) ?? 0))\n      case (\"aes-256-gcm\", 6):\n        let key = hex(row[0])\n        let nonce = hex(row[1])\n        let message = hex(row[2])\n        let associated = hex(row[3])\n        let expected = hex(row[4]) + hex(row[5])\n        try same(\n          kind, \"sealed\", expected,\n          try CryptoPrimitives.aes256GcmEncrypt(key, nonce, message, associated))\n        try holds(\n          kind, \"decrypts\",\n          CryptoPrimitives.aes256GcmDecrypt(key, nonce, expected, associated) == message)\n        try holds(\n          kind, \"rejects a changed ciphertext\",\n          CryptoPrimitives.aes256GcmDecrypt(key, nonce, flip(expected), associated) == nil)\n      case (\"mlkem768-keygen\", 4):\n        let seed = hex(row[0]) + hex(row[1])\n        let (publicKey, privateKey) = CryptoPrimitives.mlkemExpand(seed)\n        try holds(kind, \"public key\", digest(publicKey) == String(row[2]))\n        try holds(kind, \"private key\", digest(privateKey) == String(row[3]))\n        let pair = CryptoPrimitives.mlkemKeyPair(seed)\n        try holds(kind, \"key pair\", pair.publicKey == publicKey && pair.seed == seed)\n      case (\"mlkem768-encaps\", 4):\n        let (ciphertext, shared) = try CryptoPrimitives.mlkemEncapsulateWith(\n          hex(row[0]), hex(row[1]))\n        try same(kind, \"ciphertext\", hex(row[2]), ciphertext)\n        try same(kind, \"shared secret\", hex(row[3]), shared)\n      case (\"mlkem768-decaps\", 3):\n        try same(\n          kind, \"shared secret\", hex(row[2]),\n          try CryptoPrimitives.mlkemDecapsulateExpanded(hex(row[0]), hex(row[1])))\n      case (\"mlkem768-decaps-seed\", 3):\n        try same(\n          kind, \"shared secret\", hex(row[2]),\n          try CryptoPrimitives.mlkemDecapsulate(hex(row[0]), hex(row[1])))\n      case (\"mldsa65-keygen\", 3):\n        let seed = hex(row[0])\n        let (publicKey, privateKey) = CryptoPrimitives.mldsaExpand(seed)\n        try holds(kind, \"public key\", digest(publicKey) == String(row[1]))\n        try holds(kind, \"private key\", digest(privateKey) == String(row[2]))\n        try same(kind, \"public key of the seed\", publicKey, CryptoPrimitives.mldsaPublic(seed))\n      case (\"mldsa65-verify\", 5):\n        let verified = CryptoPrimitives.mldsaVerifyWith(\n          hex(row[0]), hex(row[1]), hex(row[3]), hex(row[2]))\n        try holds(kind, \"verification\", verified == (row[4] == \"true\"))\n      case (\"mldsa65-sign-seed\", 3):\n        let seed = hex(row[0])\n        let message = hex(row[1])\n        let signed = try CryptoPrimitives.mldsaSignWith(seed, message, [], deterministic: true)\n        try same(kind, \"signature\", hex(row[2]), signed)\n        let publicKey = CryptoPrimitives.mldsaPublic(seed)\n        try holds(kind, \"verifies\", CryptoPrimitives.mldsaVerify(publicKey, message, signed))\n        try holds(\n          kind, \"rejects a changed message\",\n          !CryptoPrimitives.mldsaVerify(publicKey, flip(message), signed))\n      case (\"slhdsa128f-keygen\", 5):\n        let (publicKey, privateKey) = CryptoPrimitives.slhKeyPairOf(\n          hex(row[0]) + hex(row[1]) + hex(row[2]))\n        try same(kind, \"public key\", hex(row[3]), publicKey)\n        try holds(kind, \"private key\", digest(privateKey) == String(row[4]))\n        let message = Array(\"LawSpec\".utf8)\n        let signature = try CryptoPrimitives.slhSign(privateKey, message)\n        try holds(kind, \"verifies\", CryptoPrimitives.slhVerify(publicKey, message, signature))\n        try holds(\n          kind, \"rejects a changed message\",\n          !CryptoPrimitives.slhVerify(publicKey, Array(\"LawSpeC\".utf8), signature))\n      case (\"slhdsa128f-verify\", 5):\n        let publicKey = hex(row[0])\n        let message = hex(row[1])\n        let context = hex(row[2])\n        let signature = hex(row[3])\n        try holds(\n          kind, \"verification\",\n          CryptoPrimitives.slhVerifyWith(publicKey, message, signature, context)\n            == (row[4] == \"true\"))\n        try holds(\n          kind, \"rejects a changed message\",\n          !CryptoPrimitives.slhVerifyWith(publicKey, flip(message), signature, context))\n      default:\n        throw fail(kind, \"unexpected row of \\(row.count) fields\")\n      }\n    }\n  }\n}\n"
swiftSource "LawSpecTesting/Gen.swift" = "// LawSpec's generation plans as generators of shrink trees. No maintained\n// Swift property library offers dependent generation whose shrinking stays\n// inside a refinement and replays from one seed, so the engine is here: a\n// generator draws from the portable SplitMix64 sequence at a size and builds,\n// for each value, the rose tree of the smaller values it may shrink to.\n// Shrinking a bound input rebuilds the inputs that depend on it from the same\n// random state, so every candidate stays inside the domain.\n// ref:DEC-swift-property-library ref:DEC-shrink-within-domain\n// ref:DEC-planned-generation\n\nimport LawSpecRuntime\n\n/// A value and, lazily, the values it shrinks to, best first.\npublic struct Tree<Element> {\n  public let value: Element\n  private let makeChildren: () throws -> [Tree<Element>]\n\n  public init(_ value: Element, _ children: @escaping () throws -> [Tree<Element>]) {\n    self.value = value\n    self.makeChildren = children\n  }\n\n  /// The candidates, computed when asked for.\n  public func children() throws -> [Tree<Element>] { try makeChildren() }\n\n  public static func leaf(_ value: Element) -> Tree<Element> { Tree(value) { [] } }\n\n  public func map<B>(_ f: @escaping (Element) throws -> B) throws -> Tree<B> {\n    let me = self\n    return Tree<B>(try f(value)) { try me.children().map { try $0.map(f) } }\n  }\n\n  /// Keep only the candidates a predicate accepts, with their own candidates.\n  public func filter(_ keep: @escaping (Element) throws -> Bool) -> Tree<Element> {\n    let me = self\n    return Tree(value) { try me.children().filter { try keep($0.value) }.map { $0.filter(keep) } }\n  }\n\n  /// Candidates from a function of a value, unfolded.\n  public static func unfold(_ value: Element, _ shrink: @escaping (Element) -> [Element]) -> Tree<\n    Element\n  > {\n    Tree(value) { shrink(value).map { unfold($0, shrink) } }\n  }\n\n  /// At most a number of shrink steps, each trying at most a number of\n  /// candidates.\n  public func limit(_ steps: Int, _ width: Int) -> Tree<Element> {\n    let me = self\n    return Tree(value) {\n      steps <= 0 ? [] : try me.children().prefix(width).map { $0.limit(steps - 1, width) }\n    }\n  }\n}\n\n/// A generator: from a random state and a size, a value's shrink tree, or nil\n/// for an empty domain, which discards the whole tuple of inputs.\npublic struct Gen<Element> {\n  public let generate: (Random.Seed, Int) throws -> Tree<Element>?\n\n  public init(_ generate: @escaping (Random.Seed, Int) throws -> Tree<Element>?) {\n    self.generate = generate\n  }\n\n  public static func constant(_ value: Element) -> Gen<Element> { Gen { _, _ in .leaf(value) } }\n\n  /// An empty domain: the case is discarded and redrawn.\n  public static var empty: Gen<Element> { Gen { _, _ in nil } }\n\n  public func map<B>(_ f: @escaping (Element) throws -> B) -> Gen<B> {\n    let g = self\n    return Gen<B> { seed, size in try g.generate(seed, size)?.map(f) }\n  }\n\n  private static func bindTree<B>(\n    _ tree: Tree<Element>, _ k: @escaping (Element) throws -> Tree<B>?\n  ) throws -> Tree<B>? {\n    guard let inner = try k(tree.value) else { return nil }\n    return Tree<B>(inner.value) {\n      try tree.children().compactMap { try bindTree($0, k) } + (try inner.children())\n    }\n  }\n\n  /// A generator that depends on another's value. Shrinking the first value\n  /// regenerates the second from the same random state and size.\n  public func bind<B>(_ k: @escaping (Element) throws -> Gen<B>) -> Gen<B> {\n    let g = self\n    return Gen<B> { seed, size in\n      let (first, second) = Random.split(seed)\n      guard let tree = try g.generate(first, size) else { return nil }\n      return try Gen.bindTree(tree) { try k($0).generate(second, size) }\n    }\n  }\n\n  public static func sized(_ f: @escaping (Int) throws -> Gen<Element>) -> Gen<Element> {\n    Gen { seed, size in try f(size).generate(seed, size) }\n  }\n\n  public func resize(_ size: Int) -> Gen<Element> {\n    let g = self\n    return Gen { seed, _ in try g.generate(seed, size) }\n  }\n\n  /// Redraw until a predicate accepts the value, at most a number of times;\n  /// the accepted tree's candidates are filtered too.\n  private func retry(\n    _ predicate: @escaping (Element) throws -> Bool, _ limit: Int,\n    _ exhausted: @escaping () throws -> Tree<Element>?\n  ) -> Gen<Element> {\n    let g = self\n    return Gen { seed, size in\n      if limit <= 0 { return try exhausted() }\n      var state = seed\n      for _ in 0..<limit {\n        let (attempt, following) = Random.split(state)\n        state = following\n        if let tree = try g.generate(attempt, size), try predicate(tree.value) {\n          return tree.filter(predicate)\n        }\n      }\n      return try exhausted()\n    }\n  }\n\n  /// Keep values a predicate accepts, redrawing up to a limit; candidates\n  /// are filtered too.\n  public func constrain(_ limit: Int, _ predicate: @escaping (Element) throws -> Bool) -> Gen<\n    Element\n  > {\n    retry(predicate, limit) { nil }\n  }\n\n  /// A dependent input's domain: an impossible value discards the tuple, so\n  /// an earlier input is redrawn rather than retried in vain.\n  public func refine(_ predicate: @escaping (Element) throws -> Bool) -> Gen<Element> {\n    bind { value in try predicate(value) ? .constant(value) : .empty }\n  }\n\n  /// Draw until a predicate holds, failing the harness after a limit.\n  public func suchThat(\n    _ predicate: @escaping (Element) throws -> Bool, _ limit: Int,\n    _ onExhausted: @escaping () throws -> Void\n  ) -> Gen<Element> {\n    retry(predicate, limit + 1) {\n      try onExhausted()\n      return nil\n    }\n  }\n}\n\n/// Generators of LawSpec's building blocks.\npublic enum Gens {\n  private static let int64Range = BigInt(Int64.max) + .one\n\n  /// A uniform integer in [0, n), from the random state.\n  static func below(_ n: BigInt, _ seed: Random.Seed) -> BigInt {\n    if n <= .one { return .zero }\n    if n <= int64Range {\n      let (r, _) = Random.below(n, seed)\n      return r\n    }\n    // Enough 64-bit words that the remainder's bias is negligible.\n    let words = n.bitLength / 64 + 2\n    var total = BigInt.zero\n    var state = seed\n    for _ in 0..<words {\n      let (w, following) = Random.next(state)\n      state = following\n      total = (total << 64) + BigInt(w)\n    }\n    return total % n\n  }\n\n  private static func towards(_ origin: BigInt, _ value: BigInt) -> [BigInt] {\n    if value == origin { return [] }\n    var result = [origin]\n    var distance = (value - origin) / 2\n    while !distance.isZero {\n      result.append(value - distance)\n      distance = distance / 2\n    }\n    if (value - origin).magnitude > .one {\n      result.append(value > origin ? value - .one : value + .one)\n    }\n    var seen = [BigInt]()\n    return result.filter { candidate in\n      if seen.contains(candidate) { return false }\n      seen.append(candidate)\n      return true\n    }\n  }\n\n  /// An integer in an inclusive range, shrinking towards the value nearest\n  /// zero. An open end is limited by the size, exponentially, so large\n  /// magnitudes appear as the size grows.\n  public static func integer(_ lo: BigInt?, _ hi: BigInt?) -> Gen<BigInt> {\n    Gen { seed, size in\n      let reach = BigInt.one << Swift.min(64, 2 + size / 2)\n      let low = lo ?? (hi.map { BigInt.min(.zero, $0) - reach } ?? -reach)\n      let high = hi ?? (lo.map { BigInt.max(.zero, $0) + reach } ?? reach)\n      if low > high { return nil }\n      let origin = BigInt.min(BigInt.max(.zero, low), high)\n      let drawn = low + below(high - low + .one, seed)\n      return .unfold(drawn) { towards(origin, $0) }\n    }\n  }\n\n  public static func range(_ lo: Int, _ hi: Int) -> Gen<Int> {\n    integer(BigInt(lo), BigInt(hi)).map { $0.exactly(Int.self)! }\n  }\n\n  /// One of several generators, shrinking towards the earlier ones.\n  public static func oneOf<A>(_ gens: [Gen<A>]) -> Gen<A> {\n    if gens.isEmpty { return .empty }\n    return range(0, gens.count - 1).bind { gens[$0] }\n  }\n\n  /// A weighted choice, shrinking towards the earlier ones.\n  public static func frequency<A>(_ choices: [(Int, Gen<A>)]) -> Gen<A> {\n    let total = choices.reduce(0) { $0 + $1.0 }\n    if total <= 0 { return .empty }\n    return range(0, total - 1).bind { n in\n      var rest = n\n      for (weight, g) in choices {\n        if rest < weight { return g }\n        rest -= weight\n      }\n      return .empty\n    }\n  }\n\n  private static func sequenceTrees<A>(_ trees: [Tree<A>]) -> Tree<[A]> {\n    Tree(trees.map { $0.value }) {\n      var candidates = [Tree<[A]>]()\n      let n = trees.count\n      if n > 0 {\n        candidates.append(sequenceTrees([]))\n        if n > 1 { candidates.append(sequenceTrees(Array(trees.prefix(n / 2)))) }\n        for i in 0..<n {\n          var copy = trees\n          copy.remove(at: i)\n          candidates.append(sequenceTrees(copy))\n        }\n      }\n      for (i, t) in trees.enumerated() {\n        for child in try t.children() {\n          var copy = trees\n          copy[i] = child\n          candidates.append(sequenceTrees(copy))\n        }\n      }\n      return candidates\n    }\n  }\n\n  private static func productTrees<A>(_ trees: [Tree<A>]) -> Tree<[A]> {\n    Tree(trees.map { $0.value }) {\n      var candidates = [Tree<[A]>]()\n      for (i, t) in trees.enumerated() {\n        for child in try t.children() {\n          var copy = trees\n          copy[i] = child\n          candidates.append(productTrees(copy))\n        }\n      }\n      return candidates\n    }\n  }\n\n  /// Each generator's tree in order, or nil when any domain is empty.\n  private static func draws<A>(_ gens: [Gen<A>], _ seed: Random.Seed, _ size: Int) throws -> [Tree<\n    A\n  >]? {\n    var state = seed\n    var trees = [Tree<A>]()\n    for g in gens {\n      let (one, following) = Random.split(state)\n      state = following\n      guard let tree = try g.generate(one, size) else { return nil }\n      trees.append(tree)\n    }\n    return trees\n  }\n\n  /// A fixed number of values, each shrinking in place.\n  public static func vector<A>(_ count: Int, _ g: Gen<A>) -> Gen<[A]> {\n    Gen { seed, size in\n      try draws(Array(repeating: g, count: Swift.max(0, count)), seed, size).map(productTrees)\n    }\n  }\n\n  /// Values of several generators, in order.\n  public static func tuple<A>(_ gens: [Gen<A>]) -> Gen<[A]> {\n    Gen { seed, size in try draws(gens, seed, size).map(productTrees) }\n  }\n\n  /// A list of a length the size limits, shrinking by removing items and by\n  /// shrinking them.\n  public static func list<A>(_ g: Gen<A>) -> Gen<[A]> {\n    Gen { seed, size in\n      let (first, second) = Random.split(seed)\n      let count = below(BigInt(size + 1), first).exactly(Int.self)!\n      return try draws(Array(repeating: g, count: count), second, size).map(sequenceTrees)\n    }\n  }\n\n  /// A weighted mix of fixed values and a generator.\n  public static func withExamples<A>(_ examples: [A], _ g: Gen<A>) -> Gen<A> {\n    if examples.isEmpty { return g }\n    return frequency([(1, oneOf(examples.map { Gen.constant($0) })), (9, g)])\n  }\n}\n\nextension Gens {\n  /// A generator of one value.\n  public static func constant<A>(_ value: A) -> Gen<A> { .constant(value) }\n\n  /// A generator that depends on another's value.\n  public static func bind<A, B>(_ g: Gen<A>, _ k: @escaping (A) throws -> Gen<B>) -> Gen<B> {\n    g.bind(k)\n  }\n\n  public static func map<A, B>(_ f: @escaping (A) throws -> B, _ g: Gen<A>) -> Gen<B> { g.map(f) }\n\n  /// A dependent input's domain: values outside it discard the tuple.\n  public static func refine<A>(_ predicate: @escaping (A) throws -> Bool, _ g: Gen<A>) -> Gen<A> {\n    g.refine(predicate)\n  }\n\n  /// The item of a list at a position.\n  public static func nth<A>(_ index: Int, _ items: [A]) -> A { items[index] }\n}\n"
swiftSource "LawSpecTesting/Generators.swift" = "// Generation from a program's schema: scalars within their refinement\n// bounds, lists within their lengths, and data within a structural budget\n// that counts every node, so recursive types terminate without a hidden cap\n// and deep singletons stay reachable. Indexed families are solved backwards\n// from their target index. ref:DEC-structural-size-budget\n// ref:DEC-shrink-within-domain ref:DEC-indexed-families-as-evidence\n\nimport LawSpecRuntime\n\npublic enum Generators {\n  /// A comparison bound on an input, or on its length.\n  public enum Bound {\n    case compare(String, Value)\n    case length(String, Value)\n  }\n\n  /// A native generator for a data type, given generators for its arguments.\n  public typealias Factory = ([Gen<Value>]) throws -> Gen<Value>\n\n  /// What generation reads beyond the schema: native generator factories by\n  /// type name (from lawspec.json) and the attempts budget.\n  public struct Context {\n    public let schema: Schema\n    public let symbols: SymbolContext\n    public let factories: [String: Factory]\n    public let attempts: Int\n    public init(schema: Schema, symbols: SymbolContext, factories: [String: Factory], attempts: Int)\n    {\n      self.schema = schema\n      self.symbols = symbols\n      self.factories = factories\n      self.attempts = attempts\n    }\n  }\n\n  private struct MinimumKey: Hashable {\n    let program: ObjectIdentifier\n    let type: TypeRef\n    let limit: Int\n  }\n\n  private static let minimums = Locked([MinimumKey: Int?]())\n\n  private static func exactBound(_ value: Value) throws -> (BigInt, BigInt) {\n    let (n, d) = try Scalar.exact(value)\n    let (q, r) = n.quotientAndRemainder(dividingBy: d)\n    let floor = q - (n.isNegative && !r.isZero ? .one : .zero)\n    let ceil = floor + (r.isZero ? .zero : .one)\n    return (floor, ceil)\n  }\n\n  private static func lower(_ lo: BigInt?, _ n: BigInt) -> BigInt? {\n    lo.map { BigInt.max($0, n) } ?? n\n  }\n  private static func upper(_ hi: BigInt?, _ n: BigInt) -> BigInt? {\n    hi.map { BigInt.min($0, n) } ?? n\n  }\n\n  private static func limit(_ range: (BigInt?, BigInt?), _ bound: (String, Value)) throws -> (\n    BigInt?, BigInt?\n  ) {\n    let (lo, hi) = range\n    let (floor, ceil) = try exactBound(bound.1)\n    switch bound.0 {\n    case \">\": return (lower(lo, floor + .one), hi)\n    case \">=\": return (lower(lo, ceil), hi)\n    case \"<\": return (lo, upper(hi, ceil - .one))\n    case \"<=\": return (lo, upper(hi, floor))\n    case \"==\": return (lower(lo, ceil), upper(hi, floor))\n    default: return (lo, hi)\n    }\n  }\n\n  private static func lengths(_ bounds: [Bound]) -> [(String, Value)] {\n    bounds.compactMap { if case .length(let op, let v) = $0 { return (op, v) } else { return nil } }\n  }\n\n  private static func comparisons(_ bounds: [Bound]) -> [(String, Value)] {\n    bounds.compactMap {\n      if case .compare(let op, let v) = $0 { return (op, v) } else { return nil }\n    }\n  }\n\n  private static func lengthRange(_ bounds: [Bound]) throws -> (BigInt?, BigInt?) {\n    try lengths(bounds).reduce((BigInt.zero as BigInt?, nil as BigInt?)) { try limit($0, $1) }\n  }\n\n  private static func lengthAllowed(_ n: Int, _ bounds: [Bound]) throws -> Bool {\n    let (lo, hi) = try lengthRange(bounds)\n    let count = BigInt(n)\n    return (lo.map { count >= $0 } ?? true) && (hi.map { count <= $0 } ?? true)\n  }\n\n  private static func lengthGenerator(_ bounds: [Bound], _ size: Int) throws -> Gen<Int> {\n    let (lo, hi) = try lengthRange(bounds)\n    if let l = lo, let h = hi, l > h { return .empty }\n    let low = lo ?? .zero\n    return Gens.integer(low, upper(hi, BigInt.max(low, BigInt(size)))).map {\n      $0.exactly(Int.self) ?? Int.max\n    }\n  }\n\n  private static func sequenceOf<A>(_ element: Gen<A>, _ bounds: [Bound]) -> Gen<[A]> {\n    if lengths(bounds).isEmpty { return Gens.list(element) }\n    return Gen.sized { size in try lengthGenerator(bounds, size).bind { Gens.vector($0, element) } }\n  }\n\n  private static var unicodeScalar: Gen<BigInt> {\n    Gens.oneOf([\n      Gens.integer(.zero, BigInt(0xD7FF)), Gens.integer(BigInt(0xE000), BigInt(0x10FFFF)),\n    ])\n  }\n\n  private static func ieee(_ width: Int) -> Gen<Value> {\n    Gens.integer(.zero, (BigInt.one << width) - .one).map {\n      .float(width: width, bits: $0.truncated(UInt64.self))\n    }\n  }\n\n  private static func scalar(_ context: Context, _ t: TypeRef, _ bounds: [Bound]) throws -> Gen<\n    Value\n  > {\n    guard case .named(let name, let args) = t, args.isEmpty else {\n      throw Fail.with(\"NoGenerator\", Scalar.typeKey(t))\n    }\n    switch name {\n    case \"Bool\": return Gens.oneOf([.constant(.bool(false)), .constant(.bool(true))])\n    case \"Unit\": return .constant(.unit)\n    case \"Null\": return .constant(.null)\n    case \"Undefined\": return .constant(.undefined)\n    case \"Rational\":\n      return Gens.integer(nil, nil).bind { n in\n        Gens.integer(.one, nil).map { d in try Scalar.ratio(n, d) }\n      }\n    case \"Decimal\":\n      return Gens.integer(nil, nil).bind { c in\n        Gen.sized { size in Gens.range(-size, size).map { .decimal(c, $0) } }\n      }\n    case \"Float32\": return ieee(32)\n    case \"Float64\": return ieee(64)\n    case \"Complex64\", \"Complex128\":\n      let w = name == \"Complex64\" ? 32 : 64\n      return ieee(w).bind { r in ieee(w).map { i in .complex(width: w, real: r, imaginary: i) } }\n    case \"Char\": return unicodeScalar.map { .int($0) }\n    case \"CodePoint\": return Gens.integer(.zero, BigInt(0x10FFFF)).map { .int($0) }\n    case \"CodeUnit16\": return Gens.integer(.zero, BigInt(0xFFFF)).map { .int($0) }\n    case \"Text\":\n      return sequenceOf(unicodeScalar, bounds).map {\n        .text(try Scalar.textOfPoints($0.map { $0.exactly(Int.self)! }))\n      }\n    case \"Bytes\":\n      return sequenceOf(Gens.integer(.zero, BigInt(255)), bounds).map {\n        .bytes($0.map { $0.truncated(UInt8.self) })\n      }\n    case \"CodePointText\", \"Utf16Text\":\n      let top = name == \"CodePointText\" ? 0x10FFFF : 0xFFFF\n      return sequenceOf(Gens.integer(.zero, BigInt(top)), bounds).map {\n        .raw(kind: name, units: $0.map { $0.exactly(Int.self)! })\n      }\n    case \"Symbol\":\n      return Gens.integer(.zero, nil).map { n in\n        let key = n.description\n        return .symbol(context.symbols.identity(\"generated:\" + key), key)\n      }\n    default:\n      if Scalar.isIntegerType(name) {\n        let (lo, hi) = try comparisons(bounds).reduce(try Scalar.bounds(name, context.schema.bits))\n        { try limit($0, $1) }\n        if let l = lo, let h = hi, l > h { return .empty }\n        return Gens.integer(lo, hi).map { .int($0) }\n      }\n      throw Fail.with(\"NoGenerator\", Scalar.typeKey(t))\n    }\n  }\n\n  /// Whether a value is a member of its type, contracts included.\n  public static func accepted(_ value: Value, _ t: TypeRef, _ schema: Schema) throws -> Bool {\n    do {\n      _ = try Schema.validate(value, t, schema)\n      return true\n    } catch let failure as LawSpecError where failure.code == \"RefinementViolation\" {\n      return false\n    }\n  }\n\n  private static func valueNodes(_ value: Value) -> Int {\n    switch value {\n    case .data(_, let fields): return 1 + fields.reduce(0) { $0 + valueNodes($1) }\n    case .presence(_, let v?): return 1 + valueNodes(v)\n    case .list(let items): return 1 + items.reduce(0) { $0 + 1 + valueNodes($1) }\n    default: return 1\n    }\n  }\n\n  /// Sets and maps are canonical: sorted and without duplicate keys, also\n  /// after every shrink.\n  private static func canonical(_ t: TypeRef, _ value: Value) throws -> Value {\n    func distinctSorted(_ items: [Value], _ key: (Value) -> Value) throws -> [Value] {\n      let sorted = try items.sorted { try Scalar.compareValues(key($0), key($1)) < 0 }\n      var result = [Value]()\n      for item in sorted {\n        if let last = result.last, try Scalar.compareValues(key(last), key(item)) == 0 { continue }\n        result.append(item)\n      }\n      return result\n    }\n    switch (t, value) {\n    case (.named(\"lawspec.collections::type::EqSet\", _), .data(let tag, let f)):\n      if f.count == 1, case .list(let items) = f[0] {\n        var distinct = [Value]()\n        for item in items {\n          if !distinct.contains(where: { Scalar.equal(item, $0) }) { distinct.append(item) }\n        }\n        return .data(tag, [.list(distinct)])\n      }\n    case (.named(\"lawspec.collections::type::Set\", _), .data(let tag, let f)):\n      if f.count == 1, case .list(let items) = f[0] {\n        return .data(tag, [.list(try distinctSorted(items) { $0 })])\n      }\n    case (.named(\"lawspec.collections::type::KeyVal\", _), .data(let tag, let f)):\n      if f.count == 1, case .list(let entries) = f[0] {\n        return .data(\n          tag,\n          [\n            .list(\n              try distinctSorted(entries) { entry in\n                if case .data(_, let pair) = entry, pair.count == 2 { return pair[0] }\n                return entry\n              })\n          ])\n      }\n    default:\n      break\n    }\n    return value\n  }\n\n  private static func factory(_ context: Context, _ t: TypeRef) -> Factory? {\n    guard case .named(let name, _) = t else { return nil }\n    return context.factories[name]\n  }\n\n  private static func inhabited(_ context: Context, _ t: TypeRef, _ budget: Int) throws -> Bool {\n    if budget < 1 { return false }\n    if case .named(let name, _) = t, [\"List\", \"Optional\", \"Nullable\"].contains(name) {\n      return true\n    }\n    if factory(context, t) != nil { return true }\n    guard let cs = try Schema.constructors(t, context.schema) else { return true }\n    return try cs.flatMap(Schema.witnessInstances).contains { c in\n      try allocation(context, c.fields, budget - 1 - c.witnessValues.count) != nil\n    }\n  }\n\n  /// The least structural cost of a type, if it is at most the limit.\n  public static func minimum(_ context: Context, _ t: TypeRef, _ limit: Int) throws -> Int? {\n    if limit < 1 { return nil }\n    let key = MinimumKey(program: ObjectIdentifier(context.schema.program), type: t, limit: limit)\n    if let known = minimums.with({ $0[key] }) { return known }\n    var cost: Int? = nil\n    for c in 1...limit where try inhabited(context, t, c) {\n      cost = c\n      break\n    }\n    minimums.with { $0[key] = cost }\n    return cost\n  }\n\n  private static func costs(\n    _ context: Context, _ fields: ArraySlice<(String, TypeRef)>, _ budget: Int\n  ) throws -> [Int]? {\n    guard let (_, t) = fields.first else { return budget >= 0 ? [] : nil }\n    if budget < 1 { return nil }\n    guard let cost = try minimum(context, t, budget),\n      let more = try costs(context, fields.dropFirst(), budget - cost)\n    else { return nil }\n    return [cost] + more\n  }\n\n  /// Each field's budget: its minimum, plus an even share of what is left.\n  public static func allocation(_ context: Context, _ fields: [(String, TypeRef)], _ budget: Int)\n    throws -> [Int]?\n  {\n    guard let least = try costs(context, fields[...], budget) else { return nil }\n    if least.isEmpty { return [] }\n    let extra = budget - least.reduce(0, +)\n    let count = least.count\n    return least.enumerated().map { i, cost in cost + extra / count + (i < extra % count ? 1 : 0) }\n  }\n\n  private static func build(_ context: Context, _ t: TypeRef, _ budget: Int, _ bounds: [Bound])\n    throws -> Gen<Value>\n  {\n    if let f = factory(context, t) { return try custom(context, t, budget, bounds, f) }\n    return try buildNative(context, t, budget, bounds)\n  }\n\n  private static func custom(\n    _ context: Context, _ t: TypeRef, _ budget: Int, _ bounds: [Bound], _ f: Factory\n  ) throws -> Gen<Value> {\n    var args = [TypeRef]()\n    if case .named(_, let a) = t { args = a }\n    let children = try args.map { child -> Gen<Value> in\n      let available = Swift.max(1, budget - 1)\n      return try minimum(context, child, available) == nil\n        ? .empty : try build(context, child, available, [])\n    }\n    let checked = try f(children).map { try Schema.validate($0, t, context.schema) }\n    if bounds.isEmpty { return checked }\n    let key = Scalar.typeKey(t)\n    return checked.refine { v in\n      try bounds.allSatisfy { bound in\n        switch bound {\n        case .length(let op, let b):\n          let length = try Scalar.helper(\"length\", [v], [key], context.schema.bits)\n          return Scalar.equal(try Scalar.binary(op, length, b, \"Integer\", \"Integer\"), .bool(true))\n        case .compare(let op, let b):\n          return Scalar.equal(try Scalar.binary(op, v, b, key, key), .bool(true))\n        }\n      }\n    }\n  }\n\n  private static func buildNative(\n    _ context: Context, _ t: TypeRef, _ budget: Int, _ bounds: [Bound]\n  ) throws -> Gen<Value> {\n    if case .named(\"List\", let args) = t, args.count == 1 {\n      let element = args[0]\n      let limitCost = lengths(bounds).isEmpty ? budget - 1 : Swift.max(64, budget - 1)\n      guard let cost = try minimum(context, element, limitCost) else {\n        return Gen.constant(Value.list([])).refine { _ in try lengthAllowed(0, bounds) }\n      }\n      return try lengthGenerator(bounds, (budget - 1) / cost).bind { count in\n        if count == 0 { return .constant(.list([])) }\n        return Gens.vector(\n          count, try build(context, element, Swift.max(cost, (budget - 1) / count), [])\n        ).map { .list($0) }\n      }\n    }\n    if case .named(let kind, let args) = t, args.count == 1,\n      kind == \"Optional\" || kind == \"Nullable\"\n    {\n      let absent = Gen.constant(Value.presence(kind: kind, value: nil))\n      if try minimum(context, args[0], budget - 1) == nil { return absent }\n      return Gens.oneOf([\n        absent,\n        try build(context, args[0], budget - 1, []).map { .presence(kind: kind, value: $0) },\n      ])\n    }\n    guard let raw = try Schema.constructors(t, context.schema) else {\n      return try scalar(context, t, bounds)\n    }\n    var choices = [Gen<Value>]()\n    for c0 in raw {\n      for c in Schema.witnessInstances(c0) {\n        if let shares = try allocation(context, c.fields, budget - 1 - c.witnessValues.count) {\n          choices.append(constructorGen(context, c, shares))\n        }\n      }\n    }\n    let schema = context.schema\n    return Gens.oneOf(choices).map { try canonical(t, $0) }.constrain(context.attempts) {\n      try accepted($0, t, schema)\n    }\n  }\n\n  private static func constructorGen(_ context: Context, _ c: Schema.Constructor, _ shares: [Int])\n    -> Gen<Value>\n  {\n    func fields(_ remaining: ArraySlice<((String, TypeRef), Int)>, _ values: [Value]) throws -> Gen<\n      Value\n    > {\n      guard let (field, share) = remaining.first else {\n        return .constant(.data(c.tag, values + c.witnessValues))\n      }\n      let position = values.count + 1\n      let hints = try c.generators[position].map { try $0(context.schema, c.arguments, values) }\n      let bounds =\n        (hints?.bounds.map { Bound.compare($0.0, $0.1) } ?? [])\n        + (hints?.lengths.map { Bound.length($0.0, $0.1) } ?? [])\n      let native = try build(context, field.1, share, bounds)\n      let g =\n        factory(context, field.1) != nil ? native : Gens.withExamples(hints?.hints ?? [], native)\n      return g.bind { v in try fields(remaining.dropFirst(), values + [v]) }\n    }\n    return Gen { seed, size in\n      try fields(Array(zip(c.fields, shares))[...], []).generate(seed, size)\n    }\n  }\n\n  // MARK: Indexed families\n\n  private indirect enum Term {\n    case constant(BigInt)\n    case field(Int)\n    case op(String, Term, Term)\n  }\n\n  private static func tokens(_ text: String) -> [String] {\n    text.split(separator: \" \").map(String.init)\n  }\n\n  private static func parse(_ tokens: ArraySlice<String>) throws -> (Term, ArraySlice<String>) {\n    guard let t = tokens.first else { throw Fail.with(\"InvalidIndexTerm\") }\n    let rest = tokens.dropFirst()\n    if t.hasPrefix(\"c\"), let n = BigInt(String(t.dropFirst())) { return (.constant(n), rest) }\n    if t.hasPrefix(\"f\"), let i = Int(t.dropFirst()) { return (.field(i), rest) }\n    let (a, next) = try parse(rest)\n    let (b, after) = try parse(next)\n    return (.op(t, a, b), after)\n  }\n\n  private static func termFields(_ term: Term) -> [Int] {\n    switch term {\n    case .constant: return []\n    case .field(let i): return [i]\n    case .op(_, let a, let b): return termFields(a) + termFields(b)\n    }\n  }\n\n  private static func evaluate(_ term: Term, _ assigned: [Int: BigInt]) -> BigInt? {\n    switch term {\n    case .constant(let n): return n\n    case .field(let i): return assigned[i]\n    case .op(let op, let a, let b):\n      guard let x = evaluate(a, assigned), let y = evaluate(b, assigned) else { return nil }\n      switch op {\n      case \"+\": return x + y\n      case \"-\" where x >= y: return x - y\n      case \"*\": return x * y\n      case \"div\" where y.signum > 0: return x / y\n      case \"mod\" where y.signum > 0: return x % y\n      case \"^\" where y.signum >= 0 && y <= 64: return x.power(y.exactly(Int.self)!)\n      default: return nil\n      }\n    }\n  }\n\n  private struct Equation {\n    let term: Term\n    let guards: [(String, Term, Term)]\n    let positions: [Int]\n  }\n\n  private static func equation(_ texts: [String]) throws -> Equation {\n    guard let text = texts.first else { throw Fail.with(\"InvalidIndexTerm\") }\n    let (term, _) = try parse(tokens(text)[...])\n    let parsed = try texts.dropFirst().map { g -> (String, Term, Term) in\n      let parts = tokens(g)\n      guard let op = parts.first else { throw Fail.with(\"InvalidIndexGuard\", g) }\n      let (a, next) = try parse(parts.dropFirst())\n      let (b, _) = try parse(next)\n      return (op, a, b)\n    }\n    let all = termFields(term) + parsed.flatMap { termFields($0.1) + termFields($0.2) }\n    return Equation(term: term, guards: parsed, positions: Array(Set(all)).sorted())\n  }\n\n  private static func holds(_ g: (String, Term, Term), _ assigned: [Int: BigInt]) -> Bool {\n    guard let x = evaluate(g.1, assigned), let y = evaluate(g.2, assigned) else { return false }\n    return g.0 == \"==\" ? x == y : x >= y\n  }\n\n  private struct Level: Hashable {\n    let type: TypeRef\n    let index: Int\n  }\n\n  /// An indexed family's value whose index is the target (or, for a negative\n  /// target, any of its smallest reachable indices).\n  public static func indexed(\n    _ context: Context, _ t: TypeRef, _ target: BigInt, _ equations: [String: [String]],\n    _ budget: Int\n  ) throws -> Gen<Value> {\n    let parsed = try equations.mapValues(equation)\n    func positions(_ c: Schema.Constructor) -> [Int] { parsed[c.tag]?.positions ?? [] }\n    var all = [TypeRef: [Schema.Constructor]]()\n    var order = [TypeRef]()\n    var pending = [t]\n    while let next = pending.first {\n      pending.removeFirst()\n      if all[next] != nil { continue }\n      guard let cs = try Schema.constructors(next, context.schema)?.flatMap(Schema.witnessInstances)\n      else {\n        throw Fail.with(\"IndexedTypeRequiresData\", Scalar.typeKey(next))\n      }\n      all[next] = cs\n      order.append(next)\n      pending = cs.flatMap { c in positions(c).map { c.fields[$0].1 } } + pending\n    }\n    var plain = [TypeRef: Int?]()\n    for ft in order {\n      for c in all[ft]! {\n        for (i, field) in c.fields.enumerated() where !positions(c).contains(i) {\n          plain[field.1] = try minimum(context, field.1, 64)\n        }\n      }\n    }\n    let limitIndex = (BigInt.max(.zero, target).exactly(Int.self) ?? 0) + 16\n    func assignments(_ c: Schema.Constructor, _ costs: [Level: Int]) -> [(\n      Int, [Int: BigInt], [Int]\n    )] {\n      guard let eq = parsed[c.tag] else { return [] }\n      let ok = c.fields.enumerated().allSatisfy { i, field in\n        eq.positions.contains(i) || (plain[field.1] ?? nil) != nil\n      }\n      if !ok { return [] }\n      let choices = eq.positions.map { i -> (Int, [Int]) in\n        let ft = c.fields[i].1\n        return (i, costs.keys.filter { $0.type == ft }.map { $0.index }.sorted())\n      }\n      func assign(_ choices: ArraySlice<(Int, [Int])>, _ assigned: [Int: BigInt]) -> [[Int: BigInt]]\n      {\n        let ready = eq.guards.filter { g in\n          (termFields(g.1) + termFields(g.2)).allSatisfy { assigned[$0] != nil }\n        }\n        if !ready.allSatisfy({ holds($0, assigned) }) { return [] }\n        guard let (i, values) = choices.first else { return [assigned] }\n        return values.flatMap { v in\n          assign(choices.dropFirst(), assigned.merging([i: BigInt(v)]) { $1 })\n        }\n      }\n      var result = [(Int, [Int: BigInt], [Int])]()\n      for assigned in assign(choices[...], [:]) {\n        guard let value = evaluate(eq.term, assigned), value.signum >= 0,\n          value <= BigInt(limitIndex)\n        else { continue }\n        let required = c.fields.enumerated().map { i, field -> Int in\n          if let k = assigned[i] {\n            return costs[Level(type: field.1, index: k.exactly(Int.self)!)]!\n          }\n          return (plain[field.1] ?? nil)!\n        }\n        result.append((value.exactly(Int.self)!, assigned, required))\n      }\n      return result\n    }\n    var costs = [Level: Int]()\n    while true {\n      var next = costs\n      for ft in order {\n        for c in all[ft]! {\n          for (k, _, fields) in assignments(c, costs) {\n            let cost = 1 + c.witnessValues.count + fields.reduce(0, +)\n            let key = Level(type: ft, index: k)\n            if let existing = next[key], existing <= cost { continue }\n            next[key] = cost\n          }\n        }\n      }\n      if next == costs { break }\n      costs = next\n    }\n    var solutions = [Level: [(Schema.Constructor, [Int: BigInt], [Int])]]()\n    for ft in order {\n      for c in all[ft]! {\n        for (k, targets, fields) in assignments(c, costs) {\n          solutions[Level(type: ft, index: k), default: []].append((c, targets, fields))\n        }\n      }\n    }\n    let levels: [Int]\n    if target.isNegative {\n      levels = Array(costs.keys.filter { $0.type == t }.map { $0.index }.sorted().prefix(6))\n    } else {\n      let k = target.exactly(Int.self) ?? -1\n      levels = costs[Level(type: t, index: k)] != nil ? [k] : []\n    }\n    let schema = context.schema\n    func generate(_ ft: TypeRef, _ k: Int, _ share: Int) -> Gen<Value> {\n      let choices = (solutions[Level(type: ft, index: k)] ?? []).filter { c, _, fieldCosts in\n        1 + c.witnessValues.count + fieldCosts.reduce(0, +) <= share\n      }\n      return Gens.oneOf(choices.map { Gen.constant($0) }).bind { choice in\n        let (c, targets, fieldCosts) = choice\n        let count = fieldCosts.count\n        let extra = share - 1 - c.witnessValues.count - fieldCosts.reduce(0, +)\n        let children = try zip(c.fields, fieldCosts).enumerated().map { i, pair -> Gen<Value> in\n          let ((_, childType), cost) = pair\n          let childShare = cost + (count > 0 ? extra / count + (i < extra % count ? 1 : 0) : 0)\n          if let index = targets[i] {\n            return generate(childType, index.exactly(Int.self)!, childShare)\n          }\n          return try build(context, childType, childShare, [])\n        }\n        return Gens.tuple(children).map { .data(c.tag, $0 + c.witnessValues) }\n      }.constrain(context.attempts) { try accepted($0, ft, schema) }\n    }\n    if levels.isEmpty {\n      if target.isNegative { throw Fail.with(\"NoIndexedGenerator\", Scalar.typeKey(t)) }\n      return .empty\n    }\n    return Gens.oneOf(levels.map { Gen.constant($0) }).bind { k in\n      generate(t, k, Swift.max(budget, costs[Level(type: t, index: k)]!))\n    }\n  }\n\n  /// A bound on an input.\n  public static func compareBound(_ op: String, _ value: Value) -> Bound { .compare(op, value) }\n\n  /// A bound on an input's length.\n  public static func lengthBound(_ op: String, _ value: Value) -> Bound { .length(op, value) }\n\n  /// An indexed family's target index and each constructor's index terms.\n  public struct IndexTarget {\n    let target: BigInt\n    let equations: [String: [String]]\n  }\n\n  /// No index to aim at.\n  public static func noIndex() -> IndexTarget? { nil }\n\n  /// An indexed family's target index and each constructor's index terms.\n  public static func index(_ target: Value, _ tags: [String], _ terms: [[String]]) throws\n    -> IndexTarget?\n  {\n    guard case .int(let n) = target else { throw Fail.with(\"IntegerRequired\", \"index target\") }\n    return IndexTarget(target: n, equations: Dictionary(zip(tags, terms), uniquingKeysWith: { $1 }))\n  }\n\n  /// The generator of an input of a type: native factories first, then the\n  /// type's structure within a budget that grows with the size.\n  public static func generator(\n    _ context: Context, _ t: TypeRef, _ bounds: [Bound], _ witnesses: [Value], _ index: IndexTarget?\n  ) -> Gen<Value> {\n    Gen.sized { size in\n      if let f = factory(context, t) { return try custom(context, t, size + 1, bounds, f) }\n      let limit = ([64] + witnesses.map(valueNodes)).max()!\n      guard let least = try minimum(context, t, limit) else {\n        throw Fail.with(\"NoStructuralGenerator\", Scalar.typeKey(t))\n      }\n      let budget = Swift.max(least, size + 1)\n      if let target = index {\n        return try indexed(context, t, target.target, target.equations, budget)\n      }\n      return Gens.withExamples(witnesses, try build(context, t, budget, bounds))\n    }\n  }\n}\n"
swiftSource "LawSpecTesting/Harness.swift" = "// The harness plane in Swift: how often a law runs, how long it may take,\n// whether its cases were adequate (cover, classify, labels), targeted search\n// scores, known failures, skips and benchmarks. Statistics go to\n// LAWSPEC_STATS as the same JSON records every target writes.\n// ref:REQ-harness-units ref:DEC-never-pass-vacuously\n\nimport CryptoKit\nimport Foundation\nimport LawSpecRuntime\n\n/// A JSON value, its object keys in the order they were set.\npublic indirect enum JSON {\n  case string(String)\n  case number(Double)\n  case integer(Int)\n  case bool(Bool)\n  case null\n  case array([JSON])\n  case object([(String, JSON)])\n\n  public var text: String {\n    switch self {\n    case .string(let s): return Defaults.jsonText(s)\n    case .number(let d): return d == d.rounded() && abs(d) < 1e15 ? String(Int(d)) : String(d)\n    case .integer(let n): return String(n)\n    case .bool(let b): return b ? \"true\" : \"false\"\n    case .null: return \"null\"\n    case .array(let items): return \"[\" + items.map { $0.text }.joined(separator: \",\") + \"]\"\n    case .object(let fields):\n      return \"{\" + fields.map { Defaults.jsonText($0.0) + \":\" + $0.1.text }.joined(separator: \",\")\n        + \"}\"\n    }\n  }\n\n  /// The object with a field set (replaced in place, or added last).\n  public func setting(_ key: String, _ value: JSON) -> JSON {\n    guard case .object(var fields) = self else { return self }\n    if let i = fields.firstIndex(where: { $0.0 == key }) {\n      fields[i].1 = value\n    } else {\n      fields.append((key, value))\n    }\n    return .object(fields)\n  }\n\n  public func removing(_ key: String) -> JSON {\n    guard case .object(let fields) = self else { return self }\n    return .object(fields.filter { $0.0 != key })\n  }\n\n  public subscript(key: String) -> JSON? {\n    guard case .object(let fields) = self else { return nil }\n    return fields.first { $0.0 == key }?.1\n  }\n}\n\nextension Defaults {\n  /// A JSON string literal.\n  static func jsonText(_ s: String) -> String { jsonString(s) }\n}\n\n/// A value each thread sees its own of.\npublic final class ThreadLocal<T>: @unchecked Sendable {\n  private let key = \"lawspec.local.\" + UUID().uuidString\n  private let initial: T\n  public init(_ initial: T) { self.initial = initial }\n  public var value: T {\n    get { (Thread.current.threadDictionary[key] as? Box)?.value ?? initial }\n    set { Thread.current.threadDictionary[key] = Box(newValue) }\n  }\n  private final class Box {\n    let value: T\n    init(_ value: T) { self.value = value }\n  }\n}\n\npublic enum Harness {\n  /// What one generated case observed: cover predicates, classifications,\n  /// labels and a target score.\n  public struct Observation {\n    let covers: [Value]\n    let classes: [(String, Value)]\n    let labels: [Value]\n    let score: Value?\n  }\n\n  final class State: @unchecked Sendable {\n    let law: String\n    let test: String\n    var failed = false\n    var cases = 0\n    var cover: [Int]\n    var classes: [String: Int] = [:]\n    var labels: [String: Int] = [:]\n    var target = false\n    var best: Value? = nil\n    var aborted: (any Error)? = nil\n    var extra: [(String, JSON)] = []\n    let gate = NSRecursiveLock()\n    init(law: String, test: String, covers: Int) {\n      self.law = law\n      self.test = test\n      self.cover = Array(repeating: 0, count: covers)\n    }\n  }\n\n  static let current = ThreadLocal<State?>(nil)\n\n  /// Fail the harness itself (not the law): a strategy outside its input's\n  /// refinement, a discard budget spent, a broken cover clause.\n  public static func abort(_ code: String, _ detail: String) -> LawSpecError {\n    let failure = LawSpecError(code, detail)\n    if let state = current.value {\n      state.gate.lock()\n      if state.aborted == nil { state.aborted = failure }\n      state.gate.unlock()\n    }\n    return failure\n  }\n\n  /// Mark a failure as the harness's, keeping the failure itself.\n  public static func markHarnessFailure(_ failure: any Error) {\n    if let state = current.value {\n      state.gate.lock()\n      if state.aborted == nil { state.aborted = failure }\n      state.gate.unlock()\n    }\n  }\n\n  private static func boolean(_ value: Value) throws -> Bool {\n    guard case .bool(let b) = value else { throw abort(\"InvalidHarnessPredicate\", \"\\(value)\") }\n    return b\n  }\n\n  /// Whether a score beats the best so far; a NaN never does.\n  public static func higher(_ score: Value, _ best: Value?) throws -> Bool {\n    switch score {\n    case .float:\n      if try Scalar.floatClass(score) == \"nan\" { return false }\n      guard let other = best else { return true }\n      return try Scalar.floatCompare(score, other) == 1\n    case .int, .ratio, .decimal:\n      guard let other = best else { return true }\n      return try Scalar.compareValues(score, other) == 1\n    default:\n      throw abort(\"InvalidTargetScore\", \"\\(score)\")\n    }\n  }\n\n  /// A score as the reports print it.\n  public static func scoreText(_ score: Value) -> String {\n    switch score {\n    case .int(let n): return n.description\n    case .ratio(let n, let d): return \"\\(n)/\\(d)\"\n    case .decimal(let c, let e): return \"\\(c)e\\(e)\"\n    case .float(let w, let b):\n      switch (try? Scalar.floatClass(score)) ?? \"\" {\n      case \"nan\": return \"NaN\"\n      case \"infinity\": return (b >> UInt64(w - 1)) == 0 ? \"Infinity\" : \"-Infinity\"\n      default: return roundTrip((try? Scalar.toDouble(score)) ?? 0)\n      }\n    default: return Recorded.debug(score)\n    }\n  }\n\n  /// The shortest text that reads back as the same double, as .NET's \"R\".\n  static func roundTrip(_ d: Double) -> String {\n    if d == d.rounded() && abs(d) < 1e15 { return String(Int(d)) }\n    return \"\\(d)\"\n  }\n\n  private static func observe(_ state: State, _ o: Observation) throws {\n    if o.covers.count != state.cover.count { throw abort(\"InvalidHarnessCoverObservation\", \"\") }\n    for (i, holds) in o.covers.enumerated() where try boolean(holds) { state.cover[i] += 1 }\n    for (label, _) in o.classes where state.classes[label] == nil { state.classes[label] = 0 }\n    var counted = Set<String>()\n    for (label, holds) in o.classes where try boolean(holds) && !counted.contains(label) {\n      counted.insert(label)\n      state.classes[label, default: 0] += 1\n    }\n    var seen = Set<String>()\n    for label in o.labels {\n      guard case .text(let s) = label else { throw abort(\"InvalidHarnessLabel\", \"\\(label)\") }\n      if seen.insert(s).inserted { state.labels[s, default: 0] += 1 }\n    }\n    if let score = o.score {\n      state.target = true\n      if try higher(score, state.best) { state.best = score }\n    }\n  }\n\n  /// What a case observed.\n  public static func observation(\n    _ covers: [Value], _ classes: [(String, Value)], _ labels: [Value], _ score: Value?\n  ) -> Observation {\n    Observation(covers: covers, classes: classes, labels: labels, score: score)\n  }\n\n  /// One generated case: count it, record what it observed, then run it. After\n  /// the first failure only the law runs (shrinking does not count cases).\n  public static func sample(_ observation: () throws -> Observation, _ test: () throws -> Value)\n    throws -> Value\n  {\n    guard let state = current.value else { throw Fail.with(\"HarnessObservationOutsideRun\") }\n    state.gate.lock()\n    defer { state.gate.unlock() }\n    if state.failed {\n      _ = try observation()\n      return try test()\n    }\n    state.cases += 1\n    do {\n      try observe(state, observation())\n      return try test()\n    } catch {\n      state.failed = true\n      throw error\n    }\n  }\n\n  private static func percentage(_ n: Int, _ cases: Int) -> Double {\n    cases == 0 ? 0 : (10000.0 * Double(n) / Double(cases)).rounded() / 100.0\n  }\n\n  private static func statsDirectory() -> String? {\n    guard let directory = ProcessInfo.processInfo.environment[\"LAWSPEC_STATS\"], !directory.isEmpty\n    else { return nil }\n    return directory\n  }\n\n  static func hexDigest(_ text: String) -> String {\n    SHA256.hash(data: Data(text.utf8)).map { String(format: \"%02X\", $0) }.joined()\n  }\n\n  /// Write a JSON file atomically: a temporary file, then a rename.\n  static func writeAtomically(_ path: String, _ text: String) {\n    let temporary = path + \".\\(ProcessInfo.processInfo.processIdentifier).\\(UUID().uuidString).tmp\"\n    defer { try? FileManager.default.removeItem(atPath: temporary) }\n    do {\n      try text.write(toFile: temporary, atomically: false, encoding: .utf8)\n      if FileManager.default.fileExists(atPath: path) {\n        _ = try FileManager.default.replaceItemAt(\n          URL(fileURLWithPath: path), withItemAt: URL(fileURLWithPath: temporary))\n      } else {\n        try FileManager.default.moveItem(atPath: temporary, toPath: path)\n      }\n    } catch {\n      FileHandle.standardError.write(Data(\"LawSpec could not write \\(path): \\(error)\\n\".utf8))\n    }\n  }\n\n  static func writeRecord(_ identity: String, _ record: JSON) {\n    guard let directory = statsDirectory() else { return }\n    try? FileManager.default.createDirectory(atPath: directory, withIntermediateDirectories: true)\n    writeAtomically(\n      URL(fileURLWithPath: directory).appendingPathComponent(hexDigest(identity) + \".json\").path,\n      record.text)\n  }\n\n  /// The expected-failure context of a `known failing` law.\n  final class Expected: @unchecked Sendable {\n    let law: String\n    var checks: [JSON] = []\n    var aborted: (any Error)? = nil\n    init(law: String) { self.law = law }\n  }\n\n  static let expected = ThreadLocal<Expected?>(nil)\n\n  private static func commit(_ record: JSON) {\n    guard case .string(let law)? = record[\"law\"] else { return }\n    if let e = expected.value, e.law == law {\n      e.checks.append(record)\n      if case .string(\"harness\")? = record[\"failureKind\"], e.aborted == nil {\n        e.aborted = LawSpecError(\"HarnessFailed\", law)\n      }\n      return\n    }\n    guard case .string(let test)? = record[\"test\"] else { return }\n    writeRecord(law + \"\\u{0}\" + test, record)\n  }\n\n  private struct CoverRow {\n    let label: String\n    let required: Int\n    let observed: Double\n    let hits: Int\n    let cases: Int\n    let met: Bool\n  }\n\n  private static func coverRows(_ covers: [(Int, String)], _ state: State) -> [CoverRow] {\n    zip(covers, state.cover).map { cover, n in\n      CoverRow(\n        label: cover.1, required: cover.0, observed: percentage(n, state.cases), hits: n,\n        cases: state.cases,\n        met: state.cases > 0 && 100 * n >= cover.0 * state.cases)\n    }\n  }\n\n  private static func fixed(_ d: Double) -> String { String(format: \"%.2f\", d) }\n\n  private static func reportText(_ state: State, _ rows: [CoverRow]) -> String {\n    var text = \"\\(state.law): \\(state.cases) generated case(s)\\n\"\n    for row in rows {\n      let shortfall = row.met ? \"\" : \" (not met; \\(row.hits)/\\(row.cases) cases)\"\n      text += \"  cover \\(row.required)% \\\"\\(row.label)\\\": \\(fixed(row.observed))%\\(shortfall)\\n\"\n    }\n    for label in state.classes.keys.sorted(by: { Scalar.compareText($0, $1) < 0 }) {\n      text += \"  \\(label): \\(fixed(percentage(state.classes[label]!, state.cases)))%\\n\"\n    }\n    for label in state.labels.keys.sorted(by: { Scalar.compareText($0, $1) < 0 }) {\n      text += \"  label \\(label): \\(fixed(percentage(state.labels[label]!, state.cases)))%\\n\"\n    }\n    if state.target, let best = state.best {\n      text += \"  best target score: \" + scoreText(best) + \"\\n\"\n    }\n    return text\n  }\n\n  private static func report(_ state: State, _ rows: [CoverRow]) -> JSON {\n    let cover = JSON.array(\n      rows.map { row in\n        .object([\n          (\"label\", .string(row.label)), (\"required\", .integer(row.required)),\n          (\"observed\", .number(row.observed)),\n          (\"hits\", .integer(row.hits)), (\"cases\", .integer(row.cases)), (\"met\", .bool(row.met)),\n        ])\n      })\n    let classes = JSON.object(\n      state.classes.keys.sorted { Scalar.compareText($0, $1) < 0 }.map {\n        ($0, .integer(state.classes[$0]!))\n      })\n    let labels = JSON.object(\n      state.labels.keys.sorted { Scalar.compareText($0, $1) < 0 }.map {\n        ($0, .integer(state.labels[$0]!))\n      })\n    var o = JSON.object([\n      (\"law\", .string(state.law)), (\"test\", .string(state.test)), (\"attempts\", .integer(1)),\n      (\"cases\", .integer(state.cases)), (\"cover\", cover), (\"classes\", classes), (\"labels\", labels),\n    ])\n    if state.target {\n      o = o.setting(\n        \"target\", .object([(\"best\", state.best.map { .string(scoreText($0)) } ?? .null)]))\n    }\n    for (k, v) in state.extra { o = o.setting(k, v) }\n    return o\n  }\n\n  /// Options of a controlled run.\n  public struct Options {\n    let repeatCount: Int\n    let retries: Int\n    let timeout: Int?\n    let resources: Bool\n    let observed: Bool\n  }\n\n  /// A controlled run's options.\n  public static func options(\n    _ repeatCount: Int, _ retries: Int, _ timeout: Int?, _ resources: Bool, _ observed: Bool\n  ) -> Options {\n    Options(\n      repeatCount: repeatCount, retries: retries, timeout: timeout, resources: resources,\n      observed: observed)\n  }\n\n  private static func execute(\n    _ law: String, _ options: Options, _ test: @escaping () throws -> Void\n  ) -> (any Error)? {\n    guard let ms = options.timeout else {\n      do {\n        try test()\n        return nil\n      } catch {\n        return error\n      }\n    }\n    let state = current.value\n    let outcome = Locked<(any Error)??>(nil)\n    let done = DispatchSemaphore(value: 0)\n    let work = UncheckedBox(test)\n    let carried = UncheckedBox(state)\n    LawThread.start {\n      current.value = carried.value\n      var failure: (any Error)? = nil\n      do { try work.value() } catch { failure = error }\n      outcome.with { $0 = .some(failure) }\n      done.signal()\n    }\n    if done.wait(timeout: .now() + .milliseconds(ms)) == .timedOut {\n      let failure = LawSpecError(\"TestTimeout\", \"\\(law) did not finish within \\(ms) ms\")\n      markHarnessFailure(failure)\n      return failure\n    }\n    return outcome.with { $0 } ?? nil\n  }\n\n  /// Run a test under the harness: each repeat is a complete check with its\n  /// own counters, and a retry starts the repeats again. Coverage is never\n  /// pooled across runs.\n  public static func run(\n    _ law: String, _ name: String, _ covers: [(Int, String)], _ options: Options,\n    _ test: @escaping () throws -> Void\n  ) throws {\n    let previous = current.value\n    defer { current.value = previous }\n    var history = [JSON]()\n    var attempt = 1\n    while true {\n      var outcome: (any Error)? = nil\n      var retryable = true\n      var reportObject = JSON.object([])\n      var repetition = 1\n      while true {\n        let state = State(law: law, test: name, covers: covers.count)\n        current.value = state\n        let failure = execute(law, options, test)\n        let rows = coverRows(covers, state)\n        let unmet = rows.filter { !$0.met }\n        reportObject =\n          options.observed\n          ? report(state, rows) : .object([(\"law\", .string(law)), (\"test\", .string(name))])\n        let text = options.observed ? reportText(state, rows) : \"\"\n        if options.observed { print(text, terminator: \"\") }\n        switch (failure, state.aborted, unmet.isEmpty) {\n        case (nil, let cause?, _):\n          outcome = cause\n          retryable = false\n        case (nil, nil, false):\n          outcome = LawSpecError(\"HarnessFailed\", law + \": UnmetCover\\n\" + text)\n          retryable = false\n        case (let e?, _?, _):\n          outcome = e\n          retryable = false\n        case (let e?, nil, _):\n          if options.observed && !covers.isEmpty {\n            outcome = LawSpecError(\"PropertyFailed\", \"\\(e)\\n\" + text, cause: \"\\(e)\")\n          } else {\n            outcome = e\n          }\n          retryable = true\n        case (nil, nil, true):\n          outcome = nil\n          retryable = true\n        }\n        let run = reportObject.removing(\"law\").removing(\"test\").removing(\"attempts\")\n          .setting(\"attempt\", .integer(attempt)).setting(\"repetition\", .integer(repetition))\n          .setting(\"outcome\", .string(outcome == nil ? \"passed\" : \"failed\"))\n        history.append(run)\n        if outcome == nil && repetition < options.repeatCount {\n          repetition += 1\n          continue\n        }\n        break\n      }\n      if outcome != nil && retryable && attempt <= options.retries {\n        attempt += 1\n        continue\n      }\n      let status = outcome == nil ? (attempt > 1 ? \"flaky\" : \"passed\") : \"failed\"\n      reportObject = reportObject.setting(\"outcome\", .string(status)).setting(\n        \"attempts\", .integer(attempt))\n      if !retryable { reportObject = reportObject.setting(\"failureKind\", .string(\"harness\")) }\n      if options.repeatCount != 1 || options.retries != 0 {\n        reportObject = reportObject.setting(\"repeat\", .integer(options.repeatCount)).setting(\n          \"runs\", .array(history))\n      }\n      commit(reportObject)\n      if let e = outcome { throw e }\n      if status == \"flaky\" {\n        print(\"\\(law) is flaky: it failed, then passed on attempt \\(attempt)\")\n      }\n      return\n    }\n  }\n\n  /// Record extra fields (a search's report) in the running test's record.\n  public static func record(_ fields: [(String, JSON)]) {\n    guard let state = current.value else { return }\n    for (k, v) in fields {\n      if let i = state.extra.firstIndex(where: { $0.0 == k }) {\n        state.extra[i].1 = v\n      } else {\n        state.extra.append((k, v))\n      }\n    }\n  }\n\n  /// A skipped law, recorded and reported.\n  public static func skip(_ law: String, _ reason: String) {\n    FileHandle.standardError.write(Data(\"SKIPPED \\(law): \\(reason)\\n\".utf8))\n    commit(\n      .object([\n        (\"law\", .string(law)), (\"test\", .string(law + \" skipped\")), (\"outcome\", .string(\"skipped\")),\n        (\"reason\", .string(reason)),\n      ]))\n  }\n\n  /// A law known to fail: its checks must fail, and a law that passes fails\n  /// the run so the mark is removed.\n  public static func knownFailing(\n    _ law: String, _ name: String, _ reason: String, _ checks: [() throws -> Void]\n  ) throws {\n    let previous = expected.value\n    let context = Expected(law: law)\n    expected.value = context\n    var failure: (any Error)? = nil\n    do {\n      for check in checks { try check() }\n    } catch {\n      failure = error\n    }\n    expected.value = previous\n    func record(_ outcome: String, _ extra: [(String, JSON)]) {\n      let o = JSON.object(\n        [\n          (\"law\", .string(law)), (\"test\", .string(name)), (\"reason\", .string(reason)),\n          (\"outcome\", .string(outcome)),\n        ] + extra)\n      commit(o.setting(\"checks\", .array(context.checks)))\n    }\n    switch (failure, context.aborted) {\n    case (nil, nil):\n      record(\"known-failing-passed\", [])\n      let message =\n        \"\\(law) is marked known failing (\\(reason)), but it passes; remove `known failing` from its harness\"\n      FileHandle.standardError.write(Data((message + \"\\n\").utf8))\n      throw LawSpecError(\"KnownFailingPassed\", message)\n    case (let e?, nil):\n      record(\"known-failing\", [(\"failure\", .string(\"\\(e)\"))])\n      print(\"\\(law) is known to fail (\\(reason)): \\(e)\")\n    case (let e?, _?):\n      record(\"failed\", [(\"failureKind\", .string(\"harness\")), (\"failure\", .string(\"\\(e)\"))])\n      throw e\n    case (nil, let cause?):\n      record(\"failed\", [(\"failureKind\", .string(\"harness\"))])\n      throw cause\n    }\n  }\n\n  /// Measure a body: at least three iterations, about 200 ms, at most 100,000.\n  public static func benchmark(_ unitName: String, _ name: String, _ body: () throws -> Void) throws\n  {\n    let clock = ContinuousClock()\n    let started = clock.now\n    func nanoseconds(_ d: Duration) -> Int64 {\n      d.components.seconds * 1_000_000_000 + d.components.attoseconds / 1_000_000_000\n    }\n    var count: Int64 = 0\n    var total: Int64 = 0\n    var fastest = Int64.max\n    while count < 100_000 {\n      let before = clock.now\n      if count >= 3 && nanoseconds(before - started) >= 200_000_000 { break }\n      try body()\n      let elapsed = nanoseconds(clock.now - before)\n      fastest = Swift.min(fastest, elapsed)\n      total += elapsed\n      count += 1\n    }\n    let mean = total / Swift.max(1, count)\n    writeRecord(\n      \"benchmark\\u{0}\" + unitName + \"\\u{0}\" + name,\n      .object([\n        (\"benchmark\", .string(name)), (\"unit\", .string(unitName)),\n        (\"iterations\", .integer(Int(count))),\n        (\"mean_ns\", .integer(Int(mean))), (\"min_ns\", .integer(Int(fastest))),\n      ]))\n    print(\n      \"benchmark \\(name): \\(count) iteration(s), mean \\(fixed(Double(mean) / 1000.0)) us, fastest \\(fixed(Double(fastest) / 1000.0)) us\"\n    )\n  }\n\n  /// Record that a parallel unit ran.\n  public static func recordParallel(_ unitName: String, _ fields: [(String, JSON)]) {\n    writeRecord(\"parallel\\u{0}\" + unitName, .object([(\"parallel\", .string(unitName))] + fields))\n  }\n}\n"
swiftSource "LawSpecTesting/History.swift" = "// Scenario histories carry vector clocks through sends, receives and\n// fork/join. Consistency depends on these message edges as well as each\n// caller's own order; real time is required only for linearizability.\n// ref:DEC-sessions-by-construction ref:DEC-stateful-models-linearizability\n// ref:wing-gong-linearizability\n\nimport LawSpecRuntime\n\n/// A search position: which events are done (as bits or positions) and the\n/// model state there, compared structurally.\nstruct SearchKey: Hashable {\n  let done: [Int]\n  let state: Value\n  static func == (a: SearchKey, b: SearchKey) -> Bool {\n    a.done == b.done && Recorded.identical(a.state, b.state)\n  }\n  func hash(into hasher: inout Hasher) {\n    hasher.combine(done)\n    state.portableHash(into: &hasher)\n  }\n}\n\npublic enum History {\n  /// A completed call: the model command it ran, its arguments and result, its\n  /// interval on the shared clock, its process and its vector clocks.\n  public struct Event {\n    public let command: Int\n    public let arguments: [Value]\n    public let result: Value\n    public let called: Int64\n    public let returned: Int64\n    public let process: String\n    public let callClock: [String: Int64]\n    public let returnClock: [String: Int64]\n    public init(\n      command: Int, arguments: [Value], result: Value, called: Int64, returned: Int64,\n      process: String,\n      callClock: [String: Int64], returnClock: [String: Int64]\n    ) {\n      self.command = command\n      self.arguments = arguments\n      self.result = result\n      self.called = called\n      self.returned = returned\n      self.process = process\n      self.callClock = callClock\n      self.returnClock = returnClock\n    }\n  }\n\n  /// Whether a's return happened before b's call, by their vector clocks.\n  public static func happenedBefore(_ a: Event, _ b: Event) -> Bool {\n    a.returnClock.allSatisfy { proc, count in (b.callClock[proc] ?? 0) >= count }\n  }\n\n  private static func before(_ mode: String, _ a: Event, _ b: Event) -> Bool {\n    mode == \"linearizable\" ? a.returned < b.called : happenedBefore(a, b)\n  }\n\n  private static func mask<S: Sequence>(_ indices: S) -> Set<Int> where S.Element == Int {\n    Set(indices)\n  }\n\n  private static func search(\n    _ model: Model.Machine, _ context: Model.Context, _ history: [Event], _ preds: [Set<Int>],\n    _ members: [Int], _ checked: Set<Int>, _ expected: Value, _ judge: (Value) -> Bool\n  ) -> Bool {\n    let full = mask(members)\n    var seen = Set<SearchKey>()\n    func visit(_ done: Set<Int>, _ state: Value) -> Bool {\n      if done == full { return judge(state) }\n      if !seen.insert(SearchKey(done: done.sorted(), state: state)).inserted { return false }\n      for i in members {\n        let dependencies = preds[i].intersection(full)\n        let available = !done.contains(i) && dependencies.isSubset(of: done)\n        if !available { continue }\n        let e = history[i]\n        guard let c = try? Model.command(model, e.command) else { continue }\n        guard let (next, wanted) = Model.step(c, context, e.arguments, state) else { continue }\n        let ignore = !checked.contains(i) || c.returnsUnit\n        if (ignore || Scalar.equal(e.result, wanted)) && visit(done.union([i]), next) {\n          return true\n        }\n      }\n      return false\n    }\n    return visit([], expected)\n  }\n\n  /// Whether a history has an order consistent with the model: real time for\n  /// linearizability, message order otherwise; causal histories are checked\n  /// in each process's view. Final is the system's abstract final state, if any.\n  public static func consistent(\n    _ model: Model.Machine, _ context: Model.Context, _ events: [Event], _ expected: Value,\n    _ final: Value?, _ system: Any\n  ) -> Bool {\n    let history = events\n    let indices = Array(history.indices)\n    let mode = model.consistency\n    let preds = indices.map { i in\n      mask(indices.filter { j in j != i && before(mode, history[j], history[i]) })\n    }\n    func judge(_ compareFinal: Bool, _ state: Value) -> Bool {\n      if compareFinal, let actual = final, !Scalar.equal(actual, state) { return false }\n      return (try? Model.checkState(Model.withoutAbstraction(model), context, system, state)) != nil\n    }\n    if mode == \"causal\" {\n      let processes = Array(Set(events.map { $0.process })).sorted {\n        Scalar.compareText($0, $1) < 0\n      }\n      if processes.isEmpty { return judge(false, expected) }\n      return processes.allSatisfy { proc in\n        let own = indices.filter { history[$0].process == proc }\n        var visible = own\n        for j in indices {\n          for i in own where j != i && happenedBefore(history[j], history[i]) { visible.append(j) }\n        }\n        let members = Array(Set(visible)).sorted()\n        return search(model, context, history, preds, members, mask(own), expected) {\n          judge(false, $0)\n        }\n      }\n    }\n    let checked: Set<Int> = mode == \"eventual\" ? [] : mask(indices)\n    return search(model, context, history, preds, indices, checked, expected) { judge(true, $0) }\n  }\n}\n"
swiftSource "LawSpecTesting/Model.swift" = "// Portable stateful model runs over checked logical callbacks. A fresh\n// context owns each generation, replay and shrink attempt, so no handler\n// state or workflow state is shared between attempts. The draws, the\n// rejected reference steps, the crash injection of actor models and the\n// shrink order are those of every other runtime, so one seed replays one\n// run on every target. ref:DEC-stateful-models-linearizability\n// ref:DEC-portable-seeded-generation ref:DEC-shrink-within-domain\n\nimport Foundation\nimport LawSpecRuntime\n\n/// What an actor model needs from the actor runtime: a supervised actor\n/// holding the system's state, restarted after a crash.\npublic protocol ModelActorHost {\n  /// Start one permanent child under a one-for-one supervisor that allows\n  /// the given number of restarts, run the body with the child, then stop.\n  /// start makes the first state; restart makes a state from the state at\n  /// the crash.\n  func withActor<R>(\n    _ restarts: Int, _ start: @escaping () throws -> Value,\n    _ restart: @escaping (Value) throws -> Value,\n    _ body: (AnyObject) throws -> R\n  ) throws -> R\n  /// Run an update on the actor's state in the actor: its reply and next state.\n  func call(_ actor: AnyObject, _ update: @escaping (Value) throws -> (Value, Value)) throws\n    -> Value\n  /// Crash the actor, waiting until its supervisor has restarted it.\n  func crash(_ actor: AnyObject) throws\n  /// The actor's current state.\n  func state(_ actor: AnyObject) throws -> Value\n}\n\npublic enum Model {\n  /// What a callback runs with: the schema, with the model's production\n  /// handlers in scope, and the case's symbols.\n  public typealias CallbackContext = (Schema, SymbolContext)\n\n  /// A checked entry of the program: the case's context and its arguments.\n  public typealias Callback = (CallbackContext, [Value]) throws -> Value\n\n  /// Runs a body in a fresh case context: generated code makes a symbol\n  /// context, takes the program's schema and installs production handlers\n  /// around the body.\n  public typealias ContextFactory = ((CallbackContext) throws -> Any) throws -> Any\n\n  public enum StepKind {\n    case command\n    case crash\n  }\n\n  /// A command of the model (or the injected crash of an actor model).\n  public struct Step {\n    public let name: String\n    public let arguments: [Descriptors.Descriptor]\n    public let statePosition: Int\n    public let returnsUnit: Bool\n    public let needs: [(String, BigInt)]\n    public let shifts: [(String, BigInt)]\n    public let key: Int?\n    public let restart: Bool\n    public let kind: StepKind\n    public let run: Callback\n    public let reference: Callback\n    public let when: Callback?\n  }\n\n  public struct Machine {\n    public let name: String\n    public let shared: Bool\n    public let actor: Bool\n    public let table: Descriptors.Table\n    public let startArguments: [Descriptors.Descriptor]\n    public let startIndices: [BigInt]\n    public let startRun: Callback\n    public let startModel: Callback\n    public let commands: [Step]\n    public let steps: [Step]\n    public let restartStep: Step?\n    public var abstractRun: Callback?\n    public let invariants: [(String, Callback)]\n    public let perKey: Bool\n    public let consistency: String\n    public var context: ContextFactory\n    public var actors: (any ModelActorHost)?\n  }\n\n  /// A case of the run: the model's context, its start arguments and the model.\n  public struct Context {\n    public let value: CallbackContext\n    public let start: [Value]\n    public let model: Machine\n  }\n\n  /// A run: start arguments, and each step's index and arguments.\n  public typealias Run = ([Value], [(Int, [Value])])\n\n  /// Why a run failed, and at which step (0 before the first).\n  public struct Failure {\n    public let step: Int\n    public let reason: String\n  }\n\n  static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  private static func require(_ condition: Bool, _ code: String) throws {\n    if !condition { throw fail(code) }\n  }\n\n  private static var noCallback: Callback { { _, _ in throw fail(\"ModelMissingCallback\") } }\n\n  private static func atom(_ d: Descriptors.Descriptor) throws -> String {\n    switch d {\n    case .atom(let a): return a\n    case .quoted(let q): return q\n    case .number(let n): return n.description\n    default: throw fail(\"InvalidModelSpec\", \"\\(d)\")\n    }\n  }\n\n  private static func fields(_ forms: [Descriptors.Descriptor]) -> [String: [Descriptors\n    .Descriptor]]\n  {\n    var table = [String: [Descriptors.Descriptor]]()\n    for f in forms {\n      if case .forms(let parts) = f, case .atom(let k)? = parts.first {\n        table[k] = Array(parts.dropFirst())\n      }\n    }\n    return table\n  }\n\n  private static func one(_ key: String, _ f: [String: [Descriptors.Descriptor]]) throws\n    -> Descriptors.Descriptor\n  {\n    guard let vs = f[key], vs.count == 1 else { throw fail(\"InvalidModelSpec\", key) }\n    return vs[0]\n  }\n\n  private static func flag(_ key: String, _ forms: [Descriptors.Descriptor]) -> Bool {\n    forms.contains(.forms([.atom(key), .atom(\"true\")]))\n  }\n\n  private static func form(_ key: String, _ forms: [Descriptors.Descriptor]) throws -> [Descriptors\n    .Descriptor]\n  {\n    for f in forms {\n      if case .forms(let parts) = f, case .atom(let k)? = parts.first, k == key {\n        return Array(parts.dropFirst())\n      }\n    }\n    throw fail(\"InvalidModelSpec\", key)\n  }\n\n  private static func pairs(_ ds: [Descriptors.Descriptor]) throws -> [(String, BigInt)] {\n    try ds.map { d in\n      guard case .forms(let parts) = d, parts.count == 2, case .atom(let k) = parts[0],\n        case .number(let n) = parts[1]\n      else {\n        throw fail(\"InvalidModelSpec\", \"\\(d)\")\n      }\n      return (k, n)\n    }\n  }\n\n  private static func readCommand(\n    _ forms: [Descriptors.Descriptor], _ callbacks: (Callback, Callback, Callback?)\n  ) throws -> Step {\n    guard forms.count >= 2, case .atom(\"command\") = forms[0] else {\n      throw fail(\"InvalidModelSpec\", \"command\")\n    }\n    let f = fields(Array(forms.dropFirst(2)))\n    guard case .number(let position) = try one(\"state\", f) else {\n      throw fail(\"InvalidModelSpec\", \"state\")\n    }\n    var key: Int? = nil\n    if case .number(let k) = try one(\"key\", f) { key = k.exactly(Int.self) }\n    return Step(\n      name: try atom(forms[1]), arguments: f[\"arguments\"] ?? [],\n      statePosition: position.exactly(Int.self) ?? 0,\n      returnsUnit: try atom(one(\"unit\", f)) == \"true\", needs: try pairs(f[\"needs\"] ?? []),\n      shifts: try pairs(f[\"shifts\"] ?? []),\n      key: key, restart: try atom(one(\"restart\", f)) == \"true\", kind: .command,\n      run: callbacks.0, reference: callbacks.1, when: callbacks.2)\n  }\n\n  private static var defaultContext: ContextFactory {\n    { body in try body((try Schema.create([], [], 64), SymbolContext())) }\n  }\n\n  /// A model from its spec text (LawSpec.MachineSpec), its start entries (the\n  /// system's and the reference's), each command's run, reference and optional\n  /// precondition, its optional abstraction and its invariants.\n  public static func create(\n    _ spec: String, _ start: (Callback, Callback), _ callbacks: [(Callback, Callback, Callback?)],\n    _ abstractRun: Callback?, _ invariants: [Callback]\n  ) throws -> Machine {\n    let forms = try Descriptors.read(spec)\n    guard case .forms(let head)? = forms.first, head.count == 3, case .atom(\"machine\") = head[0]\n    else {\n      throw fail(\"InvalidModelSpec\", \"machine\")\n    }\n    let name = try atom(head[1])\n    let sharing = try atom(head[2])\n    let startFields = fields(try form(\"start\", forms))\n    let commandForms = forms.compactMap { f -> [Descriptors.Descriptor]? in\n      if case .forms(let parts) = f, case .atom(\"command\")? = parts.first { return parts }\n      return nil\n    }\n    let kinds = try form(\"invariants\", forms).map(atom)\n    try require(commandForms.count == callbacks.count, \"ModelCommandCallbacks\")\n    try require(kinds.count == invariants.count, \"ModelInvariantCallbacks\")\n    let all = try zip(commandForms, callbacks).map { try readCommand($0.0, $0.1) }\n    let restarts = all.filter { $0.restart }\n    try require(restarts.count <= 1, \"ModelRestartCallbacks\")\n    let commands = all.filter { !$0.restart }\n    let actor = flag(\"actor\", forms)\n    guard let consistencyForm = try form(\"consistency\", forms).first else {\n      throw fail(\"InvalidModelSpec\", \"consistency\")\n    }\n    let consistency = try atom(consistencyForm)\n    try require(sharing == \"linear\" || sharing == \"shared\", \"ModelInvalidSharing\")\n    try require(\n      [\"linearizable\", \"sequential\", \"causal\", \"eventual\"].contains(consistency),\n      \"ModelInvalidConsistency\")\n    try require(consistency != \"eventual\" || abstractRun != nil, \"ModelEventualRequiresAbstraction\")\n    try require(!actor || sharing == \"shared\", \"ModelActorMustBeShared\")\n    try require(actor || restarts.isEmpty, \"ModelRestartRequiresActor\")\n    let crash = Step(\n      name: \"crash\", arguments: [], statePosition: 0, returnsUnit: true, needs: [], shifts: [],\n      key: nil,\n      restart: false, kind: .crash, run: noCallback, reference: noCallback, when: nil)\n    var table = Descriptors.Table()\n    for f in forms {\n      if case .forms(let parts) = f, parts.count >= 2, case .atom(\"data\") = parts[0] {\n        table[try atom(parts[1])] = f\n      }\n    }\n    let indices = try (startFields[\"indices\"] ?? []).map { d -> BigInt in\n      guard case .number(let n) = d else { throw fail(\"InvalidModelSpec\", \"\\(d)\") }\n      return n\n    }\n    return Machine(\n      name: name, shared: sharing == \"shared\", actor: actor, table: table,\n      startArguments: startFields[\"arguments\"] ?? [], startIndices: indices,\n      startRun: start.0, startModel: start.1, commands: commands,\n      steps: commands + (actor ? [crash] : []),\n      restartStep: restarts.first, abstractRun: abstractRun,\n      invariants: Array(zip(kinds, invariants)),\n      perKey: flag(\"perkey\", forms), consistency: consistency, context: defaultContext, actors: nil)\n  }\n\n  /// The model with the context factory generated code supplies.\n  public static func withContext(_ factory: @escaping ContextFactory, _ model: Machine) -> Machine {\n    var made = model\n    made.context = factory\n    return made\n  }\n\n  /// The model with the actor runtime an actor model runs its system on.\n  public static func withActors(_ host: any ModelActorHost, _ model: Machine) -> Machine {\n    var made = model\n    made.actors = host\n    return made\n  }\n\n  /// A context factory whose handler factories are made with each body's fresh\n  /// symbols, as generated code builds them.\n  public static func contextWith(\n    _ schema: Schema,\n    _ factories: @escaping (SymbolContext) throws -> [(String, (Schema) throws -> Effects.Handler)]\n  ) -> ContextFactory {\n    { body in\n      let symbols = SymbolContext()\n      let made = try factories(symbols)\n      if made.isEmpty { return try body((schema, symbols)) }\n      return try Effects.withScope(schema, made) { scoped in try body((scoped, symbols)) }\n    }\n  }\n\n  /// The step at an index (commands, then the injected crash).\n  public static func command(_ model: Machine, _ index: Int) throws -> Step {\n    if index < 0 || index >= model.steps.count { throw fail(\"ModelInvalidStep\", String(index)) }\n    return model.steps[index]\n  }\n\n  /// Whether a command's index preconditions admit the current indices.\n  public static func admits(_ step: Step, _ indices: [BigInt]) -> Bool {\n    zip(step.needs, indices).allSatisfy { need, i in need.0 == \"atleast\" ? i >= need.1 : i == need.1\n    }\n  }\n\n  /// The indices after a command.\n  public static func shifted(_ step: Step, _ indices: [BigInt]) -> [BigInt] {\n    if step.shifts.isEmpty { return indices }\n    return zip(step.shifts, indices).map { shift, i in shift.0 == \"by\" ? i + shift.1 : shift.1 }\n  }\n\n  /// Run a body in a fresh case context.\n  public static func withCase<A>(\n    _ model: Machine, _ startArgs: [Value], _ body: (Context) throws -> A\n  ) throws -> A {\n    let result = try model.context { value in\n      try body(Context(value: value, start: startArgs, model: model))\n    }\n    return result as! A\n  }\n\n  public static func callback(_ f: Callback, _ context: Context, _ arguments: [Value]) throws\n    -> Value\n  {\n    try f(context.value, arguments)\n  }\n\n  public static func initial(_ model: Machine, _ context: Context) throws -> Value {\n    try callback(model.startModel, context, context.start)\n  }\n\n  /// The reference's step: the next model state and the reply, or nil when\n  /// the reference rejects it. An invalid reference removes a candidate; it\n  /// never turns the implementation's failure into a pass.\n  public static func step(_ s: Step, _ context: Context, _ args: [Value], _ state: Value) -> (\n    Value, Value\n  )? {\n    do {\n      switch s.kind {\n      case .crash:\n        let next: Value\n        if let r = context.model.restartStep {\n          next = try callback(r.reference, context, [state])\n        } else {\n          next = try initial(context.model, context)\n        }\n        return (next, .unit)\n      case .command:\n        if let w = s.when, !Scalar.equal(try callback(w, context, [state]), .bool(true)) {\n          return nil\n        }\n        let out = try callback(s.reference, context, args + [state])\n        if s.returnsUnit { return (out, .unit) }\n        if case .data(_, let pair) = out, pair.count == 2 { return (pair[1], pair[0]) }\n        return nil\n      }\n    } catch {\n      return nil\n    }\n  }\n\n  /// The model states a run passes through, or nil when the reference\n  /// rejects it.\n  public static func simulate(_ model: Machine, _ run: Run) -> [Value]? {\n    let (startArgs, steps) = run\n    return\n      (try? withCase(model, startArgs) { context -> [Value]? in\n        var indices = model.startIndices\n        var state = try initial(model, context)\n        var states = [state]\n        for (i, args) in steps {\n          let c = try command(model, i)\n          if !admits(c, indices) { return nil }\n          guard let (next, _) = step(c, context, args, state) else { return nil }\n          indices = shifted(c, indices)\n          state = next\n          states.append(state)\n        }\n        return states\n      }) ?? nil\n  }\n\n  private static func arguments(\n    _ model: Machine, _ ds: [Descriptors.Descriptor], _ random: Random.Seed, _ size: Int\n  ) throws -> ([Value], Random.Seed) {\n    var r = random\n    let values = try ds.map { d -> Value in\n      let (v, next) = try Descriptors.generate(d, model.table, r, size)\n      r = next\n      return v\n    }\n    return (values, r)\n  }\n\n  /// A run drawn from a random state, of at most a length, at a size; crashes\n  /// are injected (one step in eight) only when asked, and only for actors.\n  public static func generateRun(\n    _ model: Machine, _ random: Random.Seed, _ length: Int, _ size: Int, _ crashes: Bool\n  ) throws -> (Run, Random.Seed) {\n    let (startArgs, r1) = try arguments(model, model.startArguments, random, size)\n    return try withCase(model, startArgs) { context -> (Run, Random.Seed) in\n      guard let started = try? initial(model, context) else { return ((startArgs, []), r1) }\n      var random = r1\n      var remaining = length\n      var indices = model.startIndices\n      var state = started\n      var steps = [(Int, [Value])]()\n      while remaining != 0 {\n        let allowed = model.commands.indices.filter { admits(model.commands[$0], indices) }\n        if allowed.isEmpty { break }\n        let (choice, next1) = Random.below(BigInt(allowed.count), random)\n        var index = allowed[choice.exactly(Int.self)!]\n        var next2 = next1\n        if crashes && model.actor {\n          let (crash, r) = Random.below(8, next1)\n          if crash.isZero { index = model.commands.count }\n          next2 = r\n        }\n        let c = try command(model, index)\n        let (args, next3) = try arguments(model, c.arguments, next2, size)\n        random = next3\n        remaining -= 1\n        if let (after, _) = step(c, context, args, state) {\n          indices = shifted(c, indices)\n          state = after\n          steps.append((index, args))\n        }\n      }\n      return ((startArgs, steps), random)\n    }\n  }\n\n  static func hostOf(_ model: Machine) throws -> any ModelActorHost {\n    guard let host = model.actors else { throw fail(\"ModelActorRuntimeMissing\", model.name) }\n    return host\n  }\n\n  /// Run a body with the system started (an actor model's under a\n  /// supervisor), its context and the reference's initial state.\n  public static func withSystem<A>(\n    _ model: Machine, _ startArgs: [Value], _ restarts: Int,\n    _ body: (Context, Any, Value) throws -> A\n  ) throws -> A {\n    try withCase(model, startArgs) { context in\n      let start = { () throws -> Value in try callback(model.startRun, context, startArgs) }\n      if !model.actor { return try body(context, try start(), try initial(model, context)) }\n      let restart = { (state: Value) throws -> Value in\n        if let r = model.restartStep { return try callback(r.run, context, [state]) }\n        return try start()\n      }\n      return try hostOf(model).withActor(restarts, start, restart) { actor in\n        try body(context, actor, try initial(model, context))\n      }\n    }\n  }\n\n  private static func insertState(_ s: Step, _ args: [Value], _ state: Value) -> [Value] {\n    let position = Swift.min(s.statePosition, args.count)\n    return Array(args[..<position]) + [state] + Array(args[position...])\n  }\n\n  private static func pair(_ out: Value) throws -> (Value, Value) {\n    guard case .data(_, let p) = out, p.count == 2 else {\n      throw fail(\"ModelInvalidReply\", Recorded.debug(out))\n    }\n    return (p[0], p[1])\n  }\n\n  /// Run a step on the system: its reply and the system after it.\n  public static func invoke(\n    _ model: Machine, _ context: Context, _ s: Step, _ args: [Value], _ system: Any\n  ) throws -> (Value, Any) {\n    switch s.kind {\n    case .crash:\n      try hostOf(model).crash(system as AnyObject)\n      return (.unit, system)\n    case .command where model.actor:\n      let reply = try hostOf(model).call(system as AnyObject) { state in\n        let out = try callback(s.run, context, insertState(s, args, state))\n        return s.returnsUnit ? (.unit, out) : try pair(out)\n      }\n      return (reply, system)\n    case .command:\n      let state = system as! Value\n      let out = try callback(s.run, context, insertState(s, args, state))\n      if model.shared { return (out, system) }\n      if s.returnsUnit {\n        guard case .data(_, let f) = out, f.count == 1 else {\n          throw fail(\"ModelInvalidReply\", Recorded.debug(out))\n        }\n        return (.unit, f[0])\n      }\n      let (reply, next) = try pair(out)\n      return (reply, next)\n    }\n  }\n\n  struct ModelFailure: Error, CustomStringConvertible {\n    let reason: String\n    var description: String { reason }\n  }\n\n  /// The system's state, as its abstraction and state invariants see it.\n  public static func systemState(_ model: Machine, _ system: Any) throws -> Value {\n    if model.actor { return try hostOf(model).state(system as AnyObject) }\n    return system as! Value\n  }\n\n  /// Check the system against the reference state: its abstraction, then the\n  /// invariants on the model state and on the system state.\n  public static func checkState(\n    _ model: Machine, _ context: Context, _ system: Any, _ expected: Value\n  ) throws {\n    let state = try systemState(model, system)\n    if let a = model.abstractRun {\n      let actual = try callback(a, context, [state])\n      if !Scalar.equal(actual, expected) {\n        throw ModelFailure(\n          reason: \"state \\(Descriptors.render(actual)), expected \\(Descriptors.render(expected))\")\n      }\n    }\n    for (kind, invariant) in model.invariants {\n      let value = kind == \"model\" ? expected : state\n      switch try callback(invariant, context, [value]) {\n      case .bool(true): continue\n      case .bool(false): throw ModelFailure(reason: \"invariant on the \" + kind + \" failed\")\n      case let other:\n        throw ModelFailure(reason: \"invariant on the \\(kind) gave \\(Descriptors.render(other))\")\n      }\n    }\n  }\n\n  /// A model without its abstraction (for the checks of each order).\n  public static func withoutAbstraction(_ model: Machine) -> Machine {\n    var made = model\n    made.abstractRun = nil\n    return made\n  }\n\n  static func raised(_ e: any Error) -> String {\n    if let failure = e as? ModelFailure { return failure.reason }\n    return \"raised \\(type(of: e)): \\(e)\"\n  }\n\n  /// Run a run on the system, checking each reply and state.\n  public static func execute(_ model: Machine, _ run: Run) -> Failure? {\n    let (startArgs, steps) = run\n    do {\n      return try withSystem(model, startArgs, steps.count) { context, system, start -> Failure? in\n        var indices = model.startIndices\n        var expected = start\n        var system = system\n        var n = 0\n        for (i, args) in steps {\n          do {\n            try checkState(model, context, system, expected)\n          } catch {\n            return Failure(step: n, reason: raised(error))\n          }\n          let c: Step\n          do { c = try command(model, i) } catch { return Failure(step: n, reason: raised(error)) }\n          if !admits(c, indices) { return Failure(step: n + 1, reason: \"invalid step\") }\n          guard let (next, wanted) = step(c, context, args, expected) else {\n            return Failure(step: n + 1, reason: \"invalid step\")\n          }\n          let result: Value\n          do {\n            (result, system) = try invoke(model, context, c, args, system)\n          } catch {\n            return Failure(step: n + 1, reason: raised(error))\n          }\n          if !(c.returnsUnit || Scalar.equal(result, wanted)) {\n            return Failure(\n              step: n + 1,\n              reason:\n                \"returned \\(Descriptors.render(result)), expected \\(Descriptors.render(wanted))\")\n          }\n          indices = shifted(c, indices)\n          expected = next\n          n += 1\n        }\n        do {\n          try checkState(model, context, system, expected)\n        } catch {\n          return Failure(step: n, reason: raised(error))\n        }\n        return nil\n      }\n    } catch {\n      return Failure(step: 0, reason: raised(error))\n    }\n  }\n\n  private static func halves(_ n: Int) -> [Int] {\n    var result = [Int]()\n    var k = n\n    while k != 0 {\n      result.append(k)\n      k /= 2\n    }\n    return result\n  }\n\n  private static func removeRange<T>(_ values: [T], _ start: Int, _ size: Int) -> [T] {\n    let before = values[..<start]\n    let rest = values[start...]\n    return Array(before) + Array(rest.dropFirst(Swift.min(size, rest.count)))\n  }\n\n  static func smallerArgs(_ model: Machine, _ ds: [Descriptors.Descriptor], _ args: [Value]) throws\n    -> [[Value]]\n  {\n    var result = [[Value]]()\n    for (i, (d, arg)) in zip(ds, args).enumerated() {\n      for v in try Descriptors.shrink(d, arg, model.table) {\n        var copy = args\n        copy[i] = v\n        result.append(copy)\n      }\n    }\n    return result\n  }\n\n  /// Shrink candidates in the portable order: remove chunks of steps, then\n  /// shrink each step's arguments, then the start arguments.\n  public static func candidates(_ model: Machine, _ run: Run) throws -> [Run] {\n    let (startArgs, steps) = run\n    let n = steps.count\n    var result = [Run]()\n    for size in halves(n / 2) {\n      for start in stride(from: 0, to: n, by: size) {\n        result.append((startArgs, removeRange(steps, start, size)))\n      }\n    }\n    for (k, (i, values)) in steps.enumerated() {\n      for smaller in try smallerArgs(model, try command(model, i).arguments, values) {\n        var copy = steps\n        copy[k] = (i, smaller)\n        result.append((startArgs, copy))\n      }\n    }\n    for smaller in try smallerArgs(model, model.startArguments, startArgs) {\n      result.append((smaller, steps))\n    }\n    return result\n  }\n\n  /// The smallest failing run within a budget of attempts.\n  public static func shrinkRun(_ model: Machine, _ run: Run, _ failure: Failure, _ budget: Int)\n    throws -> (Run, Failure)\n  {\n    var budget = budget\n    for candidate in try candidates(model, run) {\n      if budget == 0 { break }\n      let result: Failure? = simulate(model, candidate) == nil ? nil : execute(model, candidate)\n      if let found = result { return try shrinkRun(model, candidate, found, budget - 1) }\n      budget -= 1\n    }\n    return (run, failure)\n  }\n\n  private static func describeStep(_ name: String, _ args: [Value]) -> String {\n    name + \"(\" + args.map(Descriptors.render).joined(separator: \", \") + \")\"\n  }\n\n  /// A run as text: start(...); command(...); ...\n  public static func describe(_ model: Machine, _ run: Run) -> String {\n    let (startArgs, steps) = run\n    return\n      ([describeStep(\"start\", startArgs)]\n      + steps.map { describeStep((try? command(model, $0.0).name) ?? \"?\", $0.1) }).joined(\n        separator: \"; \")\n  }\n\n  /// The run's seed: given, LAWSPEC_SEED, or 0.\n  public static func seed(_ given: BigInt?) -> Random.Seed {\n    if let n = given { return Random.seed(n) }\n    if let text = ProcessInfo.processInfo.environment[\"LAWSPEC_SEED\"], !text.isEmpty,\n      let n = BigInt(text)\n    {\n      return Random.seed(n)\n    }\n    return Random.seed(.zero)\n  }\n\n  /// How many cases, how long a run may be, how many shrink attempts, and\n  /// the seed (otherwise LAWSPEC_SEED, or 0).\n  public struct Options {\n    public var cases = 100\n    public var maxLength = 20\n    public var maxShrinks = 2000\n    public var seed: BigInt? = nil\n    public init() {}\n  }\n\n  /// Check a model's sequential runs, with options.\n  public static func checkWith(_ options: Options, _ model: Machine) throws {\n    try require(options.cases > 0, \"ModelRequiresCases\")\n    try require(options.maxLength >= 0, \"ModelInvalidLength\")\n    try require(options.maxShrinks >= 0, \"ModelInvalidShrinks\")\n    let start = seed(options.seed)\n    var random = start\n    for n in 0..<options.cases {\n      let (length, r1) = Random.below(BigInt(options.maxLength + 1), random)\n      let (run, r2) = try generateRun(model, r1, length.exactly(Int.self)!, 1 + n % 8, true)\n      if let failure = execute(model, run) {\n        let (smaller, found) = try shrinkRun(model, run, failure, options.maxShrinks)\n        throw Fail.with(\n          \"ModelFailed\",\n          \"model \\(model.name): seed \\(start.state) (LAWSPEC_SEED=\\(start.state) replays it), case \\(n): \\(describe(model, smaller)); at step \\(found.step): \\(found.reason)\"\n        )\n      }\n      random = r2\n    }\n  }\n\n  /// Check a model's sequential runs.\n  public static func check(_ model: Machine) throws { try checkWith(Options(), model) }\n}\n"
swiftSource "LawSpecTesting/ModelParallel.swift" = "// Concurrent model histories, generated from a valid sequential prefix.\n// Every interleaving of the branches must be allowed by the reference.\n// The calls run on threads of their own at once; a shared counter records\n// each call's interval, and an order consistent with the model (and, for\n// linearizability, with real time) must explain the results.\n// ref:DEC-stateful-models-linearizability ref:herlihy-wing-linearizability\n// ref:wing-gong-linearizability ref:DEC-portable-seeded-generation\n\nimport Foundation\nimport LawSpecRuntime\n\npublic enum ModelParallel {\n  /// A case: a sequential prefix, then a branch of steps for each thread.\n  public typealias Case = (Model.Run, [[(Int, [Value])]])\n\n  /// A call's interval on the shared clock and its outcome.\n  public typealias Event = (Int64, Int64, Result<Value, CallFailure>)\n\n  /// A call that failed, as its report shows it.\n  public struct CallFailure: Error {\n    let text: String\n  }\n\n  private static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  private static func pending(_ branches: [[(Int, [Value])]], _ positions: [Int]) -> [(\n    Int, (Int, [Value])\n  )] {\n    branches.indices.compactMap { i in\n      positions[i] < branches[i].count ? (i, branches[i][positions[i]]) : nil\n    }\n  }\n\n  private static func advance(_ positions: [Int], _ i: Int) -> [Int] {\n    var next = positions\n    next[i] += 1\n    return next\n  }\n\n  /// Whether every interleaving of the branches is allowed by the reference.\n  public static func allowed(_ model: Model.Machine, _ c: Case) -> Bool {\n    let (prefix, branches) = c\n    guard let states = Model.simulate(model, prefix), let last = states.last else { return false }\n    return\n      (try? Model.withCase(model, prefix.0) { context -> Bool in\n        var seen = Set<SearchKey>()\n        func allOrders(_ positions: [Int], _ state: Value) -> Bool {\n          if !seen.insert(SearchKey(done: positions, state: state)).inserted { return true }\n          return pending(branches, positions).allSatisfy { i, step in\n            guard let s = try? Model.command(model, step.0),\n              let (next, _) = Model.step(s, context, step.1, state)\n            else { return false }\n            return allOrders(advance(positions, i), next)\n          }\n        }\n        return allOrders(Array(repeating: 0, count: branches.count), last)\n      }) ?? false\n  }\n\n  private static func generateBranch(\n    _ model: Model.Machine, _ context: Model.Context, _ random: Random.Seed, _ size: Int,\n    _ count: Int, _ start: Value\n  ) throws -> ([(Int, [Value])], Random.Seed) {\n    var random = random\n    var remaining = count\n    var state = start\n    var steps = [(Int, [Value])]()\n    while remaining != 0 && !model.commands.isEmpty {\n      let (index, r1) = Random.below(BigInt(model.commands.count), random)\n      let c = try Model.command(model, index.exactly(Int.self)!)\n      var r = r1\n      let args = try c.arguments.map { d -> Value in\n        let (v, next) = try Descriptors.generate(d, model.table, r, size)\n        r = next\n        return v\n      }\n      random = r\n      remaining -= 1\n      if let (next, _) = Model.step(c, context, args, state) {\n        state = next\n        steps.append((index.exactly(Int.self)!, args))\n      }\n    }\n    return (steps, random)\n  }\n\n  private static func trim(_ model: Model.Machine, _ c: Case) -> Case {\n    var (prefix, branches) = c\n    while !allowed(model, (prefix, branches)) {\n      let length = branches.map { $0.count }.max() ?? 0\n      guard let i = branches.firstIndex(where: { $0.count == length }), length > 0 else { break }\n      branches[i] = Array(branches[i].prefix(length - 1))\n    }\n    return (prefix, branches)\n  }\n\n  /// A case drawn from a random state: a prefix of up to three steps, then a\n  /// branch for each thread of one to the branch length steps.\n  public static func generateCase(\n    _ model: Model.Machine, _ random: Random.Seed, _ size: Int, _ threads: Int, _ branchLength: Int\n  ) throws -> (Case, Random.Seed) {\n    let (length, r1) = Random.below(4, random)\n    let (prefix, r2) = try Model.generateRun(model, r1, length.exactly(Int.self)!, size, false)\n    guard let states = Model.simulate(model, prefix), let last = states.last else {\n      return ((prefix, Array(repeating: [], count: threads)), r2)\n    }\n    let (branches, r3) = try Model.withCase(model, prefix.0) {\n      context -> ([[(Int, [Value])]], Random.Seed) in\n      var r = r2\n      var made = [[(Int, [Value])]]()\n      for _ in 0..<threads {\n        let (n, next) = Random.below(BigInt(branchLength), r)\n        let (branch, after) = try generateBranch(\n          model, context, next, size, n.exactly(Int.self)! + 1, last)\n        r = after\n        made.append(branch)\n      }\n      return (made, r)\n    }\n    return (trim(model, (prefix, branches)), r3)\n  }\n\n  private static func perturb(_ random: Random.Seed) -> Random.Seed {\n    let (choice, next) = Random.below(4, random)\n    if choice == .one {\n      sched_yield()\n    } else if !choice.isZero {\n      Thread.sleep(forTimeInterval: 0.001)\n    }\n    return next\n  }\n\n  private static func raisedText(_ e: any Error) -> String { \"raised \\(type(of: e)): \\(e)\" }\n\n  private static func prefixRun(\n    _ model: Model.Machine, _ context: Model.Context, _ steps: [(Int, [Value])], _ system: Any,\n    _ start: Value\n  ) throws -> Value {\n    var expected = start\n    try Model.checkState(model, context, system, expected)\n    for (i, args) in steps {\n      let c = try Model.command(model, i)\n      guard let (next, wanted) = Model.step(c, context, args, expected) else {\n        throw fail(\"ModelPrefixInvalid\", c.name)\n      }\n      let (result, _) = try Model.invoke(model, context, c, args, system)\n      if !(c.returnsUnit || Scalar.equal(result, wanted)) {\n        throw fail(\n          \"ModelPrefixReturned\",\n          \"\\(c.name) returned \\(Descriptors.render(result)), expected \\(Descriptors.render(wanted))\"\n        )\n      }\n      expected = next\n      try Model.checkState(model, context, system, expected)\n    }\n    return expected\n  }\n\n  private static func valueOf(_ result: Result<Value, CallFailure>) -> Value {\n    if case .success(let v) = result { return v }\n    return .unit\n  }\n\n  /// Search the orders consistent with each branch's order (and, for\n  /// linearizability, real time) for one the reference explains.\n  private static func findOrder(\n    _ model: Model.Machine, _ context: Model.Context, _ branches: [[(Int, [Value])]],\n    _ history: [[Event]],\n    _ expected: Value, _ finish: (Value) -> Bool\n  ) -> Bool {\n    let linear = model.consistency == \"linearizable\"\n    var seen = Set<SearchKey>()\n    func visit(_ positions: [Int], _ state: Value) -> Bool {\n      if !seen.insert(SearchKey(done: positions, state: state)).inserted { return false }\n      let next = pending(branches, positions)\n      if next.isEmpty { return finish(state) }\n      for (i, step) in next {\n        let (called, _, result) = history[i][positions[i]]\n        let blocked =\n          linear && next.contains { j, _ in j != i && history[j][positions[j]].1 < called }\n        if blocked { continue }\n        guard let c = try? Model.command(model, step.0),\n          let (after, wanted) = Model.step(c, context, step.1, state)\n        else { continue }\n        let ignore = model.consistency == \"eventual\" || c.returnsUnit\n        if (ignore || Scalar.equal(valueOf(result), wanted)) && visit(advance(positions, i), after)\n        {\n          return true\n        }\n      }\n      return false\n    }\n    return visit(Array(repeating: 0, count: branches.count), expected)\n  }\n\n  private static func causal(\n    _ model: Model.Machine, _ context: Model.Context, _ branches: [[(Int, [Value])]],\n    _ history: [[Event]],\n    _ expected: Value, _ system: Any\n  ) -> Bool {\n    zip(branches, history).allSatisfy { branch, events in\n      var state = expected\n      for ((i, args), (_, _, result)) in zip(branch, events) {\n        guard let c = try? Model.command(model, i),\n          let (next, wanted) = Model.step(c, context, args, state)\n        else { return false }\n        if !(c.returnsUnit || Scalar.equal(valueOf(result), wanted)) { return false }\n        state = next\n      }\n      return (try? Model.checkState(Model.withoutAbstraction(model), context, system, state)) != nil\n    }\n  }\n\n  private static func foldKeys(\n    _ model: Model.Machine, _ context: Model.Context,\n    _ groups: ArraySlice<[[((Int, [Value]), Event)]]>,\n    _ state: Value, _ finish: (Value) -> Bool\n  ) -> Bool {\n    guard let parts = groups.first else { return finish(state) }\n    let branches = parts.map { $0.map { $0.0 } }\n    let history = parts.map { $0.map { $0.1 } }\n    return findOrder(model, context, branches, history, state) { next in\n      foldKeys(model, context, groups.dropFirst(), next, finish)\n    }\n  }\n\n  private static func byKey(\n    _ model: Model.Machine, _ context: Model.Context, _ branches: [[(Int, [Value])]],\n    _ history: [[Event]],\n    _ expected: Value, _ finish: (Value) -> Bool\n  ) -> Bool {\n    let n = branches.count\n    var groups = [String: [[((Int, [Value]), Event)]]]()\n    for (i, (branch, events)) in zip(branches, history).enumerated() {\n      for (s, e) in zip(branch, events) {\n        guard let c = try? Model.command(model, s.0), let keyIndex = c.key else { return false }\n        let key = Descriptors.render(s.1[keyIndex])\n        var parts = groups[key] ?? Array(repeating: [], count: n)\n        parts[i].append((s, e))\n        groups[key] = parts\n      }\n    }\n    let ordered = groups.keys.sorted { Scalar.compareText($0, $1) < 0 }.map { groups[$0]! }\n    return foldKeys(model, context, ordered[...], expected, finish)\n  }\n\n  /// Whether a parallel history has an order consistent with the model.\n  public static func consistent(\n    _ model: Model.Machine, _ context: Model.Context, _ branches: [[(Int, [Value])]],\n    _ history: [[Event]],\n    _ expected: Value, _ final: Value?, _ system: Any\n  ) -> Bool {\n    func finish(_ state: Value) -> Bool {\n      if let actual = final, !Scalar.equal(actual, state) { return false }\n      return (try? Model.checkState(Model.withoutAbstraction(model), context, system, state)) != nil\n    }\n    if model.consistency == \"causal\" {\n      return causal(model, context, branches, history, expected, system)\n    }\n    let canPartition =\n      model.consistency == \"linearizable\" && model.perKey\n      && branches.joined().allSatisfy { (try? Model.command(model, $0.0))?.key != nil }\n    if canPartition { return byKey(model, context, branches, history, expected, finish) }\n    return findOrder(model, context, branches, history, expected, finish)\n  }\n\n  private static func letter(_ i: Int) -> String { String(UnicodeScalar(UInt8(65 + i))) }\n\n  /// Run a case once, its branches at the same time, with scheduling\n  /// perturbed from a shake value; nil when an order explains the results.\n  public static func execute(_ model: Model.Machine, _ c: Case, _ shake: UInt64) -> String? {\n    let ((startArgs, steps), branches) = c\n    do {\n      return try Model.withSystem(model, startArgs, steps.count) {\n        context, system, start -> String? in\n        let finalPrefix = try prefixRun(model, context, steps, system, start)\n        let clock = Locked<Int64>(0)\n        let tick: @Sendable () -> Int64 = {\n          clock.with {\n            $0 += 1\n            return $0\n          }\n        }\n        let results = Locked([[Event]](repeating: [], count: branches.count))\n        let group = DispatchGroup()\n        let shared = UncheckedBox((model, context, system))\n        for (i, branch) in branches.enumerated() {\n          group.enter()\n          let work = UncheckedBox(branch)\n          LawThread.start {\n            let (model, context, system) = shared.value\n            var random = Random.seed(\n              BigInt(shake) ^ (BigInt(i + 1) * BigInt(UInt64(0x9e37_79b9_7f4a_7c15))))\n            var events = [Event]()\n            for (index, args) in work.value {\n              random = perturb(random)\n              let called = tick()\n              let result: Result<Value, CallFailure>\n              do {\n                let s = try Model.command(model, index)\n                do {\n                  result = .success(try Model.invoke(model, context, s, args, system).0)\n                } catch {\n                  result = .failure(CallFailure(text: s.name + \": \" + raisedText(error)))\n                }\n              } catch {\n                result = .failure(CallFailure(text: raisedText(error)))\n              }\n              let returned = tick()\n              random = perturb(random)\n              events.append((called, returned, result))\n            }\n            results.with { $0[i] = events }\n            group.leave()\n          }\n        }\n        group.wait()\n        let history = results.with { $0 }\n        for events in history {\n          for (_, _, r) in events { if case .failure(let e) = r { return e.text } }\n        }\n        let final = try model.abstractRun.map {\n          try Model.callback($0, context, [try Model.systemState(model, system)])\n        }\n        if consistent(model, context, branches, history, finalPrefix, final, system) { return nil }\n        let shown = history.enumerated().map { i, events in\n          letter(i) + \": \"\n            + events.map { a, b, r -> String in\n              let text: String\n              switch r {\n              case .success(let v): text = Descriptors.render(v)\n              case .failure(let e): text = e.text\n              }\n              return \"[\\(a),\\(b)] \\(text)\"\n            }.joined(separator: \", \")\n        }\n        return \"no consistent order: \" + shown.joined(separator: \"; \")\n      }\n    } catch {\n      return raisedText(error)\n    }\n  }\n\n  /// Shrink candidates: remove a prefix step, remove a branch step, then\n  /// shrink a branch step's arguments.\n  public static func candidates(_ model: Model.Machine, _ c: Case) throws -> [Case] {\n    let (prefix, branches) = c\n    let (startArgs, steps) = prefix\n    var result = [Case]()\n    for i in steps.indices {\n      var copy = steps\n      copy.remove(at: i)\n      result.append(((startArgs, copy), branches))\n    }\n    for (i, branch) in branches.enumerated() {\n      for k in branch.indices {\n        var b = branch\n        b.remove(at: k)\n        var copy = branches\n        copy[i] = b\n        result.append((prefix, copy))\n      }\n    }\n    for (i, branch) in branches.enumerated() {\n      for (k, (index, values)) in branch.enumerated() {\n        let ds = try Model.command(model, index).arguments\n        for (a, (d, v)) in zip(ds, values).enumerated() {\n          for value in try Descriptors.shrink(d, v, model.table) {\n            var vs = values\n            vs[a] = value\n            var b = branch\n            b[k] = (index, vs)\n            var copy = branches\n            copy[i] = b\n            result.append((prefix, copy))\n          }\n        }\n      }\n    }\n    return result\n  }\n\n  private static func repeats(_ model: Model.Machine, _ c: Case, _ count: Int, _ shake: UInt64)\n    -> String?\n  {\n    var shake = shake\n    for _ in 0..<count {\n      if let error = execute(model, c, shake) { return error }\n      shake &+= 1\n    }\n    return nil\n  }\n\n  /// The smallest case still failing within a budget of attempts.\n  public static func shrinkCase(\n    _ model: Model.Machine, _ c: Case, _ failure: String, _ count: Int, _ budget: Int,\n    _ shake: UInt64\n  ) throws -> (Case, String) {\n    var budget = budget\n    for candidate in try candidates(model, c) {\n      if budget == 0 { break }\n      let found = allowed(model, candidate) ? repeats(model, candidate, count, shake) : nil\n      if let reason = found {\n        return try shrinkCase(model, candidate, reason, count, budget - 1, shake)\n      }\n      budget -= 1\n    }\n    return (c, failure)\n  }\n\n  /// A case as text: its prefix, then each branch, at the same time.\n  public static func describeCase(_ model: Model.Machine, _ c: Case) -> String {\n    let (prefix, branches) = c\n    let parts = branches.enumerated().map { i, b -> String in\n      let shown =\n        b.isEmpty ? \"nothing\" : String(Model.describe(model, ([], b)).dropFirst(\"start(); \".count))\n      return letter(i) + \": \" + shown\n    }\n    let joined: String\n    switch parts.count {\n    case 0: joined = \"nothing\"\n    case 1: joined = parts[0]\n    default: joined = parts.dropLast().joined(separator: \", \") + \" and \" + parts.last!\n    }\n    return Model.describe(model, prefix) + \", then \" + joined + \" at the same time\"\n  }\n\n  /// How many cases, how many runs of each, the shrink budget, the threads\n  /// and the longest branch.\n  public struct Options {\n    public var cases = 50\n    public var repeats = 10\n    public var maxShrinks = 300\n    public var threads = 3\n    public var branchLength = 5\n    public var seed: BigInt? = nil\n    public init() {}\n  }\n\n  /// Check a shared model's concurrent histories, with options.\n  public static func checkWith(_ options: Options, _ model: Model.Machine) throws {\n    if !model.shared { throw fail(\"ModelNotShared\", model.name) }\n    if options.cases <= 0 || options.repeats <= 0 || options.threads <= 0\n      || options.branchLength <= 0 || options.maxShrinks < 0\n    {\n      throw fail(\"ModelInvalidOptions\", model.name)\n    }\n    let start = Model.seed(options.seed)\n    var random = Random.Seed(state: start.state ^ 0x5bd1_e995)\n    for n in 0..<options.cases {\n      let (c, r1) = try generateCase(\n        model, random, 1 + n % 8, options.threads, options.branchLength)\n      let (shake, r2) = Random.next(r1)\n      if let failure = repeats(model, c, options.repeats, shake) {\n        let (smaller, found) = try shrinkCase(\n          model, c, failure, Swift.max(2, options.repeats / 2), options.maxShrinks, shake)\n        throw Fail.with(\n          \"ModelInconsistent\",\n          \"model \\(model.name) is not \\(model.consistency): seed \\(start.state) (LAWSPEC_SEED=\\(start.state) replays it), case \\(n), shake \\(shake): \\(describeCase(model, smaller)); \\(found)\"\n        )\n      }\n      random = r2\n    }\n  }\n\n  /// Check a shared model's concurrent histories.\n  public static func check(_ model: Model.Machine) throws { try checkWith(Options(), model) }\n}\n"
swiftSource "LawSpecTesting/Property.swift" = "// Running a law's property: LawSpec's generation plan draws each case from\n// the run's seed at a growing size, and the first failure shrinks along its\n// shrink tree, so every candidate stays inside the law's domain. One seed per\n// run is printed with any failure, and LAWSPEC_SEED replays it.\n// ref:DEC-swift-property-library ref:DEC-never-pass-vacuously\n\nimport Foundation\nimport LawSpecRuntime\n\npublic enum Property {\n  /// How many cases to run, how many discards the run may take, and how many\n  /// shrink steps a failure may take.\n  public struct Settings {\n    public let cases: Int\n    public let maxAttempts: Int\n    public let maxShrinks: Int\n  }\n\n  /// The run's seed: LAWSPEC_SEED, or a fresh one.\n  public static func runSeed() -> BigInt {\n    if let text = ProcessInfo.processInfo.environment[\"LAWSPEC_SEED\"], !text.isEmpty,\n      let seed = BigInt(text)\n    {\n      return seed\n    }\n    return BigInt(Int64.random(in: Int64.min...Int64.max))\n  }\n\n  private static func render(_ values: [Value]) -> String {\n    \"(\" + values.map(Recorded.renderPlain).joined(separator: \", \") + \")\"\n  }\n\n  /// The largest size a case draws at. The size grows linearly from 0 to\n  /// this over the run's cases, and with each discard too, so a domain that\n  /// small draws rarely meet is reached at larger sizes.\n  private static let maxSize = 100\n\n  /// A failure of the harness itself ends the run: it is neither a\n  /// counterexample nor shrunk.\n  private static func isAbort(_ error: any Error) -> Bool {\n    guard let failure = error as? LawSpecError else { return false }\n    return failure.code == \"StrategyOutsideRefinement\" || failure.code == \"StrategyDiscards\"\n  }\n\n  private enum Outcome {\n    case passed\n    case failed(any Error)\n    case aborted(any Error)\n  }\n\n  private static func attempt(_ property: ([Value]) throws -> Value, _ values: [Value]) -> Outcome {\n    do {\n      switch try property(values) {\n      case .bool(true): return .passed\n      case .bool(false): return .failed(LawSpecError(\"PropertyFalse\"))\n      case let other: return .failed(LawSpecError(\"NonBooleanProperty\", Recorded.debug(other)))\n      }\n    } catch {\n      return isAbort(error) ? .aborted(error) : .failed(error)\n    }\n  }\n\n  /// Check a property over a generator of its inputs.\n  public static func check(\n    _ label: String, _ settings: Settings, _ gen: Gen<[Value]>,\n    _ property: ([Value]) throws -> Value\n  ) throws {\n    let seed = runSeed()\n    let width = settings.maxShrinks * 4\n    var state = Random.seed(seed)\n    var passed = 0\n    var discards = 0\n    while passed < settings.cases {\n      let size = Swift.min(maxSize, (passed + discards) * maxSize / Swift.max(1, settings.cases))\n      let (caseSeed, following) = Random.split(state)\n      state = following\n      let drawn: Tree<[Value]>?\n      do {\n        drawn = try gen.generate(caseSeed, size)\n      } catch {\n        throw error\n      }\n      guard let tree = drawn?.limit(settings.maxShrinks, width) else {\n        discards += 1\n        if discards > settings.maxAttempts {\n          throw Harness.abort(\n            \"CannotSatisfy\",\n            \"\\(label): no input satisfied the law's domain after \\(settings.maxAttempts) attempts (\\(passed) passing case(s); seed \\(seed))\"\n          )\n        }\n        continue\n      }\n      switch attempt(property, tree.value) {\n      case .passed:\n        passed += 1\n      case .aborted(let error):\n        throw error\n      case .failed(let error):\n        var current = tree\n        var failure = error\n        var shrinks = 0\n        var aborted: (any Error)? = nil\n        shrinking: while true {\n          let candidates = (try? current.children()) ?? []\n          for child in candidates {\n            switch attempt(property, child.value) {\n            case .failed(let e):\n              current = child\n              failure = e\n              shrinks += 1\n              continue shrinking\n            case .aborted(let e):\n              aborted = e\n              break shrinking\n            case .passed:\n              continue\n            }\n          }\n          break\n        }\n        if let e = aborted { throw e }\n        let message =\n          \"\\(label) failed after \\(passed) passing case(s) and \\(shrinks) shrink(s): counterexample \\(render(current.value)); \"\n          + \"seed \\(seed) (LAWSPEC_SEED=\\(seed) replays it)\\n\\(failure)\"\n        throw LawSpecError(\"PropertyFailed\", message, cause: \"\\(failure)\")\n      }\n    }\n  }\n\n  /// A law's generation settings.\n  public static func settings(_ cases: Int, _ attempts: Int, _ shrinks: Int) -> Settings {\n    Settings(cases: cases, maxAttempts: attempts, maxShrinks: shrinks)\n  }\n\n  /// What generation reads: the schema, the case's symbols and the discard budget.\n  public static func generation(_ schema: Schema, _ symbols: SymbolContext, _ attempts: Int)\n    -> Generators.Context\n  {\n    Generators.Context(schema: schema, symbols: symbols, factories: [:], attempts: attempts)\n  }\n\n  /// As generation, with the application's generators (bound in lawspec.json)\n  /// in place of the built-in ones for their types.\n  public static func generationWith(\n    _ schema: Schema, _ symbols: SymbolContext, _ attempts: Int,\n    _ factories: [(String, Generators.Factory)]\n  ) -> Generators.Context {\n    Generators.Context(\n      schema: schema, symbols: symbols, factories: Dictionary(factories, uniquingKeysWith: { $1 }),\n      attempts: attempts)\n  }\n\n  /// Each boundary case, in order; the first that fails names its position.\n  public static func boundaries(\n    _ label: String, _ cases: [[Value]], _ law: ([Value]) throws -> Value\n  ) throws {\n    for (i, values) in cases.enumerated() {\n      do {\n        let result = try law(values)\n        guard case .bool(true) = result else {\n          throw LawSpecError(\n            \"ContractFailed\", \"\\(label) boundary \\(i) returned \\(Recorded.debug(result))\")\n        }\n      } catch let failure as LawSpecError {\n        throw LawSpecError(\n          \"BoundaryFailed\", \"\\(label) boundary \\(i) \\(render(values)): \\(failure)\",\n          cause: \"\\(failure)\")\n      }\n    }\n  }\n\n  /// A strategy's value must lie inside the input's refinement.\n  public static func checkDrawn(_ strategy: String, _ input: String, _ value: Value, _ holds: Bool)\n    throws -> Value\n  {\n    if holds { return value }\n    throw Harness.abort(\n      \"StrategyOutsideRefinement\",\n      \"strategy \\(strategy) produced \\(Recorded.renderPlain(value)) for \\(input), outside the input's refinement\"\n    )\n  }\n\n  /// A strategy's draw that keeps only values a predicate accepts.\n  public static func suchThat(\n    _ strategy: String, _ predicate: @escaping (Value) throws -> Bool, _ limit: Int,\n    _ gen: Gen<Value>\n  ) -> Gen<Value> {\n    gen.suchThat(predicate, limit) {\n      throw Harness.abort(\"StrategyDiscards\", \"strategy \\(strategy) discarded \\(limit) values\")\n    }\n  }\n}\n"
swiftSource "LawSpecTesting/Resources.swift" = "// Resources a law's cases use: acquired before a case and released after\n// it, even when it fails, or shared across a unit's cases (`share R per\n// unit`): acquired once, reset before each use, and released when the run\n// ends. A resource that is not concurrent is used by one case at a time.\n// ref:REQ-law-primitives ref:REQ-harness-units\n\nimport Foundation\nimport LawSpecRuntime\n\npublic enum Resources {\n  private static func cleanupFailure(_ detail: String, _ inner: any Error) -> LawSpecError {\n    let failure = LawSpecError(\"TestCleanupFailed\", \"\\(detail): \\(inner)\", cause: \"\\(inner)\")\n    Harness.markHarnessFailure(failure)\n    return failure\n  }\n\n  /// A resource for one case: the body's outcome stands unless releasing the\n  /// resource fails, which fails the case.\n  public static func withResource(\n    _ acquire: () throws -> Value, _ release: (Value) throws -> Value,\n    _ body: (Value) throws -> Value\n  ) throws -> Value {\n    let value = try acquire()\n    let outcome = Result { try body(value) }\n    var cleanup: (any Error)? = nil\n    do { _ = try release(value) } catch { cleanup = error }\n    switch (outcome, cleanup) {\n    case (.success(let result), nil): return result\n    case (.failure(let e), nil): throw e\n    case (.success, let c?): throw cleanupFailure(\"a resource's release failed\", c)\n    case (.failure(let e), let c?):\n      throw cleanupFailure(\"a resource's release failed after the case failed (\\(e))\", c)\n    }\n  }\n\n  private final class Shared: @unchecked Sendable {\n    let acquire: () throws -> Value\n    let reset: (Value) throws -> Value\n    let release: (Value) throws -> Value\n    let users: DispatchSemaphore?\n    let gate = NSLock()\n    var value: Value? = nil\n    var leases = 0\n\n    init(\n      _ acquire: @escaping () throws -> Value, _ reset: @escaping (Value) throws -> Value,\n      _ release: @escaping (Value) throws -> Value, _ concurrent: Bool\n    ) {\n      self.acquire = acquire\n      self.reset = reset\n      self.release = release\n      self.users = concurrent ? nil : DispatchSemaphore(value: 1)\n    }\n\n    func checkout() throws -> Value {\n      users?.wait()\n      gate.lock()\n      defer { gate.unlock() }\n      do {\n        if let v = value {\n          if leases == 0 { _ = try reset(v) }\n        } else {\n          value = try acquire()\n        }\n        leases += 1\n        return value!\n      } catch {\n        users?.signal()\n        throw error\n      }\n    }\n\n    func checkin() {\n      gate.lock()\n      leases -= 1\n      gate.unlock()\n      users?.signal()\n    }\n\n    func releaseNow() throws {\n      gate.lock()\n      defer { gate.unlock() }\n      if let v = value {\n        value = nil\n        _ = try release(v)\n      }\n    }\n  }\n\n  private static let shared = Locked([String: Shared]())\n\n  private static let released: Void = {\n    atexit {\n      for (key, entry) in Resources.shared.with({ $0 }) {\n        do { try entry.releaseNow() } catch {\n          FileHandle.standardError.write(\n            Data(\"LawSpec: releasing the shared resource \\(key) failed: \\(error)\\n\".utf8))\n        }\n      }\n    }\n  }()\n\n  /// A resource shared by a unit's cases.\n  public static func withShared(\n    _ key: String, _ acquire: @escaping () throws -> Value,\n    _ reset: @escaping (Value) throws -> Value,\n    _ release: @escaping (Value) throws -> Value, _ concurrent: Bool,\n    _ body: (Value) throws -> Value\n  ) throws -> Value {\n    _ = released\n    let entry = shared.with { table -> Shared in\n      if let found = table[key] { return found }\n      let made = Shared(acquire, reset, release, concurrent)\n      table[key] = made\n      return made\n    }\n    let value = try entry.checkout()\n    defer { entry.checkin() }\n    return try body(value)\n  }\n}\n"
swiftSource "LawSpecTesting/Scenario.swift" = "// Checked scenario programs run real concurrent processes, carrying vector\n// clocks with messages and joining every child before the final checks.\n// ref:DEC-sessions-by-construction ref:DEC-stateful-models-linearizability\n// ref:DEC-portable-seeded-generation\n\nimport Foundation\nimport LawSpecRuntime\n\npublic enum Scenario {\n  public typealias Descriptor = Descriptors.Descriptor\n\n  /// A step of a scenario process.\n  public indirect enum Act {\n    case call(String, String?, [Descriptor])\n    case send(String, Descriptor)\n    case receive(String, String)\n    case receiveOr(String, String, [Act])\n    case par([(Int, [Act])])\n    case expect(String, Descriptor)\n  }\n\n  /// A scenario program: its channels, mailboxes and root process; the\n  /// branches a crash schedule may select (identity, length); its wire forms.\n  public struct Program {\n    public let title: String\n    public let channels: [String]\n    public let mailboxes: [String]\n    public let acts: [Act]\n    public let branches: [(Int, Int)]\n    public let wire: [Descriptor]?\n  }\n\n  /// How scenarios run: cases and seed for check; and for one run, the receive\n  /// timeout (ms), whether values cross a network, whether a process crashes\n  /// (or which, at which step), network faults and the network deadline (ms).\n  public struct Options {\n    public var cases = 30\n    public var seed: BigInt?\n    public var receiveTimeout = 5000\n    public var network = false\n    public var crash = false\n    public var victim: (Int, Int)?\n    public var faults: (MemoryOptions) -> MemoryOptions = { $0 }\n    public var deadline = 5000\n    public init() {}\n  }\n\n  /// The default options.\n  public static var defaults: Options { Options() }\n\n  /// A run's report.\n  public struct Report {\n    public let title: String\n    public var history: [History.Event]\n    public var outcome: String\n    public var clock: ScenarioClock\n    public let shake: BigInt\n    public var victim: (Int, Int)?\n    public var network: ScenarioStats?\n    public var final: Value?\n    public var reason: String?\n  }\n\n  private static func fail(_ code: String, _ detail: String = \"\") -> LawSpecError {\n    Fail.with(code, detail)\n  }\n\n  private static func message(_ error: any Error) -> String {\n    if let e = error as? LawSpecError { return e.description }\n    return \"\\(type(of: error)): \\(error)\"\n  }\n\n  private static func name(_ d: Descriptor) throws -> String {\n    switch d {\n    case .atom(let a): return a\n    case .quoted(let q): return q\n    default: throw fail(\"InvalidScenario\", \"\\(d)\")\n    }\n  }\n\n  private static func annotate(_ acts: [Descriptor], _ next: Int, _ eligible: Bool) throws -> (\n    [Act], Int, [(Int, Int)]\n  ) {\n    var result = [Act]()\n    var n = next\n    var found = [(Int, Int)]()\n    for act in acts {\n      let (a, n1, b1) = try annotateAct(act, n, eligible)\n      result.append(a)\n      n = n1\n      found += b1\n    }\n    return (result, n, found)\n  }\n\n  private static func annotateAct(_ act: Descriptor, _ next: Int, _ eligible: Bool) throws -> (\n    Act, Int, [(Int, Int)]\n  ) {\n    guard case .forms(let parts) = act, let head = parts.first, case .atom(let verb) = head else {\n      throw fail(\"InvalidScenario\", \"\\(act)\")\n    }\n    let args = Array(parts.dropFirst())\n    switch verb {\n    case \"par\":\n      var branches = [(Int, [Act])]()\n      var n = next\n      var found = [(Int, Int)]()\n      for branch in args {\n        guard case .forms(let bparts) = branch, let bhead = bparts.first,\n          case .atom(\"process\") = bhead\n        else {\n          throw fail(\"InvalidScenario\", \"\\(branch)\")\n        }\n        let body = Array(bparts.dropFirst())\n        let id = n\n        let (acts, n1, b1) = try annotate(body, n + 1, eligible)\n        branches.append((id, acts))\n        found += (eligible ? [(id, body.count)] : []) + b1\n        n = n1\n      }\n      return (.par(branches), n, found)\n    case \"receiveor\" where args.count == 3:\n      guard case .forms(let bparts) = args[2], let bhead = bparts.first,\n        case .atom(\"process\") = bhead\n      else {\n        throw fail(\"InvalidScenario\", \"\\(act)\")\n      }\n      let (acts, n, _) = try annotate(Array(bparts.dropFirst()), next, false)\n      return (.receiveOr(try name(args[0]), try name(args[1]), acts), n, [])\n    case \"call\" where args.count >= 2:\n      let bound: String?\n      switch args[1] {\n      case .hole, .atom(\"_\"): bound = nil\n      default: bound = try name(args[1])\n      }\n      return (.call(try name(args[0]), bound, Array(args.dropFirst(2))), next, [])\n    case \"send\" where args.count == 2: return (.send(try name(args[0]), args[1]), next, [])\n    case \"receive\" where args.count == 2:\n      return (.receive(try name(args[0]), try name(args[1])), next, [])\n    case \"expect\" where args.count == 2: return (.expect(try name(args[0]), args[1]), next, [])\n    default: throw fail(\"InvalidScenario\", \"\\(act)\")\n    }\n  }\n\n  /// Read a program's text. Stable identities follow source order; pars inside\n  /// or-else handlers are real processes too, but crash schedules skip them.\n  public static func read(_ spec: String) throws -> Program {\n    let forms = try Descriptors.read(spec)\n    func find(_ key: String) -> [Descriptor]? {\n      for f in forms {\n        if case .forms(let parts) = f, let head = parts.first, case .atom(let k) = head, k == key {\n          return Array(parts.dropFirst())\n        }\n      }\n      return nil\n    }\n    guard case .forms(let first)? = forms.first, first.count >= 2, case .atom(\"scenario\") = first[0]\n    else {\n      throw fail(\"InvalidScenario\", \"scenario\")\n    }\n    let title = try name(first[1])\n    let (acts, _, branches) = try annotate(find(\"process\") ?? [], 1, true)\n    return Program(\n      title: title, channels: try (find(\"channels\") ?? []).map(name),\n      mailboxes: try (find(\"mailboxes\") ?? []).map(name),\n      acts: acts, branches: branches, wire: find(\"wire\"))\n  }\n\n  /// The process a crash schedule stops, and before which of its steps.\n  public static func victim(_ program: Program, _ shake: BigInt) -> (Int, Int)? {\n    if program.branches.isEmpty { return nil }\n    let r0 = Random.seed(shake ^ BigInt(UInt64(0xc3a5_c85c_97cb_3127)))\n    let (i, r1) = Random.below(BigInt(program.branches.count), r0)\n    let (identity, length) = program.branches[Int(i.truncated(Int64.self))]\n    let (at, _) = Random.below(BigInt(length + 1), r1)\n    return (identity, Int(at.truncated(Int64.self)))\n  }\n\n  /// Each case's shake, and whether it runs over a network or with a crash.\n  public static func schedules(_ seed: BigInt, _ runs: Int) -> [(BigInt, (Bool, Bool))] {\n    var random = Random.seed(seed ^ BigInt(UInt64(0x2545_f491_4f6c_dd1d)))\n    return (0..<max(0, runs)).map { i in\n      let (shake, next) = Random.next(random)\n      random = next\n      return (BigInt(shake), (i % 3 == 1, i % 3 == 2))\n    }\n  }\n\n  private final class Setup: @unchecked Sendable {\n    let program: Program\n    let model: Model.Machine\n    let context: Model.Context\n    let system: Any\n    let hub: ScenarioHub\n    let history = Locked<[Int64: History.Event]>([:])\n    let failure = Locked<String?>(nil)\n    let ticks = Locked<Int64>(0)\n    let commands: [String: Int]\n    let shake: BigInt\n    let victim: (Int, Int)?\n    let timeout: Int\n\n    init(\n      _ program: Program, _ model: Model.Machine, _ context: Model.Context, _ system: Any,\n      _ hub: ScenarioHub,\n      _ shake: BigInt, _ victim: (Int, Int)?, _ timeout: Int\n    ) {\n      self.program = program\n      self.model = model\n      self.context = context\n      self.system = system\n      self.hub = hub\n      var commands = [String: Int]()\n      for (i, c) in model.commands.enumerated() { commands[c.name] = i }\n      self.commands = commands\n      self.shake = shake\n      self.victim = victim\n      self.timeout = timeout\n    }\n\n    func tick() -> Int64 {\n      ticks.with {\n        $0 += 1\n        return $0\n      }\n    }\n  }\n\n  private struct State {\n    let id: String\n    var values: [String: Value]\n    var ends: [String: ScenarioDestination]\n    var clock: ScenarioClock\n    var random: Random.Seed\n    var crashable: Bool\n  }\n\n  private static func value(_ operand: Descriptor, _ values: [String: Value]) throws -> Value {\n    if case .forms(let parts) = operand, parts.count == 2, case .atom(let kind) = parts[0] {\n      switch (kind, parts[1]) {\n      case (\"var\", let n):\n        guard let v = values[try name(n)] else { throw fail(\"InvalidScenario\", \"\\(operand)\") }\n        return v\n      case (\"int\", .number(let n)): return .int(n)\n      case (\"bool\", let b): return .bool(try name(b) == \"true\")\n      case (\"text\", let t): return .text(try name(t))\n      case (\"tag\", let t): return .data(try name(t), [])\n      default: break\n      }\n    }\n    throw fail(\"InvalidScenario\", \"\\(operand)\")\n  }\n\n  private static func bump(_ state: State) -> State {\n    var next = state\n    next.clock[state.id] = (state.clock[state.id] ?? 0) + 1\n    return next\n  }\n\n  private static func mergeClock(_ a: ScenarioClock, _ b: ScenarioClock) -> ScenarioClock {\n    var acc = a\n    for (p, n) in b { acc[p] = max(acc[p] ?? 0, n) }\n    return acc\n  }\n\n  private static func perturb(_ state: State) -> State {\n    let (choice, next) = Random.below(BigInt(4), state.random)\n    switch choice.truncated(Int64.self) {\n    case 0: break\n    case 1: Thread.sleep(forTimeInterval: 0)\n    default: Thread.sleep(forTimeInterval: 0.001)\n    }\n    var made = state\n    made.random = next\n    return made\n  }\n\n  private static func names(_ acts: [Act]) -> [String] {\n    var found = [String]()\n    for act in acts {\n      switch act {\n      case .send(let n, let operand):\n        found.append(n)\n        if case .forms(let parts) = operand, parts.count == 2, case .atom(\"var\") = parts[0],\n          let v = try? name(parts[1])\n        {\n          found.append(v)\n        }\n      case .receive(let n, _): found.append(n)\n      case .receiveOr(let n, _, let handler): found += [n] + names(handler)\n      case .par(let branches): for (_, body) in branches { found += names(body) }\n      default: break\n      }\n    }\n    return Array(Set(found)).sorted { Scalar.compareText($0, $1) < 0 }\n  }\n\n  private static func countSends(_ acts: [Act], _ target: String) -> Int {\n    acts.reduce(0) { total, act in\n      switch act {\n      case .send(let n, _) where n == target: return total + 1\n      case .par(let branches): return total + branches.reduce(0) { $0 + countSends($1.1, target) }\n      default: return total\n      }\n    }\n  }\n\n  private static func sends(_ acts: [Act], _ boxes: [String]) -> [String: Int] {\n    var result = [String: Int]()\n    for n in boxes { result[n] = countSends(acts, n) }\n    return result\n  }\n\n  private static func receives(_ acts: [Act], _ target: String) -> Bool {\n    acts.contains { act in\n      switch act {\n      case .receive(let n, _): return n == target\n      case .par(let branches): return branches.contains { receives($0.1, target) }\n      default: return false\n      }\n    }\n  }\n\n  /// Each branch's ends: those its parent passes on, or a side of a channel the\n  /// branch is the first or second to use.\n  private static func divide(\n    _ branches: [(Int, [Act])], _ channels: [String], _ ends: [String: ScenarioDestination]\n  )\n    -> ([(Int, [Act], [String: ScenarioDestination])], [String: ScenarioDestination])\n  {\n    var users = [String: [Int]]()\n    for (i, branch) in branches.enumerated() {\n      for n in names(branch.1) { users[n, default: []].append(i) }\n    }\n    var remaining = ends\n    var plans = [(Int, [Act], [String: ScenarioDestination])]()\n    for (i, (id, body)) in branches.enumerated() {\n      var mine = [String: ScenarioDestination]()\n      for n in names(body) {\n        if let e = remaining[n] {\n          mine[n] = e\n          remaining[n] = nil\n        } else if channels.contains(n) {\n          let side = users[n]!.prefix { $0 != i }.count\n          mine[n] = .endOf(n, side)\n        }\n      }\n      plans.append((id, body, mine))\n    }\n    return (plans, remaining)\n  }\n\n  private static func destination(_ setup: Setup, _ target: String, _ state: State) throws\n    -> ScenarioDestination\n  {\n    if setup.program.mailboxes.contains(target) { return .mailboxOf(target) }\n    guard let d = state.ends[target] else { throw fail(\"InvalidScenario\", \"no end \" + target) }\n    return d\n  }\n\n  private static func give(_ operand: Descriptor, _ state: State) throws -> (ScenarioPayload, State)\n  {\n    if case .forms(let parts) = operand, parts.count == 2, case .atom(\"var\") = parts[0] {\n      let n = try name(parts[1])\n      if case .endOf(let c, let s)? = state.ends[n] {\n        var next = state\n        next.ends[n] = nil\n        return (.moved(c, s), next)\n      }\n      return (.plain(try value(operand, state.values)), state)\n    }\n    return (.plain(try value(operand, [:])), state)\n  }\n\n  private enum Step {\n    case next(State)\n    case finish(String, State)\n  }\n\n  private static func steps(_ setup: Setup, _ acts: [Act], _ state: State) throws -> (String, State)\n  {\n    var current = state\n    for (index, act) in acts.enumerated() {\n      let interrupted =\n        setup.failure.with({ $0 }) != nil\n        || (current.crashable\n          && setup.victim.map { \"\\($0.0)\" == current.id && $0.1 == index } == true)\n      if interrupted { return (\"failed\", current) }\n      switch try perform(setup, act, current) {\n      case .next(let next): current = next\n      case .finish(let outcome, let last): return (outcome, last)\n      }\n    }\n    let interrupted =\n      setup.failure.with({ $0 }) != nil\n      || (current.crashable\n        && setup.victim.map { \"\\($0.0)\" == current.id && $0.1 == acts.count } == true)\n    return (interrupted ? \"failed\" : \"done\", current)\n  }\n\n  private static func perform(_ setup: Setup, _ act: Act, _ state: State) throws -> Step {\n    switch act {\n    case .call(let command, let bound, let operands):\n      guard let index = setup.commands[command] else {\n        throw fail(\"InvalidScenario\", \"command \" + command)\n      }\n      let step = try Model.command(setup.model, index)\n      let args = try operands.map { try value($0, state.values) }\n      let s1 = bump(perturb(state))\n      let called = setup.tick()\n      let (result, _) = try Model.invoke(setup.model, setup.context, step, args, setup.system)\n      let returned = setup.tick()\n      var s2 = bump(s1)\n      let event = History.Event(\n        command: index, arguments: args, result: result, called: called, returned: returned,\n        process: state.id, callClock: s1.clock, returnClock: s2.clock)\n      setup.history.with { $0[called] = event }\n      if let bound { s2.values[bound] = result }\n      return .next(s2)\n    case .send(let target, let operand):\n      let d = try destination(setup, target, state)\n      let (payload, s1) = try give(operand, state)\n      let s2 = bump(perturb(s1))\n      try setup.hub.send(state.id, d, payload, s2.clock)\n      return .next(s2)\n    case .receive(let source, let variable):\n      return try accept(setup, source, variable, nil, state)\n    case .receiveOr(let source, let variable, let handler):\n      return try accept(setup, source, variable, handler, state)\n    case .par(let branches):\n      let program = setup.program\n      let (plans, ends) = divide(branches, program.channels, state.ends)\n      let children = plans.map { (id, body, mine) in\n        ScenarioChild(\n          id: \"\\(id)\", ends: mine.keys.sorted().map { mine[$0]! },\n          sends: sends(body, program.mailboxes),\n          receives: program.mailboxes.filter { receives(body, $0) })\n      }\n      try setup.hub.fork(state.id, children)\n      let outcomes = Locked([(String, ScenarioClock)?](repeating: nil, count: plans.count))\n      let group = DispatchGroup()\n      for (i, plan) in plans.enumerated() {\n        let random = Random.seed(\n          setup.shake ^ (BigInt(i + 1) * BigInt(UInt64(0x9e37_79b9_7f4a_7c15))))\n        let work = UncheckedBox((plan, state.values, state.clock))\n        group.enter()\n        LawThread.start {\n          let ((id, body, mine), values, clock) = work.value\n          let outcome = run(setup, \"\\(id)\", body, values, mine, clock, random)\n          outcomes.with { $0[i] = outcome }\n          group.leave()\n        }\n      }\n      group.wait()\n      let results = outcomes.with { $0 }.map { $0! }\n      var next = state\n      next.ends = ends\n      next.clock = results.reduce(state.clock) { mergeClock($0, $1.1) }\n      next = bump(next)\n      return results.contains { $0.0 == \"failed\" } ? .finish(\"failed\", next) : .next(next)\n    case .expect(let variable, let constant):\n      guard let actual = state.values[variable] else {\n        throw fail(\"InvalidScenario\", \"unbound \" + variable)\n      }\n      let wanted = try value(constant, [:])\n      if Scalar.equal(actual, wanted) { return .next(state) }\n      throw fail(\n        \"ScenarioExpectation\",\n        \"\\(variable) is \\(Recorded.debug(actual)), expected \\(Recorded.debug(wanted))\")\n    }\n  }\n\n  private static func accept(\n    _ setup: Setup, _ source: String, _ variable: String, _ handler: [Act]?, _ state: State\n  ) throws -> Step {\n    let d = try destination(setup, source, state)\n    switch try setup.hub.receive(state.id, d, setup.timeout) {\n    case .senderGone:\n      guard let acts = handler else { return .finish(\"failed\", state) }\n      if case .endOf = d { try setup.hub.abandon(state.id, d) }\n      var next = state\n      next.ends[source] = nil\n      next.crashable = false\n      let (outcome, last) = try steps(setup, acts, next)\n      return .finish(outcome, last)\n    case .arrived(let payload, let sent):\n      var next = state\n      next.clock = mergeClock(state.clock, sent)\n      next = bump(next)\n      switch payload {\n      case .moved(let c, let s): next.ends[variable] = .endOf(c, s)\n      case .plain(let v): next.values[variable] = v\n      }\n      return .next(next)\n    }\n  }\n\n  private static func run(\n    _ setup: Setup, _ id: String, _ acts: [Act], _ values: [String: Value],\n    _ ends: [String: ScenarioDestination],\n    _ clock: ScenarioClock, _ random: Random.Seed\n  ) -> (String, ScenarioClock) {\n    defer { try? setup.hub.leave(id) }\n    do {\n      if id != \"root\" { try setup.hub.enter(id) }\n      let state = State(\n        id: id, values: values, ends: ends, clock: clock, random: random, crashable: true)\n      let (outcome, last) = try steps(setup, acts, state)\n      return (outcome, last.clock)\n    } catch {\n      let text = \"process \\(id) raised \\(message(error))\"\n      setup.failure.with { if $0 == nil { $0 = text } }\n      return (\"failed\", clock)\n    }\n  }\n\n  /// Run a program once with a shake; its report, as a success or a failure.\n  public static func runOnce(\n    _ model: Model.Machine, _ program: Program, _ shake: BigInt, _ options: Options\n  ) -> Result<Report, ReportFailure> {\n    func failed(_ reason: String) -> Result<Report, ReportFailure> {\n      .failure(\n        ReportFailure(\n          report: Report(\n            title: program.title, history: [], outcome: \"failed\", clock: [:], shake: shake,\n            victim: nil, network: nil, final: nil, reason: reason)))\n    }\n    do {\n      if !model.shared { throw fail(\"ScenarioRequiresSharedModel\", model.name) }\n      let chosen = options.victim ?? (options.crash ? victim(program, shake) : nil)\n      if let (id, at) = chosen {\n        guard let (_, length) = program.branches.first(where: { $0.0 == id }), at >= 0, at <= length\n        else {\n          throw fail(\"InvalidScenarioVictim\", \"\\(id) \\(at)\")\n        }\n      }\n      let start = try model.startArguments.map { try Descriptors.minimal($0, model.table) }\n      return try Model.withSystem(model, start, 0) { context, system, expected in\n        let io = ScenarioIoOptions(\n          network: options.network, wire: program.wire, shake: shake, faults: options.faults,\n          deadline: options.deadline)\n        return try ScenarioIo.withIo(program.channels, sends(program.acts, program.mailboxes), io) {\n          hub in\n          let setup = Setup(\n            program, model, context, system, hub, shake, chosen, options.receiveTimeout)\n          let (outcome, clock) = run(setup, \"root\", program.acts, [:], [:], [:], Random.seed(shake))\n          let events = setup.history.with { $0 }.sorted { $0.key < $1.key }.map { $0.value }\n          var report = Report(\n            title: program.title, history: events, outcome: outcome, clock: clock, shake: shake,\n            victim: chosen, network: try hub.networkStats(), final: nil, reason: nil)\n          if let failure = setup.failure.with({ $0 }) {\n            report.reason = failure\n            return .failure(ReportFailure(report: report))\n          }\n          if outcome == \"failed\" && chosen == nil {\n            report.reason = \"process_failed\"\n            return .failure(ReportFailure(report: report))\n          }\n          let final = try model.abstractRun.map {\n            try Model.callback($0, context, [try Model.systemState(model, system)])\n          }\n          report.final = final\n          if History.consistent(model, context, events, expected, final, system) {\n            return .success(report)\n          }\n          report.reason = \"no_consistent_order\"\n          return .failure(ReportFailure(report: report))\n        }\n      }\n    } catch {\n      return failed(message(error))\n    }\n  }\n\n  /// A failed run's report.\n  public struct ReportFailure: Error, @unchecked Sendable {\n    public let report: Report\n  }\n\n  /// Run a program text once with a shake: nil, or why it failed.\n  public static func execute(\n    _ model: Model.Machine, _ spec: String, _ shake: BigInt, _ options: Options\n  ) throws -> Report? {\n    switch runOnce(model, try read(spec), shake, options) {\n    case .success: return nil\n    case .failure(let f): return f.report\n    }\n  }\n\n  private static func describe(_ victim: (Int, Int)?) -> String {\n    guard let (id, at) = victim else { return \"none\" }\n    return \"(\\(id), \\(at))\"\n  }\n\n  /// Check a scenario over its cases: plain, over a faulty network, and with a\n  /// crash, in turn; the first failure is raised with its seed and shake.\n  public static func checkWith(_ options: Options, _ model: Model.Machine, _ spec: String) throws {\n    let program = try read(spec)\n    let seed = Model.seed(options.seed).state\n    if options.cases <= 0 { throw fail(\"ScenarioRequiresCases\") }\n    for (i, (shake, (network, crash))) in schedules(BigInt(seed), options.cases).enumerated() {\n      var run = options\n      run.network = network\n      run.crash = crash\n      if case .failure(let f) = runOnce(model, program, shake, run) {\n        throw fail(\n          \"ScenarioFailed\",\n          \"\\(program.title): seed \\(seed) (LAWSPEC_SEED=\\(seed) replays it), case \\(i), shake \\(shake), network \\(network), crash \\(crash), victim \\(describe(f.report.victim)): \\(f.report.reason ?? \"\")\"\n        )\n      }\n    }\n  }\n\n  /// Check a scenario with the default options.\n  public static func check(_ model: Model.Machine, _ spec: String) throws {\n    try checkWith(defaults, model, spec)\n  }\n}\n"
swiftSource "LawSpecTesting/ScenarioIo.swift" = "// A scenario's channels, delegated ends and mailbox send obligations have\n// one owner. A single serial queue transfers them atomically and never runs\n// application code. Leaving a process releases both its current and its\n// unforked work. ref:DEC-sessions-by-construction\n\nimport Foundation\nimport LawSpecRuntime\n\n/// What a receive gives: a payload and the clock it was sent at, or that its\n/// sender has gone.\npublic enum ScenarioReceived {\n  case arrived(ScenarioPayload, ScenarioClock)\n  case senderGone\n}\n\n/// A child process to reserve before it runs: the ends it takes, the mailbox\n/// sends it may make and the mailboxes it receives from.\nstruct ScenarioChild {\n  let id: String\n  let ends: [ScenarioDestination]\n  let sends: [String: Int]\n  let receives: [String]\n}\n\n/// How the hub's run is carried: over a network (with the program's wire\n/// forms, the run's shake, fault options and the deadline in ms) or not.\nstruct ScenarioIoOptions {\n  let network: Bool\n  let wire: [Descriptors.Descriptor]?\n  let shake: BigInt\n  let faults: (MemoryOptions) -> MemoryOptions\n  let deadline: Int\n}\n\n/// The hub of one scenario run. Every request runs on its serial queue.\nfinal class ScenarioHub: @unchecked Sendable {\n  private struct Invalid: Error {\n    let reason: String\n  }\n\n  private struct Waiting {\n    let reply: (ScenarioReceived) -> Void\n    let fail: (String) -> Void\n    let ticket: Int64\n  }\n\n  private final class QueueState {\n    var owner = \"root\"\n    var closed = false\n    var items: [(ScenarioPayload, ScenarioClock)] = []\n    var waiting: Waiting?\n    var inFlight = 0\n    var remoteGone = false\n    var outstanding: Int\n    init(_ outstanding: Int) { self.outstanding = outstanding }\n  }\n\n  private final class ProcessState {\n    var entered: Bool\n    let parent: String?\n    var sends: [String: Int]\n    var closed = false\n    init(_ entered: Bool, _ parent: String?, _ sends: [String: Int]) {\n      self.entered = entered\n      self.parent = parent\n      self.sends = sends\n    }\n  }\n\n  private let queue = DispatchQueue(label: \"lawspec.scenario.hub\")\n  // Destinations in a stable order, so closing follows creation order.\n  private var order: [ScenarioDestination] = []\n  private var queues: [ScenarioDestination: QueueState] = [:]\n  private var processOrder: [String] = []\n  private var processes: [String: ProcessState] = [:]\n  private var tickets: Int64 = 0\n  private var network: ScenarioNetwork?\n  private var stopped = false\n\n  init(_ channels: [String], _ mailboxes: [String: Int], _ options: ScenarioIoOptions) throws {\n    for name in channels {\n      for side in [0, 1] { add(.endOf(name, side), 0) }\n    }\n    for name in mailboxes.keys.sorted() { add(.mailboxOf(name), mailboxes[name]!) }\n    processes[\"root\"] = ProcessState(true, nil, mailboxes)\n    processOrder.append(\"root\")\n    if options.network {\n      // Reports posted while the network starts wait until it is set.\n      queue.suspend()\n      defer { queue.resume() }\n      network = try ScenarioNetwork(\n        channels, mailboxes.keys.sorted(), options.wire, options.shake, options.faults,\n        options.deadline\n      ) { [weak self] incoming in self?.post(incoming) }\n    }\n  }\n\n  private func add(_ d: ScenarioDestination, _ outstanding: Int) {\n    order.append(d)\n    queues[d] = QueueState(outstanding)\n  }\n\n  private func post(_ incoming: ScenarioIncoming) {\n    queue.async { self.handleNetwork(incoming) }\n  }\n\n  private static func require(_ condition: Bool, _ reason: String) throws {\n    if !condition { throw Invalid(reason: reason) }\n  }\n\n  private static func describe(_ d: ScenarioDestination) -> String {\n    switch d {\n    case .endOf(let n, let s): return \"end \\(n) \\(s)\"\n    case .mailboxOf(let n): return \"mailbox \" + n\n    }\n  }\n\n  private func queueOf(_ d: ScenarioDestination) throws -> QueueState {\n    guard let q = queues[d] else {\n      throw Invalid(reason: \"unknown_destination \" + Self.describe(d))\n    }\n    return q\n  }\n\n  private func process(_ id: String) throws -> ProcessState {\n    guard let p = processes[id] else { throw Invalid(reason: \"unknown_process \" + id) }\n    return p\n  }\n\n  @discardableResult\n  private func ownedProcess(_ id: String) throws -> ProcessState {\n    let p = try process(id)\n    try Self.require(!p.closed && p.entered, \"not_process_owner \" + id)\n    return p\n  }\n\n  @discardableResult\n  private func ownedQueue(_ id: String, _ d: ScenarioDestination) throws -> QueueState {\n    let q = try queueOf(d)\n    try Self.require(!q.closed && q.owner == id, \"not_endpoint_owner \" + Self.describe(d))\n    return q\n  }\n\n  private func discard(_ payload: ScenarioPayload) throws {\n    if case .moved(let n, let s) = payload { try closeQueue(.endOf(n, s)) }\n  }\n\n  private func arrive(_ d: ScenarioDestination, _ payload: ScenarioPayload, _ clock: ScenarioClock)\n    throws\n  {\n    let q = try queueOf(d)\n    if q.closed {\n      try discard(payload)\n    } else {\n      q.items.append((payload, clock))\n      try wake(d)\n    }\n  }\n\n  /// Drain accepted values before reporting that a sender has gone. A moved\n  /// end is owned by the queue until its recipient receives it.\n  private func wake(_ d: ScenarioDestination) throws {\n    let q = try queueOf(d)\n    guard let waiting = q.waiting else { return }\n    if !q.items.isEmpty {\n      let (payload, clock) = q.items.removeFirst()\n      q.waiting = nil\n      if case .moved(let n, let s) = payload { try queueOf(.endOf(n, s)).owner = q.owner }\n      waiting.reply(.arrived(payload, clock))\n      return\n    }\n    let gone: Bool\n    switch d {\n    case .mailboxOf: gone = q.outstanding + q.inFlight == 0\n    case .endOf(let n, let s):\n      gone = network == nil ? try queueOf(.endOf(n, 1 - s)).closed : q.remoteGone\n    }\n    if gone {\n      q.waiting = nil\n      waiting.reply(.senderGone)\n    }\n  }\n\n  private func closeQueue(_ d: ScenarioDestination) throws {\n    let q = try queueOf(d)\n    if q.closed { return }\n    // Mark closed before following delegated ends, so cyclic queues end.\n    q.closed = true\n    if let waiting = q.waiting {\n      q.waiting = nil\n      waiting.reply(.senderGone)\n    }\n    let items = q.items\n    q.items.removeAll()\n    for (payload, _) in items { try discard(payload) }\n    if let network {\n      network.abandon(d)\n    } else if case .endOf(let n, let s) = d {\n      try wake(.endOf(n, 1 - s))\n    }\n  }\n\n  private func closeProcess(_ id: String) throws {\n    let p = try process(id)\n    if p.closed { return }\n    let sends = p.sends\n    p.closed = true\n    p.sends = [:]\n    for child in processOrder where processes[child]?.parent == id { try closeProcess(child) }\n    for d in order where queues[d]!.owner == id || id == \"root\" { try closeQueue(d) }\n    for (name, count) in sends.sorted(by: { $0.key < $1.key }) {\n      let q = try queueOf(.mailboxOf(name))\n      q.outstanding -= count\n      try wake(.mailboxOf(name))\n    }\n  }\n\n  private func reserve(_ parent: String, _ child: ScenarioChild) throws {\n    try Self.require(processes[child.id] == nil, \"duplicate_process \" + child.id)\n    let p = try process(parent)\n    var remaining = p.sends\n    for (name, count) in child.sends.sorted(by: { $0.key < $1.key }) {\n      let available = remaining[name] ?? 0\n      try Self.require(count >= 0 && count <= available, \"send_quota \" + name)\n      remaining[name] = available - count\n    }\n    for d in child.ends + child.receives.map({ ScenarioDestination.mailboxOf($0) }) {\n      let q = try ownedQueue(parent, d)\n      try Self.require(q.waiting == nil, \"already_receiving \" + Self.describe(d))\n      q.owner = child.id\n    }\n    p.sends = remaining\n    processes[child.id] = ProcessState(false, parent, child.sends)\n    processOrder.append(child.id)\n  }\n\n  private func outcome(_ outcome: ScenarioOutcome) throws {\n    func unflight(_ d: ScenarioDestination) throws {\n      if case .mailboxOf = d { try queueOf(d).inFlight -= 1 }\n    }\n    switch outcome {\n    case .delivered(let d, let payload, let clock):\n      try unflight(d)\n      try arrive(d, payload, clock)\n    case .lost(let d, let payload):\n      try unflight(d)\n      try discard(payload)\n      try wake(d)\n    case .gone(let d):\n      try queueOf(d).remoteGone = true\n      try wake(d)\n    }\n  }\n\n  private func handleNetwork(_ incoming: ScenarioIncoming) {\n    guard !stopped, let network else { return }\n    let outcomes = (try? network.event(incoming)) ?? []\n    for o in outcomes { try? outcome(o) }\n  }\n\n  private func timedOut(_ d: ScenarioDestination, _ ticket: Int64) {\n    guard let q = queues[d], let waiting = q.waiting, waiting.ticket == ticket else { return }\n    q.waiting = nil\n    waiting.fail(\"receive_timeout \" + Self.describe(d))\n  }\n\n  /// Run a request on the queue; its result, or the reason it is invalid.\n  private func call<T>(\n    _ request: @escaping (@escaping (Result<T, ScenarioFault>) -> Void) throws -> Void\n  ) throws -> T {\n    let result = Locked<Result<T, ScenarioFault>?>(nil)\n    let done = DispatchSemaphore(value: 0)\n    let reply: (Result<T, ScenarioFault>) -> Void = { r in\n      let first = result.with { (s: inout Result<T, ScenarioFault>?) -> Bool in\n        if s != nil { return false }\n        s = r\n        return true\n      }\n      if first { done.signal() }\n    }\n    let work = UncheckedBox((request, reply))\n    queue.async {\n      let (request, reply) = work.value\n      do {\n        try request(reply)\n      } catch let invalid as Invalid {\n        reply(.failure(ScenarioFault(invalid.reason)))\n      } catch let e as LawSpecError {\n        reply(.failure(ScenarioFault(e.description)))\n      } catch {\n        reply(.failure(ScenarioFault(\"\\(type(of: error)): \\(error)\")))\n      }\n    }\n    done.wait()\n    switch result.with({ $0 })! {\n    case .success(let value): return value\n    case .failure(let fault): throw Fail.with(\"ScenarioIo\", fault.reason)\n    }\n  }\n\n  func fork(_ parent: String, _ children: [ScenarioChild]) throws {\n    try call { (reply: @escaping (Result<Void, ScenarioFault>) -> Void) in\n      try self.ownedProcess(parent)\n      // Reserve every child's obligations before any of them runs.\n      for child in children { try self.reserve(parent, child) }\n      reply(.success(()))\n    }\n  }\n\n  func enter(_ id: String) throws {\n    try call { (reply: @escaping (Result<Void, ScenarioFault>) -> Void) in\n      let p = try self.process(id)\n      try Self.require(!p.closed && !p.entered, \"cannot_enter \" + id)\n      p.entered = true\n      reply(.success(()))\n    }\n  }\n\n  func leave(_ id: String) throws {\n    try call { (reply: @escaping (Result<Void, ScenarioFault>) -> Void) in\n      _ = try self.process(id)\n      try self.closeProcess(id)\n      reply(.success(()))\n    }\n  }\n\n  func abandon(_ id: String, _ d: ScenarioDestination) throws {\n    try call { (reply: @escaping (Result<Void, ScenarioFault>) -> Void) in\n      try self.ownedProcess(id)\n      try self.ownedQueue(id, d)\n      try self.closeQueue(d)\n      reply(.success(()))\n    }\n  }\n\n  func send(\n    _ id: String, _ d: ScenarioDestination, _ payload: ScenarioPayload, _ clock: ScenarioClock\n  ) throws {\n    try call { (reply: @escaping (Result<Void, ScenarioFault>) -> Void) in\n      try self.ownedProcess(id)\n      if case .moved(let n, let s) = payload {\n        try self.ownedQueue(id, .endOf(n, s))\n        try Self.require(\n          ScenarioDestination.endOf(n, s) != d, \"self_delegation \" + Self.describe(d))\n      }\n      let target: ScenarioDestination\n      switch d {\n      case .endOf(let n, let s):\n        try self.ownedQueue(id, d)\n        target = .endOf(n, 1 - s)\n      case .mailboxOf(let name):\n        let p = try self.process(id)\n        let count = p.sends[name] ?? 0\n        try Self.require(count > 0, \"send_quota \" + name)\n        p.sends[name] = count - 1\n        try self.queueOf(d).outstanding -= 1\n        target = d\n      }\n      if case .moved(let n, let s) = payload { try self.queueOf(.endOf(n, s)).owner = \"queued\" }\n      if try self.queueOf(target).closed {\n        try self.discard(payload)\n        reply(.success(()))\n      } else if let network = self.network {\n        if !(try network.send(d, payload, clock, reply)) {\n          try self.queueOf(target).inFlight += 1\n        } else {\n          reply(.success(()))\n        }\n      } else {\n        try self.arrive(target, payload, clock)\n        reply(.success(()))\n      }\n    }\n  }\n\n  /// Receive at a destination, within a timeout in ms.\n  func receive(_ id: String, _ d: ScenarioDestination, _ timeout: Int) throws -> ScenarioReceived {\n    try call { (reply: @escaping (Result<ScenarioReceived, ScenarioFault>) -> Void) in\n      try self.ownedProcess(id)\n      let q = try self.ownedQueue(id, d)\n      try Self.require(q.waiting == nil, \"already_receiving \" + Self.describe(d))\n      try Self.require(timeout >= 0, \"invalid_timeout\")\n      self.tickets += 1\n      let ticket = self.tickets\n      q.waiting = Waiting(\n        reply: { reply(.success($0)) }, fail: { reply(.failure(ScenarioFault($0))) }, ticket: ticket\n      )\n      self.queue.asyncAfter(\n        deadline: .now() + .milliseconds(timeout), execute: { [self] in self.timedOut(d, ticket) })\n      try self.wake(d)\n    }\n  }\n\n  func networkStats() throws -> ScenarioStats? {\n    try call { (reply: @escaping (Result<ScenarioStats?, ScenarioFault>) -> Void) in\n      reply(.success(self.network?.stats()))\n    }\n  }\n\n  func stop() throws {\n    try call { (reply: @escaping (Result<Void, ScenarioFault>) -> Void) in\n      for d in self.order {\n        let q = self.queues[d]!\n        q.waiting?.fail(\"hub_stopped\")\n        q.waiting = nil\n      }\n      self.network?.close()\n      self.stopped = true\n      reply(.success(()))\n    }\n  }\n}\n\nenum ScenarioIo {\n  /// A hub for a body, stopped after it.\n  static func withIo<A>(\n    _ channels: [String], _ mailboxes: [String: Int], _ options: ScenarioIoOptions,\n    _ body: (ScenarioHub) throws -> A\n  ) throws -> A {\n    let hub = try ScenarioHub(channels, mailboxes, options)\n    defer { try? hub.stop() }\n    return try body(hub)\n  }\n}\n"
swiftSource "LawSpecTesting/ScenarioNetwork.swift" = "// Scenario values use the same canonical frames, reliable endpoints and\n// mailbox receipts as native distribution. Only causal metadata stays beside\n// the transport: channel clocks follow sequence order, and mailbox clocks\n// follow the actual source/request identity, even after reordering.\n// ref:DEC-distribution-canonical-wire ref:DEC-stateful-models-linearizability\n\nimport Foundation\nimport LawSpecRuntime\n\n/// A channel end (channel, side) or a mailbox of a scenario.\npublic enum ScenarioDestination: Hashable, Sendable {\n  case endOf(String, Int)\n  case mailboxOf(String)\n}\n\n/// What a scenario sends: a value, or a channel end it hands over.\npublic enum ScenarioPayload: Sendable {\n  case plain(Value)\n  case moved(String, Int)\n}\n\n/// Why a scenario hub or network request failed.\npublic struct ScenarioFault: Error, Sendable {\n  public let reason: String\n  public init(_ reason: String) { self.reason = reason }\n}\n\n/// A vector clock: each process's count of steps.\npublic typealias ScenarioClock = [String: Int64]\n\n/// A mailbox request's identity, set once the request is made.\nfinal class RequestCell: @unchecked Sendable {\n  var identity: UInt64 = 0\n}\n\n/// What the network's services report, posted to the scenario's hub.\nenum ScenarioIncoming: @unchecked Sendable {\n  case channelResult(ScenarioDestination, Int64, Result<[UInt8], NodeFailure>)\n  case mailFrame(ScenarioDestination, Node, Frame)\n  case mailReply(RequestCell, Result<(Int, [UInt8]), NodeFailure>)\n}\n\n/// What a report means for the hub's queues.\nenum ScenarioOutcome {\n  case delivered(ScenarioDestination, ScenarioPayload, ScenarioClock)\n  case lost(ScenarioDestination, ScenarioPayload)\n  case gone(ScenarioDestination)\n}\n\n/// Frame counts of a run over the network.\npublic struct ScenarioStats: Sendable {\n  public let frames: Int\n  public let lost: Int\n  public let duplicated: Int\n  public let pendingRequests: Int\n}\n\n/// The network of one scenario run: a seeded faulty memory network, a node per\n/// channel end and two per mailbox. Only the hub calls it, one call at a time.\nfinal class ScenarioNetwork: @unchecked Sendable {\n  private final class EndEntry {\n    let endpoint: Endpoint\n    var sends: [Descriptors.Descriptor]\n    var receives: [Descriptors.Descriptor]\n    var clocks: [(ScenarioPayload, ScenarioClock)] = []\n    var ticket: Int64?\n    init(\n      _ endpoint: Endpoint, _ sends: [Descriptors.Descriptor], _ receives: [Descriptors.Descriptor]\n    ) {\n      self.endpoint = endpoint\n      self.sends = sends\n      self.receives = receives\n    }\n  }\n\n  private struct Box {\n    let sender: Node\n    let address: String\n    let type: Descriptors.Descriptor\n  }\n\n  private struct Flight {\n    let destination: ScenarioDestination\n    let value: ScenarioPayload\n    let clock: ScenarioClock\n  }\n\n  private struct FlightKey: Hashable {\n    let source: String\n    let identity: UInt64\n  }\n\n  private static func fail(_ reason: String) -> LawSpecError {\n    Fail.with(\"ScenarioNetwork\", reason)\n  }\n\n  private static func require(_ condition: Bool, _ reason: String) throws {\n    if !condition { throw fail(reason) }\n  }\n\n  private static func unquote(_ d: Descriptors.Descriptor) throws -> String {\n    switch d {\n    case .quoted(let q), .atom(let q): return q\n    default: throw fail(\"invalid_wire\")\n    }\n  }\n\n  private let table: Descriptors.Table\n  private let network: MemoryNetwork\n  private let deadline: Int\n  private let post: @Sendable (ScenarioIncoming) -> Void\n  private var nodes: [Node] = []\n  private var ends: [ScenarioDestination: EndEntry] = [:]\n  private var boxes: [ScenarioDestination: Box] = [:]\n  private var flights: [FlightKey: Flight] = [:]\n  private var pending: [UInt64: ((Result<Void, ScenarioFault>) -> Void, FlightKey)] = [:]\n\n  init(\n    _ channels: [String], _ mailboxes: [String], _ wire: [Descriptors.Descriptor]?, _ shake: BigInt,\n    _ faults: (MemoryOptions) -> MemoryOptions, _ deadline: Int,\n    _ post: @escaping @Sendable (ScenarioIncoming) -> Void\n  ) throws {\n    let forms: [Descriptors.Descriptor]\n    if let wire {\n      forms = wire\n    } else if channels.isEmpty && mailboxes.isEmpty {\n      forms = []\n    } else {\n      throw Self.fail(\"scenario_wire_required\")\n    }\n    var steps: [String: [Descriptors.Descriptor]] = [:]\n    var types: [String: Descriptors.Descriptor] = [:]\n    var table = Descriptors.Table()\n    for form in forms {\n      guard case .forms(let parts) = form, let head = parts.first, case .atom(let key) = head else {\n        continue\n      }\n      if key == \"channel\", parts.count >= 2 {\n        steps[try Self.unquote(parts[1])] = Array(parts.dropFirst(2))\n      }\n      if key == \"mailbox\", parts.count == 3 { types[try Self.unquote(parts[1])] = parts[2] }\n      if key == \"data\", parts.count >= 2 { table[try Self.unquote(parts[1])] = form }\n    }\n    try Self.require(steps.keys.sorted() == channels.sorted(), \"channel_wire_required\")\n    try Self.require(types.keys.sorted() == mailboxes.sorted(), \"mailbox_wire_required\")\n    self.table = table\n    self.deadline = deadline\n    self.post = post\n    let defaults = MemoryOptions(\n      seed: shake ^ BigInt(UInt64(0x7f4a_7c15_9e37_79b9)), loss: 0.1, duplicate: 0.1, delay: 0.002,\n      record: true)\n    network = try MemoryNetwork(faults(defaults))\n    for name in channels {\n      let a = try addEnd(name, 0, steps[name]!)\n      let b = try addEnd(name, 1, steps[name]!)\n      try b.connect(a.address)\n    }\n    for name in mailboxes.sorted() {\n      let owner = try addNode()\n      let sender = try addNode()\n      let destination = ScenarioDestination.mailboxOf(name)\n      let address = try owner.registerReceiver(\"mail\") { frame in\n        post(.mailFrame(destination, owner, frame))\n      }\n      boxes[destination] = Box(sender: sender, address: address, type: types[name]!)\n    }\n  }\n\n  private func addNode() throws -> Node {\n    let node = try Node(\n      Transports.insecureMemoryForTests(network, \"scenario-\\(nodes.count)\"), NetworkConfig.empty)\n    nodes.append(node)\n    return node\n  }\n\n  private func listen(_ destination: ScenarioDestination, _ entry: EndEntry) throws {\n    // The callback may come before the ticket is known; the hub reads it later.\n    let ticket = Locked<Int64>(0)\n    let post = self.post\n    let made = try entry.endpoint.receiveAsync(nil) { result in\n      post(.channelResult(destination, ticket.with { $0 }, result))\n    }\n    ticket.with { $0 = made }\n    entry.ticket = made\n  }\n\n  private func addEnd(_ name: String, _ side: Int, _ ss: [Descriptors.Descriptor]) throws\n    -> Endpoint\n  {\n    let node = try addNode()\n    let endpoint = try Endpoint(node, \"end\", deadline)\n    let verbs: [(Bool, Descriptors.Descriptor)] = try ss.map { s in\n      guard case .forms(let parts) = s, parts.count == 2, case .atom(let verb) = parts[0] else {\n        throw Self.fail(\"invalid_wire\")\n      }\n      return (verb == \"send\", parts[1])\n    }\n    let entry = EndEntry(\n      endpoint, verbs.filter { $0.0 == (side == 0) }.map { $0.1 },\n      verbs.filter { $0.0 != (side == 0) }.map { $0.1 })\n    ends[.endOf(name, side)] = entry\n    try listen(.endOf(name, side), entry)\n    return endpoint\n  }\n\n  private func isEnd(_ d: Descriptors.Descriptor) -> Bool {\n    if case .forms(let parts) = d, parts.count == 1, case .atom(\"end\") = parts[0] { return true }\n    return false\n  }\n\n  private func encode(_ d: Descriptors.Descriptor, _ payload: ScenarioPayload) throws -> [UInt8] {\n    switch payload {\n    case .moved(let name, let side) where isEnd(d):\n      try Self.require(ends[.endOf(name, side)] != nil, \"unknown_delegated_end\")\n      return try Descriptors.encode(.forms([.atom(\"text\")]), .text(\"\\(name)#\\(side)\"), [:])\n    case .plain(let value):\n      return try Descriptors.encode(d, value, table)\n    default:\n      throw Self.fail(\"invalid_payload\")\n    }\n  }\n\n  private func decode(_ d: Descriptors.Descriptor, _ bytes: [UInt8]) throws -> ScenarioPayload {\n    guard isEnd(d) else { return .plain(try Descriptors.decode(d, bytes, table)) }\n    guard case .text(let address) = try Descriptors.decode(.forms([.atom(\"text\")]), bytes, [:]),\n      let at = address.lastIndex(of: \"#\"), let side = Int(address[address.index(after: at)...])\n    else {\n      throw Self.fail(\"unknown_delegated_end\")\n    }\n    let name = String(address[..<at])\n    try Self.require(ends[.endOf(name, side)] != nil, \"unknown_delegated_end\")\n    return .moved(name, side)\n  }\n\n  /// Send from an end, or to a mailbox (whose reply comes later): whether\n  /// the send is complete now.\n  func send(\n    _ destination: ScenarioDestination, _ payload: ScenarioPayload, _ clock: ScenarioClock,\n    _ reply: @escaping (Result<Void, ScenarioFault>) -> Void\n  ) throws -> Bool {\n    switch destination {\n    case .endOf(let name, let side):\n      let entry = ends[destination]!\n      guard let d = entry.sends.first else { throw Self.fail(\"protocol_complete\") }\n      try entry.endpoint.send(try encode(d, payload))\n      entry.sends.removeFirst()\n      ends[.endOf(name, 1 - side)]!.clocks.append((payload, clock))\n      return true\n    case .mailboxOf:\n      let box = boxes[destination]!\n      let bytes = try encode(box.type, payload)\n      let cell = RequestCell()\n      let post = self.post\n      let identity = try box.sender.requestAsync(box.address, \"mail\", bytes, deadline) { result in\n        post(.mailReply(cell, result))\n      }\n      cell.identity = identity\n      let key = FlightKey(source: box.sender.address, identity: identity)\n      flights[key] = Flight(destination: destination, value: payload, clock: clock)\n      pending[identity] = (reply, key)\n      return false\n    }\n  }\n\n  func abandon(_ destination: ScenarioDestination) {\n    if case .endOf = destination { ends[destination]?.endpoint.abandon() }\n  }\n\n  /// What an incoming report means.\n  func event(_ incoming: ScenarioIncoming) throws -> [ScenarioOutcome] {\n    switch incoming {\n    case .channelResult(let destination, let ticket, let result):\n      guard let entry = ends[destination], entry.ticket == ticket else { return [] }\n      switch result {\n      case .success(let bytes):\n        guard let d = entry.receives.first else { throw Self.fail(\"protocol_complete\") }\n        let (_, clock) = entry.clocks.removeFirst()\n        let value = try decode(d, bytes)\n        entry.receives.removeFirst()\n        try listen(destination, entry)\n        return [.delivered(destination, value, clock)]\n      case .failure:\n        let lost = entry.clocks.map { ScenarioOutcome.lost(destination, $0.0) }\n        entry.clocks.removeAll()\n        entry.ticket = nil\n        return lost + [.gone(destination)]\n      }\n    case .mailFrame(let destination, let owner, let frame):\n      let key = FlightKey(source: frame.source, identity: frame.id)\n      if let flight = flights[key], flight.destination == destination, frame.kind == \"mail\" {\n        let value = ScenarioPayload.plain(\n          try Descriptors.decode(boxes[destination]!.type, frame.payload, table))\n        try owner.reply(frame.source, frame.id, 0, [])\n        flights[key] = nil\n        return [.delivered(destination, value, flight.clock)]\n      }\n      if frame.id != 0 {\n        try owner.reply(frame.source, frame.id, 3, Array(\"not a scenario mailbox request\".utf8))\n      }\n      return []\n    case .mailReply(let cell, let result):\n      return replied(cell.identity, result)\n    }\n  }\n\n  /// A mailbox reply, by the request identity it answers.\n  private func replied(_ identity: UInt64, _ result: Result<(Int, [UInt8]), NodeFailure>)\n    -> [ScenarioOutcome]\n  {\n    guard let (reply, key) = pending[identity] else { return [] }\n    pending[identity] = nil\n    switch result {\n    case .success(let (status, body)) where status == 0 && body.isEmpty: reply(.success(()))\n    case .success(let (status, _)):\n      reply(.failure(ScenarioFault(\"mailbox_send_failed status \\(status)\")))\n    case .failure(let failure):\n      reply(.failure(ScenarioFault(\"mailbox_send_failed \\(failure.reason)\")))\n    }\n    // A timed-out request may never have arrived: release what it carried.\n    guard let flight = flights[key] else { return [] }\n    flights[key] = nil\n    return [.lost(flight.destination, flight.value)]\n  }\n\n  func stats() -> ScenarioStats {\n    let trace = network.trace()\n    return ScenarioStats(\n      frames: trace.count, lost: trace.filter { $0.outcome == \"lost\" }.count,\n      duplicated: trace.filter { $0.delaySlots.count == 2 }.count, pendingRequests: pending.count)\n  }\n\n  func close() {\n    for (reply, _) in pending.values { reply(.failure(ScenarioFault(\"network_closed\"))) }\n    pending.removeAll()\n    for node in nodes { node.close() }\n    network.close()\n  }\n}\n"
swiftSource "LawSpecTesting/Schedule.swift" = "// How a harness runs a unit's laws on Swift Testing: `order random` runs a\n// unit's tests in an order the run's seed chooses (the same seed, the same\n// order), and `parallel` lets them run at once, while other units' tests run\n// one at a time. ref:REQ-harness-units ref:DEC-portable-seeded-generation\n\nimport CryptoKit\nimport Foundation\nimport LawSpecRuntime\n\npublic enum Schedule {\n  private static let chosen = BigInt(UInt64.random(in: 0...UInt64.max))\n\n  /// The run's seed for ordering: LAWSPEC_SEED, or one chosen once per run.\n  public static func seed() -> BigInt {\n    if let text = ProcessInfo.processInfo.environment[\"LAWSPEC_SEED\"], !text.isEmpty,\n      let s = BigInt(text)\n    {\n      return s\n    }\n    return chosen\n  }\n\n  /// Items in the order a seed chooses for a unit: by the hash of the seed,\n  /// the unit and each item's position.\n  public static func order<T>(_ unitName: String, _ items: [T]) -> [T] {\n    let s = seed()\n    FileHandle.standardError.write(\n      Data(\"order random seed \\(s) (\\(unitName)): LAWSPEC_SEED=\\(s) replays this order\\n\".utf8))\n    let keyed = items.enumerated().map { i, item -> ([UInt8], Int, T) in\n      let key = Array(\n        SHA256.hash(data: Data((s.description + \"\\u{0}\" + unitName + \"\\u{0}\" + String(i + 1)).utf8))\n      )\n      return (key, i, item)\n    }\n    return keyed.sorted { a, b in\n      let c = Scalar.compareBytes(a.0, b.0)\n      return c != 0 ? c < 0 : a.1 < b.1\n    }.map { $0.2 }\n  }\n}\n"
swiftSource "LawSpecTesting/Search.swift" = "// LawSpec's descriptor search, apart from generation and shrinking: the\n// portable seeded climb of a `target` (ten starting points, sixty rounds, at\n// most twenty-four moves a round and four hundred checks), and the failure\n// database that keeps a failing law's inputs (LAWSPEC_FAILURES) and replays\n// them first on the next run. ref:REQ-harness-units\n// ref:DEC-portable-seeded-generation ref:DEC-shrink-within-domain\n\nimport Foundation\nimport LawSpecRuntime\n\npublic enum Search {\n  private static func inputFile(_ law: String) -> String? {\n    guard let directory = ProcessInfo.processInfo.environment[\"LAWSPEC_FAILURES\"],\n      !directory.isEmpty\n    else { return nil }\n    let name = Harness.hexDigest(law).lowercased()\n    return URL(fileURLWithPath: directory).appendingPathComponent(\"inputs\").appendingPathComponent(\n      name + \".json\"\n    ).path\n  }\n\n  static func hex(_ bytes: [UInt8]) -> String { bytes.map { String(format: \"%02x\", $0) }.joined() }\n\n  static func unhex(_ text: String) -> [UInt8]? {\n    let chars = Array(text.utf8)\n    guard chars.count % 2 == 0 else { return nil }\n    var bytes = [UInt8]()\n    var i = 0\n    while i < chars.count {\n      guard let b = UInt8(String(decoding: chars[i..<(i + 2)], as: UTF8.self), radix: 16) else {\n        return nil\n      }\n      bytes.append(b)\n      i += 2\n    }\n    return bytes\n  }\n\n  /// Keep a failing case's inputs, encoded on the canonical wire.\n  public static func remember(_ law: String, _ descriptors: [String], _ values: [Value]) throws {\n    guard let file = inputFile(law) else { return }\n    let inputs = try zip(descriptors, values).map { descriptor, value -> JSON in\n      let (table, d) = try Descriptors.fromText(descriptor)\n      return .string(hex(try Descriptors.encode(d, value, table)))\n    }\n    let record = JSON.object([(\"law\", .string(law)), (\"inputs\", .array(inputs))])\n    try? FileManager.default.createDirectory(\n      atPath: (file as NSString).deletingLastPathComponent, withIntermediateDirectories: true)\n    Harness.writeAtomically(file, record.text)\n  }\n\n  private static func keep(_ law: String, _ descriptors: [String], _ values: [Value]) {\n    do { try remember(law, descriptors, values) } catch {\n      FileHandle.standardError.write(\n        Data(\"LawSpec could not save inputs for \\(law): \\(error)\\n\".utf8))\n    }\n  }\n\n  /// Run a case, keeping its inputs when it fails.\n  public static func guardCase(\n    _ law: String, _ descriptors: [String], _ values: [Value], _ check: () throws -> Value\n  ) throws -> Value {\n    do {\n      let result = try check()\n      if case .bool(false) = result { keep(law, descriptors, values) }\n      return result\n    } catch {\n      keep(law, descriptors, values)\n      throw error\n    }\n  }\n\n  /// Replay the kept failing inputs of a law, if any, before its generated\n  /// cases; a repaired or obsolete one is removed.\n  public static func replay(\n    _ law: String, _ descriptors: [String], _ check: ([Value]) throws -> Value?\n  ) throws {\n    guard let file = inputFile(law), FileManager.default.fileExists(atPath: file) else { return }\n    var values: [Value]? = nil\n    if let data = FileManager.default.contents(atPath: file),\n      let record = try? JSONSerialization.jsonObject(with: data) as? [String: Any],\n      record[\"law\"] as? String == law, let inputs = record[\"inputs\"] as? [String],\n      inputs.count == descriptors.count\n    {\n      values = try? zip(descriptors, inputs).map { descriptor, text -> Value in\n        let (table, d) = try Descriptors.fromText(descriptor)\n        guard let bytes = unhex(text) else { throw Fail.with(\"InvalidSavedInputs\") }\n        return try Descriptors.decode(d, bytes, table)\n      }\n    }\n    if let values {\n      FileHandle.standardError.write(\n        Data(\"\\(law): replaying the failing inputs kept in .lawspec/failures\\n\".utf8))\n      if case .bool(false)? = try check(values) { throw Fail.with(\"ReplayFailed\", law) }\n    } else {\n      FileHandle.standardError.write(Data(\"\\(law): discarding incompatible saved inputs\\n\".utf8))\n    }\n    try? FileManager.default.removeItem(atPath: file)\n  }\n\n  private static func bounds(_ d: Descriptors.Descriptor) -> (BigInt, BigInt) {\n    guard case .forms(let parts) = d, parts.count == 4 else { return (.zero, .zero) }\n    func number(_ x: Descriptors.Descriptor) -> BigInt? {\n      if case .number(let n) = x { return n } else { return nil }\n    }\n    return Descriptors.generationBounds(number(parts[2]), number(parts[3]))\n  }\n\n  /// Each move changes one integer leaf, within its wire bounds.\n  private static func moves(_ d: Descriptors.Descriptor, _ value: Value, _ table: Descriptors.Table)\n    throws -> [Value]\n  {\n    let resolved = try Descriptors.resolve(d, table)\n    guard case .forms(let parts) = resolved, case .atom(let head)? = parts.first else { return [] }\n    switch (head, value) {\n    case (\"int\", .int(let n)) where parts.count == 4:\n      let (lo, hi) = bounds(resolved)\n      var result = [BigInt]()\n      for x in [n + .one, n - .one, n * 2, n / 2, n + (hi - n) / 2, n - (n - lo) / 2]\n      where x != n && x >= lo && x <= hi && !result.contains(x) { result.append(x) }\n      return result.map { .int($0) }\n    case (\"list\", .list(let items)) where parts.count == 2:\n      return try fieldMoves(items.map { _ in parts[1] }, items, table).map { .list($0) }\n    case (\"maybe\", .data(\"Maybe::Present\", let f)) where parts.count == 2 && f.count == 1:\n      return try moves(parts[1], f[0], table).map { .data(\"Maybe::Present\", [$0]) }\n    case (\"either\", .data(let tag, let f)) where parts.count == 3 && f.count == 1:\n      return try moves(tag == \"Either::Left\" ? parts[1] : parts[2], f[0], table).map {\n        .data(tag, [$0])\n      }\n    case (\"data\", .data(let tag, let values)) where parts.count >= 2:\n      for c in parts.dropFirst(2) {\n        if case .forms(let cparts) = c, cparts.count >= 2, case .atom(\"ctor\") = cparts[0] {\n          var name = \"\"\n          if case .quoted(let s) = cparts[1] { name = s }\n          if case .atom(let s) = cparts[1] { name = s }\n          if name == tag {\n            return try fieldMoves(Array(cparts.dropFirst(2)), values, table).map { .data(tag, $0) }\n          }\n        }\n      }\n      throw Fail.with(\"ForeignWireConstructor\", tag)\n    default:\n      return []\n    }\n  }\n\n  private static func fieldMoves(\n    _ ds: [Descriptors.Descriptor], _ values: [Value], _ table: Descriptors.Table\n  ) throws -> [[Value]] {\n    guard let d = ds.first, let v = values.first else { return [] }\n    let rest = Array(values.dropFirst())\n    return try moves(d, v, table).map { [$0] + rest }\n      + (try fieldMoves(Array(ds.dropFirst()), rest, table)).map { [v] + $0 }\n  }\n\n  private static func inputMoves(\n    _ tables: [(Descriptors.Table, Descriptors.Descriptor)], _ values: [Value]\n  ) throws -> [[Value]] {\n    guard let (table, d) = tables.first, let v = values.first else { return [] }\n    let rest = Array(values.dropFirst())\n    return try moves(d, v, table).map { [$0] + rest }\n      + (try inputMoves(Array(tables.dropFirst()), rest)).map { [v] + $0 }\n  }\n\n  private struct Climb {\n    var tried = 0\n    var accepted = 0\n    var best: Value? = nil\n    var values: [Value]? = nil\n  }\n\n  private struct SearchFailed: Error {\n    let error: any Error\n    let state: Climb\n    let values: [Value]\n  }\n\n  /// Climb towards the highest score of a law's `target`, from the run's seed.\n  /// The check gives nil for inputs outside the law's domain, or the score.\n  public static func climb(\n    _ law: String, _ descriptors: [String], _ check: ([Value]) throws -> Value?\n  ) throws {\n    let text = ProcessInfo.processInfo.environment[\"LAWSPEC_SEED\"] ?? \"\"\n    let seed = text.isEmpty ? BigInt.zero : (BigInt(text) ?? .zero)\n    let tables = try descriptors.map(Descriptors.fromText)\n    func generate(_ s: BigInt) throws -> [Value] {\n      var state = Random.seed(s)\n      return try tables.map { table, d in\n        let (v, next) = try Descriptors.generate(d, table, state, 8)\n        state = next\n        return v\n      }\n    }\n    func attempt(_ values: [Value], _ state: Climb) throws -> (Bool, Climb) {\n      if state.tried >= 400 { return (false, state) }\n      var next = state\n      next.tried += 1\n      let score: Value?\n      do { score = try check(values) } catch {\n        throw SearchFailed(error: error, state: next, values: values)\n      }\n      guard let s = score else { return (false, next) }\n      next.accepted += 1\n      if try Harness.higher(s, state.best) {\n        next.best = s\n        next.values = values\n        return (true, next)\n      }\n      return (false, next)\n    }\n    func publish(_ outcome: String, _ state: Climb) {\n      let best = state.best.map(Harness.scoreText)\n      print(\n        \"\\(law): targeted search tried \\(state.tried) case(s)\"\n          + (best.map { \"; best score \" + $0 } ?? \"\"))\n      let search = JSON.object([\n        (\"seed\", .string(seed.description)), (\"tried\", .integer(state.tried)),\n        (\"accepted\", .integer(state.accepted)), (\"best\", best.map { .string($0) } ?? .null),\n      ])\n      Harness.record([(\"search\", search), (\"outcome\", .string(outcome))])\n    }\n    do {\n      var state = Climb()\n      for k in 0..<10 { state = try attempt(try generate(seed + BigInt(k)), state).1 }\n      var step = 0\n      while step < 60 && state.tried < 400 {\n        let candidates = try state.values.map { Array(try inputMoves(tables, $0).prefix(24)) } ?? []\n        var rose = false\n        for candidate in candidates {\n          let (rising, next) = try attempt(candidate, state)\n          rose = rose || rising\n          state = next\n        }\n        if !rose { state = try attempt(try generate(seed + BigInt(1000) + BigInt(step)), state).1 }\n        step += 1\n      }\n      publish(\"passed\", state)\n    } catch let failed as SearchFailed {\n      keep(law, descriptors, failed.values)\n      publish(\"failed\", failed.state)\n      let inputs =\n        (try? zip(tables, failed.values).map { pair, v in\n          hex(try Descriptors.encode(pair.1, v, pair.0)).uppercased()\n        }) ?? []\n      throw LawSpecError(\n        \"TargetFailed\",\n        \"\\(law) (seed \\(seed), inputs \\(inputs.joined(separator: \", \"))): \\(failed.error)\",\n        cause: \"\\(failed.error)\")\n    }\n  }\n}\n"
swiftSource "LawSpecTesting/Supervision.swift" = "// Supervision evidence: the generated check of a program with supervisors\n// exercises real trees of the runtime's actors, every restart strategy and\n// lifetime, restart budgets and escalation, links, committed checkpoints and\n// stable mailboxes. ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\n\nimport Foundation\nimport LawSpecRuntime\n\npublic enum Supervision {\n  private typealias Handle = Actors.Handle\n\n  private struct Probe: Error, CustomStringConvertible {\n    var description: String { \"supervision probe\" }\n  }\n\n  private static func failure(_ label: String, _ expected: Any, _ actual: Any) -> LawSpecError {\n    Fail.with(\"SupervisionFailed\", \"\\(label): expected \\(expected), actual \\(actual)\")\n  }\n\n  private static func expect<T: Equatable>(_ label: String, _ expected: T, _ actual: T) throws {\n    if expected != actual { throw failure(label, expected, actual) }\n  }\n\n  private static func counter() -> Actors.Spec { Actors.actor({ 0 }, { _ in 0 }) }\n\n  private static func counters(_ names: [String]) -> [(String, Actors.Lifetime, Actors.Spec)] {\n    names.map { ($0, .permanent, counter()) }\n  }\n\n  private static func tree(\n    _ strategy: Actors.Strategy, _ limit: Int, _ children: [(String, Actors.Lifetime, Actors.Spec)],\n    _ body: (Handle) throws -> Void\n  ) throws {\n    try Actors.withSpec(try Actors.supervisor(strategy, limit, 10_000_000, children), body)\n  }\n\n  private static func value(_ h: Handle) throws -> Int { try Actors.state(h) as! Int }\n\n  private static func states(_ handles: [Handle]) throws -> [Int] { try handles.map(value) }\n\n  @discardableResult\n  private static func bump(_ h: Handle) throws -> Int {\n    try Actors.call(h) { s in\n      let n = (s as! Int) + 1\n      return (n, n)\n    } as! Int\n  }\n\n  private static func failCall(_ h: Handle) throws {\n    do {\n      let answer = try Actors.call(h) { _ in throw Probe() }\n      throw failure(\"failing handler\", \"ActorCrashed\", answer)\n    } catch let e as LawSpecError\n      where e.code == \"ActorCrashed\" && e.detail.contains(\"supervision probe\")\n    {\n      return\n    } catch let e as LawSpecError where e.code == \"SupervisionFailed\" {\n      throw e\n    } catch {\n      throw failure(\"failing handler\", \"ActorCrashed\", error)\n    }\n  }\n\n  private static func stopped(_ h: Handle) throws {\n    do {\n      let s = try Actors.state(h)\n      throw failure(\"stopped actor\", \"ActorStopped\", s)\n    } catch let e as LawSpecError where e.code == \"ActorStopped\" {\n      return\n    } catch let e as LawSpecError where e.code == \"SupervisionFailed\" {\n      throw e\n    } catch {\n      throw failure(\"stopped actor\", \"ActorStopped\", error)\n    }\n  }\n\n  private static func crashed(_ inbox: Actors.Inbox, _ h: Handle) throws {\n    guard case .crashed? = Actors.receiveEvent(inbox, h, 2000) else {\n      throw failure(\"crash monitor\", \"Crashed\", \"nothing\")\n    }\n  }\n\n  private static func waitFor(_ label: String, _ signal: DispatchSemaphore) throws {\n    if signal.wait(timeout: .now() + 2) == .timedOut { throw failure(label, \"signal\", \"timeout\") }\n  }\n\n  private static func strategies() throws {\n    for (strategy, expected) in [\n      (Actors.Strategy.oneForOne, [1, 0, 1]), (.oneForAll, [0, 0, 0]), (.restForOne, [1, 0, 0]),\n    ] {\n      try tree(strategy, 5, counters([\"a\", \"b\", \"c\"])) { sup in\n        let actors = try [\"a\", \"b\", \"c\"].map { try Actors.child(sup, $0) }\n        let before = actors.map(Actors.worker)\n        for a in actors { try bump(a) }\n        try expect(\"three children\", 3, Actors.children(sup).count)\n        try failCall(actors[1])\n        try expect(\"\\(strategy)\", expected, try states(actors))\n        let after = actors.map(Actors.worker)\n        try expect(\n          \"\\(strategy) replaced workers\", expected.map { $0 == 0 },\n          zip(before, after).map { $0 != $1 })\n      }\n    }\n  }\n\n  private static func lifetimes() throws {\n    try tree(\n      .oneForOne, 5,\n      [(\"p\", .permanent, counter()), (\"t\", .transient, counter()), (\"x\", .temporary, counter())]\n    ) { sup in\n      let p = try Actors.child(sup, \"p\")\n      let t = try Actors.child(sup, \"t\")\n      let x = try Actors.child(sup, \"x\")\n      try bump(p)\n      Actors.stop(p)\n      try expect(\"permanent normal stop\", 0, try value(p))\n      try bump(t)\n      try failCall(t)\n      try expect(\"transient crash\", 0, try value(t))\n      Actors.stop(t)\n      try stopped(t)\n      try failCall(x)\n      try stopped(x)\n      try expect(\"remaining children\", [\"p\"], Actors.children(sup).map(\\.0))\n    }\n  }\n\n  private static func limits() throws {\n    try tree(.oneForOne, 2, counters([\"a\", \"b\"])) { sup in\n      let a = try Actors.child(sup, \"a\")\n      let b = try Actors.child(sup, \"b\")\n      let inbox = Actors.Inbox()\n      Actors.monitor(sup, inbox)\n      for _ in 1...3 { try failCall(a) }\n      try stopped(b)\n      try crashed(inbox, sup)\n      try expect(\"one limit notification\", true, Actors.receiveEvent(inbox, sup, 0) == nil)\n    }\n  }\n\n  private static func escalation() throws {\n    let inner = try Actors.supervisor(.oneForOne, 1, 10_000_000, counters([\"a\", \"b\"]))\n    try tree(.oneForOne, 5, [(\"inner\", .permanent, inner), (\"c\", .permanent, counter())]) { sup in\n      let innerHandle = try Actors.child(sup, \"inner\")\n      let c = try Actors.child(sup, \"c\")\n      let a = try Actors.child(innerHandle, \"a\")\n      let b = try Actors.child(innerHandle, \"b\")\n      let old = Actors.worker(innerHandle)\n      try bump(b)\n      try bump(c)\n      try failCall(a)\n      try failCall(a)\n      try expect(\"escalated children\", [0, 0, 1], try states([a, b, c]))\n      try expect(\"replaced inner supervisor\", true, old != Actors.worker(innerHandle))\n      try expect(\"outer restart count\", 1, Actors.restartCount(sup))\n      try expect(\"fresh inner budget\", 0, Actors.restartCount(innerHandle))\n    }\n  }\n\n  private static func links() throws {\n    try Actors.withSpec(counter()) { a in\n      try Actors.withSpec(counter()) { b in\n        Actors.link(a, b)\n        let inbox = Actors.Inbox()\n        Actors.monitor(b, inbox)\n        try failCall(a)\n        try crashed(inbox, b)\n        try stopped(b)\n      }\n    }\n    try tree(.oneForOne, 10, counters([\"a\", \"b\", \"c\"])) { sup in\n      let actors = try [\"a\", \"b\", \"c\"].map { try Actors.child(sup, $0) }\n      Actors.link(actors[0], actors[1])\n      Actors.link(actors[1], actors[2])\n      Actors.link(actors[2], actors[0])\n      let inbox = Actors.Inbox()\n      for x in actors {\n        try bump(x)\n        Actors.monitor(x, inbox)\n      }\n      try failCall(actors[0])\n      for x in actors { try crashed(inbox, x) }\n      let deadline = Date().addingTimeInterval(2)\n      while Actors.restartCount(sup) < 3 && Date() < deadline { usleep(1000) }\n      try expect(\"link cycle\", [0, 0, 0], try states(actors))\n      try expect(\"one restart per linked actor\", 3, Actors.restartCount(sup))\n    }\n  }\n\n  private static func checkpointAndMailbox() throws {\n    let spec = Actors.actor({ 0 }, { $0 })\n    try tree(.oneForOne, 5, [(\"a\", .permanent, spec)]) { sup in\n      let a = try Actors.child(sup, \"a\")\n      try bump(a)\n      try failCall(a)\n      try expect(\"committed checkpoint\", 1, try value(a))\n      let entered = DispatchSemaphore(value: 0)\n      let finish = DispatchSemaphore(value: 0)\n      defer { finish.signal() }\n      let inbox = Actors.Inbox()\n      Actors.monitor(a, inbox)\n      let w = Actors.worker(a)\n      try Actors.tell(a) { s in\n        entered.signal()\n        finish.wait()\n        finish.signal()\n        return ((), (s as! Int) + 10)\n      }\n      try waitFor(\"mailbox handler started\", entered)\n      try Actors.tell(a) { s in ((), (s as! Int) + 2) }\n      Actors.kill(a)\n      try crashed(inbox, a)\n      try expect(\"queued tell after an external kill\", 3, try value(a))\n      try expect(\"stable mailbox handle\", a, try Actors.child(sup, \"a\"))\n      try expect(\"replaced killed worker\", true, w != Actors.worker(a))\n    }\n  }\n\n  private static func queuedSiblingRestart(_ strategy: Actors.Strategy) throws {\n    let restored = Locked<Int?>(nil)\n    let sibling = Actors.actor(\n      { 0 },\n      { s in\n        restored.with { $0 = s as? Int }\n        return 0\n      })\n    try tree(strategy, 5, [(\"a\", .permanent, counter()), (\"b\", .permanent, sibling)]) { sup in\n      let a = try Actors.child(sup, \"a\")\n      let b = try Actors.child(sup, \"b\")\n      let entered = DispatchSemaphore(value: 0)\n      let finish = DispatchSemaphore(value: 0)\n      defer { finish.signal() }\n      let queued = Locked<Int?>(nil)\n      try Actors.tell(b) { s in\n        entered.signal()\n        finish.wait()\n        finish.signal()\n        return ((), (s as! Int) + 1)\n      }\n      try waitFor(\"sibling started\", entered)\n      try Actors.tell(b) { s in\n        queued.with { $0 = s as? Int }\n        return ((), (s as! Int) + 3)\n      }\n      try Actors.tell(a) { _ in throw Probe() }\n      let deadline = Date().addingTimeInterval(2)\n      while Actors.restartCount(sup) == 0 {\n        if Date() > deadline { throw failure(\"restart admitted\", true, false) }\n        usleep(1000)\n      }\n      // This tell follows the restart; the two accepted earlier belong\n      // to the old checkpoint, and their order survives the restart.\n      try Actors.tell(b) { s in ((), (s as! Int) + 10) }\n      finish.signal()\n      try expect(\"\\(strategy) post-restart tell\", 10, try value(b))\n      try expect(\"\\(strategy) queued checkpoint\", 1, queued.with { $0 })\n      try expect(\"\\(strategy) restart checkpoint\", 4, restored.with { $0 })\n    }\n  }\n\n  /// The supervision check: fails with SupervisionFailed naming what broke.\n  public static func check() throws {\n    try Actors.withSpec(counter()) { a in\n      try expect(\"initial increment\", 1, try bump(a))\n      try failCall(a)\n      try stopped(a)\n    }\n    try strategies()\n    try lifetimes()\n    try limits()\n    try escalation()\n    try links()\n    try checkpointAndMailbox()\n    for strategy in [Actors.Strategy.oneForAll, .restForOne] { try queuedSiblingRestart(strategy) }\n  }\n}\n"
